    /// Push a `PendingRespawn` into the shared map's respawn queue.
    ///
    /// The registration bootstrap still defaults to instance `0`; live removal/mutation
    /// follows the canonical Player instance. The canonical respawn store
    /// (`wow_map::RespawnStoreLikeCpp`) is a separate step.
    /// Lock is acquired, respawn is pushed, then lock is released before returning.
    /// No `.await` is performed under lock.
    pub(crate) fn push_map_respawn_like_cpp(
        &mut self,
        map_id: u16,
        instance_id: u32,
        r: crate::map_manager::PendingRespawn,
    ) {
        if let Some(manager) = &self.map_manager {
            manager
                .write()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .push_respawn(map_id, instance_id, r);
        }
    }

    /// Drain ready respawns from the shared map's respawn queue for this (map_id, instance_id).
    ///
    /// Lock is acquired, ready entries are drained, then lock is released before returning.
    /// Packet building and `register_world_creature` calls MUST happen after this returns
    /// (never under lock). No `.await` is performed under lock.
    pub(crate) fn drain_ready_map_respawns_like_cpp(
        &mut self,
        map_id: u16,
        instance_id: u32,
        now: std::time::Instant,
    ) -> Vec<crate::map_manager::PendingRespawn> {
        if let Some(manager) = &self.map_manager {
            return manager
                .write()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .drain_ready_respawns(map_id, instance_id, now);
        }
        Vec::new()
    }

    pub(crate) fn visible_world_creatures_from_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
    ) -> Vec<crate::map_manager::WorldCreature> {
        if self
            .current_canonical_player_map_key_like_cpp()
            .is_some_and(|key| key.map_id != u32::from(map_id))
        {
            return Vec::new();
        }

        let mut creatures = Vec::new();
        let mut seen = std::collections::HashSet::new();
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();
        let Some(player_phase_shift) = self.represented_player_phase_shift_like_cpp() else {
            return Vec::new();
        };

        if let Some(manager) = &self.map_manager {
            let (_, instance_id) = self.current_legacy_runtime_map_key_like_cpp();
            let visibility_range = self.player_map_visibility_range_like_cpp(map_id);
            // Materialize the legacy candidates and release its map-manager
            // read guard before visibility filters consult canonical Player
            // state. Spell validation takes these managers in the opposite
            // order (canonical, then legacy write), so retaining the legacy
            // guard here would permit an ABBA deadlock.
            let legacy_candidates = {
                manager
                    .read()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .get_visible_creatures_in_phase(
                        map_id,
                        instance_id,
                        position.x,
                        position.y,
                        position.z,
                        // C++ visits cells around `GetSightRange()` and applies
                        // `_IsWithinDist` with both combat reaches. One extra
                        // cell keeps borderline target centers in the legacy
                        // candidate set before the exact check below.
                        visibility_range + source_combat_reach + SIZE_OF_GRID_CELL,
                        Some(&player_phase_shift),
                    )
            };
            creatures.extend(
                legacy_candidates
                    .into_iter()
                    .filter(|creature| {
                        Self::visibility_distance_allows_like_cpp(
                            position,
                            source_combat_reach,
                            &creature.position(),
                            creature.creature.unit().world().combat_reach(),
                            visibility_range,
                        )
                    })
                    .filter(|creature| {
                        self.represented_can_see_or_detect_world_creature_like_cpp(creature)
                    })
                    .filter(|creature| seen.insert(creature.guid())),
            );
        }

        // C++ has one map-owned Creature object. During Rust's temporary
        // canonical/legacy split, the legacy creature owns live movement
        // splines, so prefer it for duplicate GUIDs and use canonical only as
        // a fallback for objects absent from the legacy runtime.
        creatures.extend(
            self.visible_creatures_from_canonical_map_like_cpp(map_id, position)
                .unwrap_or_default()
                .into_iter()
                .filter(|creature| seen.insert(creature.guid())),
        );
        creatures
    }

    pub(crate) fn visible_creatures_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
    ) -> Option<Vec<crate::map_manager::WorldCreature>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let player_map_key = player_map_key?;
        if player_map_key.map_id != requested_map_id {
            return Some(Vec::new());
        }
        let source_combat_reach =
            self.with_owned_player_like_cpp(|player| player.unit().world().combat_reach())?;
        let player_phase_shift = self.represented_player_phase_shift_like_cpp()?;
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = manager.find_map(player_map_key.map_id, player_map_key.instance_id)?;
        let visibility_range = self.player_map_visibility_range_like_cpp(map_id);
        let nearby = map.map().nearby_cell_guids_like_cpp(
            position.x,
            position.y,
            visibility_range + source_combat_reach,
        );

        let mut candidates = Vec::new();
        for guid in nearby
            .world
            .creatures
            .into_iter()
            .chain(nearby.grid.creatures)
        {
            let Some(creature) = map.map().get_typed_creature(guid) else {
                continue;
            };
            let world = creature.unit().world();
            if !world.object().is_in_world()
                || world.map_id() != requested_map_id
                // C++ visibility is a horizontal (XY) range test: CanSeeOrDetect ->
                // IsWithinDist(obj, GetSightRange, is3D=false) (Object.cpp:1587-1609).
                // #NEXT.R8.ENTITIES.1223 — use 2D so vertically-separated objects (e.g. ICC
                // layered floors) within horizontal range are not dropped.
                || !Self::visibility_distance_allows_like_cpp(
                    position,
                    source_combat_reach,
                    &world.position(),
                    world.combat_reach(),
                    visibility_range,
                )
                || !player_phase_shift.can_see(world.phase_shift())
            {
                continue;
            }
            candidates.push(creature.clone());
        }
        drop(manager);

        self.with_owned_player_like_cpp(move |player| {
            candidates
                .into_iter()
                .filter(|creature| {
                    player.unit().can_see_or_detect_unit_like_cpp(
                        creature.unit(),
                        false,
                        true,
                        false,
                    )
                })
                .map(|creature| {
                    let create_data =
                        crate::map_manager::WorldCreature::create_data_from_canonical_like_cpp(
                            &creature,
                        );
                    crate::map_manager::WorldCreature::from_canonical(creature, create_data)
                })
                .collect()
        })
    }

    pub(crate) fn send_initial_visible_packets_for_creature_like_cpp(
        &self,
        creature: &crate::map_manager::WorldCreature,
    ) {
        let aura_subsystem = &creature.creature.unit().subsystems().auras;
        if aura_subsystem.visible_auras.is_empty() {
            return;
        }

        let mut visible: Vec<_> = aura_subsystem.visible_auras.iter().collect();
        visible.sort_by_key(|(slot, _)| **slot);
        let auras = visible
            .into_iter()
            .map(|(slot, aura_ref)| {
                let active_flags = aura_subsystem
                    .applied_auras
                    .iter()
                    .filter(|applied| applied.aura_ref() == *aura_ref)
                    .fold(0u32, |mask, applied| mask | applied.effect_mask);
                let application = aura_subsystem.visible_aura_applications_like_cpp.get(slot);
                let flags = application.map_or(active_flags, |application| application.flags);
                let points = if flags & AFLAG_SCALABLE_LIKE_CPP != 0 {
                    application
                        .map(|application| {
                            application
                                .effect_amounts
                                .iter()
                                .filter(|effect| {
                                    effect.effect_index < u32::BITS as u8
                                        && active_flags & (1u32 << effect.effect_index) != 0
                                })
                                .map(|effect| effect.amount as f32)
                                .collect()
                        })
                        .unwrap_or_default()
                } else {
                    Vec::new()
                };

                wow_packet::packets::misc::AuraInfoLikeCpp {
                    slot: *slot,
                    aura_data: Some(wow_packet::packets::misc::AuraDataInfoLikeCpp {
                        cast_id: ObjectGuid::create_world_object(
                            HighGuid::Cast,
                            3,
                            1,
                            self.player_map_id_like_cpp(),
                            0,
                            aura_ref.spell_id,
                            i64::from(*slot) + 1,
                        ),
                        spell_id: i32::try_from(aura_ref.spell_id).unwrap_or(i32::MAX),
                        flags: flags.min(u32::from(u16::MAX)) as u16,
                        active_flags,
                        caster_guid: aura_ref.caster_guid,
                        cast_level: creature.level().into(),
                        applications: 0,
                        duration_ms: None,
                        remaining_ms: None,
                        points,
                    }),
                }
            })
            .collect();

        self.send_packet(&wow_packet::packets::misc::AuraUpdate::full_for(
            creature.guid(),
            auras,
        ));
    }

    pub(crate) fn send_initial_player_auras_like_cpp(&self) {
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return;
        };
        if visible_auras.is_empty() {
            return;
        }
        let Some(player_guid) = self.player_guid() else {
            return;
        };

        let mut visible: Vec<_> = visible_auras.values().collect();
        visible.sort_by_key(|aura| aura.slot);
        let auras = visible
            .into_iter()
            .map(|aura| {
                Self::player_aura_info_like_cpp(
                    aura,
                    self.player_level_like_cpp(),
                    self.player_map_id_like_cpp(),
                )
            })
            .collect();
        self.send_packet(&wow_packet::packets::misc::AuraUpdate::full_for(
            player_guid,
            auras,
        ));
    }

    fn player_aura_info_like_cpp(
        aura: &AuraApplication,
        player_level: u8,
        map_id: u16,
    ) -> wow_packet::packets::misc::AuraInfoLikeCpp {
        let duration_ms = (aura.duration_total > 0).then_some(aura.duration_total);
        let remaining_ms = (aura.duration_remaining > 0).then_some(aura.duration_remaining);
        let points = if aura.aura_flags & AFLAG_SCALABLE_LIKE_CPP != 0 {
            aura.represented_effect_amounts
                .iter()
                .filter(|effect| {
                    effect.effect_index < u32::BITS as u8
                        && aura.effect_mask & (1u32 << effect.effect_index) != 0
                })
                .map(|effect| effect.amount as f32)
                .collect()
        } else {
            Vec::new()
        };

        wow_packet::packets::misc::AuraInfoLikeCpp {
            slot: aura.slot,
            aura_data: Some(wow_packet::packets::misc::AuraDataInfoLikeCpp {
                cast_id: ObjectGuid::create_world_object(
                    HighGuid::Cast,
                    3,
                    aura.caster_guid.realm_id().max(1),
                    map_id,
                    0,
                    u32::try_from(aura.spell_id).unwrap_or(0),
                    i64::from(aura.slot) + 1,
                ),
                spell_id: aura.spell_id,
                flags: aura.aura_flags.min(u32::from(u16::MAX)) as u16,
                active_flags: aura.effect_mask,
                caster_guid: aura.caster_guid,
                cast_level: player_level.into(),
                applications: aura.stack_count.saturating_sub(1),
                duration_ms,
                remaining_ms,
                points,
            }),
        }
    }

    pub(crate) fn player_map_visibility_range_like_cpp(&self, map_id: u16) -> f32 {
        self.legacy_creature_aggro_config_like_cpp
            .map_visibility_range_like_cpp(map_id)
    }

    fn represented_can_see_or_detect_world_creature_like_cpp(
        &self,
        creature: &crate::map_manager::WorldCreature,
    ) -> bool {
        let expected = wow_map::MapKey::new(
            u32::from(self.player_map_id_like_cpp()),
            creature.instance_id(),
        );
        if self.current_canonical_player_map_key_like_cpp() != Some(expected) {
            return false;
        }
        self.with_owned_player_like_cpp(|player| {
            player.unit().can_see_or_detect_unit_like_cpp(
                creature.creature.unit(),
                false,
                true,
                false,
            )
        })
        .unwrap_or(false)
    }

    fn represented_can_receive_creature_message_to_set_like_cpp(
        &self,
        guid: ObjectGuid,
        creature: &crate::map_manager::WorldCreature,
        required_3d: bool,
    ) -> bool {
        if !self.client_visible_guids_like_cpp.contains(&guid) {
            return false;
        }

        let Some(player_position) = self.player_position_like_cpp() else {
            return false;
        };
        let player_map_id = u32::from(self.player_map_id_like_cpp());
        let player_instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let Some(player_phase_shift) = self.represented_player_phase_shift_like_cpp() else {
            return false;
        };

        Self::creature_message_to_set_target_allows_like_cpp(
            creature,
            // The HaveAtClient membership was proven above.
            true,
            player_map_id,
            player_instance_id,
            &player_position,
            &player_phase_shift,
            required_3d,
        )
    }

    fn creature_message_to_set_target_allows_like_cpp(
        creature: &crate::map_manager::WorldCreature,
        source_is_visible_like_cpp: bool,
        player_map_id: u32,
        player_instance_id: u32,
        player_position: &Position,
        player_phase_shift: &PhaseShift,
        required_3d: bool,
    ) -> bool {
        if !source_is_visible_like_cpp {
            return false;
        }
        if creature.map_id() != player_map_id || creature.instance_id() != player_instance_id {
            return false;
        }
        if !player_phase_shift.can_see(creature.phase_shift()) {
            return false;
        }

        let range = creature.visibility_range_like_cpp();
        if required_3d {
            position_is_in_dist_strict_3d_like_cpp(&creature.position(), player_position, range)
        } else {
            position_is_in_dist_strict_2d_like_cpp(&creature.position(), player_position, range)
        }
    }

    pub(crate) fn represented_can_receive_creature_message_to_set_by_guid_like_cpp(
        &self,
        guid: ObjectGuid,
        map_id: u16,
        instance_id: u32,
        required_3d: bool,
    ) -> Option<bool> {
        self.represented_can_receive_creature_message_to_set_by_guid_with_legacy_fallback_like_cpp(
            guid,
            map_id,
            instance_id,
            required_3d,
            false,
        )
    }

    pub(crate) fn represented_can_receive_creature_message_to_set_by_guid_with_legacy_fallback_like_cpp(
        &self,
        guid: ObjectGuid,
        map_id: u16,
        instance_id: u32,
        required_3d: bool,
        allow_legacy_fallback: bool,
    ) -> Option<bool> {
        if let Some(manager) = &self.canonical_map_manager {
            let creature = {
                let manager = manager.lock().ok()?;
                manager
                    .find_map(u32::from(map_id), instance_id)
                    .and_then(|map| map.map().get_typed_creature(guid))
                    .map(|creature| {
                        let create_data =
                            crate::map_manager::WorldCreature::create_data_from_canonical_like_cpp(
                                creature,
                            );
                        crate::map_manager::WorldCreature::from_canonical(
                            creature.clone(),
                            create_data,
                        )
                    })
            };
            if let Some(creature) = creature {
                if creature.map_id() != u32::from(map_id) || creature.instance_id() != instance_id {
                    return Some(false);
                }
                return Some(
                    self.represented_can_receive_creature_message_to_set_like_cpp(
                        guid,
                        &creature,
                        required_3d,
                    ),
                );
            }
            if !allow_legacy_fallback {
                return None;
            }
        }

        // The two map managers coexist during the incremental runtime
        // migration. A canonical manager being installed does not prove that
        // it owns a source already validated from the legacy map. Only the
        // provenance-marked command path may cross this fallback boundary.
        let creature = {
            let manager = self.map_manager.as_ref()?;
            manager
                .read()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .find_creature(map_id, instance_id, guid)
                .cloned()
        }?;
        Some(
            self.represented_can_receive_creature_message_to_set_like_cpp(
                guid,
                &creature,
                required_3d,
            ),
        )
    }

    pub(crate) fn visible_gameobjects_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::GameObjectCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby = map.map().nearby_cell_guids_like_cpp(
            position.x,
            position.y,
            visibility_radius + source_combat_reach,
        );
        let now = Instant::now();
        let mut gameobjects = Vec::new();

        for guid in nearby.grid.gameobjects {
            let Some(gameobject) = map.map().get_typed_game_object(guid) else {
                continue;
            };
            let object = gameobject.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !Self::visibility_distance_allows_like_cpp(
                    position,
                    source_combat_reach,
                    &object.position(),
                    object.combat_reach(),
                    visibility_radius,
                )
            {
                continue;
            }
            if let Some(phase_shift) = self.represented_gameobject_phase_shifts.get(&guid)
                && !self.can_see_phase_shift_like_cpp(phase_shift)
            {
                continue;
            }
            let state = self.represented_gameobject_use_states.get(&guid);
            if state.is_some_and(|state| {
                state
                    .per_player_despawn_until
                    .is_some_and(|until| until > now)
            }) {
                continue;
            }

            let create_data = if let Some(state) = state {
                let Some(display_id) = state.display_id else {
                    continue;
                };
                let Some(go_type) = state.go_type else {
                    continue;
                };
                let state_for_viewer =
                    self.represented_gameobject_go_state_for_viewer_like_cpp(state, now);

                wow_packet::packets::update::GameObjectCreateData {
                    guid,
                    entry: object.object().entry(),
                    dynamic_flags: self.represented_gameobject_dynamic_flags_for_player_like_cpp(
                        object.object().entry(),
                        state,
                    ),
                    display_id,
                    go_type,
                    position: object.position(),
                    rotation: state.rotation,
                    anim_progress: 255,
                    state: state_for_viewer as i8,
                    art_kit: gameobject.data().art_kit,
                    created_by: state.owner_guid.unwrap_or(ObjectGuid::EMPTY),
                    faction_template: state.faction_template.unwrap_or(0) as i32,
                    gameobject_flags: state.gameobject_flags,
                    world_effect_id: 0,
                    scale: state.scale,
                    level: 0, // non-transport GameObject: Level unused (period via AnimationData)
                    // Canonical state path does not yet record per-spawn ParentRotation;
                    // identity until state population is added (#NEXT.R8.ENTITIES.1216 follow-up).
                    parent_rotation: [0.0, 0.0, 0.0, 1.0],
                }
            } else {
                let Some(create_data) =
                    self.gameobject_create_data_from_canonical_like_cpp(guid, gameobject)
                else {
                    continue;
                };
                create_data
            };

            gameobjects.push(create_data);
        }

        Some(gameobjects)
    }

    fn represented_gameobject_go_state_for_viewer_like_cpp(
        &self,
        state: &RepresentedGameObjectUseState,
        now: Instant,
    ) -> wow_entities::GoState {
        if state.per_player_state_player_guid == self.player_guid()
            && state
                .per_player_go_state_until
                .is_none_or(|until| until > now)
            && let Some(per_player_go_state) = state.per_player_go_state
        {
            return per_player_go_state;
        }

        state.go_state.unwrap_or(wow_entities::GoState::Ready)
    }

    fn gameobject_create_data_from_canonical_like_cpp(
        &self,
        guid: ObjectGuid,
        gameobject: &wow_entities::GameObject,
    ) -> Option<wow_packet::packets::update::GameObjectCreateData> {
        let object = gameobject.world();
        let data = gameobject.data();
        let display_id = u32::try_from(data.display_id).ok()?;
        if display_id == 0 {
            return None;
        }
        let go_type = u8::try_from(data.type_id).ok()?;
        let go_state = match data.state {
            0 => Some(wow_entities::GoState::Active),
            1 => Some(wow_entities::GoState::Ready),
            2 => Some(wow_entities::GoState::Destroyed),
            24 => Some(wow_entities::GoState::TransportActive),
            25 => Some(wow_entities::GoState::TransportStopped),
            _ => None,
        };

        Some(wow_packet::packets::update::GameObjectCreateData {
            guid,
            entry: object.object().entry(),
            dynamic_flags: self.represented_gameobject_dynamic_flags_for_player_like_cpp(
                object.object().entry(),
                &RepresentedGameObjectUseState {
                    go_type: Some(go_type),
                    go_state,
                    dynamic_flags: object.object().dynamic_flags(),
                    ..Default::default()
                },
            ),
            display_id,
            go_type,
            position: object.position(),
            rotation: gameobject.local_rotation_like_cpp(),
            anim_progress: gameobject.go_anim_progress_like_cpp(),
            state: data.state,
            art_kit: data.art_kit,
            created_by: data.created_by,
            faction_template: data.faction_template,
            gameobject_flags: data.flags,
            world_effect_id: 0,
            scale: object.object().scale(),
            level: 0, // non-transport GameObject: Level unused (period via AnimationData)
            // Canonical GameObject entity does not yet carry per-spawn ParentRotation;
            // identity until the entity stores it (#NEXT.R8.ENTITIES.1216 follow-up).
            parent_rotation: [0.0, 0.0, 0.0, 1.0],
        })
    }

    fn dynamic_object_create_data_from_canonical_like_cpp(
        guid: ObjectGuid,
        dynamic_object: &wow_entities::DynamicObject,
    ) -> wow_packet::packets::update::DynamicObjectCreateData {
        let object = dynamic_object.world();
        let object_data = object.object().object_data_values();
        let data = dynamic_object.data();
        wow_packet::packets::update::DynamicObjectCreateData {
            guid,
            entry_id: u32::try_from(object_data.entry_id).unwrap_or(0),
            dynamic_flags: object_data.dynamic_flags,
            scale: object_data.scale,
            position: object.position(),
            caster: data.caster,
            dynamic_object_type: data.dynamic_object_type,
            spell_visual_id: data.spell_visual_id,
            spell_id: data.spell_id,
            radius: data.radius,
            cast_time_ms: data.cast_time_ms,
        }
    }

    pub(crate) fn visible_dynamic_objects_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::DynamicObjectCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby = map.map().nearby_cell_guids_like_cpp(
            position.x,
            position.y,
            visibility_radius + source_combat_reach,
        );
        let mut dynamic_objects = Vec::new();

        for guid in nearby
            .world
            .dynamic_objects
            .into_iter()
            .chain(nearby.grid.dynamic_objects)
        {
            let Some(dynamic_object) = map.map().get_typed_dynamic_object(guid) else {
                continue;
            };
            let object = dynamic_object.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !Self::visibility_distance_allows_like_cpp(
                    position,
                    source_combat_reach,
                    &object.position(),
                    object.combat_reach(),
                    visibility_radius,
                )
            {
                continue;
            }
            dynamic_objects.push(Self::dynamic_object_create_data_from_canonical_like_cpp(
                guid,
                dynamic_object,
            ));
        }

        Some(dynamic_objects)
    }

    pub(crate) fn visible_area_triggers_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::AreaTriggerCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby = map.map().nearby_cell_guids_like_cpp(
            position.x,
            position.y,
            visibility_radius + source_combat_reach,
        );
        let mut area_triggers = Vec::new();

        for guid in nearby.grid.area_triggers {
            let Some(area_trigger) = map
                .map()
                .map_object_record(guid)
                .and_then(wow_entities::MapObjectRecord::area_trigger)
            else {
                continue;
            };
            let object = area_trigger.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !Self::visibility_distance_allows_like_cpp(
                    position,
                    source_combat_reach,
                    &object.position(),
                    object.combat_reach(),
                    visibility_radius,
                )
                || !self.can_see_phase_shift_like_cpp(object.phase_shift())
            {
                continue;
            }
            if area_trigger.is_server_side() || area_trigger.is_removed() {
                continue;
            }
            area_triggers.push(
                crate::entity_update_bridge::area_trigger_create_data_from_entity_like_cpp(
                    area_trigger,
                ),
            );
        }

        Some(area_triggers)
    }

    pub(crate) fn visible_misc_objects_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<(
        Vec<wow_packet::packets::update::CorpseCreateData>,
        Vec<wow_packet::packets::update::SceneObjectCreateData>,
        Vec<wow_packet::packets::update::ConversationCreateData>,
    )> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby = map.map().nearby_cell_guids_like_cpp(
            position.x,
            position.y,
            visibility_radius + source_combat_reach,
        );

        let allows_world_object = |world: &wow_entities::WorldObject| {
            world.object().is_in_world()
                && world.map_id() == requested_map_id
                && self.can_see_phase_shift_like_cpp(world.phase_shift())
                && Self::visibility_distance_allows_like_cpp(
                    position,
                    source_combat_reach,
                    &world.position(),
                    world.combat_reach(),
                    visibility_radius,
                )
        };

        let mut corpses = Vec::new();
        for guid in nearby.world.corpses.into_iter().chain(nearby.grid.corpses) {
            let Some(corpse) = map.map().get_typed_corpse(guid) else {
                continue;
            };
            if allows_world_object(corpse.world()) {
                corpses.push(
                    crate::entity_update_bridge::corpse_create_data_from_entity_like_cpp(corpse),
                );
            }
        }

        let mut scene_objects = Vec::new();
        for guid in nearby.grid.scene_objects {
            let Some(scene_object) = map
                .map()
                .map_object_record(guid)
                .and_then(wow_entities::MapObjectRecord::scene_object)
            else {
                continue;
            };
            if allows_world_object(scene_object.world()) {
                scene_objects.push(
                    crate::entity_update_bridge::scene_object_create_data_from_entity_like_cpp(
                        scene_object,
                    ),
                );
            }
        }

        let mut conversations = Vec::new();
        for guid in nearby.grid.conversations {
            let Some(conversation) = map
                .map()
                .map_object_record(guid)
                .and_then(wow_entities::MapObjectRecord::conversation)
            else {
                continue;
            };
            if !conversation.is_removed() && allows_world_object(conversation.world()) {
                conversations.push(
                    crate::entity_update_bridge::conversation_create_data_from_entity_like_cpp(
                        conversation,
                        &self.locale,
                    ),
                );
            }
        }

        Some((corpses, scene_objects, conversations))
    }

    pub(crate) fn visible_other_players_from_registry_like_cpp(
        &self,
        map_id: u16,
        position: &Position,
        visibility_radius: f32,
    ) -> Vec<(ObjectGuid, PlayerVisibilityCreateSnapshot)> {
        let Some(player_guid) = self.player_guid() else {
            return Vec::new();
        };
        let Some(registry) = &self.player_registry else {
            return Vec::new();
        };
        let instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let source_combat_reach = self.represented_visibility_source_combat_reach_like_cpp();

        registry
            .player_visibility_create_candidates(
                player_guid,
                map_id,
                instance_id,
                *position,
                source_combat_reach,
                visibility_radius,
            )
            .into_iter()
            .filter(|candidate| {
                self.canonical_player_phase_visible_like_cpp(map_id, instance_id, candidate.guid)
                    == Some(true)
            })
            .map(|candidate| (candidate.guid, candidate))
            .collect()
    }

    /// Require the target to exist in the canonical map and apply the same
    /// phase gate as C++ `VisibleNotifier::Visit(PlayerMapType&)`. Missing map
    /// state returns `None` and fails closed at the caller: C++ cannot visit a
    /// registry-only player.
    fn canonical_player_phase_visible_like_cpp(
        &self,
        map_id: u16,
        instance_id: u32,
        target_guid: ObjectGuid,
    ) -> Option<bool> {
        // Resolve the viewer before taking the map lock; the handle resolver
        // takes the same manager and must not recurse into that mutex.
        let player_phase_shift = self.represented_player_phase_shift_like_cpp()?;
        let manager = self.canonical_map_manager.as_ref()?;
        let manager = manager.lock().ok()?;
        let map = manager.find_map(u32::from(map_id), instance_id)?;
        let target = map.map().get_typed_player(target_guid)?;
        Some(player_phase_shift.can_see(target.unit().world().phase_shift()))
    }

    pub fn set_realm_id(&mut self, realm_id: u16) {
        self.realm_id = realm_id;
    }

    pub fn set_realm_handle_like_cpp(&mut self, region: u8, battlegroup: u8, realm_id: u16) {
        self.realm_region = region;
        self.realm_battlegroup = battlegroup;
        self.realm_id = realm_id;
    }

    pub fn set_realm_names_like_cpp(
        &mut self,
        names: impl IntoIterator<Item = (u32, String, String)>,
    ) {
        self.realm_names_like_cpp = names
            .into_iter()
            .map(|(address, actual, normalized)| (address, (actual, normalized)))
            .collect();
    }

    /// Compute the Virtual Realm Address: `(Region << 24) | (Battlegroup << 16) | RealmId`.
    ///
    /// Region and Battlegroup come from the active `realmlist` row, matching C++
    /// `Battlenet::RealmHandle{ realm.Id.Region, realm.Id.Site, realm.Id.Realm }.GetAddress()`.
    pub(crate) fn virtual_realm_address(&self) -> u32 {
        (u32::from(self.realm_region) << 24)
            | (u32::from(self.realm_battlegroup) << 16)
            | u32::from(self.realm_id)
    }

    pub(crate) fn realm_names_for_address_like_cpp(
        &self,
        realm_address: u32,
    ) -> Option<(&str, &str)> {
        self.realm_names_like_cpp
            .get(&realm_address)
            .map(|(actual, normalized)| (actual.as_str(), normalized.as_str()))
    }

