    pub(crate) fn account_toy_rows_like_cpp(&self) -> Vec<(u32, bool, bool)> {
        self.player_collection_state_snapshot_like_cpp()
            .map(|collections| {
                collections
                    .toys
                    .into_iter()
                    .map(|(item_id, flags)| {
                        (
                            item_id,
                            (flags & TOY_FLAG_FAVORITE_LIKE_CPP) != 0,
                            (flags & TOY_FLAG_HAS_FANFARE_LIKE_CPP) != 0,
                        )
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

