    /// Bounded C++ `SpellHistory::GetCooldownDurations(spellInfo, itemId)`.
    ///
    /// C++ lets `ItemEffect` override spell/category cooldowns for item-backed
    /// casts. Rust still lacks full `_categoryCooldowns`, so this represented
    /// helper returns the longest positive item cooldown as the single spell-id
    /// keyed duration used by the current `SpellHistory` seam.
    pub(crate) fn toy_item_spell_cooldown_ms_like_cpp(
        &self,
        item_id: u32,
        spell_id: i32,
        spell_info: &wow_data::SpellInfo,
    ) -> u32 {
        if let Some(effect) = self
            .item_effect_store
            .as_ref()
            .and_then(|store| store.effect_for_item_spell_like_cpp(item_id, spell_id))
        {
            if effect.cooldown_msec >= 0 || effect.category_cooldown_msec >= 0 {
                return effect
                    .cooldown_msec
                    .max(effect.category_cooldown_msec)
                    .max(0) as u32;
            }
        }

        spell_info.recovery_time_ms.max(spell_info.cooldown_ms)
    }

    /// Bounded C++ `SpellHistory::HasCooldown`.
    ///
    /// C++ primarily keys `_spellCooldowns` by spell id; item id influences the
    /// duration/category calculation. Category sharing is intentionally outside
    /// this represented slice.
    pub(crate) fn represented_spell_cooldown_remaining_ms_like_cpp(
        &self,
        spell_id: i32,
        cooldown_ms: u32,
    ) -> Option<u32> {
        if cooldown_ms == 0 {
            return None;
        }

        let last_cast = self.last_spell_cast_time_per_spell.get(&spell_id)?;
        let elapsed_ms = last_cast.elapsed().as_millis() as u32;
        (elapsed_ms < cooldown_ms).then_some(cooldown_ms - elapsed_ms)
    }

    fn player_spell_history_snapshot_like_cpp(&self) -> Option<wow_entities::SpellHistory> {
        let canonical = self
            .with_owned_player_like_cpp(|player| player.unit().subsystems().spells.history.clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            let mut history = wow_entities::SpellHistory {
                cooldowns_loaded: self.represented_character_spell_cooldowns_loaded_like_cpp,
                charges_loaded: self.represented_character_spell_charges_loaded_like_cpp,
                ..Default::default()
            };
            history.cooldowns = self
                .represented_character_spell_cooldowns_like_cpp
                .values()
                .map(|row| {
                    (
                        row.spell_id,
                        wow_entities::SpellCooldown {
                            spell_id: row.spell_id,
                            item_id: row.item_id,
                            cooldown_end_ms: u64::try_from(row.cooldown_end_unix_secs)
                                .unwrap_or(0)
                                .saturating_mul(1_000),
                            category_id: row.category_id,
                            category_end_ms: u64::try_from(row.category_end_unix_secs)
                                .unwrap_or(0)
                                .saturating_mul(1_000),
                            on_hold: false,
                        },
                    )
                })
                .collect();
            history.charges = self
                .represented_character_spell_charges_like_cpp
                .iter()
                .map(|(&category_id, rows)| {
                    (
                        category_id,
                        rows.iter()
                            .map(|row| wow_entities::SpellChargeState {
                                recharge_start_ms: u64::try_from(row.recharge_start_unix_secs)
                                    .unwrap_or(0)
                                    .saturating_mul(1_000),
                                recharge_end_ms: u64::try_from(row.recharge_end_unix_secs)
                                    .unwrap_or(0)
                                    .saturating_mul(1_000),
                            })
                            .collect(),
                    )
                })
                .collect();
            return Some(history);
        }
        canonical
    }

    fn replace_player_spell_history_like_cpp(
        &mut self,
        history: wow_entities::SpellHistory,
    ) -> bool {
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                player.unit_mut().subsystems_mut().spells.history = history.clone();
            })
            .is_some();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_character_spell_cooldowns_loaded_like_cpp = history.cooldowns_loaded;
            self.represented_character_spell_charges_loaded_like_cpp = history.charges_loaded;
            self.represented_character_spell_cooldowns_like_cpp = history
                .cooldowns
                .values()
                .map(|row| {
                    (
                        row.spell_id,
                        RepresentedCharacterSpellCooldownLikeCpp {
                            spell_id: row.spell_id,
                            item_id: row.item_id,
                            cooldown_end_unix_secs: (row.cooldown_end_ms / 1_000)
                                .min(i64::MAX as u64)
                                as i64,
                            category_id: row.category_id,
                            category_end_unix_secs: (row.category_end_ms / 1_000)
                                .min(i64::MAX as u64)
                                as i64,
                        },
                    )
                })
                .collect();
            self.represented_character_spell_charges_like_cpp = history
                .charges
                .iter()
                .map(|(&category_id, rows)| {
                    (
                        category_id,
                        rows.iter()
                            .map(|row| RepresentedCharacterSpellChargeLikeCpp {
                                category_id,
                                recharge_start_unix_secs: (row.recharge_start_ms / 1_000)
                                    .min(i64::MAX as u64)
                                    as i64,
                                recharge_end_unix_secs: (row.recharge_end_ms / 1_000)
                                    .min(i64::MAX as u64)
                                    as i64,
                            })
                            .collect(),
                    )
                })
                .collect();
            return true;
        }
        canonical
    }

    fn mutate_player_spell_history_like_cpp<R>(
        &mut self,
        f: impl FnOnce(&mut wow_entities::SpellHistory) -> R,
    ) -> Option<R> {
        let mut history = self.player_spell_history_snapshot_like_cpp()?;
        let result = f(&mut history);
        self.replace_player_spell_history_like_cpp(history)
            .then_some(result)
    }

    pub(crate) fn reset_represented_character_spell_cooldowns_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.cooldowns.clear();
            history.cooldowns_loaded = false;
        });
    }

    pub(crate) fn mark_represented_character_spell_cooldowns_loaded_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.cooldowns_loaded = true;
        });
    }

    pub(crate) fn record_loaded_character_spell_cooldown_like_cpp(
        &mut self,
        spell_id: u32,
        item_id: u32,
        cooldown_end_unix_secs: i64,
        category_id: u32,
        category_end_unix_secs: i64,
    ) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.cooldowns.insert(
                spell_id,
                wow_entities::SpellCooldown {
                    spell_id,
                    item_id,
                    cooldown_end_ms: u64::try_from(cooldown_end_unix_secs)
                        .unwrap_or(0)
                        .saturating_mul(1_000),
                    category_id,
                    category_end_ms: u64::try_from(category_end_unix_secs)
                        .unwrap_or(0)
                        .saturating_mul(1_000),
                    on_hold: false,
                },
            );
        });
    }

    fn record_cast_character_spell_cooldown_like_cpp(&mut self, spell_id: i32, cooldown_ms: u32) {
        if !self
            .player_spell_history_snapshot_like_cpp()
            .is_some_and(|history| history.cooldowns_loaded)
            || cooldown_ms == 0
        {
            return;
        }
        let Ok(spell_id) = u32::try_from(spell_id) else {
            return;
        };
        let cooldown_secs = i64::from(cooldown_ms.saturating_add(999) / 1_000);
        if cooldown_secs == 0 {
            return;
        }
        self.record_loaded_character_spell_cooldown_like_cpp(
            spell_id,
            0,
            unix_now().saturating_add(cooldown_secs),
            0,
            0,
        );
    }

    pub(crate) fn reset_represented_character_spell_charges_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.charges.clear();
            history.charges_loaded = false;
        });
    }

    pub(crate) fn mark_represented_character_spell_charges_loaded_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.charges_loaded = true;
        });
    }

    pub(crate) fn record_loaded_character_spell_charge_like_cpp(
        &mut self,
        category_id: u32,
        recharge_start_unix_secs: i64,
        recharge_end_unix_secs: i64,
    ) {
        let _ = self.mutate_player_spell_history_like_cpp(|history| {
            history.charges.entry(category_id).or_default().push_back(
                wow_entities::SpellChargeState {
                    recharge_start_ms: u64::try_from(recharge_start_unix_secs)
                        .unwrap_or(0)
                        .saturating_mul(1_000),
                    recharge_end_ms: u64::try_from(recharge_end_unix_secs)
                        .unwrap_or(0)
                        .saturating_mul(1_000),
                },
            );
        });
    }

    fn restore_represented_character_spell_charge_like_cpp(&mut self, category_id: u32) -> bool {
        self.mutate_player_spell_history_like_cpp(|history| {
            if !history.charges_loaded {
                return false;
            }
            let Some(charges) = history.charges.get_mut(&category_id) else {
                return false;
            };
            if charges.pop_back().is_none() {
                return false;
            }
            if charges.is_empty() {
                history.charges.remove(&category_id);
            }
            true
        })
        .unwrap_or(false)
    }

    /// C++ `CollectionMgr::AddToy` / `UpdateAccountToys`.
    pub(crate) fn add_account_toy_like_cpp(
        &mut self,
        item_id: u32,
        is_favorite: bool,
        has_fanfare: bool,
    ) -> bool {
        let mut flags = 0_u32;
        if is_favorite {
            flags |= TOY_FLAG_FAVORITE_LIKE_CPP;
        }
        if has_fanfare {
            flags |= TOY_FLAG_HAS_FANFARE_LIKE_CPP;
        }
        self.mutate_player_collection_state_like_cpp(|collections| {
            if collections.toys.contains_key(&item_id) {
                return false;
            }
            collections.toys.insert(item_id, flags);
            true
        })
        .unwrap_or(false)
    }

    pub(crate) fn remove_account_toy_like_cpp(&mut self, item_id: u32) -> bool {
        self.mutate_player_collection_state_like_cpp(|state| state.toys.remove(&item_id).is_some())
            .unwrap_or(false)
    }

    /// C++ `Player::AddToy`, called from `CollectionMgr::AddToy` after the
    /// account collection accepts a new toy.
    pub(crate) fn add_player_toy_dynamic_field_like_cpp(
        &mut self,
        item_id: u32,
    ) -> Option<wow_entities::PlayerValuesUpdate> {
        let item_id = i32::try_from(item_id).ok()?;
        self.mutate_canonical_player_like_cpp(|player| {
            player.add_toy_like_cpp(item_id);
            player.values_update(true)
        })
    }

    /// C++ `CollectionMgr::ToyClearFanfare`.
    pub(crate) fn toy_clear_fanfare_like_cpp(&mut self, item_id: u32) -> bool {
        self.mutate_player_collection_state_like_cpp(|collections| {
            let Some(flags) = collections.toys.get_mut(&item_id) else {
                return false;
            };
            *flags &= !TOY_FLAG_HAS_FANFARE_LIKE_CPP;
            true
        })
        .unwrap_or(false)
    }

    /// C++ `CollectionMgr::ToySetFavorite`.
    pub(crate) fn toy_set_favorite_like_cpp(&mut self, item_id: u32, favorite: bool) -> bool {
        self.mutate_player_collection_state_like_cpp(|collections| {
            let Some(flags) = collections.toys.get_mut(&item_id) else {
                return false;
            };
            if favorite {
                *flags |= TOY_FLAG_FAVORITE_LIKE_CPP;
            } else {
                *flags &= !TOY_FLAG_FAVORITE_LIKE_CPP;
            }
            true
        })
        .unwrap_or(false)
    }

    /// C++ `CollectionMgr::LoadAccountItemAppearances`.
    pub(crate) fn load_represented_account_item_appearances_like_cpp(
        &mut self,
        known_appearance_blocks: impl IntoIterator<Item = (u32, u32)>,
        favorite_appearances: impl IntoIterator<Item = u32>,
    ) {
        let mut blocks = BTreeMap::new();
        for (block_index, appearance_mask) in known_appearance_blocks {
            if appearance_mask != 0 {
                blocks.insert(block_index, appearance_mask);
            }
        }

        let mut item_appearances = HashSet::new();
        for (&block_index, &appearance_mask) in &blocks {
            for bit_index in 0..32 {
                if (appearance_mask & (1_u32 << bit_index)) != 0 {
                    item_appearances.insert(block_index * 32 + bit_index);
                }
            }
        }

        let mut item_appearance_blocks = Vec::new();
        if let Some((&highest_block, _)) = blocks.iter().next_back() {
            item_appearance_blocks = vec![0; highest_block as usize + 1];
            for (&block_index, &appearance_mask) in &blocks {
                item_appearance_blocks[block_index as usize] = appearance_mask;
            }

            self.mutate_canonical_player_like_cpp(|player| {
                while player.transmog_blocks_like_cpp().len() <= highest_block as usize {
                    player.add_transmog_block_like_cpp(0);
                }

                for (&block_index, &appearance_mask) in &blocks {
                    if appearance_mask != 0 {
                        player.add_transmog_flag_like_cpp(block_index as usize, appearance_mask);
                    }
                }
            });
        }

        let favorite_item_appearances = favorite_appearances
            .into_iter()
            .map(|appearance| (appearance, FavoriteAppearanceStateLikeCpp::Unchanged))
            .collect();
        let _ = self.mutate_player_collection_state_like_cpp(|collections| {
            collections.item_appearances = item_appearances;
            collections.item_appearance_blocks = item_appearance_blocks;
            collections.favorite_item_appearances = favorite_item_appearances;
        });
    }

    /// C++ `CollectionMgr::SaveAccountItemAppearances`.
    pub(crate) fn account_item_appearance_save_plan_like_cpp(
        &mut self,
    ) -> Option<AccountItemAppearanceSavePlanLikeCpp> {
        let mut collections = self.player_collection_state_snapshot_like_cpp()?;
        let mut blocks = BTreeMap::<u32, u32>::new();
        for &item_modified_appearance_id in &collections.item_appearances {
            let block_index = item_modified_appearance_id / 32;
            let bit_index = item_modified_appearance_id % 32;
            if let Some(flag) = 1_u32.checked_shl(bit_index) {
                *blocks.entry(block_index).or_default() |= flag;
            }
        }

        let mut favorite_inserts = Vec::new();
        let mut favorite_deletes = Vec::new();
        let favorite_states = collections
            .favorite_item_appearances
            .iter()
            .map(|(&appearance, &state)| (appearance, state))
            .collect::<BTreeMap<_, _>>();
        for (item_modified_appearance_id, state) in favorite_states {
            match state {
                FavoriteAppearanceStateLikeCpp::New => {
                    favorite_inserts.push(item_modified_appearance_id);
                    collections.favorite_item_appearances.insert(
                        item_modified_appearance_id,
                        FavoriteAppearanceStateLikeCpp::Unchanged,
                    );
                }
                FavoriteAppearanceStateLikeCpp::Removed => {
                    favorite_deletes.push(item_modified_appearance_id);
                    collections
                        .favorite_item_appearances
                        .remove(&item_modified_appearance_id);
                }
                FavoriteAppearanceStateLikeCpp::Unchanged => {}
            }
        }

        let plan = AccountItemAppearanceSavePlanLikeCpp {
            appearance_blocks: blocks
                .into_iter()
                .filter(|(_, appearance_mask)| *appearance_mask != 0)
                .collect(),
            favorite_inserts,
            favorite_deletes,
        };
        let _ = self.replace_player_collection_state_like_cpp(collections);
        Some(plan)
    }

    /// C++ `CollectionMgr::SetAppearanceIsFavorite`.
    pub fn set_appearance_is_favorite_like_cpp(
        &mut self,
        item_modified_appearance_id: u32,
        apply: bool,
    ) -> bool {
        use FavoriteAppearanceStateLikeCpp::{New, Removed, Unchanged};
        use std::collections::hash_map::Entry;

        let changed = self
            .mutate_player_collection_state_like_cpp(|collections| {
                if apply {
                    match collections
                        .favorite_item_appearances
                        .entry(item_modified_appearance_id)
                    {
                        Entry::Vacant(entry) => {
                            entry.insert(New);
                            true
                        }
                        Entry::Occupied(mut entry) if *entry.get() == Removed => {
                            entry.insert(Unchanged);
                            true
                        }
                        Entry::Occupied(_) => false,
                    }
                } else {
                    match collections
                        .favorite_item_appearances
                        .entry(item_modified_appearance_id)
                    {
                        Entry::Occupied(entry) if *entry.get() == New => {
                            entry.remove();
                            true
                        }
                        Entry::Occupied(mut entry) => {
                            entry.insert(Removed);
                            true
                        }
                        Entry::Vacant(_) => false,
                    }
                }
            })
            .unwrap_or(false);

        if changed {
            if !Self::account_transmog_update_opcode_resolved_like_cpp() {
                warn!(
                    "Skipping AccountTransmogUpdate favorite delta: legacy C++ opcode is unresolved 0xBADD for 54261"
                );
                return changed;
            }

            self.send_packet(
                &wow_packet::packets::collection::AccountTransmogUpdate::favorite_delta(
                    item_modified_appearance_id,
                    apply,
                ),
            );
        }

        changed
    }

    fn account_transmog_update_opcode_resolved_like_cpp() -> bool {
        // The inspected 3.4.3 legacy C++ tree still declares
        // SMSG_ACCOUNT_TRANSMOG_UPDATE as NULL_OPCODE/0xBADD. Sending it during
        // login can make the client close the connection after the initial burst.
        <wow_packet::packets::collection::AccountTransmogUpdate as wow_packet::ServerPacket>::OPCODE
            != ServerOpcodes::UpdateCapturePoint
    }

    /// C++ `CollectionMgr::SendFavoriteAppearances`.
    pub fn send_favorite_appearances_like_cpp(&self) {
        if !Self::account_transmog_update_opcode_resolved_like_cpp() {
            warn!(
                "Skipping AccountTransmogUpdate full update: legacy C++ opcode is unresolved 0xBADD for 54261"
            );
            return;
        }

        let Some(collections) = self.player_collection_state_snapshot_like_cpp() else {
            return;
        };
        let favorite_appearances = collections
            .favorite_item_appearances
            .into_iter()
            .filter_map(|(appearance, state)| {
                (state != FavoriteAppearanceStateLikeCpp::Removed).then_some(appearance)
            })
            .collect::<Vec<_>>();

        self.send_packet(&wow_packet::packets::collection::AccountTransmogUpdate {
            is_full_update: true,
            is_set_favorite: false,
            favorite_appearances,
            new_appearances: Vec::new(),
        });
    }

    /// C++ `CollectionMgr::LoadAccountTransmogIllusions`.
    pub(crate) fn load_represented_account_transmog_illusions_like_cpp(
        &mut self,
        known_illusion_blocks: impl IntoIterator<Item = (u32, u32)>,
    ) {
        let mut illusions = HashSet::new();
        for (block_index, illusion_mask) in known_illusion_blocks {
            for bit_index in 0..32 {
                if (illusion_mask & (1_u32 << bit_index)) != 0 {
                    illusions.insert(block_index * 32 + bit_index);
                }
            }
        }

        for illusion_id in DEFAULT_TRANSMOG_ILLUSIONS_LIKE_CPP {
            illusions.insert(illusion_id);
        }
        let _ = self.mutate_player_collection_state_like_cpp(|collections| {
            collections.transmog_illusions = illusions;
        });
    }

    /// C++ `CollectionMgr::HasTransmogIllusion`.
    #[allow(dead_code)]
    pub(crate) fn has_transmog_illusion_like_cpp(&self, transmog_illusion_id: u32) -> bool {
        self.player_collection_state_snapshot_like_cpp()
            .is_some_and(|collections| {
                collections
                    .transmog_illusions
                    .contains(&transmog_illusion_id)
            })
    }

    /// C++ `CollectionMgr::SaveAccountTransmogIllusions`.
    pub(crate) fn account_transmog_illusion_save_plan_like_cpp(
        &self,
    ) -> Option<AccountTransmogIllusionSavePlanLikeCpp> {
        let mut blocks = BTreeMap::<u32, u32>::new();
        let collections = self.player_collection_state_snapshot_like_cpp()?;
        for &illusion_id in &collections.transmog_illusions {
            let block_index = illusion_id / 32;
            let bit_index = illusion_id % 32;
            if let Some(flag) = 1_u32.checked_shl(bit_index) {
                *blocks.entry(block_index).or_default() |= flag;
            }
        }

        Some(AccountTransmogIllusionSavePlanLikeCpp {
            illusion_blocks: blocks
                .into_iter()
                .filter(|(_, illusion_mask)| *illusion_mask != 0)
                .collect(),
        })
    }

