    pub fn set_item_set_store(&mut self, store: Arc<ItemSetStore>) {
        self.item_set_store = Some(store);
    }

    pub fn set_item_set_spell_store(&mut self, store: Arc<ItemSetSpellStore>) {
        self.item_set_spell_store = Some(store);
    }

    pub(crate) fn item_set_for_item_id_like_cpp(
        &self,
        item_id: u32,
    ) -> Option<&wow_data::ItemSetEntry> {
        self.item_set_store
            .as_ref()
            .and_then(|store| store.item_set_for_item_id_like_cpp(item_id))
    }

    pub(crate) fn item_set_spells_like_cpp(
        &self,
        item_set_id: u32,
    ) -> Vec<&wow_data::ItemSetSpellEntry> {
        self.item_set_spell_store
            .as_ref()
            .map(|store| store.item_set_spells_like_cpp(item_set_id))
            .unwrap_or_default()
    }

    pub fn set_item_stats_store(&mut self, store: Arc<ItemStatsStore>) {
        self.item_stats_store = Some(store);
    }

    fn player_item_modifier_runtime_snapshot_like_cpp(
        &self,
    ) -> Option<wow_entities::PlayerItemModifierRuntimeStateLikeCpp> {
        let canonical = self
            .with_owned_player_like_cpp(|player| player.gameplay_state().item_modifiers.clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(wow_entities::PlayerItemModifierRuntimeStateLikeCpp {
                bonuses: self.represented_item_bonus_state_like_cpp.clone(),
                item_set_effects: self.represented_item_set_effects_like_cpp.clone(),
                item_level_caps: self.represented_item_level_caps_like_cpp,
            });
        }
        canonical
    }

    fn mutate_player_item_modifier_runtime_like_cpp<R>(
        &mut self,
        mutate: impl FnOnce(&mut wow_entities::PlayerItemModifierRuntimeStateLikeCpp) -> R,
    ) -> Option<R> {
        let mut mutate = Some(mutate);
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            let mut state = self.player_item_modifier_runtime_snapshot_like_cpp()?;
            let result =
                mutate
                    .take()
                    .expect("test item-modifier mutation executes once")(&mut state);
            self.represented_item_bonus_state_like_cpp = state.bonuses;
            self.represented_item_set_effects_like_cpp = state.item_set_effects;
            self.represented_item_level_caps_like_cpp = state.item_level_caps;
            return Some(result);
        }
        self.with_owned_player_mut_like_cpp(|player| {
            mutate
                .take()
                .expect("Player item-modifier mutation executes once")(
                &mut player.gameplay_state_mut().item_modifiers,
            )
        })
    }

    pub(crate) fn set_represented_item_level_caps_like_cpp(
        &mut self,
        caps: RepresentedItemLevelCapsLikeCpp,
    ) -> bool {
        self.mutate_player_item_modifier_runtime_like_cpp(|state| state.item_level_caps = caps)
            .is_some()
    }

    pub(crate) fn set_represented_using_pvp_item_levels_like_cpp(&mut self, active: bool) -> bool {
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                player.gameplay_state_mut().using_pvp_item_levels = active
            })
            .is_some();
        if canonical {
            return true;
        }
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_using_pvp_item_levels_like_cpp = active;
            return true;
        }
        false
    }

    fn resolved_using_pvp_item_levels_like_cpp(&self) -> Option<bool> {
        let canonical =
            self.with_owned_player_like_cpp(|player| player.gameplay_state().using_pvp_item_levels);
        if canonical.is_some() {
            return canonical;
        }
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            return Some(self.represented_using_pvp_item_levels_like_cpp);
        }
        None
    }

    #[cfg(test)]
    pub(crate) fn represented_using_pvp_item_levels_like_cpp(&self) -> bool {
        self.resolved_using_pvp_item_levels_like_cpp()
            .expect("test Player PvP item-level owner must resolve")
    }

    fn represented_has_pvp_rules_enabled_like_cpp(&self) -> bool {
        self.player_has_visible_aura_spell_like_cpp(SPELL_PVP_RULES_ENABLED_LIKE_CPP)
            .unwrap_or(false)
    }

    pub(crate) fn update_represented_item_level_area_based_scaling_like_cpp(&mut self) -> bool {
        let map_pvp_activity = self
            .map_store()
            .and_then(|store| store.get(u32::from(self.player_map_id_like_cpp())))
            .is_some_and(|entry| {
                entry.is_battleground_or_arena() || entry.activates_pvp_item_levels_like_cpp()
            });
        let pvp_activity = map_pvp_activity || self.represented_has_pvp_rules_enabled_like_cpp();
        let Some(using_pvp_item_levels) = self.resolved_using_pvp_item_levels_like_cpp() else {
            return false;
        };
        if using_pvp_item_levels == pvp_activity {
            return false;
        }

        let Some((health_before, max_health_before, _)) = self.resolved_player_vitals_like_cpp()
        else {
            return false;
        };
        let Some(item_mod_targets) = self.represented_top_level_item_mod_targets_like_cpp() else {
            return false;
        };
        self.record_represented_all_item_mods_like_cpp(&item_mod_targets, false);
        if !self.set_represented_using_pvp_item_levels_like_cpp(pvp_activity) {
            return false;
        }
        self.record_represented_all_item_mods_like_cpp(&item_mod_targets, true);
        self.restore_represented_health_pct_after_item_mod_scaling_like_cpp(
            health_before,
            max_health_before,
        );
        if !item_mod_targets.is_empty() {
            self.send_represented_item_bonus_player_stat_update_like_cpp();
        }
        true
    }

    fn represented_top_level_item_mod_targets_like_cpp(&self) -> Option<Vec<(u8, ObjectGuid)>> {
        let mut targets = self
            .resolved_inventory_item_objects_like_cpp()?
            .values()
            .filter(|item| {
                item.container_guid().is_empty()
                    && item.slot() < INVENTORY_SLOT_BAG_END
                    && !item.is_broken()
            })
            .map(|item| (item.slot(), item.object().guid()))
            .collect::<Vec<_>>();
        targets.sort_by_key(|(slot, guid)| (*slot, guid.counter()));
        Some(targets)
    }

    fn record_represented_all_item_mods_like_cpp(
        &mut self,
        targets: &[(u8, ObjectGuid)],
        apply: bool,
    ) {
        for (slot, item_guid) in targets {
            self.record_represented_item_mods_like_cpp(*item_guid, *slot, apply);
        }
    }

    fn record_represented_item_mods_like_cpp(
        &mut self,
        item_guid: ObjectGuid,
        slot: u8,
        apply: bool,
    ) -> usize {
        #[cfg(test)]
        {
            self.represented_item_mod_reapply_events_like_cpp.push(
                RepresentedItemModsReapplyEventLikeCpp {
                    item_guid,
                    slot,
                    apply,
                },
            );
        }

        let Some(item_entry) = self
            .resolved_inventory_item_object_like_cpp(item_guid)
            .map(|item| item.object().entry())
        else {
            return 0;
        };
        let Some(item_stats_store) = self.item_stats_store.as_ref().cloned() else {
            return 0;
        };
        let mut planned_actions = Vec::new();

        let scaling_context = self.represented_scaling_stat_context_like_cpp(item_entry);
        if let Some(context) = scaling_context {
            planned_actions.extend(
                item_scaling_stat_bonus_actions_like_cpp(
                    &context.stat_id,
                    &context.bonus,
                    context.ssd_multiplier,
                    apply,
                )
                .into_iter()
                .map(|action| RepresentedItemBonusActionLikeCpp {
                    item_guid,
                    slot,
                    action,
                }),
            );
            if context.spell_bonus > 0 {
                planned_actions.push(RepresentedItemBonusActionLikeCpp {
                    item_guid,
                    slot,
                    action: ApplyEnchantmentEffectAction::SpellPowerBonus {
                        amount: context.spell_bonus as u32,
                        apply,
                    },
                });
            } else if context.spell_bonus < 0 {
                planned_actions.push(RepresentedItemBonusActionLikeCpp {
                    item_guid,
                    slot,
                    action: ApplyEnchantmentEffectAction::UnhandledStatModifier {
                        item_mod: wow_constants::ItemModType::SpellPower,
                        amount: context.spell_bonus.unsigned_abs(),
                        apply,
                    },
                });
            }
        } else if let Some(stat_entry) = item_stats_store.get(item_entry) {
            planned_actions.extend(
                item_stat_bonus_actions_like_cpp(&stat_entry.stats, apply)
                    .into_iter()
                    .map(|action| RepresentedItemBonusActionLikeCpp {
                        item_guid,
                        slot,
                        action,
                    }),
            );
        }

        if let Some(stat_entry) = item_stats_store.get(item_entry) {
            let resistances = self.represented_resistances_with_scaling_armor_like_cpp(
                &stat_entry.resistances,
                scaling_context,
            );
            planned_actions.extend(
                item_resistance_bonus_actions_like_cpp(&resistances, apply)
                    .into_iter()
                    .map(|action| RepresentedItemBonusActionLikeCpp {
                        item_guid,
                        slot,
                        action,
                    }),
            );
        }

        if let Some(action) =
            self.item_shield_block_value_like_cpp(item_entry)
                .and_then(|shield_block_value| {
                    item_shield_block_bonus_action_like_cpp(shield_block_value, true, apply)
                })
        {
            planned_actions.push(RepresentedItemBonusActionLikeCpp {
                item_guid,
                slot,
                action,
            });
        }

        if let (Some(weapon), Some(inventory_type)) = (
            item_stats_store.weapon_template(item_entry),
            self.represented_item_inventory_type_like_cpp(item_entry, item_guid),
        ) {
            let (min_damage, max_damage) =
                self.represented_weapon_damage_bounds_like_cpp(item_entry, weapon);
            planned_actions.extend(
                item_weapon_damage_actions_like_cpp(
                    slot,
                    inventory_type,
                    min_damage,
                    max_damage,
                    weapon.item_delay,
                    apply,
                    false,
                    true,
                    false,
                    true,
                )
                .into_iter()
                .map(|action| RepresentedItemBonusActionLikeCpp {
                    item_guid,
                    slot,
                    action,
                }),
            );
        }

        #[cfg(test)]
        self.represented_item_bonus_actions_like_cpp
            .extend(planned_actions.iter().cloned());
        let action_count = planned_actions.len();
        for planned in planned_actions {
            self.apply_represented_item_bonus_action_state_like_cpp(planned.action);
        }
        action_count
    }

    pub(crate) fn record_destroyed_inventory_item_mod_remove_like_cpp(
        &mut self,
        bag: u8,
        slot: u8,
        item_guid: ObjectGuid,
    ) -> bool {
        if bag != INVENTORY_SLOT_BAG_0 || slot >= INVENTORY_SLOT_BAG_END {
            return false;
        }
        if self
            .resolved_inventory_item_object_like_cpp(item_guid)
            .is_some_and(|item| item.is_broken())
        {
            return false;
        }

        self.record_represented_item_mods_like_cpp(item_guid, slot, false) != 0
    }

    pub(crate) fn record_direct_inventory_item_set_remove_like_cpp(
        &mut self,
        bag: u8,
        slot: u8,
        item_guid: ObjectGuid,
    ) -> bool {
        if bag != INVENTORY_SLOT_BAG_0 || slot >= INVENTORY_SLOT_BAG_END {
            return false;
        }

        self.record_represented_items_set_item_like_cpp(item_guid, false)
    }

    pub(crate) fn record_represented_items_set_item_like_cpp(
        &mut self,
        item_guid: ObjectGuid,
        apply: bool,
    ) -> bool {
        !self
            .record_represented_items_set_item_events_like_cpp(item_guid, apply)
            .is_empty()
    }

    fn record_represented_items_set_item_events_like_cpp(
        &mut self,
        item_guid: ObjectGuid,
        apply: bool,
    ) -> Vec<RepresentedItemSetSpellEventLikeCpp> {
        let Some(item_entry) = self
            .resolved_inventory_item_object_like_cpp(item_guid)
            .map(|item| item.object().entry())
        else {
            return Vec::new();
        };
        let Some(item_set) = self.item_set_for_item_id_like_cpp(item_entry).cloned() else {
            return Vec::new();
        };

        let events = if apply {
            self.record_represented_add_items_set_item_like_cpp(item_guid, &item_set)
        } else {
            self.record_represented_remove_items_set_item_like_cpp(item_guid, &item_set)
        };
        #[cfg(test)]
        self.represented_item_set_spell_events_like_cpp
            .extend(events.iter().copied());
        events
    }

    fn record_represented_add_items_set_item_like_cpp(
        &mut self,
        item_guid: ObjectGuid,
        item_set: &wow_data::ItemSetEntry,
    ) -> Vec<RepresentedItemSetSpellEventLikeCpp> {
        if item_set.required_skill != 0 {
            let Some(skill_value) =
                self.resolved_player_skill_value_like_cpp(item_set.required_skill as u16)
            else {
                return Vec::new();
            };
            if skill_value < item_set.required_skill_rank {
                return Vec::new();
            }
        }
        if item_set.set_flags & ITEM_SET_FLAG_LEGACY_INACTIVE_LIKE_CPP != 0 {
            return Vec::new();
        }
        if self.represented_heirloom_item_set_bonus_over_level_cap_like_cpp(item_guid) {
            return Vec::new();
        }

        let mut events = Vec::new();
        let Some(equipped_count_after) =
            self.mutate_player_item_modifier_runtime_like_cpp(|state| {
                let effect = state
                    .item_set_effects
                    .entry(item_set.id)
                    .or_insert_with(|| RepresentedItemSetEffectLikeCpp {
                        item_set_id: item_set.id,
                        ..Default::default()
                    });
                effect.equipped_items.insert(item_guid);
                effect.equipped_items.len()
            })
        else {
            return Vec::new();
        };

        let primary_spec = self.represented_primary_specialization_id_like_cpp();
        let spells: Vec<_> = self
            .item_set_spells_like_cpp(item_set.id)
            .into_iter()
            .cloned()
            .collect();
        for item_set_spell in spells {
            if usize::from(item_set_spell.threshold) > equipped_count_after {
                continue;
            }
            if !self.represented_item_set_spell_exists_like_cpp(item_set_spell.spell_id) {
                continue;
            }
            let inserted = self
                .mutate_player_item_modifier_runtime_like_cpp(|state| {
                    state
                        .item_set_effects
                        .get_mut(&item_set.id)
                        .is_some_and(|effect| effect.set_bonuses.insert(item_set_spell.id))
                })
                .unwrap_or(false);
            if !inserted {
                continue;
            }
            if item_set_spell.chr_spec_id != 0
                && Some(u32::from(item_set_spell.chr_spec_id)) != primary_spec
            {
                continue;
            }
            events.push(RepresentedItemSetSpellEventLikeCpp {
                item_set_id: item_set.id,
                spell_entry_id: item_set_spell.id,
                spell_id: item_set_spell.spell_id,
                threshold: item_set_spell.threshold,
                apply: true,
            });
        }

        events
    }

    fn represented_item_set_spell_exists_like_cpp(&self, spell_id: u32) -> bool {
        let Ok(spell_id) = i32::try_from(spell_id) else {
            return false;
        };
        self.spell_store
            .as_ref()
            .is_none_or(|store| store.get(spell_id).is_some())
    }

    fn represented_heirloom_item_set_bonus_over_level_cap_like_cpp(
        &self,
        item_guid: ObjectGuid,
    ) -> bool {
        let Some(item_entry) = self
            .resolved_inventory_item_object_like_cpp(item_guid)
            .map(|item| item.object().entry())
        else {
            return false;
        };
        if !self
            .heirloom_store
            .as_ref()
            .is_some_and(|store| store.get_by_item_id_like_cpp(item_entry).is_some())
        {
            return false;
        }

        let Some(template) = self
            .item_stats_store
            .as_ref()
            .and_then(|store| store.sparse_template(item_entry))
        else {
            return false;
        };
        let curve_id = template.player_level_to_item_level_curve_id_like_cpp();
        if curve_id == 0 {
            return false;
        }

        let Some((curve_store, curve_point_store)) = self
            .curve_store
            .as_ref()
            .zip(self.curve_point_store.as_ref())
        else {
            return false;
        };
        let Some((_min_level, max_level)) =
            curve_store.curve_x_axis_range_like_cpp(curve_point_store, curve_id)
        else {
            return false;
        };
        if !max_level.is_finite() || max_level < 0.0 {
            return false;
        }
        let mut max_level = max_level as u32;

        if let Some(content_tuning) = self.content_tuning_store.as_ref().and_then(|store| {
            store
                .content_tuning_data_like_cpp(template.scaling_stat_content_tuning_like_cpp(), true)
        }) {
            max_level = max_level.min(u32::try_from(content_tuning.max_level).unwrap_or(0));
        }

        u32::from(self.player_level_like_cpp()) > max_level
    }

    fn represented_equip_spell_fits_shapeshift_like_cpp(&self, spell_id: u32) -> bool {
        let Some(spell_store) = self.spell_store.as_ref() else {
            return true;
        };
        let Ok(spell_id) = i32::try_from(spell_id) else {
            return false;
        };

        let Some(form_id) = self.represented_shapeshift_form_like_cpp() else {
            return false;
        };
        spell_store
            .check_shapeshift_like_cpp(spell_id, form_id, |form| {
                self.spell_shapeshift_form_store
                    .as_ref()
                    .and_then(|store| store.get(form))
            })
            .unwrap_or(SpellCastResult::Success)
            == SpellCastResult::Success
    }

    fn record_represented_remove_items_set_item_like_cpp(
        &mut self,
        item_guid: ObjectGuid,
        item_set: &wow_data::ItemSetEntry,
    ) -> Vec<RepresentedItemSetSpellEventLikeCpp> {
        let Some(equipped_count_after) = self
            .mutate_player_item_modifier_runtime_like_cpp(|state| {
                let effect = state.item_set_effects.get_mut(&item_set.id)?;
                effect.equipped_items.remove(&item_guid);
                Some(effect.equipped_items.len())
            })
            .flatten()
        else {
            return Vec::new();
        };
        let mut events = Vec::new();

        let spells: Vec<_> = self
            .item_set_spells_like_cpp(item_set.id)
            .into_iter()
            .cloned()
            .collect();
        for item_set_spell in spells {
            if usize::from(item_set_spell.threshold) <= equipped_count_after {
                continue;
            }
            let removed = self
                .mutate_player_item_modifier_runtime_like_cpp(|state| {
                    state
                        .item_set_effects
                        .get_mut(&item_set.id)
                        .is_some_and(|effect| effect.set_bonuses.remove(&item_set_spell.id))
                })
                .unwrap_or(false);
            if !removed {
                continue;
            }
            events.push(RepresentedItemSetSpellEventLikeCpp {
                item_set_id: item_set.id,
                spell_entry_id: item_set_spell.id,
                spell_id: item_set_spell.spell_id,
                threshold: item_set_spell.threshold,
                apply: false,
            });
        }

        let _ = self.mutate_player_item_modifier_runtime_like_cpp(|state| {
            if state
                .item_set_effects
                .get(&item_set.id)
                .is_some_and(|effect| effect.equipped_items.is_empty())
            {
                state.item_set_effects.remove(&item_set.id);
            }
        });

        events
    }

    pub(crate) fn record_represented_update_item_set_auras_like_cpp(
        &mut self,
        form_change: bool,
    ) -> usize {
        let events = self.plan_represented_update_item_set_auras_like_cpp(form_change);
        #[cfg(test)]
        self.represented_item_set_aura_refresh_events_like_cpp
            .extend(events.iter().cloned());
        events.len()
    }

    fn plan_represented_update_item_set_auras_like_cpp(
        &self,
        form_change: bool,
    ) -> Vec<RepresentedItemSetAuraRefreshEventLikeCpp> {
        let mut events = Vec::new();
        let primary_spec = self.represented_primary_specialization_id_like_cpp();
        let Some(active_effects) = self
            .player_item_modifier_runtime_snapshot_like_cpp()
            .map(|state| state.item_set_effects.values().cloned().collect::<Vec<_>>())
        else {
            return events;
        };

        for effect in active_effects {
            let active_bonus_ids = effect.set_bonuses.clone();
            let spells: Vec<_> = self
                .item_set_spells_like_cpp(effect.item_set_id)
                .into_iter()
                .filter(|spell| active_bonus_ids.contains(&spell.id))
                .cloned()
                .collect();

            for item_set_spell in spells {
                if item_set_spell.chr_spec_id != 0
                    && Some(u32::from(item_set_spell.chr_spec_id)) != primary_spec
                {
                    events.push(RepresentedItemSetAuraRefreshEventLikeCpp {
                        item_set_id: effect.item_set_id,
                        spell_entry_id: item_set_spell.id,
                        spell_id: item_set_spell.spell_id,
                        apply: false,
                        form_change: false,
                    });
                    continue;
                }

                let fits_shapeshift =
                    self.represented_equip_spell_fits_shapeshift_like_cpp(item_set_spell.spell_id);
                if !form_change || !fits_shapeshift {
                    events.push(RepresentedItemSetAuraRefreshEventLikeCpp {
                        item_set_id: effect.item_set_id,
                        spell_entry_id: item_set_spell.id,
                        spell_id: item_set_spell.spell_id,
                        apply: false,
                        form_change,
                    });
                }
                if fits_shapeshift {
                    events.push(RepresentedItemSetAuraRefreshEventLikeCpp {
                        item_set_id: effect.item_set_id,
                        spell_entry_id: item_set_spell.id,
                        spell_id: item_set_spell.spell_id,
                        apply: true,
                        form_change,
                    });
                }
            }
        }

        events
    }

    pub(crate) fn apply_initial_equipped_item_equip_auras_like_cpp(&mut self) -> Option<usize> {
        let mut equipped: Vec<_> = self
            .resolved_inventory_item_objects_like_cpp()?
            .values()
            .filter(|item| item.container_guid().is_empty() && item.slot() < INVENTORY_SLOT_BAG_END)
            .map(|item| (item.slot(), item.object().guid()))
            .collect();
        equipped.sort_by_key(|(slot, guid)| (*slot, guid.counter()));
        Some(
            equipped
                .into_iter()
                .map(|(_slot, item_guid)| self.apply_initial_item_equip_auras_like_cpp(item_guid))
                .sum(),
        )
    }

    fn apply_initial_item_equip_auras_like_cpp(&mut self, item_guid: ObjectGuid) -> usize {
        let Some(_player_guid) = self.player_guid() else {
            return 0;
        };
        let Some(item_effect_store) = self.item_effect_store.as_ref().cloned() else {
            return 0;
        };
        let Some(item_entry) = self
            .resolved_inventory_item_object_like_cpp(item_guid)
            .filter(|item| item.container_guid().is_empty() && item.slot() < INVENTORY_SLOT_BAG_END)
            .map(|item| item.object().entry())
        else {
            return 0;
        };
        if !self.initial_loaded_item_mods_can_apply_like_cpp(item_guid) {
            return 0;
        }

        let primary_spec = self.represented_primary_specialization_id_like_cpp();
        let mut applied = 0usize;
        if self
            .item_stats_store
            .as_ref()
            .and_then(|store| store.sparse_template(item_entry))
            .is_some_and(|template| template.item_flags().contains(ItemFlags::LEGACY))
        {
            return 0;
        }

        let effects: Vec<_> = item_effect_store
            .item_effects_for_item_id_like_cpp(item_entry)
            .into_iter()
            .cloned()
            .collect();
        for effect in effects {
            if effect.trigger_type != 1 {
                continue;
            }
            if effect.spell_id <= 0 {
                continue;
            }
            if effect.chr_specialization_id != 0
                && Some(u32::from(effect.chr_specialization_id)) != primary_spec
            {
                continue;
            }
            if !self.represented_equip_spell_fits_shapeshift_like_cpp(effect.spell_id as u32) {
                continue;
            }

            let Some(spell_info) = self
                .spell_store()
                .and_then(|store| store.get(effect.spell_id))
                .cloned()
            else {
                continue;
            };
            let effect_mask = unit_owned_apply_aura_effect_mask_like_cpp(&spell_info);
            if effect_mask == 0 {
                continue;
            }
            if self
                .apply_aura_with_effect_mask_like_cpp(
                    effect.spell_id,
                    item_guid,
                    0,
                    AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100 | 0x0000_0200,
                    effect_mask,
                )
                .is_ok()
            {
                applied += 1;
            }
        }

        applied
    }

    pub(crate) fn apply_initial_equipped_item_set_auras_like_cpp(&mut self) -> Option<usize> {
        let mut equipped: Vec<_> = self
            .resolved_inventory_item_objects_like_cpp()?
            .values()
            .filter(|item| item.container_guid().is_empty() && item.slot() < INVENTORY_SLOT_BAG_END)
            .map(|item| (item.slot(), item.object().guid()))
            .collect();
        equipped.sort_by_key(|(slot, guid)| (*slot, guid.counter()));
        Some(
            equipped
                .into_iter()
                .map(|(_slot, item_guid)| self.apply_initial_item_set_auras_like_cpp(item_guid))
                .sum(),
        )
    }

    fn apply_initial_item_set_auras_like_cpp(&mut self, item_guid: ObjectGuid) -> usize {
        let Some(player_guid) = self.player_guid() else {
            return 0;
        };
        let events = self.record_represented_items_set_item_events_like_cpp(item_guid, true);
        let mut applied = 0usize;
        for event in events {
            if !event.apply {
                continue;
            }
            let Ok(spell_id) = i32::try_from(event.spell_id) else {
                continue;
            };
            if self.player_has_visible_aura_spell_like_cpp(spell_id) != Some(false) {
                continue;
            }
            let effect_mask = self
                .spell_store()
                .and_then(|store| store.get(spell_id))
                .map(unit_owned_apply_aura_effect_mask_like_cpp)
                .unwrap_or(0x0000_0001)
                .max(0x0000_0001);
            if self
                .apply_aura_with_effect_mask_like_cpp(
                    spell_id,
                    player_guid,
                    0,
                    AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100 | 0x0000_0200,
                    effect_mask,
                )
                .is_ok()
            {
                applied += 1;
            }
        }
        applied
    }

    /// Replays the aura-producing part of C++ `Player::_ApplyAllItemMods` after
    /// `Player::_LoadAuras`. C++ walks equipment slots and, for each item,
    /// applies its item-set effect, regular equip spell, and enchantments before
    /// advancing to the next slot; preserve that exact order for aura slots.
    pub(crate) fn apply_initial_loaded_item_mods_like_cpp(
        &mut self,
        loaded_equipped_item_guids: &[ObjectGuid],
    ) -> InitialLoadedItemModsOutcomeLikeCpp {
        // This is the initial C++ `_ApplyAllItemMods` replay for a newly
        // constructed Player. Start from the same empty modifier state even
        // after a failed/retried login that did not reach normal teardown.
        self.reset_represented_item_bonus_runtime_like_cpp();

        let mut equipped = loaded_equipped_item_guids
            .iter()
            .filter_map(|&item_guid| {
                self.resolved_inventory_item_object_like_cpp(item_guid)
                    .map(|item| (item.slot(), item_guid))
            })
            .collect::<Vec<_>>();
        equipped.sort_by_key(|(slot, guid)| (*slot, guid.counter()));

        let mut item_set_auras = 0usize;
        let mut item_equip_auras = 0usize;
        let mut enchantments = LoadedEquippedItemEnchantmentsOutcomeLikeCpp::default();
        for (_slot, item_guid) in equipped {
            item_set_auras += self.apply_initial_item_set_auras_like_cpp(item_guid);
            item_equip_auras += self.apply_initial_item_equip_auras_like_cpp(item_guid);
            enchantments.append(self.apply_loaded_equipped_item_enchantments_like_cpp(item_guid));
        }

        InitialLoadedItemModsOutcomeLikeCpp {
            item_set_auras,
            item_equip_auras,
            enchantments,
        }
    }

    pub(crate) fn apply_represented_item_set_aura_refresh_events_like_cpp(
        &mut self,
        form_change: bool,
    ) -> usize {
        let events = self.plan_represented_update_item_set_auras_like_cpp(form_change);
        #[cfg(test)]
        self.represented_item_set_aura_refresh_events_like_cpp
            .extend(events.iter().cloned());
        let recorded = events.len();
        let Some(player_guid) = self.player_guid() else {
            return recorded;
        };

        for event in events {
            let Ok(spell_id) = i32::try_from(event.spell_id) else {
                continue;
            };
            if event.apply {
                if event.form_change
                    && self.player_has_visible_aura_spell_like_cpp(spell_id) != Some(false)
                {
                    continue;
                }
                let effect_mask = self
                    .spell_store()
                    .and_then(|store| store.get(spell_id))
                    .map(unit_owned_apply_aura_effect_mask_like_cpp)
                    .unwrap_or(0x0000_0001)
                    .max(0x0000_0001);
                let _ = self.apply_aura_with_effect_mask_like_cpp(
                    spell_id,
                    player_guid,
                    0,
                    AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100 | 0x0000_0200,
                    effect_mask,
                );
            } else {
                let _ = self.remove_represented_auras_due_to_spell_like_cpp(spell_id);
            }
        }

        recorded
    }

