    pub(crate) fn forget_represented_player_recent_instance_like_cpp(
        &mut self,
        map_id: u32,
    ) -> bool {
        let canonical = self.with_owned_player_mut_like_cpp(|player| {
            player
                .gameplay_state_mut()
                .recent_instances
                .remove(&map_id)
                .is_some()
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return self
                .represented_player_recent_instances_like_cpp
                .remove(&map_id)
                .is_some();
        }
        canonical.unwrap_or(false)
    }

    pub(crate) fn apply_represented_player_instance_reset_result_like_cpp(
        &mut self,
        map_id: u32,
        result: GroupInstanceResetResultLikeCpp,
        method: GroupInstanceResetMethodLikeCpp,
    ) -> bool {
        match result {
            GroupInstanceResetResultLikeCpp::Success => {
                self.forget_represented_player_recent_instance_like_cpp(map_id)
            }
            GroupInstanceResetResultLikeCpp::NotEmpty
                if method == GroupInstanceResetMethodLikeCpp::OnChangeDifficulty =>
            {
                self.forget_represented_player_recent_instance_like_cpp(map_id)
            }
            GroupInstanceResetResultLikeCpp::NotEmpty
            | GroupInstanceResetResultLikeCpp::CannotReset
            | GroupInstanceResetResultLikeCpp::Other => false,
        }
    }

    pub(crate) fn represented_toggle_difficulty_target_like_cpp(&self) -> Option<u32> {
        let store = self.difficulty_store()?;
        let (dungeon, raid, _) = self.player_difficulty_preferences_snapshot_like_cpp()?;
        let raid_entry = store.get(raid);
        let entry = match raid_entry {
            Some(entry) if entry.toggle_difficulty_id != 0 => entry,
            _ => store.get(dungeon)?,
        };

        (entry.toggle_difficulty_id != 0).then_some(u32::from(entry.toggle_difficulty_id))
    }

    /// C++ `Player::LoadFromDB` applies `CheckLoaded*DifficultyID` to the raw
    /// `characters` columns before any login packets are sent.
    pub(crate) fn load_represented_player_difficulties_like_cpp(
        &mut self,
        dungeon_difficulty_id: u32,
        raid_difficulty_id: u32,
        legacy_raid_difficulty_id: u32,
    ) {
        let Some(store) = self.difficulty_store() else {
            let _ = self.replace_player_difficulty_preferences_like_cpp(
                DIFFICULTY_NORMAL_LIKE_CPP,
                DIFFICULTY_NORMAL_RAID_LIKE_CPP,
                DIFFICULTY_10_N_LIKE_CPP,
            );
            return;
        };

        let dungeon_difficulty_id =
            store.check_loaded_dungeon_difficulty_id_like_cpp(dungeon_difficulty_id);
        let raid_difficulty_id = store.check_loaded_raid_difficulty_id_like_cpp(raid_difficulty_id);
        let legacy_raid_difficulty_id =
            store.check_loaded_legacy_raid_difficulty_id_like_cpp(legacy_raid_difficulty_id);

        let _ = self.replace_player_difficulty_preferences_like_cpp(
            dungeon_difficulty_id,
            raid_difficulty_id,
            legacy_raid_difficulty_id,
        );
    }

    /// C++ `Player::_LoadGroup` overwrites the loaded player difficulties with
    /// the current group values because the leader may change them while the
    /// member is offline.
    pub(crate) fn load_represented_group_difficulties_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(group_registry)) = (
            self.resolved_group_guid_like_cpp(),
            self.group_registry.as_ref(),
        ) else {
            return false;
        };

        let preferences = {
            let Some(group) = group_registry.get(&group_guid) else {
                return false;
            };
            (
                group.dungeon_difficulty_id,
                group.raid_difficulty_id,
                group.legacy_raid_difficulty_id,
            )
        };

        self.replace_player_difficulty_preferences_like_cpp(
            preferences.0,
            preferences.1,
            preferences.2,
        )
    }

    /// Resolve C++ `Player::m_group` through this session incarnation's
    /// generation-checked canonical Player handle. An unresolved owner never
    /// falls back in production.
    pub(crate) fn resolved_group_guid_like_cpp(&self) -> Option<u64> {
        let canonical = self.with_owned_player_like_cpp(|player| {
            player
                .gameplay_state()
                .group
                .as_ref()
                .map(|group| group.group_guid.counter() as u64)
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return self.group_guid;
        }
        canonical.flatten()
    }

    fn resolved_group_subgroup_like_cpp(&self) -> Option<u8> {
        let canonical = self.with_owned_player_like_cpp(|player| {
            player
                .gameplay_state()
                .group
                .as_ref()
                .map(|group| group.subgroup)
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return self.represented_subgroup_like_cpp;
        }
        canonical.flatten()
    }

    /// C++ `Player::SetGroup`: replace the Player-owned `GroupReference`
    /// snapshot. Group membership itself remains authoritative in GroupRegistry.
    pub(crate) fn set_owned_player_group_like_cpp(
        &mut self,
        membership: Option<(u64, u8)>,
    ) -> bool {
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.group_guid = membership.map(|(group_guid, _)| group_guid);
            self.represented_subgroup_like_cpp = membership.map(|(_, subgroup)| subgroup);
            return true;
        }

        let state = match membership {
            None => None,
            Some((group_guid, subgroup)) => {
                let Some(player_guid) = self.player_guid() else {
                    return false;
                };
                let Some(group_registry) = self.group_registry.as_ref() else {
                    return false;
                };
                let Some(group) = group_registry.get(&group_guid) else {
                    return false;
                };
                let Some(slot) = group.member_slot_like_cpp(player_guid) else {
                    return false;
                };
                Some(wow_entities::PlayerGroupState {
                    group_guid: ObjectGuid::create_group(group_guid),
                    leader_guid: group.leader_guid,
                    role_mask: slot.roles,
                    subgroup,
                })
            }
        };

        self.with_owned_player_mut_like_cpp(move |player| {
            player.gameplay_state_mut().group = state;
        })
        .is_some()
    }

    /// C++ `Player::SetGroup(group, subgroup)` stores the subgroup on the
    /// player's `GroupReference`; `Player::GetSubGroup()` reads it from there.
    pub(crate) fn load_represented_group_subgroup_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(player_guid), Some(group_registry)) = (
            self.resolved_group_guid_like_cpp(),
            self.player_guid(),
            self.group_registry.as_ref(),
        ) else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };
        let Some(slot) = group.member_slot_like_cpp(player_guid) else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };

        self.set_owned_player_group_like_cpp(Some((group_guid, slot.subgroup)))
    }

    pub(crate) fn apply_group_subgroup_like_cpp(&mut self, group_guid: u64, subgroup: u8) {
        if self.resolved_group_guid_like_cpp() == Some(group_guid)
            && self.set_owned_player_group_like_cpp(Some((group_guid, subgroup)))
        {
            self.sync_player_registry_state_like_cpp();
        }
    }

    pub(crate) fn apply_group_join_like_cpp(&mut self, group_guid: u64, subgroup: u8) {
        if self.set_owned_player_group_like_cpp(Some((group_guid, subgroup))) {
            self.sync_player_registry_party_member_party_type_like_cpp();
        }
    }

    pub(crate) fn sync_player_registry_party_member_party_type_like_cpp(&self) {
        let (Some(guid), Some(registry)) = (self.player_guid(), &self.player_registry) else {
            return;
        };
        let party_type = self.party_member_party_type_like_cpp();
        registry.publish_party_type_for_control_channel(guid, &self.session_command_tx, party_type);
    }

    pub(crate) fn clear_represented_group_subgroup_like_cpp(&mut self) {
        let _ = self.set_owned_player_group_like_cpp(None);
    }

    #[cfg(test)]
    pub(crate) fn represented_subgroup_like_cpp(&self) -> Option<u8> {
        self.resolved_group_subgroup_like_cpp()
    }

    /// C++ `Player::_LoadGroup` resolves `CHAR_SEL_GROUP_MEMBER.guid` through
    /// `sGroupMgr->GetGroupByDbStoreId` before attaching the player to the
    /// already-loaded group.
    pub(crate) fn load_represented_group_by_db_store_id_like_cpp(
        &mut self,
        db_store_id: u32,
    ) -> bool {
        let Some(group_registry) = self.group_registry.as_ref() else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };
        let Some(group_guid) = group_guid_by_db_store_id_like_cpp(db_store_id) else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };
        if !group_registry.contains_key(&group_guid) {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        }

        let Some(player_guid) = self.player_guid() else {
            return false;
        };
        let Some(subgroup) = group_registry.get(&group_guid).and_then(|group| {
            group
                .member_slot_like_cpp(player_guid)
                .map(|slot| slot.subgroup)
        }) else {
            let _ = self.set_owned_player_group_like_cpp(None);
            return false;
        };
        if !self.set_owned_player_group_like_cpp(Some((group_guid, subgroup))) {
            return false;
        }
        self.load_represented_group_difficulties_like_cpp()
    }

    /// C++ `Player::ResetGroupUpdateSequenceIfNeeded` resets the per-player
    /// sequence for a group category only when the loaded group guid changed.
    pub(crate) fn reset_group_update_sequence_if_needed_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(group_registry)) = (
            self.resolved_group_guid_like_cpp(),
            self.group_registry.as_ref(),
        ) else {
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            return false;
        };
        let category = group.group_category_like_cpp();
        if category >= wow_social::group::MAX_GROUP_CATEGORY_LIKE_CPP {
            return false;
        }

        let canonical = self.with_owned_player_mut_like_cpp(|player| {
            let sequence =
                &mut player.gameplay_state_mut().group_update_sequences[usize::from(category)];
            if sequence.group_guid == Some(group_guid) {
                return false;
            }
            sequence.group_guid = Some(group_guid);
            sequence.update_sequence_number = 1;
            true
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            let sequence =
                &mut self.represented_group_update_sequences_like_cpp[usize::from(category)];
            if sequence.group_guid == Some(group_guid) {
                return false;
            }
            sequence.group_guid = Some(group_guid);
            sequence.update_sequence_number = 1;
            return true;
        }
        canonical.unwrap_or(false)
    }

    /// C++ `Player::NextGroupUpdateSequenceNumber` returns the current
    /// per-player category sequence and then increments it.
    pub(crate) fn next_group_update_sequence_number_like_cpp(
        &mut self,
        category: u8,
    ) -> Option<i32> {
        if category >= wow_social::group::MAX_GROUP_CATEGORY_LIKE_CPP {
            return None;
        }

        let canonical = self.with_owned_player_mut_like_cpp(|player| {
            let sequence =
                &mut player.gameplay_state_mut().group_update_sequences[usize::from(category)];
            let current = sequence.update_sequence_number;
            sequence.update_sequence_number = sequence.update_sequence_number.saturating_add(1);
            current
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            let sequence =
                &mut self.represented_group_update_sequences_like_cpp[usize::from(category)];
            let current = sequence.update_sequence_number;
            sequence.update_sequence_number = sequence.update_sequence_number.saturating_add(1);
            return Some(current);
        }
        canonical
    }

    /// C++ `Group::SendUpdateDestroyGroupToPlayer` (`Group.cpp:917-926`): the
    /// removed member tears down its party frames from a destroyed
    /// `PartyUpdate` that carries no members. `Group::RemoveMember` sends it
    /// after the kick when the group survives (`Group.cpp:654-655`) and
    /// `Group::Disband` sends it to every member (`Group.cpp:746`).
    pub(crate) fn send_destroyed_group_party_update_like_cpp(
        &mut self,
        group_guid: u64,
        category: u8,
    ) {
        let Some(sequence_num) = self.next_group_update_sequence_number_like_cpp(category) else {
            return;
        };
        self.send_packet_realm(&wow_packet::packets::party::PartyUpdate {
            party_flags: wow_social::group::GROUP_FLAG_DESTROYED_LIKE_CPP,
            party_index: category,
            party_type: wow_social::group::GROUP_TYPE_NONE_LIKE_CPP,
            my_index: -1,
            party_guid: group_guid,
            sequence_num,
            leader_guid: ObjectGuid::EMPTY,
            leader_faction_group: 0,
            player_list: Vec::new(),
            loot_settings: None,
            difficulty_settings: None,
        });
    }

    /// C++ `Player::_LoadGroup` sets `PLAYER_FLAGS_GROUP_LEADER` when the
    /// loaded group leader matches the player, and removes it otherwise.
    pub(crate) fn apply_represented_group_leader_flag_like_cpp(&mut self) -> bool {
        let Some(player_guid) = self.player_guid() else {
            return false;
        };

        let is_group_leader = self
            .resolved_group_guid_like_cpp()
            .and_then(|group_guid| {
                self.group_registry
                    .as_ref()
                    .and_then(|registry| registry.get(&group_guid).map(|group| group.leader_guid))
            })
            .is_some_and(|leader_guid| leader_guid == player_guid);

        let updated = self
            .mutate_canonical_player_like_cpp(|player| {
                if is_group_leader {
                    player.set_player_flag(PLAYER_FLAGS_GROUP_LEADER_LIKE_CPP);
                } else {
                    player.remove_player_flag(PLAYER_FLAGS_GROUP_LEADER_LIKE_CPP);
                }
            })
            .is_some();

        if updated {
            self.sync_player_registry_state_like_cpp();
        }

        updated
    }

    pub(crate) fn represented_dungeon_difficulty_packet_like_cpp(
        &self,
    ) -> Option<DungeonDifficultySet> {
        Some(DungeonDifficultySet {
            difficulty_id: i32::try_from(self.resolved_dungeon_difficulty_id_like_cpp()?)
                .unwrap_or(i32::MAX),
        })
    }

    pub(crate) fn apply_group_difficulty_like_cpp(
        &mut self,
        group_guid: u64,
        difficulty_id: u32,
        kind: wow_social::group::GroupDifficultyKindLikeCpp,
    ) {
        if self.resolved_group_guid_like_cpp() != Some(group_guid) {
            return;
        }

        if self
            .mutate_player_difficulty_preferences_like_cpp(
                |dungeon, raid, legacy_raid| match kind {
                    wow_social::group::GroupDifficultyKindLikeCpp::Dungeon => {
                        *dungeon = difficulty_id;
                    }
                    wow_social::group::GroupDifficultyKindLikeCpp::Raid => {
                        *raid = difficulty_id;
                    }
                    wow_social::group::GroupDifficultyKindLikeCpp::LegacyRaid => {
                        *legacy_raid = difficulty_id;
                    }
                },
            )
            .is_none()
        {
            return;
        }

        match kind {
            wow_social::group::GroupDifficultyKindLikeCpp::Dungeon => {
                self.send_packet(&DungeonDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                });
            }
            wow_social::group::GroupDifficultyKindLikeCpp::Raid => {
                self.send_packet(&RaidDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                    legacy: false,
                });
            }
            wow_social::group::GroupDifficultyKindLikeCpp::LegacyRaid => {
                self.send_packet(&RaidDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                    legacy: true,
                });
            }
        }
    }

    fn current_map_instanceable_like_cpp(&self) -> bool {
        let map_id = u32::from(self.player_map_id_like_cpp());
        self.map_store()
            .and_then(|store| store.get(map_id))
            .is_some_and(|entry| {
                matches!(
                    entry.instance_type,
                    wow_data::map::MAP_INSTANCE
                        | wow_data::map::MAP_RAID
                        | wow_data::map::MAP_BATTLEGROUND
                        | wow_data::map::MAP_ARENA
                        | wow_data::map::MAP_SCENARIO
                )
            })
    }

    pub(crate) fn represented_set_difficulty_id_like_cpp(
        &mut self,
        difficulty_id: u32,
    ) -> Vec<wow_persistence::RepresentedGroupPersistenceCommandLikeCpp> {
        let Some((current_dungeon, current_raid, current_legacy_raid)) =
            self.player_difficulty_preferences_snapshot_like_cpp()
        else {
            return Vec::new();
        };
        let Some(entry) = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()
        else {
            return Vec::new();
        };

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) {
            return Vec::new();
        }

        if self.current_map_instanceable_like_cpp() {
            return Vec::new();
        }

        if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
            if let Some(statement) = self.set_represented_group_difficulty_like_cpp(
                difficulty_id,
                wow_social::group::GroupDifficultyKindLikeCpp::Dungeon,
            ) {
                return vec![statement];
            }
            if self.resolved_group_guid_like_cpp().is_some() || difficulty_id == current_dungeon {
                return Vec::new();
            }

            if self
                .mutate_player_difficulty_preferences_like_cpp(|dungeon, _, _| {
                    *dungeon = difficulty_id;
                })
                .is_none()
            {
                return Vec::new();
            }
            self.send_packet(&DungeonDifficultySet {
                difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
            });
            Vec::new()
        } else if entry.instance_type == MAP_RAID_LIKE_CPP {
            let legacy = flags.contains(DifficultyFlags::LEGACY);
            let kind = if legacy {
                wow_social::group::GroupDifficultyKindLikeCpp::LegacyRaid
            } else {
                wow_social::group::GroupDifficultyKindLikeCpp::Raid
            };
            if let Some(statement) =
                self.set_represented_group_difficulty_like_cpp(difficulty_id, kind)
            {
                return vec![statement];
            }
            if self.resolved_group_guid_like_cpp().is_some() {
                return Vec::new();
            }
            let current = if legacy {
                current_legacy_raid
            } else {
                current_raid
            };
            if difficulty_id == current {
                return Vec::new();
            }

            if self
                .mutate_player_difficulty_preferences_like_cpp(|_, raid, legacy_raid| {
                    if legacy {
                        *legacy_raid = difficulty_id;
                    } else {
                        *raid = difficulty_id;
                    }
                })
                .is_none()
            {
                return Vec::new();
            }

            self.send_packet(&RaidDifficultySet {
                difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                legacy,
            });
            Vec::new()
        } else {
            Vec::new()
        }
    }

    pub(crate) fn represented_raid_difficulty_request_like_cpp(
        &self,
        difficulty_id: i32,
        legacy: bool,
    ) -> Option<u32> {
        let difficulty_id = u32::try_from(difficulty_id).ok()?;
        let entry = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()?;
        if entry.instance_type != MAP_RAID_LIKE_CPP {
            return None;
        }

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) {
            return None;
        }

        (flags.contains(DifficultyFlags::LEGACY) == legacy).then_some(difficulty_id)
    }

    fn set_represented_group_difficulty_like_cpp(
        &mut self,
        difficulty_id: u32,
        kind: wow_social::group::GroupDifficultyKindLikeCpp,
    ) -> Option<wow_persistence::RepresentedGroupPersistenceCommandLikeCpp> {
        let group_guid = self.resolved_group_guid_like_cpp()?;
        let player_guid = self.player_guid()?;
        let registry = self.group_registry.as_ref()?;
        let outcome = registry
            .set_difficulty_transition_like_cpp(group_guid, player_guid, difficulty_id, kind)
            .ok()?;
        let persistence = outcome.persistence;
        let members = outcome.group.members;

        for member_guid in members {
            if member_guid == player_guid {
                self.apply_group_difficulty_like_cpp(group_guid, difficulty_id, kind);
                continue;
            }
            let Some(player_registry) = self.player_registry.as_ref() else {
                continue;
            };
            if let Some(member) = player_registry.group_presence(member_guid) {
                let _ = player_registry.try_send_current_command(
                    member.registration,
                    SessionCommand::ApplyGroupDifficultyLikeCpp(
                        crate::session::mailbox::ApplyGroupDifficultyLikeCppCommand {
                            group_guid,
                            difficulty_id,
                            kind,
                        },
                    ),
                );
            }
        }

        persistence
            .into_iter()
            .next()
            .map(crate::handlers::group::group_persistence_command_like_cpp)
    }

    pub(crate) fn represented_set_difficulty_reset_owner_like_cpp(
        &self,
        difficulty_id: u32,
    ) -> Option<ObjectGuid> {
        let entry = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()?;

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) || self.current_map_instanceable_like_cpp()
        {
            return None;
        }

        let player_guid = self.player_guid()?;
        if let Some(group_guid) = self.resolved_group_guid_like_cpp() {
            let group = self.group_registry.as_ref()?.get(&group_guid)?;
            if !group.is_leader_like_cpp(player_guid) || group.is_lfg_group_like_cpp() {
                return None;
            }

            let current = if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
                group.dungeon_difficulty_id
            } else if entry.instance_type == MAP_RAID_LIKE_CPP {
                if flags.contains(DifficultyFlags::LEGACY) {
                    group.legacy_raid_difficulty_id
                } else {
                    group.raid_difficulty_id
                }
            } else {
                return None;
            };

            return (current != difficulty_id).then_some(group.leader_guid);
        }

        let (dungeon, raid, legacy_raid) =
            self.player_difficulty_preferences_snapshot_like_cpp()?;
        let current = if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
            dungeon
        } else if entry.instance_type == MAP_RAID_LIKE_CPP {
            if flags.contains(DifficultyFlags::LEGACY) {
                legacy_raid
            } else {
                raid
            }
        } else {
            return None;
        };

        (current != difficulty_id).then_some(player_guid)
    }

