    pub(crate) fn creature_create_model_scalars_like_cpp(
        &self,
        display_id: u32,
        object_scale: f32,
        display_scale: f32,
    ) -> Option<CreatureCreateModelScalarsLikeCpp> {
        let model = self.creature_model_info_store.as_ref()?.get(display_id)?;
        let display_scale = if display_scale <= 0.0 {
            1.0
        } else {
            display_scale
        };
        let hover_height = self
            .creature_display_info_store
            .as_ref()
            .and_then(|display_store| display_store.get(display_id))
            .and_then(|display| {
                self.creature_model_data_store
                    .as_ref()
                    .and_then(|model_store| model_store.get(u32::from(display.model_id)))
                    .map(|model_data| {
                        model_data.hover_height
                            * model_data.model_scale
                            * display.creature_model_scale
                            * display_scale
                    })
            })
            .filter(|height| *height > 0.0)
            .unwrap_or(1.0);
        Some(CreatureCreateModelScalarsLikeCpp {
            display_scale,
            native_x_display_scale: display_scale,
            bounding_radius: model.bounding_radius * object_scale * display_scale,
            combat_reach: model.combat_reach * object_scale * display_scale,
            hover_height,
        })
    }

    pub(crate) fn choose_creature_display_like_cpp(
        &self,
        entry: u32,
        spawn_display_id: u32,
        template_flags_extra: u32,
        fallback_template_display_id: u32,
        fallback_template_display_scale: f32,
    ) -> Option<CreatureCreateDisplaySelectionLikeCpp> {
        // C++ `ObjectMgr::LoadCreatures` stores creature.modelid as
        // CreatureData::display with DEFAULT_PLAYER_DISPLAY_SCALE.
        if spawn_display_id != 0 {
            return Some(CreatureCreateDisplaySelectionLikeCpp {
                display_id: spawn_display_id,
                display_scale: 1.0,
            });
        }

        let template = self
            .creature_template_lifecycle_store_like_cpp
            .as_ref()
            .and_then(|store| store.get(entry));
        let mut selected = template.and_then(|template| {
            if template_flags_extra & CreatureFlagsExtra::TRIGGER.bits() != 0 {
                let model_info_store = self.creature_model_info_store.as_ref()?;
                template
                    .models
                    .iter()
                    .copied()
                    .find(|model| {
                        model_info_store
                            .get(model.creature_display_id)
                            .is_some_and(|info| info.is_trigger)
                    })
                    .or(Some(wow_data::CreatureTemplateLifecycleModelLikeCpp {
                        creature_display_id: 11686,
                        display_scale: 1.0,
                        probability: 1.0,
                    }))
            } else {
                match template.models.as_slice() {
                    [] => None,
                    [model] => Some(*model),
                    models => {
                        let total: f32 =
                            models.iter().map(|model| model.probability.max(0.0)).sum();
                        if total <= f32::EPSILON {
                            models.first().copied()
                        } else {
                            let mut roll = rand::thread_rng().gen_range(0.0..total);
                            let mut picked = *models.last()?;
                            for model in models {
                                roll -= model.probability.max(0.0);
                                if roll <= 0.0 {
                                    picked = *model;
                                    break;
                                }
                            }
                            Some(picked)
                        }
                    }
                }
            }
        });

        if selected.is_none() && fallback_template_display_id != 0 {
            selected = Some(wow_data::CreatureTemplateLifecycleModelLikeCpp {
                creature_display_id: fallback_template_display_id,
                display_scale: if fallback_template_display_scale <= 0.0 {
                    1.0
                } else {
                    fallback_template_display_scale
                },
                probability: 1.0,
            });
        }

        let mut selected = selected?;
        if let Some(other_gender) = self
            .creature_model_info_store
            .as_ref()
            .and_then(|store| store.get(selected.creature_display_id))
            .map(|info| info.display_id_other_gender)
            .filter(|id| *id != 0)
        {
            if rand::thread_rng().gen_range(0..=1) == 0 {
                selected.creature_display_id = other_gender;
                if let Some(template_model) = template.and_then(|template| {
                    template
                        .models
                        .iter()
                        .copied()
                        .find(|model| model.creature_display_id == other_gender)
                }) {
                    selected = template_model;
                }
            }
        }

        Some(CreatureCreateDisplaySelectionLikeCpp {
            display_id: selected.creature_display_id,
            display_scale: selected.display_scale,
        })
    }

    pub(crate) fn creature_create_stats_like_cpp(
        &self,
        entry: u32,
        level: u8,
        unit_class: u8,
        classification: u32,
        regen_health: bool,
        db_cur_health: u32,
        db_cur_mana: u32,
    ) -> CreatureCreateStatsLikeCpp {
        let power_type =
            power_type_from_u8_like_cpp(self.creature_display_power_for_class_like_cpp(unit_class));
        let db_cur_power = i32::try_from(db_cur_mana).unwrap_or(i32::MAX);
        let fallback_power = if power_type == PowerType::Mana {
            wow_data::character_progression::CreatureInitialPowerLikeCpp {
                max_power: db_cur_power,
                power: db_cur_power,
            }
        } else {
            self.power_type_store.as_ref().map_or(
                wow_data::character_progression::CreatureInitialPowerLikeCpp {
                    max_power: 0,
                    power: 0,
                },
                |store| store.creature_initial_power_like_cpp(power_type as i8, 0, 1.0),
            )
        };
        let Some(difficulty_store) = self.creature_difficulty_store_like_cpp.as_ref() else {
            let health = i64::from(db_cur_health.max(1));
            return CreatureCreateStatsLikeCpp {
                health,
                max_health: health,
                power_type,
                power: fallback_power.power,
                max_power: fallback_power.max_power,
                base_mana: 0,
            };
        };
        let Some(base_stats_store) = self.creature_base_stats_store_like_cpp.as_ref() else {
            let health = i64::from(db_cur_health.max(1));
            return CreatureCreateStatsLikeCpp {
                health,
                max_health: health,
                power_type,
                power: fallback_power.power,
                max_power: fallback_power.max_power,
                base_mana: 0,
            };
        };
        let difficulty = difficulty_store.get_like_cpp(entry, 0);

        let base_stats = base_stats_store.get_like_cpp(level, unit_class);
        let health_rate = self
            .creature_health_rates_like_cpp
            .modifier_for_classification_like_cpp(classification);
        let max_health = i64::from(
            (base_stats.generate_health_like_cpp(difficulty) as f32 * health_rate) as u32,
        );
        let health = if regen_health {
            max_health
        } else if db_cur_health != 0 {
            i64::from(((db_cur_health as f32 * health_rate) as u32).max(1))
        } else {
            0
        };

        let base_mana = i32::try_from(base_stats.base_mana).unwrap_or(i32::MAX);
        let initial_power = self.power_type_store.as_ref().map_or_else(
            || {
                let max_power = if power_type == PowerType::Mana {
                    i32::try_from(base_stats.generate_mana_like_cpp(difficulty)).unwrap_or(i32::MAX)
                } else {
                    0
                };
                wow_data::character_progression::CreatureInitialPowerLikeCpp {
                    max_power,
                    power: max_power,
                }
            },
            |store| {
                store.creature_initial_power_like_cpp(
                    power_type as i8,
                    base_mana,
                    difficulty.mana_modifier,
                )
            },
        );
        // C++ `Creature::SetSpawnHealth` only applies the `curmana` column through
        // `SetPower(POWER_MANA, ...)`. A Focus/Energy/Rage creature keeps the
        // default/full power seeded by `UpdateLevelDependantStats`.
        let power = if !regen_health && power_type == PowerType::Mana {
            i32::try_from(db_cur_mana).unwrap_or(i32::MAX)
        } else {
            initial_power.power
        };

        CreatureCreateStatsLikeCpp {
            health,
            max_health,
            power_type,
            power,
            max_power: initial_power.max_power,
            base_mana,
        }
    }

    pub(crate) fn creature_display_power_for_class_like_cpp(&self, unit_class: u8) -> u8 {
        self.chr_classes_store
            .as_ref()
            .and_then(|store| store.get(u32::from(unit_class)))
            .map(|entry| entry.display_power)
            .unwrap_or_else(|| match unit_class {
                1 => PowerType::Rage as u8,
                4 => PowerType::Energy as u8,
                6 => PowerType::RunicPower as u8,
                _ => PowerType::Mana as u8,
            })
    }

