    async fn reconcile_durable_loot_money_before_save_like_cpp(&mut self) -> bool {
        let tracker = Arc::clone(&self.durable_loot_money_persistence_like_cpp);
        tracker.wait_until_idle_like_cpp().await;
        let completions = tracker.pending_completions_like_cpp();
        for completion in completions {
            if completion
                .applied
                .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                continue;
            }
            let Some(old_money) = self.resolved_player_money_like_cpp() else {
                self.kick(
                    "canonical Player money owner is unavailable during durable reconciliation",
                );
                return false;
            };
            let new_money = old_money
                .checked_add(completion.durable_applied_amount)
                .filter(|money| *money <= MAX_MONEY_AMOUNT)
                .unwrap_or(old_money);
            if !self.set_player_gold_like_cpp(new_money) {
                self.kick(
                    "canonical Player money owner became unavailable during durable reconciliation",
                );
                return false;
            }
            if old_money != new_money {
                self.enqueue_represented_quest_objective_progress_like_cpp(
                    RepresentedQuestObjectiveProgressEventLikeCpp::MoneyChanged {
                        old_money,
                        new_money,
                    },
                );
            }
        }

        // Do not drain money criteria while the save fence is held. That path
        // can reward a quest and re-enter `save_player_gold`, which would wait
        // on this same fence. Queue the exact transition here; normal command
        // publication or the save caller drains it only after releasing the
        // fence. This keeps a save-first completion from losing MoneyChanged.

        if tracker.is_indeterminate_like_cpp() {
            self.kick("loot-money COMMIT outcome is unknown; skipping absolute money save");
            return false;
        }
        true
    }

    /// Close detached-payout admission, wait for every previously admitted
    /// worker, apply its exact-once durable deltas, then acquire the character
    /// money mutation lock. Callers must derive old/new runtime values only
    /// after this returns and retain the guard through their DB COMMIT.
    pub(crate) async fn begin_exclusive_player_money_persistence_like_cpp(
        &mut self,
    ) -> Option<ExclusivePlayerMoneyPersistenceLikeCpp> {
        let tracker = Arc::clone(&self.durable_loot_money_persistence_like_cpp);
        let save_fence = tracker.close_admission_for_save_like_cpp();
        tracker.wait_until_idle_like_cpp().await;
        if !self
            .reconcile_durable_loot_money_before_save_like_cpp()
            .await
        {
            return None;
        }
        let mutation_lock = tracker.lock_money_mutation_like_cpp().await;
        Some(ExclusivePlayerMoneyPersistenceLikeCpp {
            _save_fence: save_fence,
            _mutation_lock: mutation_lock,
        })
    }

    /// Derive one runtime money change only after the shared payout barrier,
    /// persist it while admission and the mutation mutex remain held, then
    /// publish the runtime value. Criteria must be queued/drained by the caller
    /// after this returns so reward callbacks cannot re-enter under the fence.
    pub(crate) async fn mutate_and_persist_player_gold_exclusive_like_cpp<F>(
        &mut self,
        mutation: F,
    ) -> Option<(u64, u64)>
    where
        F: FnOnce(u64) -> u64,
    {
        let money_persistence = self
            .begin_exclusive_player_money_persistence_like_cpp()
            .await?;
        let guid = self.player_guid()?.counter() as u64;
        let old_money = self.resolved_player_money_like_cpp()?;
        let new_money = mutation(old_money);

        #[cfg(test)]
        if let Some(success) = self.loot_money_persistence_test_result_like_cpp {
            if !success {
                return None;
            }
            if !self.set_player_gold_like_cpp(new_money) {
                return None;
            }
            drop(money_persistence);
            return Some((old_money, new_money));
        }

        if old_money == new_money {
            drop(money_persistence);
            return Some((old_money, new_money));
        }

        let port = self.player_lifecycle_port_like_cpp().map(Arc::clone)?;
        let request = wow_persistence::PlayerMoneyTransactionRequestLikeCpp {
            player_guid: guid,
            money_after: new_money,
            durability_repairs: Vec::new(),
        };
        let money_persistence = self
            .await_exclusive_player_money_transaction_outcome_like_cpp(
                money_persistence,
                port.persist_money_transaction_like_cpp(request),
                old_money,
                new_money,
                "exclusive player-money mutation",
            )
            .await?;
        if !self.set_player_gold_like_cpp(new_money) {
            self.kick("canonical Player money owner became unavailable after durable COMMIT");
            return None;
        }
        drop(money_persistence);
        Some((old_money, new_money))
    }

    /// Commit a trainer fee when the represented cast has no durable
    /// spell/skill mutation (for example, every acquisition effect was
    /// suppressed by target immunity). C++ charges and publishes its trainer
    /// visuals before that triggered cast resolves its hit effects.
    pub(crate) async fn commit_exclusive_trainer_money_only_like_cpp(
        &mut self,
        money_persistence: ExclusivePlayerMoneyPersistenceLikeCpp,
        money_before: u64,
        money_after: u64,
    ) -> Option<ExclusivePlayerMoneyPersistenceLikeCpp> {
        #[cfg(test)]
        if let Some(success) = self.loot_money_persistence_test_result_like_cpp {
            return success.then_some(money_persistence);
        }

        if money_before == money_after {
            return Some(money_persistence);
        }
        let guid = self.player_guid()?.counter() as u64;
        let port = self.player_lifecycle_port_like_cpp().map(Arc::clone)?;
        let request = wow_persistence::PlayerMoneyTransactionRequestLikeCpp {
            player_guid: guid,
            money_after,
            durability_repairs: Vec::new(),
        };
        self.await_exclusive_player_money_transaction_outcome_like_cpp(
            money_persistence,
            port.persist_money_transaction_like_cpp(request),
            money_before,
            money_after,
            "trainer fee without durable acquisition mutation",
        )
        .await
    }

    /// Commit one trainer fee and its prepared spell/skill acquisition under
    /// the same per-character money exclusion. Runtime publication remains the
    /// caller's responsibility and must complete before the returned guard is
    /// dropped.
    pub(crate) async fn commit_exclusive_player_money_and_spell_acquisition_like_cpp(
        &mut self,
        money_persistence: ExclusivePlayerMoneyPersistenceLikeCpp,
        prepared: &crate::spell_acquisition::PreparedPlayerSpellAcquisitionLikeCpp,
        money_before: u64,
        money_after: u64,
    ) -> Option<ExclusivePlayerMoneyPersistenceLikeCpp> {
        #[cfg(test)]
        if let Some(success) = self.loot_money_persistence_test_result_like_cpp {
            return success.then_some(money_persistence);
        }

        let port = self
            .persistence_ports_like_cpp
            .player
            .player_spell_acquisition
            .clone()?;
        let player_guid = self.player_guid()?;
        let guid_counter = player_guid.counter() as u64;
        let mut cancellation_fence = PlayerMoneyCommitCancellationFenceLikeCpp::new(Arc::clone(
            &self.durable_loot_money_persistence_like_cpp,
        ));
        let mut operation_token = [0u8; 16];
        rand::thread_rng().fill_bytes(&mut operation_token);
        let request =
            match crate::spell_acquisition::player_spell_acquisition_persistence_request_like_cpp(
                guid_counter,
                prepared,
                money_before,
                money_after,
                operation_token,
            ) {
                Ok(request) => request,
                Err(error) => {
                    cancellation_fence.disarm_like_cpp();
                    warn!(%error, "trainer purchase request was not persistence-safe");
                    return None;
                }
            };
        use crate::spell_acquisition::PlayerSpellAcquisitionPersistenceOutcomeLikeCpp as Outcome;
        match crate::spell_acquisition::persist_player_spell_acquisition_through_port_like_cpp(
            &*port, request,
        )
        .await
        {
            Outcome::Applied => {
                cancellation_fence.disarm_like_cpp();
                Some(money_persistence)
            }
            Outcome::DefinitelyRolledBack(reason) => {
                cancellation_fence.disarm_like_cpp();
                warn!(error = %reason, "trainer purchase transaction definitely rolled back");
                None
            }
            Outcome::ReconciledCommit(reason) => {
                cancellation_fence.disarm_like_cpp();
                warn!(error = %reason, "trainer COMMIT reply was lost but durable rows prove commit");
                Some(money_persistence)
            }
            Outcome::Indeterminate(reason) => {
                self.durable_loot_money_persistence_like_cpp
                    .mark_indeterminate_like_cpp();
                cancellation_fence.disarm_like_cpp();
                self.kick("trainer purchase COMMIT outcome is unknown; relog required");
                warn!(error = %reason, "trainer COMMIT outcome remains indeterminate; session quarantined");
                None
            }
        }
    }

    /// Persist an explicit player-money value and surface database failures to
    /// callers that must not expose a loot payout before it is durable.
    ///
    /// Unlike [`Self::save_player_gold`], this helper fails closed when there is
    /// no selected player or lifecycle port. Focused tests must opt into an
    /// explicit persistence result through the test seam below.
    pub(crate) async fn persist_player_gold_checked_like_cpp(
        &self,
        money: u64,
    ) -> Result<(), LootMoneyPersistenceErrorLikeCpp> {
        #[cfg(test)]
        if let Some(success) = self.loot_money_persistence_test_result_like_cpp {
            return success
                .then_some(())
                .ok_or(LootMoneyPersistenceErrorLikeCpp::MissingCharacterDatabase);
        }

        let guid = self
            .player_guid()
            .ok_or(LootMoneyPersistenceErrorLikeCpp::MissingPlayer)?;
        let port = self
            .player_lifecycle_port_like_cpp()
            .map(Arc::clone)
            .ok_or(LootMoneyPersistenceErrorLikeCpp::MissingCharacterDatabase)?;
        match port
            .persist_money_write_like_cpp(wow_persistence::PlayerMoneyWriteRequestLikeCpp {
                player_guid: guid.counter() as u64,
                money,
            })
            .await
        {
            wow_persistence::PersistenceOutcomeLikeCpp::Applied { .. } => Ok(()),
            wow_persistence::PersistenceOutcomeLikeCpp::Failed { reason }
            | wow_persistence::PersistenceOutcomeLikeCpp::Unknown { reason } => {
                Err(LootMoneyPersistenceErrorLikeCpp::Persistence(reason))
            }
        }
    }

    /// Start the complete durable half of one shared money claim in a detached
    /// task.  The task owns the lease across `COMMIT`, commits the authority in
    /// the same task immediately after SQL success, then schedules the
    /// already-durable session-local applications.
    ///
    /// Dropping or aborting the packet-handler future only drops its
    /// `JoinHandle`; Tokio keeps this worker alive.  This closes the duplicate
    /// window where SQL could commit after the handler was cancelled while the
    /// lease's `Drop` reopened the object pool.
    ///
    /// Boundary: this is an in-process guarantee, not a durable claim journal.
    /// Aborting this detached task (including runtime/process shutdown) at the
    /// database commit await boundary can still lose the continuation between
    /// durable SQL and the synchronous authority commit. Recovery across that
    /// boundary requires persisting claim identity in the same transaction and
    /// replaying it at startup; #106 does not yet provide such a journal.
    /// Delivery tasks may likewise outlive a target session, but they carry
    /// only runtime publication: durable player money reloads from SQL and the
    /// already-committed authority prevents a second in-process payout.
    pub(crate) fn spawn_group_loot_money_persistence_like_cpp(
        &self,
        mut payouts: Vec<(ObjectGuid, u64)>,
        claim: LootClaimLease,
        mut deliveries: Vec<(LootMoneyDeliveryAddressLikeCpp, SessionCommand)>,
        authority_committed: Arc<AtomicBool>,
        viewer_fanout: LootMoneyViewerFanoutLikeCpp,
    ) -> Result<
        tokio::task::JoinHandle<Result<(), LootMoneyPersistenceErrorLikeCpp>>,
        LootMoneyPersistenceErrorLikeCpp,
    > {
        if payouts.is_empty() {
            return Err(LootMoneyPersistenceErrorLikeCpp::MissingPlayer);
        }
        if self.player_guid().is_none() {
            return Err(LootMoneyPersistenceErrorLikeCpp::MissingPlayer);
        }

        #[cfg(test)]
        let test_result = self.loot_money_persistence_test_result_like_cpp;
        #[cfg(not(test))]
        let test_result: Option<bool> = None;

        payouts
            .sort_unstable_by_key(|(recipient, _)| (recipient.high_value(), recipient.low_value()));
        payouts.dedup_by_key(|(recipient, _)| *recipient);

        // Register every recipient directly before any SQL begins. Commands
        // are publication-only; waiting for target acknowledgements here would
        // create self/A↔B deadlocks between concurrent group looters.
        let payout_recipients = payouts
            .iter()
            .map(|(recipient, _)| *recipient)
            .collect::<HashSet<_>>();
        let mut money_persistence_guards = HashMap::<
            ObjectGuid,
            DurableLootMoneyPersistenceGuardLikeCpp,
        >::with_capacity(payouts.len());
        let mut money_mutation_trackers = HashMap::<
            ObjectGuid,
            Arc<DurableLootMoneyPersistenceTrackerLikeCpp>,
        >::with_capacity(payouts.len());
        for (_, command) in &deliveries {
            let SessionCommand::ApplyLootMoneyLikeCpp(command) = command else {
                continue;
            };
            if payout_recipients.contains(&command.recipient)
                && !money_persistence_guards.contains_key(&command.recipient)
            {
                let guard = command
                    .durable_persistence_tracker
                    .begin_like_cpp()
                    .map_err(|_| LootMoneyPersistenceErrorLikeCpp::MissingPlayer)?;
                money_persistence_guards.insert(command.recipient, guard);
                money_mutation_trackers.insert(
                    command.recipient,
                    Arc::clone(&command.durable_persistence_tracker),
                );
            }
        }
        if money_persistence_guards.len() != payouts.len() {
            return Err(LootMoneyPersistenceErrorLikeCpp::MissingPlayer);
        }

        let persistence_port = if test_result.is_some() {
            None
        } else {
            Some(
                self.group_loot_money_persistence_port_like_cpp()
                    .ok_or(LootMoneyPersistenceErrorLikeCpp::MissingCharacterDatabase)?,
            )
        };

        let mut persistence_guard = claim
            .begin_persistence_guard_like_cpp()
            .map_err(LootMoneyPersistenceErrorLikeCpp::Claim)?;
        drop(claim);

        Ok(tokio::spawn(async move {
            // Match the sorted character-row lock order below. Stored-item
            // money uses the same per-character lock before it takes the row,
            // so COMMIT reconciliation cannot be confused by a later local
            // payout interleaving between the failed reply and our reads.
            let mut _money_mutation_locks = Vec::with_capacity(payouts.len());
            for (recipient, _) in &payouts {
                _money_mutation_locks.push(
                    money_mutation_trackers
                        .get(recipient)
                        .expect("every payout retained its target mutation lock")
                        .lock_money_mutation_like_cpp()
                        .await,
                );
            }

            let durable_outcomes = if let Some(success) = test_result {
                // Give cancellation regressions a deterministic opportunity to
                // drop the outer waiter while this detached task owns `claim`.
                tokio::task::yield_now().await;
                if !success {
                    return Err(LootMoneyPersistenceErrorLikeCpp::MissingCharacterDatabase);
                }
                payouts
                    .iter()
                    .map(|(recipient, amount)| {
                        (
                            recipient.counter() as u64,
                            wow_persistence::GroupLootMoneyPersistenceOutcomeLikeCpp {
                                recipient_guid: recipient.counter() as u64,
                                before: 0,
                                after: *amount,
                                applied_delta: *amount,
                            },
                        )
                    })
                    .collect::<HashMap<_, _>>()
            } else {
                let persistence_port = persistence_port
                    .expect("production loot-money worker must own a persistence port");
                let request = wow_persistence::GroupLootMoneyPersistenceRequestLikeCpp {
                    payouts: payouts
                        .iter()
                        .map(
                            |(recipient, amount)| wow_persistence::GroupLootMoneyPayoutLikeCpp {
                                recipient_guid: recipient.counter() as u64,
                                requested_delta: *amount,
                            },
                        )
                        .collect(),
                    max_money: MAX_MONEY_AMOUNT,
                };
                let durable_outcomes = match persistence_port
                    .attempt_group_loot_money_like_cpp(request)
                    .await
                {
                    wow_persistence::GroupLootMoneyPersistenceAttemptLikeCpp::Applied(outcomes) => outcomes
                        .into_iter()
                        .map(|outcome| (outcome.recipient_guid, outcome))
                        .collect::<HashMap<_, _>>(),
                    wow_persistence::GroupLootMoneyPersistenceAttemptLikeCpp::DefinitelyRolledBack {
                        kind,
                        reason,
                        ..
                    } => {
                        return Err(match kind {
                            wow_persistence::GroupLootMoneyRollbackKindLikeCpp::MissingPlayer { .. } => {
                                LootMoneyPersistenceErrorLikeCpp::MissingPlayer
                            }
                            wow_persistence::GroupLootMoneyRollbackKindLikeCpp::Database => {
                                LootMoneyPersistenceErrorLikeCpp::Persistence(reason)
                            }
                        });
                    }
                    wow_persistence::GroupLootMoneyPersistenceAttemptLikeCpp::CommitOutcomeUnknown {
                        reason,
                        outcomes: durable_outcomes,
                    } => match persistence_port
                        .reconcile_group_loot_money_like_cpp(durable_outcomes.clone())
                        .await
                    {
                        wow_persistence::GroupLootMoneyReconciliationLikeCpp::RolledBack => {
                            return Err(LootMoneyPersistenceErrorLikeCpp::Persistence(
                                "loot-money COMMIT was reconciled as rolled back".to_owned(),
                            ));
                        }
                        wow_persistence::GroupLootMoneyReconciliationLikeCpp::Indeterminate { .. } => {
                            for guard in money_persistence_guards.values_mut() {
                                guard.mark_indeterminate_like_cpp();
                            }
                            let _ = persistence_guard.quarantine_commit_unknown_like_cpp();
                            for (delivery, _) in &deliveries {
                                let kick = SessionCommand::KickLikeCpp(KickLikeCppCommand {
                                    reason: "loot-money COMMIT outcome is unknown; relog required"
                                        .to_string(),
                                });
                                delivery.clone().queue_reliably_like_cpp(kick);
                            }
                            return Err(
                                LootMoneyPersistenceErrorLikeCpp::CommitOutcomeUnknownPersistence(
                                    reason,
                                ),
                            );
                        }
                        wow_persistence::GroupLootMoneyReconciliationLikeCpp::CommittedOrCapOnlyNoop => durable_outcomes
                            .into_iter()
                            .map(|outcome| (outcome.recipient_guid, outcome))
                            .collect::<HashMap<_, _>>(),
                    },
                };
                durable_outcomes
            };

            for (_, command) in &mut deliveries {
                if let SessionCommand::ApplyLootMoneyLikeCpp(command) = command {
                    let outcome = durable_outcomes
                        .get(&(command.recipient.counter() as u64))
                        .copied()
                        .expect("every admitted payout retains its locked DB outcome");
                    command
                        .durable_applied_amount
                        .store(outcome.applied_delta, Ordering::Release);
                    money_persistence_guards
                        .get_mut(&command.recipient)
                        .expect("every payout registered its target money fence")
                        .commit_like_cpp(DurableLootMoneyCompletionLikeCpp {
                            durable_money_before: outcome.before,
                            durable_money_after: outcome.after,
                            durable_applied_amount: outcome.applied_delta,
                            applied: Arc::clone(&command.applied),
                        });
                }
            }

            let committed_snapshot = match persistence_guard.commit_with_snapshot_like_cpp() {
                Ok((_, committed_snapshot)) => {
                    authority_committed.store(true, Ordering::Release);
                    committed_snapshot
                }
                Err(error) => {
                    // SQL is already durable. Never let a lifecycle race reopen
                    // this old allocation; payout publication still proceeds,
                    // but replacement loot is not touched.
                    warn!(?error, "durable loot-money authority commit failed closed");
                    let _ = persistence_guard.quarantine_commit_unknown_like_cpp();
                    None
                }
            };

            // `Loot::PlayersLooting` can grow while the detached SQL task is
            // running. The snapshot above was captured by the commit while
            // holding the same authority mutex: every included opener saw
            // non-zero money, and every later opener sees zero directly.
            let mut viewers = committed_snapshot
                .filter(|snapshot| {
                    snapshot.generation == viewer_fanout.authority_generation
                        && snapshot.loot.loot_guid == viewer_fanout.loot_obj
                })
                .map(|snapshot| {
                    snapshot
                        .loot
                        .players_looting
                        .into_iter()
                        .collect::<HashSet<_>>()
                })
                .unwrap_or_default();

            for (_, command) in &mut deliveries {
                if let SessionCommand::ApplyLootMoneyLikeCpp(command) = command {
                    command
                        .send_coin_removed
                        .store(viewers.remove(&command.recipient), Ordering::Release);
                }
            }

            for viewer in viewers {
                if viewer_fanout.payout_recipients.contains(&viewer) {
                    continue;
                }
                let delivery = if viewer == viewer_fanout.source_player {
                    Some(LootMoneyDeliveryAddressLikeCpp::Source(
                        viewer_fanout.source_command_tx.clone(),
                    ))
                } else {
                    viewer_fanout.player_registry.as_ref().and_then(|registry| {
                        let registration = registry.in_world_loot_delivery_recipient(
                            viewer,
                            viewer_fanout.map_id,
                            viewer_fanout.instance_id,
                        )?;
                        Some(LootMoneyDeliveryAddressLikeCpp::Directory {
                            registry: Arc::clone(registry),
                            registration,
                        })
                    })
                };
                let Some(delivery) = delivery else {
                    continue;
                };
                deliveries.push((
                    delivery,
                    SessionCommand::NotifyLootMoneyRemovedLikeCpp(
                        NotifyLootMoneyRemovedLikeCppCommand {
                            recipient: viewer,
                            loot_owner: viewer_fanout.loot_owner,
                            loot_obj: viewer_fanout.loot_obj,
                            authority: viewer_fanout.authority.clone(),
                            authority_generation: viewer_fanout.authority_generation,
                            authority_committed: Arc::clone(&authority_committed),
                        },
                    ),
                ));
            }

            // Do not make persistence wait for another session's bounded
            // command queue. Each delivery task owns its command until the
            // target drains capacity or disconnects.
            for (delivery, command) in deliveries {
                delivery.queue_reliably_like_cpp(command);
            }
            Ok(())
        }))
    }

    #[cfg(test)]
    pub(crate) fn set_loot_money_persistence_test_result_like_cpp(&mut self, success: bool) {
        self.loot_money_persistence_test_result_like_cpp = Some(success);
    }

    #[cfg(test)]
    pub(crate) fn clear_loot_money_persistence_test_result_like_cpp(&mut self) {
        self.loot_money_persistence_test_result_like_cpp = None;
    }

    pub(crate) fn loot_money_persistence_test_result_for_worker_like_cpp(&self) -> Option<bool> {
        #[cfg(test)]
        {
            self.loot_money_persistence_test_result_like_cpp
        }
        #[cfg(not(test))]
        {
            None
        }
    }

    pub(crate) fn begin_durable_item_loot_persistence_like_cpp(
        &self,
    ) -> DurableItemLootPersistenceGuardLikeCpp {
        self.durable_item_loot_persistence_like_cpp.begin_like_cpp()
    }

    pub(crate) async fn wait_for_durable_item_loot_persistence_like_cpp(&self) {
        self.durable_item_loot_persistence_like_cpp
            .wait_until_idle_like_cpp()
            .await;
    }

    pub(crate) fn durable_loot_money_persistence_tracker_like_cpp(
        &self,
    ) -> Arc<DurableLootMoneyPersistenceTrackerLikeCpp> {
        Arc::clone(&self.durable_loot_money_persistence_like_cpp)
    }

    pub(crate) fn take_durable_item_loot_completions_like_cpp(
        &self,
    ) -> Vec<DurableItemLootCompletionLikeCpp> {
        self.durable_item_loot_persistence_like_cpp
            .take_completions_like_cpp()
    }

    #[cfg(test)]
    pub(crate) fn set_loot_item_store_test_seam_like_cpp(
        &mut self,
        grants: Arc<AtomicUsize>,
        success: bool,
    ) {
        self.loot_item_store_test_grants_like_cpp = Some(grants);
        self.loot_item_store_test_success_like_cpp = success;
    }

    #[cfg(test)]
    pub(crate) fn set_loot_item_store_test_commit_gate_like_cpp(
        &mut self,
        gate: Arc<tokio::sync::Notify>,
    ) {
        self.loot_item_store_test_commit_gate_like_cpp = Some(gate);
    }

    pub(crate) fn current_game_time_secs_like_cpp() -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs()
    }

    fn sanitize_rest_bonus_like_cpp(rest_bonus: f32) -> f32 {
        if rest_bonus.is_finite() {
            rest_bonus
        } else {
            0.0
        }
    }

    fn valid_player_rest_state_like_cpp(rest_state: u8) -> bool {
        matches!(
            rest_state,
            REST_STATE_RESTED_LIKE_CPP
                | REST_STATE_NORMAL_LIKE_CPP
                | REST_STATE_RAF_LINKED_LIKE_CPP
        )
    }

    fn player_is_at_configured_max_level_like_cpp(&self) -> bool {
        let max_level = self.max_player_level_config_like_cpp;
        max_level != 0 && u32::from(self.player_level_like_cpp()) >= max_level
    }

    /// C++ `Player::IsMaxLevel` reads `ActivePlayerData::MaxLevel`, which
    /// `InitStatsForLevel` derives from both the account's active expansion
    /// and CONFIG_MAX_PLAYER_LEVEL. RestMgr deliberately uses the config-only
    /// check above instead, so keep these two concepts separate.
    pub(crate) fn player_active_max_level_like_cpp(&self) -> u32 {
        let expansion_max = u32::from(max_level_for_expansion_like_cpp(self.expansion));
        let configured_max = self.max_player_level_config_like_cpp;
        if expansion_max == 80 || expansion_max >= configured_max {
            configured_max
        } else {
            expansion_max
        }
    }

    fn player_is_max_level_like_cpp(&self) -> bool {
        u32::from(self.player_level_like_cpp()) >= self.player_active_max_level_like_cpp()
    }

    fn can_gain_represented_xp_rest_bonus_like_cpp(&self) -> Option<bool> {
        if self.player_is_at_configured_max_level_like_cpp() {
            return Some(false);
        }

        let next_level_xp = self.resolved_player_next_level_xp_like_cpp()?;
        Some(next_level_xp != 0 && next_level_xp != u32::MAX)
    }

    fn represented_xp_rest_bonus_cap_like_cpp(&self) -> Option<f32> {
        Some(
            self.resolved_player_next_level_xp_like_cpp()? as f32
                * REST_BONUS_MAX_NEXT_LEVEL_XP_FACTOR_LIKE_CPP,
        )
    }

    fn represented_recruit_a_friend_xp_rest_state_applies_like_cpp(&self) -> bool {
        self.gets_recruit_a_friend_xp_bonus_like_cpp()
    }

    pub(crate) fn player_rest_state_snapshot_like_cpp(
        &self,
    ) -> Option<wow_entities::PlayerRestState> {
        let canonical =
            self.with_owned_player_for_rest_like_cpp(|player| player.rest_state_like_cpp().clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(wow_entities::PlayerRestState {
                rest_bonus: self.represented_rest_bonus_xp_like_cpp,
                rest_state: self.represented_rest_state_xp_like_cpp,
                rest_flag_mask: self.represented_rest_flag_mask_like_cpp,
                location_initialized: self.represented_rest_location_initialized_like_cpp,
                defer_flag_sync: self.represented_defer_rest_flag_sync_like_cpp,
                deferred_flag_update_dirty: self
                    .represented_deferred_rest_flag_update_dirty_like_cpp,
                inn_area_trigger_id: self.represented_inn_area_trigger_id_like_cpp,
                rest_time_secs: self.represented_rest_time_secs_like_cpp,
                ..Default::default()
            });
        }
        canonical
    }

    fn replace_player_rest_state_like_cpp(&mut self, state: wow_entities::PlayerRestState) -> bool {
        let canonical = self
            .with_owned_player_mut_for_rest_like_cpp(|player| {
                player.set_xp_rest_info_like_cpp(
                    state.rest_bonus.clamp(0.0, u32::MAX as f32) as u32,
                    state.rest_state,
                );
                if state.location_initialized {
                    if state.rest_flag_mask != 0 {
                        player.set_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
                    } else {
                        player.remove_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
                    }
                }
                player.replace_rest_state_like_cpp(state.clone());
            })
            .is_some();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_rest_bonus_xp_like_cpp = state.rest_bonus;
            self.represented_rest_state_xp_like_cpp = state.rest_state;
            self.represented_rest_flag_mask_like_cpp = state.rest_flag_mask;
            self.represented_rest_location_initialized_like_cpp = state.location_initialized;
            self.represented_defer_rest_flag_sync_like_cpp = state.defer_flag_sync;
            self.represented_deferred_rest_flag_update_dirty_like_cpp =
                state.deferred_flag_update_dirty;
            self.represented_inn_area_trigger_id_like_cpp = state.inn_area_trigger_id;
            self.represented_rest_time_secs_like_cpp = state.rest_time_secs;
            return true;
        }
        canonical
    }

    fn mutate_player_rest_state_like_cpp<R>(
        &mut self,
        f: impl FnOnce(&mut wow_entities::PlayerRestState) -> R,
    ) -> Option<R> {
        let mut state = self.player_rest_state_snapshot_like_cpp()?;
        let result = f(&mut state);
        self.replace_player_rest_state_like_cpp(state)
            .then_some(result)
    }

    pub(crate) fn load_represented_xp_rest_bonus_like_cpp(
        &mut self,
        rest_state: u8,
        rest_bonus: f32,
    ) {
        self.clear_represented_rest_flags_for_character_load_like_cpp();
        // C++ `RestMgr::LoadRestBonus` restores both DB values verbatim. It does
        // not clamp or recompute the state until a later `AddRestBonus` reaches
        // `SetRestBonus` (for example when offline time is applied).
        // C++-created rows only contain the declared PlayerRestState values.
        // Normalize legacy Rust rows that persisted the old invalid value 0,
        // while preserving every valid DB state verbatim like LoadRestBonus.
        let rest_state = if Self::valid_player_rest_state_like_cpp(rest_state) {
            rest_state
        } else {
            REST_STATE_NORMAL_LIKE_CPP
        };
        let _ = self.mutate_player_rest_state_like_cpp(|state| {
            state.rest_state = rest_state;
            state.rest_bonus = rest_bonus;
        });
    }

    fn clear_represented_rest_flags_for_character_load_like_cpp(&mut self) {
        let loaded_resting = self
            .canonical_player_snapshot_like_cpp(|player| player.data().player_flags)
            .is_some_and(|flags| (flags & PLAYER_FLAGS_RESTING_LIKE_CPP) != 0);
        let _canonical = self.with_owned_player_mut_for_rest_like_cpp(|player| {
            let mut state = player.rest_state_like_cpp().clone();
            state.rest_flag_mask = 0;
            state.location_initialized = false;
            state.defer_flag_sync = false;
            state.deferred_flag_update_dirty = false;
            state.inn_area_trigger_id = 0;
            state.rest_time_secs = 0;
            player.replace_rest_state_like_cpp(state);
            if loaded_resting {
                player.set_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
            } else {
                player.remove_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
            }
        });
        #[cfg(test)]
        if _canonical.is_none() && self.player_handle_like_cpp.is_none() {
            self.represented_rest_flag_mask_like_cpp = 0;
            self.represented_rest_location_initialized_like_cpp = false;
            self.represented_defer_rest_flag_sync_like_cpp = false;
            self.represented_deferred_rest_flag_update_dirty_like_cpp = false;
            self.represented_inn_area_trigger_id_like_cpp = 0;
            self.represented_rest_time_secs_like_cpp = 0;
        }
    }

    fn set_represented_xp_rest_bonus_like_cpp(&mut self, rest_bonus: f32) -> u8 {
        let Some(old_threshold) = self.resolved_xp_rest_threshold_like_cpp() else {
            return 0;
        };
        let Some(old_state) = self.resolved_xp_rest_state_like_cpp() else {
            return 0;
        };
        let mut rest_bonus = Self::sanitize_rest_bonus_like_cpp(rest_bonus);
        let Some(can_gain) = self.can_gain_represented_xp_rest_bonus_like_cpp() else {
            return 0;
        };
        if !can_gain {
            rest_bonus = 0.0;
        }

        let Some(rest_bonus_cap) = self.represented_xp_rest_bonus_cap_like_cpp() else {
            return 0;
        };
        rest_bonus = rest_bonus.clamp(0.0, rest_bonus_cap);
        let is_raf_linked = self.represented_recruit_a_friend_xp_rest_state_applies_like_cpp();
        let new_state = if is_raf_linked {
            REST_STATE_RAF_LINKED_LIKE_CPP
        } else if rest_bonus >= 1.0 {
            REST_STATE_RESTED_LIKE_CPP
        } else {
            REST_STATE_NORMAL_LIKE_CPP
        };
        // The older legacy2 snapshot uses a `rest_bonus > 10` deadband here.
        // Current legacy1 uses `rest_bonus >= 1` with multi-type RestInfo and
        // is the selected port target; the divergence is retained as evidence
        // that matching one C++ tree alone is not proof that behavior is sound.
        let Some(()) = self.mutate_player_rest_state_like_cpp(|state| {
            state.rest_bonus = rest_bonus;
            state.rest_state = new_state;
        }) else {
            return 0;
        };
        let Some(new_threshold) = self.resolved_xp_rest_threshold_like_cpp() else {
            return 0;
        };
        let Some(new_state) = self.resolved_xp_rest_state_like_cpp() else {
            return 0;
        };
        // C++ writes both RestInfo fields after this combined early-return,
        // and `ModifyValue` marks both nested bits even if one value stayed
        // equal. Therefore every emitted SetRestBonus delta carries 0x07.
        let nested_mask = if old_threshold != new_threshold || old_state != new_state {
            0x07
        } else {
            0
        };
        nested_mask
    }

    pub(crate) fn add_represented_xp_rest_bonus_like_cpp(&mut self, rest_bonus: f32) -> u8 {
        let Some(current) = self.resolved_xp_rest_bonus_like_cpp() else {
            return 0;
        };
        let total = current + rest_bonus;
        self.set_represented_xp_rest_bonus_like_cpp(total)
    }

    fn calc_represented_xp_rest_extra_per_sec_like_cpp(&self, bubble: f32) -> Option<f32> {
        if !self.can_gain_represented_xp_rest_bonus_like_cpp()? {
            return Some(0.0);
        }
        Some(self.resolved_player_next_level_xp_like_cpp()? as f32 / 72_000.0 * bubble)
    }

    pub(crate) fn apply_offline_xp_rest_bonus_like_cpp(
        &mut self,
        logout_time_secs: u64,
        now_secs: u64,
        was_logout_resting: bool,
    ) -> f32 {
        // Issue #81 input hardening: both C++ references assume a valid past
        // logout timestamp and subtract into `uint32`, so zero/future rows can
        // wrap into an immediately capped bonus. Rust intentionally rejects
        // those corrupt persistence values rather than reproducing that bug.
        if logout_time_secs == 0 {
            return 0.0;
        }
        let Some(time_diff) = now_secs.checked_sub(logout_time_secs) else {
            return 0.0;
        };
        if time_diff == 0 {
            return 0.0;
        }

        let bubble = if was_logout_resting {
            REST_OFFLINE_TAVERN_OR_CITY_BUBBLE_LIKE_CPP
                * self.rest_offline_tavern_or_city_rate_like_cpp
        } else {
            REST_OFFLINE_WILDERNESS_BUBBLE_LIKE_CPP * self.rest_offline_wilderness_rate_like_cpp
        };
        let Some(extra_per_sec) = self.calc_represented_xp_rest_extra_per_sec_like_cpp(bubble)
        else {
            return 0.0;
        };
        let extra = time_diff as f32 * extra_per_sec;
        let _ = self.add_represented_xp_rest_bonus_like_cpp(extra);
        extra
    }

    fn update_represented_online_xp_rest_bonus_like_cpp(&mut self, now_secs: u64) -> (f32, u8) {
        let Some(rest_time) = self
            .player_rest_state_snapshot_like_cpp()
            .map(|state| state.rest_time_secs)
        else {
            return (0.0, 0);
        };
        if rest_time == 0 {
            return (0.0, 0);
        }
        let Some(time_diff) = now_secs.checked_sub(rest_time) else {
            return (0.0, 0);
        };
        if time_diff < 10 {
            return (0.0, 0);
        }

        if self
            .mutate_player_rest_state_like_cpp(|state| state.rest_time_secs = now_secs)
            .is_none()
        {
            return (0.0, 0);
        }
        let bubble = REST_ONLINE_INGAME_BUBBLE_LIKE_CPP * self.rest_ingame_rate_like_cpp;
        let Some(extra_per_sec) = self.calc_represented_xp_rest_extra_per_sec_like_cpp(bubble)
        else {
            return (0.0, 0);
        };
        let extra = time_diff as f32 * extra_per_sec;
        let nested_mask = self.add_represented_xp_rest_bonus_like_cpp(extra);
        (extra, nested_mask)
    }

    fn tick_represented_online_xp_rest_bonus_like_cpp(&mut self, now_secs: u64) {
        // C++ `RestMgr::Update` freezes the elapsed-time update behind
        // `roll_chance_i(3)`. Use the session's runtime RNG so the gate is
        // probabilistic in production and seedable in focused tests.
        let update_roll_passed = self.represented_urand_u32_like_cpp(1, 100) <= 3;
        self.tick_represented_online_xp_rest_bonus_with_roll_like_cpp(now_secs, update_roll_passed);
    }

    fn tick_represented_online_xp_rest_bonus_with_roll_like_cpp(
        &mut self,
        now_secs: u64,
        update_roll_passed: bool,
    ) {
        if !update_roll_passed {
            return;
        }
        let (_, nested_mask) = self.update_represented_online_xp_rest_bonus_like_cpp(now_secs);
        if nested_mask != 0 {
            self.send_represented_rest_info_update_like_cpp(nested_mask);
        }
    }

    fn revalidate_represented_tavern_resting_with_catalog_like_cpp(
        &mut self,
        area_trigger_db2_store: &AreaTriggerDb2Store,
    ) {
        let Some(rest) = self.player_rest_state_snapshot_like_cpp() else {
            return;
        };
        if (rest.rest_flag_mask & REST_FLAG_IN_TAVERN_LIKE_CPP) == 0 {
            return;
        }

        let Some(at_entry) = area_trigger_db2_store
            .get(rest.inn_area_trigger_id)
            .cloned()
        else {
            if self.remove_represented_rest_flag_like_cpp(REST_FLAG_IN_TAVERN_LIKE_CPP) {
                self.send_represented_resting_player_flag_update_like_cpp();
            }
            return;
        };

        if !self.player_is_in_area_trigger_radius_like_cpp(&at_entry)
            && self.remove_represented_rest_flag_like_cpp(REST_FLAG_IN_TAVERN_LIKE_CPP)
        {
            self.send_represented_resting_player_flag_update_like_cpp();
        }
    }

    #[cfg(test)]
    fn revalidate_represented_tavern_resting_like_cpp(&mut self) {
        let db2 = self
            .area_trigger_db2_store
            .clone()
            .unwrap_or_else(|| Arc::new(AreaTriggerDb2Store::from_entries([])));
        self.revalidate_represented_tavern_resting_with_catalog_like_cpp(db2.as_ref());
    }

    fn apply_represented_pct_modifier_to_u32_like_cpp(value: u32, pct: i32) -> u32 {
        let adjusted = i64::from(value) + (i64::from(value) * i64::from(pct)) / 100;
        adjusted.clamp(0, i64::from(u32::MAX)) as u32
    }

    pub(crate) fn represented_player_has_flag_like_cpp(&self, flag: u32) -> bool {
        let canonical = self
            .player_guid()
            .and_then(|guid| self.canonical_player_has_player_flag_like_cpp(guid, flag));
        if let Some(value) = canonical {
            return value;
        }
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            return self
                .represented_loaded_player_flags_like_cpp
                .is_some_and(|flags| (flags & flag) != 0);
        }
        false
    }

    pub(crate) fn represented_player_flags_value_like_cpp(&self) -> Option<u32> {
        let canonical =
            self.canonical_player_snapshot_like_cpp(|player| player.data().player_flags);
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return self.represented_loaded_player_flags_like_cpp;
        }
        canonical
    }

    pub(crate) fn void_storage_is_unlocked_like_cpp(&self) -> bool {
        self.represented_player_has_flag_like_cpp(PLAYER_FLAGS_VOID_UNLOCKED_LIKE_CPP)
    }

    /// Apply the already-committed void-storage unlock to runtime state and
    /// emit the same PlayerData::Flags values delta that C++ SetPlayerFlag does.
    pub(crate) fn apply_committed_void_storage_unlock_like_cpp(&mut self) {
        let values_update = self.player_values_update_snapshot().and_then(|mut player| {
            player.set_player_flag(PLAYER_FLAGS_VOID_UNLOCKED_LIKE_CPP);
            Some(player.values_update(true))
        });

        let Some(_current_flags) = self.represented_player_flags_value_like_cpp() else {
            return;
        };
        let _canonical = self
            .mutate_canonical_player_like_cpp(|player| {
                player.set_player_flag(PLAYER_FLAGS_VOID_UNLOCKED_LIKE_CPP);
            })
            .is_some();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_loaded_player_flags_like_cpp =
                Some(_current_flags | PLAYER_FLAGS_VOID_UNLOCKED_LIKE_CPP);
            self.represented_loaded_player_flags_applied_like_cpp = _canonical;
        }

        if let Some(update) = values_update {
            self.send_player_values_update_like_cpp(&update);
        }
    }

    fn represented_creature_has_loot_recipient_like_cpp(
        &self,
        creature_guid: wow_core::ObjectGuid,
    ) -> Option<bool> {
        if let Some(manager) = self.map_manager.as_ref() {
            let manager = manager
                .read()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if let Some(creature) =
                manager.find_creature(self.player_map_id_like_cpp(), 0, creature_guid)
            {
                return Some(creature.creature.has_loot_recipient());
            }
        }

        let key = self
            .current_canonical_player_map_key_like_cpp()
            .unwrap_or(wow_map::MapKey::new(
                u32::from(self.player_map_id_like_cpp()),
                0,
            ));
        let manager = self.canonical_map_manager.as_ref()?.lock().ok()?;
        manager
            .find_map(key.map_id, key.instance_id)?
            .map()
            .get_typed_creature(creature_guid)
            .map(|creature| creature.has_loot_recipient())
    }

    fn take_represented_xp_rest_bonus_for_gain_like_cpp(
        &mut self,
        xp: u32,
        victim: wow_core::ObjectGuid,
    ) -> (u32, u8) {
        if victim.is_empty() {
            return (0, 0);
        }

        let Some(current_rest_bonus) = self.resolved_xp_rest_bonus_like_cpp() else {
            return (0, 0);
        };
        let rested_bonus = (current_rest_bonus as u32).min(xp);
        let Some(rested_consumption_modifier) = self
            .resolved_total_represented_aura_modifier_like_cpp(
                RepresentedAuraEffectLikeCpp::ModRestedXpConsumption,
            )
        else {
            return (0, 0);
        };
        let rested_loss = Self::apply_represented_pct_modifier_to_u32_like_cpp(
            rested_bonus,
            rested_consumption_modifier,
        );
        // Both C++ RestMgr implementations call SetRestBonus unconditionally,
        // including when the float bonus truncates to a zero integer award.
        // That call normalizes a verbatim loaded RestState against the current
        // bonus even though no rested XP is awarded or consumed.
        let nested_mask =
            self.set_represented_xp_rest_bonus_like_cpp(current_rest_bonus - rested_loss as f32);
        (rested_bonus, nested_mask)
    }

    pub(crate) fn resolved_xp_rest_bonus_like_cpp(&self) -> Option<f32> {
        self.player_rest_state_snapshot_like_cpp()
            .map(|state| state.rest_bonus)
    }

    pub(crate) fn resolved_xp_rest_state_like_cpp(&self) -> Option<u8> {
        self.player_rest_state_snapshot_like_cpp()
            .map(|state| state.rest_state)
    }

    pub(crate) fn resolved_xp_rest_threshold_like_cpp(&self) -> Option<u32> {
        Some(
            self.resolved_xp_rest_bonus_like_cpp()?
                .clamp(0.0, u32::MAX as f32) as u32,
        )
    }

    #[cfg(test)]
    pub(crate) fn represented_xp_rest_bonus_like_cpp(&self) -> f32 {
        self.resolved_xp_rest_bonus_like_cpp()
            .expect("test Player rest owner must resolve")
    }

    #[cfg(test)]
    pub(crate) fn represented_xp_rest_state_like_cpp(&self) -> u8 {
        self.resolved_xp_rest_state_like_cpp()
            .expect("test Player rest owner must resolve")
    }

    #[cfg(test)]
    pub(crate) fn represented_xp_rest_threshold_like_cpp(&self) -> u32 {
        self.resolved_xp_rest_threshold_like_cpp()
            .expect("test Player rest owner must resolve")
    }

    fn update_represented_hostile_area_state_like_cpp(&mut self, zone: &wow_data::AreaTableEntry) {
        let war_mode_active = self.player_war_mode_local_active_like_cpp();
        let zone_hostile = if zone.is_sanctuary_like_cpp() {
            false
        } else if (zone.flags
            & (AREA_FLAG_FREE_FOR_ALL_PVP_LIKE_CPP | AREA_FLAG_COMBAT_ZONE_LIKE_CPP))
            != 0
        {
            true
        } else if (zone.flags & AREA_FLAG_ENEMIES_PVP_FLAGGED_LIKE_CPP) != 0 {
            if (zone.flags & AREA_FLAG_CONTESTED_LIKE_CPP) != 0 {
                war_mode_active
            } else {
                let faction_group_mask = self
                    .area_table_store
                    .as_ref()
                    .map(|store| store.faction_group_mask_like_cpp(zone.id))
                    .unwrap_or(0);
                self.player_faction_template_id_like_cpp()
                    .and_then(|id| {
                        self.faction_template_store
                            .as_ref()
                            .and_then(|store| store.get(id))
                    })
                    .is_some_and(|faction_template| {
                        if (faction_template.friend_group & faction_group_mask) != 0 {
                            false
                        } else if (faction_template.enemy_group & faction_group_mask) != 0 {
                            true
                        } else {
                            self.is_pvp_realm_like_cpp
                        }
                    })
            }
        } else {
            false
        };
        let _ = self.mutate_player_world_local_state_like_cpp(|state| {
            state.pvp_hostile = zone_hostile || war_mode_active;
        });
    }

    pub(crate) fn resolved_is_resting_like_cpp(&self) -> Option<bool> {
        self.player_rest_state_snapshot_like_cpp()
            .map(|state| state.rest_flag_mask != 0)
    }

    #[cfg(test)]
    pub(crate) fn represented_is_resting_like_cpp(&self) -> bool {
        self.resolved_is_resting_like_cpp()
            .expect("test Player rest owner must resolve")
    }

    pub(crate) fn resolved_visible_resting_like_cpp(&self) -> Option<bool> {
        let rest = self.player_rest_state_snapshot_like_cpp()?;
        if rest.location_initialized {
            return Some(rest.rest_flag_mask != 0);
        }

        let canonical = self.with_owned_player_for_rest_like_cpp(|player| {
            (player.data().player_flags & PLAYER_FLAGS_RESTING_LIKE_CPP) != 0
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(
                self.represented_loaded_player_flags_like_cpp
                    .map(|flags| (flags & PLAYER_FLAGS_RESTING_LIKE_CPP) != 0)
                    .unwrap_or(rest.rest_flag_mask != 0),
            );
        }
        canonical
    }

    #[cfg(test)]
    pub(crate) fn represented_visible_resting_like_cpp(&self) -> bool {
        self.resolved_visible_resting_like_cpp()
            .expect("test Player rest owner must resolve")
    }

    pub(crate) fn set_represented_rest_flag_like_cpp(
        &mut self,
        rest_flag: u32,
        trigger_id: u32,
    ) -> bool {
        self.mutate_player_rest_state_like_cpp(|state| {
            let old_mask = state.rest_flag_mask;
            state.location_initialized = true;
            state.rest_flag_mask |= rest_flag;
            let crossed_zero = old_mask == 0 && state.rest_flag_mask != 0;
            if crossed_zero {
                state.rest_time_secs = Self::current_game_time_secs_like_cpp();
            }
            if trigger_id != 0 {
                state.inn_area_trigger_id = trigger_id;
            }
            if crossed_zero && state.defer_flag_sync {
                state.deferred_flag_update_dirty = true;
            }
            crossed_zero
        })
        .unwrap_or(false)
    }

    pub(crate) fn remove_represented_rest_flag_like_cpp(&mut self, rest_flag: u32) -> bool {
        self.mutate_player_rest_state_like_cpp(|state| {
            let old_mask = state.rest_flag_mask;
            state.rest_flag_mask &= !rest_flag;
            if old_mask != state.rest_flag_mask {
                state.location_initialized = true;
            }
            if (rest_flag & REST_FLAG_IN_TAVERN_LIKE_CPP) != 0
                && (state.rest_flag_mask & REST_FLAG_IN_TAVERN_LIKE_CPP) == 0
            {
                state.inn_area_trigger_id = 0;
            }
            let crossed_zero = old_mask != 0 && state.rest_flag_mask == 0;
            if crossed_zero {
                state.rest_time_secs = 0;
                if state.defer_flag_sync {
                    state.deferred_flag_update_dirty = true;
                }
            }
            crossed_zero
        })
        .unwrap_or(false)
    }

    fn update_represented_rest_flag_like_cpp(&mut self, rest_flag: u32, active: bool) -> bool {
        if active {
            self.set_represented_rest_flag_like_cpp(rest_flag, 0)
        } else {
            self.remove_represented_rest_flag_like_cpp(rest_flag)
        }
    }

    pub(crate) fn set_represented_tavern_resting_like_cpp(
        &mut self,
        trigger_id: u32,
        entered: bool,
    ) -> bool {
        if entered {
            self.set_represented_rest_flag_like_cpp(REST_FLAG_IN_TAVERN_LIKE_CPP, trigger_id)
        } else {
            self.remove_represented_rest_flag_like_cpp(REST_FLAG_IN_TAVERN_LIKE_CPP)
        }
    }

    /// Mirror `Unit::SetPvpFlag` / `RemovePvpFlag` for the realm-wide FFA bit.
    ///
    /// The canonical player remains the runtime authority. The isolated delta
    /// keeps this direct owner update limited to `UnitData::PvpFlags` without
    /// clearing or leaking any other dirty canonical fields that the map tick
    /// still owns.
    fn set_represented_ffa_pvp_flag_like_cpp(&mut self, enabled: bool) -> bool {
        let update = self
            .mutate_canonical_player_like_cpp(|player| {
                let before = player.unit().pvp_flags_like_cpp();
                if before.contains(UnitPvpFlags::FFA_PVP) == enabled {
                    return None;
                }

                if enabled {
                    player
                        .unit_mut()
                        .set_pvp_flag_like_cpp(UnitPvpFlags::FFA_PVP);
                } else {
                    player
                        .unit_mut()
                        .remove_pvp_flag_like_cpp(UnitPvpFlags::FFA_PVP);
                }
                let after = player.unit().pvp_flags_like_cpp();

                let mut delta = Player::new(None, false);
                delta.unit_mut().replace_all_pvp_flags_like_cpp(before);
                delta.clear_data_changes();
                delta.unit_mut().replace_all_pvp_flags_like_cpp(after);
                Some(delta.values_update(true))
            })
            .flatten();
        let Some(update) = update else {
            return false;
        };

        self.send_player_values_update_like_cpp(&update);
        self.sync_player_registry_state_like_cpp();
        true
    }

    /// C++ `HandlePlayerLogin`: realm-wide FFA is enabled after the player is
    /// in the map, except for GMs and players whose loaded/zone-restored flags
    /// already say they are resting.
    fn apply_represented_ffa_pvp_login_state_like_cpp(&mut self) -> bool {
        if !self.is_ffa_pvp_realm_like_cpp
            || self.player_is_game_master_like_cpp() != Some(false)
            || self.resolved_visible_resting_like_cpp() != Some(false)
        {
            return false;
        }

        self.set_represented_ffa_pvp_flag_like_cpp(true)
    }

    pub(crate) fn handle_represented_tavern_area_trigger_with_catalog_like_cpp(
        &mut self,
        taverns: &TavernAreaTriggerStoreLikeCpp,
        trigger_id: u32,
        entered: bool,
    ) -> bool {
        if !self.represented_is_tavern_area_trigger_like_cpp(taverns, trigger_id) {
            return false;
        }

        if self.set_represented_tavern_resting_like_cpp(trigger_id, entered) {
            self.send_represented_resting_player_flag_update_like_cpp();
        }
        if self.is_ffa_pvp_realm_like_cpp {
            // C++ `MiscHandler.cpp::HandleAreaTriggerOpcode` toggles FFA
            // directly from `packet.Entered`, independently of RestMgr's
            // aggregate mask. Leaving an inn can therefore restore FFA while
            // a city/faction rest flag still keeps PLAYER_FLAGS_RESTING set.
            self.set_represented_ffa_pvp_flag_like_cpp(!entered);
        }
        true
    }

    #[cfg(test)]
    pub(crate) fn handle_represented_tavern_area_trigger_like_cpp(
        &mut self,
        trigger_id: u32,
        entered: bool,
    ) -> bool {
        let taverns = self
            .tavern_area_trigger_store
            .clone()
            .unwrap_or_else(|| Arc::new(TavernAreaTriggerStoreLikeCpp::default()));
        self.handle_represented_tavern_area_trigger_with_catalog_like_cpp(
            taverns.as_ref(),
            trigger_id,
            entered,
        )
    }

    pub(crate) fn send_represented_resting_player_flag_update_like_cpp(&self) {
        let Some(guid) = self.player_guid() else {
            return;
        };
        let Some(mut player) = self.player_values_update_snapshot() else {
            return;
        };

        let canonical_flags = self
            .canonical_player_snapshot_like_cpp(|player| player.data().player_flags)
            .unwrap_or_default();
        let Some(is_resting) = self.resolved_is_resting_like_cpp() else {
            return;
        };
        if is_resting {
            player.replace_all_player_flags(canonical_flags & !PLAYER_FLAGS_RESTING_LIKE_CPP);
            player.set_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
        } else {
            player.replace_all_player_flags(canonical_flags | PLAYER_FLAGS_RESTING_LIKE_CPP);
            player.remove_player_flag(PLAYER_FLAGS_RESTING_LIKE_CPP);
        }
        let update = player.values_update(true);
        if let Some(packet) =
            player_values_update_to_update_object(guid, self.player_map_id_like_cpp(), &update)
        {
            self.send_packet(&packet);
        }
    }

    pub(crate) fn send_represented_rest_info_update_like_cpp(&self, nested_mask: u8) {
        let Some(guid) = self.player_guid() else {
            return;
        };
        let mut player = Player::new(None, false);
        let Some(rest_threshold) = self.resolved_xp_rest_threshold_like_cpp() else {
            return;
        };
        let Some(rest_state) = self.resolved_xp_rest_state_like_cpp() else {
            return;
        };
        player.prepare_rest_info_values_update_like_cpp(0, rest_threshold, rest_state, nested_mask);
        let update = player.values_update(true);
        if let Some(packet) =
            player_values_update_to_update_object(guid, self.player_map_id_like_cpp(), &update)
        {
            self.send_packet(&packet);
        }
    }

    fn resolved_player_flags_for_rest_state_save_like_cpp(&self) -> Option<u32> {
        let canonical_flags =
            self.with_owned_player_for_rest_like_cpp(|player| player.data().player_flags);
        #[cfg(test)]
        let canonical_flags = if canonical_flags.is_none() && self.player_handle_like_cpp.is_none()
        {
            self.represented_loaded_player_flags_like_cpp.or(Some(0))
        } else {
            canonical_flags
        };
        let mut player_flags = canonical_flags?;
        let rest = self.player_rest_state_snapshot_like_cpp()?;
        if rest.location_initialized {
            if rest.rest_flag_mask != 0 {
                player_flags |= PLAYER_FLAGS_RESTING_LIKE_CPP;
            } else {
                player_flags &= !PLAYER_FLAGS_RESTING_LIKE_CPP;
            }
        }
        Some(player_flags)
    }

    pub(crate) fn resolved_player_flags_for_create_like_cpp(&self) -> Option<(u32, u32)> {
        let player_flags = self.resolved_player_flags_for_rest_state_save_like_cpp()?;
        let canonical_flags_ex =
            self.with_owned_player_for_rest_like_cpp(|player| player.data().player_flags_ex);
        #[cfg(test)]
        let canonical_flags_ex =
            if canonical_flags_ex.is_none() && self.player_handle_like_cpp.is_none() {
                self.represented_loaded_player_flags_ex_like_cpp.or(Some(0))
            } else {
                canonical_flags_ex
            };
        let player_flags_ex = canonical_flags_ex?;
        Some((player_flags, player_flags_ex))
    }

    #[cfg(test)]
    fn represented_player_flags_for_rest_state_save_like_cpp(&self) -> u32 {
        self.resolved_player_flags_for_rest_state_save_like_cpp()
            .unwrap_or_else(|| self.represented_loaded_player_flags_like_cpp.unwrap_or(0))
    }

    #[cfg(test)]
    pub(crate) fn represented_player_flags_for_create_like_cpp(&self) -> (u32, u32) {
        self.resolved_player_flags_for_create_like_cpp()
            .unwrap_or_else(|| {
                (
                    self.represented_loaded_player_flags_like_cpp.unwrap_or(0),
                    self.represented_loaded_player_flags_ex_like_cpp
                        .unwrap_or(0),
                )
            })
    }

    fn resolved_current_player_xp_persistence_request_like_cpp(
        &self,
        level_changed: bool,
        rest_info_changed: bool,
        guid_counter: u64,
    ) -> Option<wow_persistence::PlayerXpPersistenceRequestLikeCpp> {
        let rest = if rest_info_changed {
            Some(wow_persistence::PlayerXpRestStateSaveLikeCpp {
                rest_state: self.resolved_xp_rest_state_like_cpp()?,
                player_flags: self.resolved_player_flags_for_rest_state_save_like_cpp()?,
                rest_bonus: Self::sanitize_rest_bonus_like_cpp(
                    self.resolved_xp_rest_bonus_like_cpp()?,
                ),
            })
        } else {
            None
        };
        Some(wow_persistence::PlayerXpPersistenceRequestLikeCpp {
            player_guid: guid_counter,
            level_changed,
            level: self.player_level_like_cpp(),
            xp: self.resolved_player_xp_like_cpp()?,
            rest,
        })
    }

    #[cfg(test)]
    fn current_player_xp_persistence_request_like_cpp(
        &self,
        level_changed: bool,
        rest_info_changed: bool,
        guid_counter: u64,
    ) -> wow_persistence::PlayerXpPersistenceRequestLikeCpp {
        wow_persistence::PlayerXpPersistenceRequestLikeCpp {
            player_guid: guid_counter,
            level_changed,
            level: self.player_level_like_cpp(),
            xp: self.player_xp_like_cpp(),
            rest: rest_info_changed.then(|| wow_persistence::PlayerXpRestStateSaveLikeCpp {
                rest_state: self.represented_xp_rest_state_like_cpp(),
                player_flags: self.represented_player_flags_for_rest_state_save_like_cpp(),
                rest_bonus: Self::sanitize_rest_bonus_like_cpp(
                    self.represented_xp_rest_bonus_like_cpp(),
                ),
            }),
        }
    }

    fn represented_xp_rest_info_changed_since_like_cpp(
        &self,
        old_rest_bonus: f32,
        old_rest_state: u8,
    ) -> bool {
        self.resolved_xp_rest_bonus_like_cpp()
            .zip(self.resolved_xp_rest_state_like_cpp())
            .is_some_and(|(bonus, state)| {
                bonus.to_bits() != old_rest_bonus.to_bits() || state != old_rest_state
            })
    }

    pub(crate) fn current_played_time_values_like_cpp(&self) -> (u32, u32) {
        let session_secs: u32 = self
            .login_time
            .map(|time| time.elapsed().as_secs() as u32)
            .unwrap_or(0);
        (
            self.total_played_time.saturating_add(session_secs),
            self.level_played_time.saturating_add(session_secs),
        )
    }

    async fn process_pending_periodic_player_save_with_generator_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
    ) {
        if !self.pending_periodic_player_save_like_cpp || self.state != SessionState::LoggedIn {
            return;
        }
        if self.pending_teleport_save_destination_like_cpp().is_some() {
            return;
        }

        self.save_current_player_to_db_with_generator_like_cpp(item_guid_generator)
            .await;
    }

    #[cfg(test)]
    async fn process_pending_periodic_player_save_like_cpp(&mut self) {
        let generators = self.id_generators_for_test_like_cpp();
        self.process_pending_periodic_player_save_with_generator_like_cpp(generators.item.as_ref())
            .await;
    }

    pub(crate) fn player_talent_runtime_snapshot_like_cpp(
        &self,
    ) -> Option<wow_entities::PlayerTalentRuntimeState> {
        let canonical =
            self.with_owned_player_like_cpp(|player| player.talent_runtime_like_cpp().clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(wow_entities::PlayerTalentRuntimeState {
                talent_groups: self.represented_talents_like_cpp.clone(),
                talents_loaded: self.represented_talents_loaded_like_cpp,
                glyph_groups: self.represented_glyphs_like_cpp,
                glyphs_loaded: self.represented_glyphs_loaded_like_cpp,
                active_group: self.represented_active_talent_group_like_cpp,
                bonus_groups: self.represented_bonus_talent_groups_like_cpp,
                reset_talents_cost: self.represented_talent_reset_cost_like_cpp,
                reset_talents_time_secs: self.represented_talent_reset_time_secs_like_cpp,
            });
        }
        canonical
    }

    pub(crate) fn replace_player_talent_runtime_like_cpp(
        &mut self,
        runtime: wow_entities::PlayerTalentRuntimeState,
    ) -> bool {
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                player.replace_talent_runtime_like_cpp(runtime.clone())
            })
            .is_some();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_talents_like_cpp = runtime.talent_groups;
            self.represented_talents_loaded_like_cpp = runtime.talents_loaded;
            self.represented_glyphs_like_cpp = runtime.glyph_groups;
            self.represented_glyphs_loaded_like_cpp = runtime.glyphs_loaded;
            self.represented_active_talent_group_like_cpp = runtime.active_group;
            self.represented_bonus_talent_groups_like_cpp = runtime.bonus_groups;
            self.represented_talent_reset_cost_like_cpp = runtime.reset_talents_cost;
            self.represented_talent_reset_time_secs_like_cpp = runtime.reset_talents_time_secs;
            return true;
        }
        canonical
    }

    fn mutate_player_talent_runtime_like_cpp<R>(
        &mut self,
        f: impl FnOnce(&mut wow_entities::PlayerTalentRuntimeState) -> R,
    ) -> Option<R> {
        let mut runtime = self.player_talent_runtime_snapshot_like_cpp()?;
        let result = f(&mut runtime);
        self.replace_player_talent_runtime_like_cpp(runtime)
            .then_some(result)
    }

    pub(crate) fn reset_represented_glyphs_like_cpp(&mut self) {
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        let _ = self.mutate_player_talent_runtime_like_cpp(|runtime| {
            runtime.glyph_groups = [[0; wow_entities::PLAYER_MAX_GLYPH_SLOTS_LIKE_CPP];
                wow_entities::PLAYER_MAX_SPECIALIZATIONS_LIKE_CPP];
            runtime.glyphs_loaded = false;
        });
    }

    pub(crate) fn mark_represented_glyphs_loaded_like_cpp(&mut self) {
        let _ = self.mutate_player_talent_runtime_like_cpp(|runtime| {
            runtime.glyphs_loaded = true;
        });
    }

    pub(crate) fn set_represented_active_talent_group_like_cpp(
        &mut self,
        active_group: u8,
    ) -> bool {
        let active_group = active_group.min((MAX_SPECIALIZATIONS_LIKE_CPP - 1) as u8);
        if self.represented_active_talent_group_like_cpp() != Some(active_group) {
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        self.mutate_player_talent_runtime_like_cpp(|runtime| runtime.active_group = active_group)
            .is_some()
    }

    pub(crate) fn represented_active_talent_group_like_cpp(&self) -> Option<u8> {
        self.player_talent_runtime_snapshot_like_cpp()
            .map(|runtime| runtime.active_group)
    }

    pub(crate) fn represented_action_button_db_context_like_cpp(&self) -> Option<(u8, i32)> {
        // Trait-config-specific action bars are not represented yet. Both load and save must use
        // the same C++ fallback context so an autosave cannot mutate rows it never loaded.
        Some((self.represented_active_talent_group_like_cpp()?, 0))
    }

    pub(crate) fn set_represented_bonus_talent_groups_like_cpp(
        &mut self,
        bonus_groups: u8,
    ) -> bool {
        let bonus_groups = bonus_groups.min((MAX_SPECIALIZATIONS_LIKE_CPP - 1) as u8);
        self.mutate_player_talent_runtime_like_cpp(|runtime| runtime.bonus_groups = bonus_groups)
            .is_some()
    }

    pub(crate) fn reset_represented_talents_like_cpp(&mut self) {
        let _ = self.mutate_player_talent_runtime_like_cpp(|runtime| {
            for talents in &mut runtime.talent_groups {
                talents.clear();
            }
            runtime.talents_loaded = false;
        });
        // Login reconstructs a fresh C++ Player after this reset. Retaining the
        // previous character's runtime edges would affect GetCastSpellInfo, and
        // retaining per-spell traits could contaminate a coincident spell ID.
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.override_spells.clear();
            runtime.trait_definition_ids.clear();
            runtime.trait_config_rows.clear();
            runtime.trait_config_rows_complete = false;
            runtime.trait_entry_rows_complete = false;
            runtime.trait_entry_rows_empty = false;
        });
        self.invalidate_represented_spell_acquisition_auxiliary_authority_like_cpp();
    }

    pub(crate) fn reset_represented_active_talents_like_cpp(&mut self) -> bool {
        let Some(talent_group) = self.represented_active_talent_group_like_cpp() else {
            return false;
        };
        let talent_group_index = usize::from(talent_group);
        if talent_group_index >= MAX_SPECIALIZATIONS_LIKE_CPP {
            return false;
        }

        let Some(active_talents) = self
            .mutate_player_talent_runtime_like_cpp(|runtime| {
                runtime
                    .talents_loaded
                    .then(|| std::mem::take(&mut runtime.talent_groups[talent_group_index]))
            })
            .flatten()
        else {
            return false;
        };
        for (talent_id, rank) in active_talents {
            self.remove_represented_active_talent_side_effects_like_cpp(talent_id, rank);
        }
        self.refresh_represented_talent_points_like_cpp();
        true
    }

    pub(crate) fn apply_represented_login_talent_reset_if_needed_like_cpp(&mut self) -> bool {
        const AT_LOGIN_RESET_TALENTS_LIKE_CPP: u16 = 0x004;

        if !self
            .resolved_represented_at_login_flags_like_cpp()
            .is_some_and(|flags| (flags & AT_LOGIN_RESET_TALENTS_LIKE_CPP) != 0)
        {
            return false;
        }

        self.record_represented_talent_reset_script_hook_like_cpp(true);
        self.remove_represented_at_login_flag_like_cpp(AT_LOGIN_RESET_TALENTS_LIKE_CPP, true);
        self.remove_represented_pet_not_in_slot_like_cpp();

        if self.reset_represented_active_talents_like_cpp() {
            let Some(talent_data) = self.resolved_update_talent_data_packet_like_cpp() else {
                return false;
            };
            self.send_packet(&talent_data);
            self.send_notification_like_cpp(self.reset_talents_notification_text_like_cpp());
            return true;
        }

        false
    }

    pub(crate) fn apply_represented_login_spell_reset_if_needed_like_cpp(&mut self) -> bool {
        const AT_LOGIN_RESET_SPELLS_LIKE_CPP: u16 = 0x002;

        if !self
            .resolved_represented_at_login_flags_like_cpp()
            .is_some_and(|flags| (flags & AT_LOGIN_RESET_SPELLS_LIKE_CPP) != 0)
        {
            return false;
        }

        self.remove_represented_at_login_flag_like_cpp(AT_LOGIN_RESET_SPELLS_LIKE_CPP, true);
        let spells = self.known_spells_like_cpp().to_vec();
        for spell_id in spells {
            self.remove_known_spell_like_cpp(spell_id);
        }
        self.apply_represented_quest_rewarded_spells_like_cpp();
        self.send_notification_like_cpp(self.reset_spells_notification_text_like_cpp());
        true
    }

    pub(crate) fn apply_represented_first_login_flag_if_needed_like_cpp(&mut self) -> bool {
        const AT_LOGIN_FIRST_LIKE_CPP: u16 = 0x020;

        if !self
            .resolved_represented_at_login_flags_like_cpp()
            .is_some_and(|flags| (flags & AT_LOGIN_FIRST_LIKE_CPP) != 0)
        {
            return false;
        }

        self.remove_represented_at_login_flag_like_cpp(AT_LOGIN_FIRST_LIKE_CPP, false)
    }

    pub(crate) fn load_represented_explored_zones_like_cpp(&mut self, input: &str) -> usize {
        let blocks = parse_explored_zones_db_string_like_cpp(input);
        let Some(previous) = self.player_explored_zones_snapshot_like_cpp() else {
            return 0;
        };
        let changed = previous != blocks;

        let canonical = self
            .mutate_canonical_player_like_cpp(|player| {
                let applied = player.set_explored_zones_blocks_like_cpp(&blocks);
                (applied > 0).then(|| player.values_update(true))
            })
            .flatten();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_explored_zones_like_cpp = blocks;
        }
        if let Some(update) = canonical {
            self.send_player_values_update_like_cpp(&update);
        }

        if changed {
            blocks.iter().filter(|block| **block != 0).count()
        } else {
            0
        }
    }

    pub(crate) fn player_explored_zones_snapshot_like_cpp(
        &self,
    ) -> Option<[u64; PLAYER_EXPLORED_ZONES_SIZE_LIKE_CPP]> {
        let canonical =
            self.with_owned_player_like_cpp(|player| *player.explored_zones_blocks_like_cpp());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(self.represented_explored_zones_like_cpp);
        }
        canonical
    }

    pub(crate) fn represented_explored_zones_db_string_like_cpp(&self) -> Option<String> {
        Some(explored_zones_db_string_from_blocks_like_cpp(
            &self.player_explored_zones_snapshot_like_cpp()?,
        ))
    }

    /// Represented C++ `Player::UpdateArea` criteria branch.
    ///
    /// C++ records `EnterArea`/`LeaveArea` after updating area-dependent state when
    /// `oldArea != newArea`; this represented slice records those criteria and
    /// the C++ area rest flag side effects. PvP flags, phasing, aura checks, quest push, mount
    /// capability refresh, and chat-channel updates remain runtime gaps.
    pub(crate) fn update_area_represented_like_cpp(&mut self, new_area: u32) -> bool {
        self.update_area_represented_with_rest_update_like_cpp(new_area, true)
    }

    fn update_area_represented_with_rest_update_like_cpp(
        &mut self,
        new_area: u32,
        send_rest_update: bool,
    ) -> bool {
        let Some(world_local) = self.player_world_local_state_like_cpp() else {
            return false;
        };
        let old_area = world_local.area_id;
        if old_area != new_area {
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        if self
            .mutate_player_world_local_state_like_cpp(|state| {
                if old_area != new_area {
                    state.zone_area_authority_complete = false;
                }
                state.area_id = new_area;
            })
            .is_none()
        {
            return false;
        }
        let zone_id = world_local.zone_id;
        let _ = self.with_owned_player_mut_like_cpp(|player| {
            player
                .unit_mut()
                .world_mut()
                .set_zone_and_area(zone_id, new_area);
        });

        let mut rest_changed = false;
        let area_resting = self.area_table_store.as_ref().and_then(|store| {
            store.get(new_area).map(|area| {
                let team = player_team_for_race_cpp(self.player_race_like_cpp());
                match team {
                    Team::Alliance => area.alliance_resting_like_cpp(),
                    Team::Horde | Team::Other => area.horde_resting_like_cpp(),
                }
            })
        });
        rest_changed |= self.update_represented_rest_flag_like_cpp(
            REST_FLAG_IN_FACTION_AREA_LIKE_CPP,
            area_resting.unwrap_or(false),
        );
        if send_rest_update && rest_changed {
            self.send_represented_resting_player_flag_update_like_cpp();
        }

        if old_area == new_area {
            return false;
        }

        #[cfg(test)]
        {
            self.represented_area_zone_criteria_like_cpp
                .push(RepresentedAreaZoneCriteriaLikeCpp::EnterArea(new_area));
            self.represented_area_zone_criteria_like_cpp
                .push(RepresentedAreaZoneCriteriaLikeCpp::LeaveArea(old_area));
        }
        true
    }

    /// Represented C++ `Player::UpdateZone` criteria branch.
    ///
    /// C++ first updates `m_zoneUpdateId`, then calls `UpdateArea(newArea)`, then
    /// returns early if the new zone has no `AreaTableEntry`. Therefore top-level
    /// area criteria are recorded only when the zone changes and the new zone row
    /// exists, while area criteria may already have been recorded by `UpdateArea`.
    pub(crate) fn update_zone_represented_like_cpp(
        &mut self,
        new_zone: u32,
        new_area: u32,
    ) -> bool {
        self.update_zone_represented_with_rest_update_like_cpp(new_zone, new_area, true)
    }

    pub(crate) fn update_zone_represented_without_rest_update_packet_like_cpp(
        &mut self,
        new_zone: u32,
        new_area: u32,
    ) -> bool {
        self.update_zone_represented_with_rest_update_like_cpp(new_zone, new_area, false)
    }

    pub(crate) fn take_deferred_rest_flag_update_dirty_like_cpp(&mut self) -> bool {
        self.mutate_player_rest_state_like_cpp(|state| {
            std::mem::take(&mut state.deferred_flag_update_dirty)
        })
        .unwrap_or(false)
    }

    fn update_zone_represented_with_rest_update_like_cpp(
        &mut self,
        new_zone: u32,
        new_area: u32,
        send_rest_update: bool,
    ) -> bool {
        if self.player_guid().is_none() {
            return false;
        }

        let Some(world_local) = self.player_world_local_state_like_cpp() else {
            return false;
        };
        let old_zone = world_local.zone_id;
        if old_zone != new_zone {
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        if self
            .mutate_player_world_local_state_like_cpp(|state| {
                if old_zone != new_zone {
                    state.zone_area_authority_complete = false;
                }
                state.zone_id = new_zone;
            })
            .is_none()
        {
            return false;
        }
        let area_id = world_local.area_id;
        let _ = self.with_owned_player_mut_like_cpp(|player| {
            player
                .unit_mut()
                .world_mut()
                .set_zone_and_area(new_zone, area_id);
        });
        if self
            .mutate_player_rest_state_like_cpp(|state| {
                state.deferred_flag_update_dirty = false;
                state.defer_flag_sync = true;
            })
            .is_none()
        {
            return false;
        }
        self.update_area_represented_with_rest_update_like_cpp(new_area, false);

        let zone_entry = self
            .area_table_store
            .as_ref()
            .and_then(|store| store.get(new_zone).copied());
        let Some(zone) = zone_entry else {
            let rest_flag_update_dirty = self
                .mutate_player_rest_state_like_cpp(|state| {
                    state.defer_flag_sync = false;
                    state.deferred_flag_update_dirty
                })
                .unwrap_or(false);
            if send_rest_update && rest_flag_update_dirty {
                self.send_represented_resting_player_flag_update_like_cpp();
                let _ = self.mutate_player_rest_state_like_cpp(|state| {
                    state.deferred_flag_update_dirty = false;
                });
            }
            return true;
        };

        self.update_represented_hostile_area_state_like_cpp(&zone);
        let Some(world_local) = self.player_world_local_state_like_cpp() else {
            return false;
        };
        // C++ keeps an existing city-rest flag in a hostile, non-sanctuary
        // LinkedChat zone. It removes the flag only in the outer non-LinkedChat
        // branch; the hostile inner branch performs no RestMgr mutation.
        if zone.linked_chat_like_cpp() {
            if !world_local.pvp_hostile || zone.is_sanctuary_like_cpp() {
                self.set_represented_rest_flag_like_cpp(REST_FLAG_IN_CITY_LIKE_CPP, 0);
            }
        } else {
            self.remove_represented_rest_flag_like_cpp(REST_FLAG_IN_CITY_LIKE_CPP);
        }
        let rest_flag_update_dirty = self
            .mutate_player_rest_state_like_cpp(|state| {
                state.defer_flag_sync = false;
                state.deferred_flag_update_dirty
            })
            .unwrap_or(false);
        if send_rest_update && rest_flag_update_dirty {
            self.send_represented_resting_player_flag_update_like_cpp();
            let _ = self.mutate_player_rest_state_like_cpp(|state| {
                state.deferred_flag_update_dirty = false;
            });
        }

        if old_zone == new_zone {
            return false;
        }

        #[cfg(test)]
        {
            self.represented_area_zone_criteria_like_cpp.push(
                RepresentedAreaZoneCriteriaLikeCpp::EnterTopLevelArea(new_zone),
            );
            self.represented_area_zone_criteria_like_cpp.push(
                RepresentedAreaZoneCriteriaLikeCpp::LeaveTopLevelArea(old_zone),
            );
        }
        true
    }

    /// Represented C++ `Player::CheckAreaExploreAndOutdoor` discovery branch.
    ///
    /// This slice covers `AreaTableEntry::AreaBit`, `AddExploredZones`, the player-values update,
    /// `CriteriaType::RevealWorldMapOverlay`, the exploration XP branch, and the
    /// `CONFIG_VMAP_INDOOR_CHECK` aura-removal branch when a represented
    /// `WorldObject::IsOutdoors()` value is available. Terrain/VMAP ownership of
    /// the outdoors state remains a map-runtime gap.
    pub(crate) async fn check_area_explore_and_outdoor_represented_like_cpp(
        &mut self,
        area_id: u32,
    ) -> bool {
        if self.resolved_player_is_alive_like_cpp() != Some(true) {
            return false;
        }

        if self.resolved_is_in_taxi_flight_like_cpp() != Some(false) {
            return false;
        }

        self.remove_indoor_outdoor_auras_for_current_position_represented_like_cpp();

        if area_id == 0 {
            return false;
        }

        let Some(area_entry) = self
            .area_table_store
            .as_ref()
            .and_then(|store| store.get(area_id))
            .copied()
        else {
            return false;
        };

        let Some((offset, mask)) =
            area_entry.explored_zone_bit_like_cpp(PLAYER_EXPLORED_ZONES_SIZE_LIKE_CPP)
        else {
            return false;
        };

        let Some(explored_zones) = self.player_explored_zones_snapshot_like_cpp() else {
            return false;
        };
        if explored_zones[offset] & mask != 0 {
            return false;
        }

        #[cfg(test)]
        self.represented_reveal_world_map_overlay_criteria_like_cpp
            .push(area_id);

        if let Some(update) = self.mutate_canonical_player_like_cpp(|player| {
            player.add_explored_zones_like_cpp(offset, mask);
            player.values_update(true)
        }) {
            self.send_player_values_update_like_cpp(&update);
        }

        if area_entry.exploration_level > 0 {
            use wow_packet::packets::misc::ExplorationExperience;

            let max_level = max_level_for_expansion_like_cpp(self.server_expansion_like_cpp);
            let xp = if self.player_level_like_cpp() >= max_level {
                0
            } else {
                self.exploration_base_xp_store
                    .as_ref()
                    .map(|store| {
                        store.exploration_xp_reward_like_cpp(
                            self.player_level_like_cpp(),
                            area_entry.exploration_level,
                            self.exploration_xp_rate_like_cpp,
                            self.min_discovered_scaled_xp_ratio_like_cpp,
                        )
                    })
                    .unwrap_or(0)
            };

            if xp != 0 {
                self.give_xp(xp, ObjectGuid::EMPTY, 1.0).await;
            }
            self.send_packet(&ExplorationExperience {
                area_id: area_id as i32,
                experience: xp as i32,
            });
        }

        true
    }

    fn remove_indoor_outdoor_auras_for_current_position_represented_like_cpp(&mut self) -> usize {
        if !self.vmap_indoor_check_like_cpp {
            return 0;
        }

        let Some(is_outdoors) = self
            .player_world_local_state_like_cpp()
            .and_then(|state| state.is_outdoors)
        else {
            return 0;
        };

        let attribute = if is_outdoors {
            wow_data::spell::attributes::SPELL_ATTR0_ONLY_INDOORS
        } else {
            wow_data::spell::attributes::SPELL_ATTR0_ONLY_OUTDOORS
        };
        self.remove_represented_auras_with_attribute0_like_cpp(attribute)
    }

    #[cfg(test)]
    pub(crate) fn represented_reveal_world_map_overlay_criteria_like_cpp(&self) -> &[u32] {
        &self.represented_reveal_world_map_overlay_criteria_like_cpp
    }

    #[cfg(test)]
    pub(crate) fn represented_area_zone_criteria_like_cpp(
        &self,
    ) -> &[RepresentedAreaZoneCriteriaLikeCpp] {
        &self.represented_area_zone_criteria_like_cpp
    }

    /// Represented C++ first-login `PlayerInfo::castSpells[GetCreateMode()]`.
    ///
    /// C++ executes these casts after clearing `AT_LOGIN_FIRST` and before
    /// `CONFIG_START_ALL_EXPLORED` / `CONFIG_START_ALL_REP`. This slice uses the
    /// represented spell executor; full triggered-cast semantics still depend on
    /// the remaining Spell runtime port.
    pub(crate) async fn apply_represented_first_login_cast_spells_with_catalogs_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
        player_bootstrap: &PlayerBootstrapCatalogsLikeCpp,
    ) -> usize {
        let Some(player_guid) = self.player_guid() else {
            return 0;
        };
        let Some(create_mode) = self.player_create_mode_like_cpp() else {
            return 0;
        };
        let spells = player_bootstrap
            .cast_spells
            .cast_spells_like_cpp(
                self.player_race_like_cpp(),
                self.player_class_like_cpp(),
                create_mode,
            )
            .to_vec();

        let mut cast_count = 0usize;
        for spell_id in spells {
            if self
                .execute_spell_with_generator_like_cpp(
                    item_guid_generator,
                    spell_id as i32,
                    player_guid,
                )
                .await
                .is_ok()
            {
                cast_count += 1;
            }
        }

        cast_count
    }

    #[cfg(test)]
    pub(crate) async fn apply_represented_first_login_cast_spells_like_cpp(&mut self) -> usize {
        let generators = self.id_generators_for_test_like_cpp();
        let player_bootstrap = self.player_bootstrap_catalogs_for_test_like_cpp();
        self.apply_represented_first_login_cast_spells_with_catalogs_like_cpp(
            generators.item.as_ref(),
            &player_bootstrap,
        )
        .await
    }

    /// Represented C++ `Player::LearnCustomSpells` / `CONFIG_START_ALL_SPELLS`.
    ///
    /// C++ calls `AddSpell` while the player is not in world, so the full port
    /// still needs character_spell persistence semantics. This represented slice
    /// mirrors the login spell snapshot: configured custom spells are included in
    /// `INITIAL_SPELLS` without duplicating spells already loaded from DB/DBC.
    pub(crate) fn apply_represented_start_all_spells_with_catalogs_like_cpp(
        &mut self,
        player_bootstrap: &PlayerBootstrapCatalogsLikeCpp,
        known_spells: &mut Vec<i32>,
    ) -> usize {
        if !self.start_all_spells_like_cpp() {
            return 0;
        }

        let spells = player_bootstrap
            .custom_spells
            .custom_spells_like_cpp(self.player_race_like_cpp(), self.player_class_like_cpp())
            .to_vec();

        let mut applied = 0usize;
        for spell_id in spells {
            let Ok(spell_id) = i32::try_from(spell_id) else {
                continue;
            };
            if !known_spells.contains(&spell_id) {
                known_spells.push(spell_id);
                applied += 1;
            }
            let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
                runtime.dependent_known_spells.insert(spell_id);
            });
        }

        applied
    }

    #[cfg(test)]
    pub(crate) fn apply_represented_start_all_spells_like_cpp(
        &mut self,
        known_spells: &mut Vec<i32>,
    ) -> usize {
        let player_bootstrap = self.player_bootstrap_catalogs_for_test_like_cpp();
        self.apply_represented_start_all_spells_with_catalogs_like_cpp(
            &player_bootstrap,
            known_spells,
        )
    }

    /// Represented C++ `Player::LearnQuestRewardedSpells`.
    ///
    /// C++ casts each rewarded quest's `RewardSpell` only when that spell exists,
    /// has a missing `SPELL_EFFECT_LEARN_SPELL` trigger, and the first learned
    /// spell is tied to `SKILL_LINE_ABILITY_REWARDED_FROM_QUEST` when it is not
    /// already known. This represented slice applies only the resulting direct
    /// learned-spell side effect; full `CastSpell` runtime semantics remain in
    /// the spell-system roadmap.
    pub(crate) fn apply_represented_quest_rewarded_spells_like_cpp(&mut self) -> usize {
        let Some(quest_store) = self.quest_store.clone() else {
            return 0;
        };

        let Some(quests) = self.player_quest_gameplay_snapshot_like_cpp() else {
            return 0;
        };
        let mut quest_ids = quests
            .rewarded_quest_ids
            .iter()
            .copied()
            .collect::<Vec<_>>();
        quest_ids.sort_unstable();

        let mut learned = 0usize;
        for quest_id in quest_ids {
            let Some(quest) = quest_store.get(quest_id) else {
                continue;
            };
            if quest.reward_spell == u32::MAX && quest.source_spell_id != 0 {
                let Ok(source_spell_id) = i32::try_from(quest.source_spell_id) else {
                    continue;
                };
                learned += self.remove_represented_auras_due_to_spell_like_cpp(source_spell_id);
                continue;
            }
            for spell_id in self.represented_quest_rewarded_spell_triggers_like_cpp(quest) {
                self.learn_known_spell_like_cpp(spell_id);
                learned += 1;
            }
        }

        learned
    }

    fn represented_quest_rewarded_spell_triggers_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> Vec<i32> {
        if quest.reward_spell == 0 {
            return Vec::new();
        }

        let Ok(reward_spell_id) = i32::try_from(quest.reward_spell) else {
            return Vec::new();
        };

        let Some(spell_info) = self
            .spell_store()
            .and_then(|store| store.get(reward_spell_id))
        else {
            return Vec::new();
        };

        let missing_learn_triggers = spell_info
            .effects()
            .iter()
            .filter(|effect| {
                effect.effect == wow_data::spell::spell_effect_types::SPELL_EFFECT_LEARN_SPELL
                    && effect.effect_trigger_spell > 0
                    && !self
                        .known_spells_like_cpp()
                        .contains(&effect.effect_trigger_spell)
            })
            .map(|effect| effect.effect_trigger_spell)
            .collect::<Vec<_>>();

        if missing_learn_triggers.is_empty() || spell_info.effects().is_empty() {
            return Vec::new();
        }

        let learned_0 = spell_info.effects()[0].effect_trigger_spell;
        if learned_0 > 0
            && !self.known_spells_like_cpp().contains(&learned_0)
            && !self.skill_store().is_some_and(|store| {
                store
                    .get_skill_line_ability_map_bounds_like_cpp(learned_0)
                    .iter()
                    .any(|ability| {
                        ability.acquire_method
                            == wow_data::skill::SKILL_LINE_ABILITY_REWARDED_FROM_QUEST_LIKE_CPP
                    })
            })
        {
            return Vec::new();
        }

        missing_learn_triggers
    }

    pub(crate) fn remove_represented_auras_due_to_spell_like_cpp(
        &mut self,
        spell_id: i32,
    ) -> usize {
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return 0;
        };
        let slots = visible_auras
            .values()
            .filter_map(|aura| (aura.spell_id == spell_id).then_some(aura.slot))
            .collect::<Vec<_>>();
        let removed = slots.len();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        removed
    }

    pub(crate) fn apply_represented_first_login_reputation_like_cpp(&mut self) -> usize {
        if !self.start_all_reputation_like_cpp() {
            return 0;
        }

        let Some(faction_store) = self.faction_store().map(Arc::clone) else {
            return 0;
        };
        let friendship_rep_reaction_store = self.friendship_rep_reaction_store().map(Arc::clone);
        let paragon_reputation_store = self.paragon_reputation_store().map(Arc::clone);
        let currency_types_store = self.currency_types_store().map(Arc::clone);
        let player_race = self.player_race_like_cpp();
        let player_class = self.player_class_like_cpp();
        let team_factions = match player_team_for_race_cpp(player_race) {
            Team::Horde => FIRST_LOGIN_START_REPUTATION_HORDE_FACTIONS_LIKE_CPP,
            _ => FIRST_LOGIN_START_REPUTATION_ALLIANCE_FACTIONS_LIKE_CPP,
        };

        let Some((applied, packet)) = self.mutate_reputation_mgr_like_cpp(|mgr| {
            let mut applied = 0usize;
            for faction_id in FIRST_LOGIN_START_REPUTATION_COMMON_FACTIONS_LIKE_CPP
                .iter()
                .chain(team_factions.iter())
            {
                let Some(faction_entry) = faction_store.get(*faction_id).cloned() else {
                    continue;
                };
                let outcome = mgr.set_one_faction_reputation_like_cpp(
                    &faction_entry,
                    FIRST_LOGIN_START_REPUTATION_STANDING_LIKE_CPP,
                    false,
                    1.0,
                    friendship_rep_reaction_store.as_deref(),
                    paragon_reputation_store.as_deref(),
                    true,
                    currency_types_store.as_deref(),
                    0,
                    0,
                    player_race,
                    player_class,
                );
                if outcome.applied {
                    applied += 1;
                }
            }
            let packet = (applied > 0).then(|| mgr.set_faction_standing_packet_like_cpp(None));
            (applied, packet)
        }) else {
            return 0;
        };
        if let Some(packet) = packet {
            self.send_packet(&packet);
        }

        applied
    }

    /// C++ `Player::AddExploredZones` loop for `CONFIG_START_ALL_EXPLORED` on first login.
    pub(crate) fn apply_represented_first_login_explored_zones_like_cpp(&mut self) -> usize {
        if !self.start_all_explored_like_cpp() {
            return 0;
        }

        let Some((applied, update)) = self
            .mutate_canonical_player_like_cpp(|player| {
                let mut applied = 0usize;
                for index in 0..wow_entities::PLAYER_EXPLORED_ZONES_SIZE_LIKE_CPP {
                    if player.add_explored_zones_like_cpp(index, u64::MAX) {
                        applied += 1;
                    }
                }

                (applied > 0).then(|| (applied, player.values_update(true)))
            })
            .flatten()
        else {
            return 0;
        };

        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_explored_zones_like_cpp =
                [u64::MAX; PLAYER_EXPLORED_ZONES_SIZE_LIKE_CPP];
        }
        self.send_player_values_update_like_cpp(&update);
        applied
    }

    pub(crate) fn mark_represented_talents_loaded_like_cpp(&mut self) {
        let _ = self.mutate_player_talent_runtime_like_cpp(|runtime| {
            runtime.talents_loaded = true;
        });
        self.refresh_represented_talent_points_like_cpp();
    }

    pub(crate) fn represented_talents_loaded_like_cpp(&self) -> bool {
        self.player_talent_runtime_snapshot_like_cpp()
            .is_some_and(|runtime| runtime.talents_loaded)
    }

    pub(crate) fn learn_represented_talent_like_cpp(
        &mut self,
        talent_id: u32,
        requested_rank: u16,
    ) -> bool {
        if !self.represented_talents_loaded_like_cpp() {
            return false;
        }

        let Ok(rank) = u8::try_from(requested_rank) else {
            return false;
        };

        if !self.validate_represented_talent_learn_like_cpp(talent_id, rank) {
            return false;
        }

        let Some(runtime) = self.player_talent_runtime_snapshot_like_cpp() else {
            return false;
        };
        let talent_group = runtime.active_group;
        let previous_rank = runtime
            .talent_groups
            .get(usize::from(talent_group))
            .and_then(|talents| talents.get(&talent_id).copied());
        let learned = self.load_represented_talent_row_like_cpp(talent_id, rank, talent_group);
        if learned {
            self.apply_represented_active_talent_spell_side_effects_like_cpp(
                talent_id,
                previous_rank,
                rank,
                talent_group,
            );
            self.refresh_represented_talent_points_like_cpp();
        }
        learned
    }

    fn validate_represented_talent_learn_like_cpp(&self, talent_id: u32, rank: u8) -> bool {
        let Some(available_points) = self.resolved_player_character_points_like_cpp() else {
            return false;
        };
        let available_points = available_points.max(0) as u32;
        if available_points == 0 {
            return false;
        }

        let Some(runtime) = self.player_talent_runtime_snapshot_like_cpp() else {
            return false;
        };
        let talent_group_index = usize::from(runtime.active_group);
        if talent_group_index >= MAX_SPECIALIZATIONS_LIKE_CPP {
            return false;
        }

        let Some(talent) = self.talent_store().and_then(|store| store.get(talent_id)) else {
            return false;
        };

        let talents = &runtime.talent_groups[talent_group_index];
        if let Some(current_rank) = talents.get(&talent_id) {
            if *current_rank >= rank {
                return false;
            }
        }

        let needed_talent_points =
            self.represented_needed_talent_points_for_learn_like_cpp(talent_id, rank);
        if needed_talent_points > available_points {
            return false;
        }

        for (prereq_talent, prereq_rank) in talent.prereq_talent.iter().zip(talent.prereq_rank) {
            let Ok(prereq_talent_id) = u32::try_from(*prereq_talent) else {
                return false;
            };
            if prereq_talent_id == 0 {
                continue;
            }

            let Ok(required_rank) = u8::try_from(prereq_rank) else {
                return false;
            };
            if talents
                .get(&prereq_talent_id)
                .is_none_or(|known_rank| *known_rank < required_rank)
            {
                return false;
            }
        }

        if talent.tier_id > 0 {
            let Some(talent_store) = self.talent_store() else {
                return false;
            };
            let spent_points = talent_store
                .iter()
                .filter(|entry| entry.tab_id == talent.tab_id)
                .filter_map(|entry| {
                    talents
                        .get(&entry.id)
                        .map(|rank| {
                            entry
                                .spell_rank
                                .get(usize::from(*rank))
                                .copied()
                                .unwrap_or(0)
                        })
                        .filter(|spell_id| *spell_id != 0)
                        .map(|_| u32::from(talents[&entry.id]) + 1)
                })
                .sum::<u32>();

            if spent_points < u32::from(talent.tier_id) * NEEDED_TALENT_POINT_PER_TIER_LIKE_CPP {
                return false;
            }
        }

        true
    }

    fn represented_needed_talent_points_for_learn_like_cpp(&self, talent_id: u32, rank: u8) -> u32 {
        let Some(runtime) = self.player_talent_runtime_snapshot_like_cpp() else {
            return u32::from(rank) + 1;
        };
        let talent_group_index = usize::from(runtime.active_group);
        let Some(talents) = runtime.talent_groups.get(talent_group_index) else {
            return u32::from(rank) + 1;
        };
        if let Some(current_rank) = talents.get(&talent_id) {
            (i32::from(*current_rank) - i32::from(rank) + 1).max(0) as u32
        } else {
            u32::from(rank) + 1
        }
    }

    fn represented_spent_talent_points_count_like_cpp(&self) -> Option<u32> {
        let runtime = self.player_talent_runtime_snapshot_like_cpp()?;
        let talent_group_index = usize::from(runtime.active_group);
        Some(
            runtime
                .talent_groups
                .get(talent_group_index)
                .into_iter()
                .flat_map(|talents| talents.iter())
                .filter(|(talent_id, rank)| {
                    self.represented_talent_info_like_cpp(**talent_id, **rank)
                        .is_some()
                })
                .map(|(_, rank)| u32::from(*rank) + 1)
                .sum(),
        )
    }

    fn represented_quest_rewarded_talent_points_like_cpp(&self) -> Option<u32> {
        let canonical = self.with_owned_player_like_cpp(|player| {
            player.gameplay_state().quest_rewarded_talent_points
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(
                self.represented_quest_reward_talent_points_like_cpp
                    .iter()
                    .map(|reward| reward.points)
                    .sum(),
            );
        }
        canonical
    }

    fn represented_calculate_talents_points_like_cpp(&self) -> Option<u32> {
        let base_points = self
            .num_talents_at_level_store()
            .map(|store| {
                store.num_talents_at_level_like_cpp(
                    u32::from(self.player_level_like_cpp()),
                    self.player_class_like_cpp(),
                )
            })
            .unwrap_or(0);
        Some(base_points + self.represented_quest_rewarded_talent_points_like_cpp()?)
    }

    pub(crate) fn refresh_represented_talent_points_like_cpp(&mut self) {
        let Some(spent) = self.represented_spent_talent_points_count_like_cpp() else {
            return;
        };
        let Some(available) = self
            .represented_calculate_talents_points_like_cpp()
            .map(|points| points.saturating_sub(spent))
        else {
            return;
        };
        self.set_player_character_points_like_cpp(available.min(i32::MAX as u32) as i32);
    }

    pub(crate) fn add_represented_quest_reward_talent_points_like_cpp(
        &mut self,
        quest_id: u32,
        points: u32,
    ) -> bool {
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                let rewarded = &mut player.gameplay_state_mut().quest_rewarded_talent_points;
                *rewarded = rewarded.saturating_add(points);
            })
            .is_some();
        if canonical {
            return true;
        }
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.represented_quest_reward_talent_points_like_cpp.push(
                RepresentedQuestRewardTalentPointsLikeCpp {
                    quest_id,
                    points,
                    init_talent_for_level_unrepresented: true,
                },
            );
            return true;
        }
        let _ = quest_id;
        false
    }

    pub(crate) fn load_represented_talent_row_like_cpp(
        &mut self,
        talent_id: u32,
        rank: u8,
        talent_group: u8,
    ) -> bool {
        let talent_group_index = usize::from(talent_group);
        if talent_group_index >= MAX_SPECIALIZATIONS_LIKE_CPP {
            return false;
        }

        let Some(talent) = self
            .talent_store()
            .and_then(|store| store.get(talent_id))
            .cloned()
        else {
            return false;
        };

        let Some(talent_tab) = self
            .talent_tab_store()
            .and_then(|store| store.get(u32::from(talent.tab_id)))
        else {
            return false;
        };

        let Some(class_mask) = player_class_mask_for_talent_like_cpp(self.player_class_like_cpp())
        else {
            return false;
        };

        let Ok(talent_class_mask) = u32::try_from(talent_tab.class_mask) else {
            return false;
        };
        if (class_mask & talent_class_mask) == 0 {
            return false;
        }

        let rank_index = usize::from(rank);
        let Some(spell_id) = talent.spell_rank.get(rank_index).copied() else {
            return false;
        };
        if spell_id <= 0 {
            return false;
        }

        if !self.represented_spell_valid_for_talent_like_cpp(spell_id) {
            return false;
        }

        self.mutate_player_talent_runtime_like_cpp(|runtime| {
            runtime.talent_groups[talent_group_index].insert(talent_id, rank);
        })
        .is_some()
    }

    pub(crate) fn load_represented_talent_row_with_spell_side_effects_like_cpp(
        &mut self,
        talent_id: u32,
        rank: u8,
        talent_group: u8,
        known_spells: &mut Vec<i32>,
        dependent_spells: &mut HashSet<i32>,
    ) -> bool {
        let previous_rank = self
            .player_talent_runtime_snapshot_like_cpp()
            .and_then(|runtime| {
                runtime
                    .talent_groups
                    .get(usize::from(talent_group))
                    .and_then(|talents| talents.get(&talent_id).copied())
            });

        if !self.load_represented_talent_row_like_cpp(talent_id, rank, talent_group) {
            return false;
        }

        if self.represented_active_talent_group_like_cpp() != Some(talent_group) {
            return true;
        }

        if let Some(previous_rank) = previous_rank {
            if let Some(previous_spell_id) =
                self.represented_talent_spell_id_like_cpp(talent_id, previous_rank)
            {
                known_spells.retain(|known_spell| *known_spell != previous_spell_id);
                dependent_spells.remove(&previous_spell_id);
                for trigger_spell in
                    self.represented_direct_learn_spell_triggers_like_cpp(previous_spell_id)
                {
                    known_spells.retain(|known_spell| *known_spell != trigger_spell);
                    dependent_spells.remove(&trigger_spell);
                }
            }
        }

        if let Some(spell_id) = self.represented_talent_spell_id_like_cpp(talent_id, rank) {
            if !known_spells.contains(&spell_id) {
                known_spells.push(spell_id);
            }
            dependent_spells.insert(spell_id);
            for trigger_spell in self.represented_direct_learn_spell_triggers_like_cpp(spell_id) {
                if !known_spells.contains(&trigger_spell) {
                    known_spells.push(trigger_spell);
                }
                dependent_spells.insert(trigger_spell);
            }
        }

        if let Some((overriden_spell_id, new_spell_id)) =
            self.represented_talent_override_spell_pair_like_cpp(talent_id)
        {
            self.add_represented_override_spell_like_cpp(overriden_spell_id, new_spell_id);
        }

        true
    }

    fn represented_talent_info_like_cpp(
        &self,
        talent_id: u32,
        rank: u8,
    ) -> Option<wow_packet::packets::misc::TalentInfoLikeCpp> {
        let talent = self.talent_store()?.get(talent_id)?;
        let spell_id = talent.spell_rank.get(usize::from(rank)).copied()?;
        if spell_id <= 0 {
            return None;
        }
        if !self.represented_spell_valid_for_talent_like_cpp(spell_id) {
            return None;
        }

        Some(wow_packet::packets::misc::TalentInfoLikeCpp { talent_id, rank })
    }

    fn represented_spell_valid_for_talent_like_cpp(&self, spell_id: i32) -> bool {
        let Some(spell_store) = self.spell_store() else {
            return true;
        };
        Self::represented_spell_valid_with_seen_like_cpp(spell_store, spell_id, &mut HashSet::new())
    }

    fn represented_spell_valid_for_learning_like_cpp(&self, spell_id: i32) -> bool {
        let Some(spell_store) = self.spell_store() else {
            return false;
        };
        Self::represented_spell_valid_with_seen_like_cpp(spell_store, spell_id, &mut HashSet::new())
    }

    fn represented_spell_valid_with_seen_like_cpp(
        spell_store: &wow_data::SpellStore,
        spell_id: i32,
        seen: &mut HashSet<i32>,
    ) -> bool {
        if !seen.insert(spell_id) {
            return true;
        }

        let Some(spell_info) = spell_store.get(spell_id) else {
            return false;
        };

        spell_info.effects().iter().all(|effect| {
            if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_LEARN_SPELL {
                return true;
            }
            if effect.effect_trigger_spell <= 0 {
                return false;
            }
            Self::represented_spell_valid_with_seen_like_cpp(
                spell_store,
                effect.effect_trigger_spell,
                seen,
            )
        })
    }

    fn apply_represented_active_talent_spell_side_effects_like_cpp(
        &mut self,
        talent_id: u32,
        previous_rank: Option<u8>,
        rank: u8,
        talent_group: u8,
    ) {
        if self.represented_active_talent_group_like_cpp() != Some(talent_group) {
            return;
        }

        if let Some(previous_rank) = previous_rank {
            if let Some(previous_spell_id) =
                self.represented_talent_spell_id_like_cpp(talent_id, previous_rank)
            {
                self.remove_known_spell_like_cpp(previous_spell_id);
                for trigger_spell in
                    self.represented_direct_learn_spell_triggers_like_cpp(previous_spell_id)
                {
                    self.remove_known_spell_like_cpp(trigger_spell);
                }
            }
        }

        if let Some(spell_id) = self.represented_talent_spell_id_like_cpp(talent_id, rank) {
            self.learn_known_spell_like_cpp(spell_id);
            for trigger_spell in self.represented_direct_learn_spell_triggers_like_cpp(spell_id) {
                self.learn_known_spell_like_cpp(trigger_spell);
            }
        }

        if let Some((overriden_spell_id, new_spell_id)) =
            self.represented_talent_override_spell_pair_like_cpp(talent_id)
        {
            self.add_represented_override_spell_like_cpp(overriden_spell_id, new_spell_id);
        }

        self.remove_auras_with_interrupt_flags_like_cpp(
            0,
            SPELL_AURA_INTERRUPT_FLAG2_CHANGE_TALENT_LIKE_CPP,
        );
    }

    fn remove_represented_active_talent_side_effects_like_cpp(&mut self, talent_id: u32, rank: u8) {
        if let Some(spell_id) = self.represented_talent_spell_id_like_cpp(talent_id, rank) {
            self.remove_known_spell_like_cpp(spell_id);
            for trigger_spell in self.represented_direct_learn_spell_triggers_like_cpp(spell_id) {
                self.remove_known_spell_like_cpp(trigger_spell);
            }
        }

        if let Some((overriden_spell_id, new_spell_id)) =
            self.represented_talent_override_spell_pair_like_cpp(talent_id)
        {
            self.remove_represented_override_spell_like_cpp(overriden_spell_id, new_spell_id);
        }
    }

    fn represented_talent_spell_id_like_cpp(&self, talent_id: u32, rank: u8) -> Option<i32> {
        self.talent_store()?
            .get(talent_id)?
            .spell_rank
            .get(usize::from(rank))
            .copied()
            .filter(|spell_id| *spell_id > 0)
    }

    fn represented_talent_override_spell_pair_like_cpp(
        &self,
        talent_id: u32,
    ) -> Option<(i32, i32)> {
        let talent = self.talent_store()?.get(talent_id)?;
        (talent.overrides_spell_id > 0 && talent.spell_id > 0)
            .then_some((talent.overrides_spell_id, talent.spell_id))
    }

    fn represented_direct_learn_spell_triggers_like_cpp(&self, spell_id: i32) -> Vec<i32> {
        self.spell_store()
            .and_then(|store| store.get(spell_id))
            .map(|spell_info| {
                spell_info
                    .effects()
                    .iter()
                    .filter(|effect| {
                        effect.effect
                            == wow_data::spell::spell_effect_types::SPELL_EFFECT_LEARN_SPELL
                            && effect.effect_trigger_spell > 0
                    })
                    .map(|effect| effect.effect_trigger_spell)
                    .collect()
            })
            .unwrap_or_default()
    }

    fn represented_talent_reset_state_plan_like_cpp(
        &self,
    ) -> Option<RepresentedTalentResetStatePlanLikeCpp> {
        let runtime = self.player_talent_runtime_snapshot_like_cpp()?;
        if !runtime.talents_loaded {
            return None;
        }

        let active_group = runtime.active_group;
        let active_group_index = usize::from(active_group);
        let active_talents = runtime.talent_groups.get(active_group_index)?.clone();
        let mut post_talents = runtime.talent_groups;
        post_talents[active_group_index].clear();

        Some(RepresentedTalentResetStatePlanLikeCpp {
            active_group,
            active_talents,
            post_talents,
        })
    }

    /// Build the represented durable talent-reset request without mutating the
    /// session. Statement identity, transaction construction and ambiguous
    /// COMMIT reconciliation belong to the lifecycle adapter.
    fn represented_talent_reset_persistence_plan_like_cpp(
        &self,
        guid_counter: u64,
        old_money: u64,
        new_money: u64,
        cost: u32,
        reset_time_secs: u64,
    ) -> Option<(
        RepresentedTalentResetStatePlanLikeCpp,
        wow_persistence::PlayerTalentResetPersistenceRequestLikeCpp,
    )> {
        let state_plan = self.represented_talent_reset_state_plan_like_cpp()?;
        let mut retained_talents = Vec::new();

        for (talent_group, talents) in state_plan.post_talents.iter().enumerate() {
            for (talent_id, rank) in talents {
                if self
                    .represented_talent_info_like_cpp(*talent_id, *rank)
                    .is_none()
                {
                    continue;
                }
                retained_talents.push(wow_persistence::PlayerTalentResetSaveRowLikeCpp {
                    talent_id: *talent_id,
                    rank: *rank,
                    talent_group: talent_group as u8,
                });
            }
        }

        debug_assert_eq!(old_money.saturating_sub(new_money), u64::from(cost));
        Some((
            state_plan,
            wow_persistence::PlayerTalentResetPersistenceRequestLikeCpp {
                player_guid: guid_counter,
                money_before: old_money,
                money_after: new_money,
                reset_cost: cost,
                reset_time_secs,
                retained_talents,
            },
        ))
    }

    pub(crate) fn load_represented_glyph_row_like_cpp(
        &mut self,
        talent_group: u8,
        glyph_slot: u8,
        glyph_id: u16,
    ) -> bool {
        let talent_group_index = usize::from(talent_group);
        if talent_group_index >= MAX_SPECIALIZATIONS_LIKE_CPP {
            return false;
        }

        let glyph_slot_index = usize::from(glyph_slot);
        if glyph_slot_index >= wow_packet::packets::misc::MAX_GLYPH_SLOT_INDEX_LIKE_CPP {
            return false;
        }

        if glyph_id != 0
            && self
                .glyph_properties_store()
                .is_some_and(|store| store.get(u32::from(glyph_id)).is_none())
        {
            return false;
        }

        let previous = self
            .player_talent_runtime_snapshot_like_cpp()
            .map(|runtime| runtime.glyph_groups[talent_group_index][glyph_slot_index]);
        if previous != Some(glyph_id) {
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        self.mutate_player_talent_runtime_like_cpp(|runtime| {
            runtime.glyph_groups[talent_group_index][glyph_slot_index] = glyph_id;
        })
        .is_some()
    }

    pub(crate) fn resolved_update_talent_data_packet_like_cpp(
        &self,
    ) -> Option<wow_packet::packets::misc::UpdateTalentData> {
        self.build_update_talent_data_packet_like_cpp(
            self.resolved_player_character_points_like_cpp()?,
        )
    }

    fn build_update_talent_data_packet_like_cpp(
        &self,
        character_points: i32,
    ) -> Option<wow_packet::packets::misc::UpdateTalentData> {
        let runtime = self.player_talent_runtime_snapshot_like_cpp()?;
        let group_count = (1 + usize::from(runtime.bonus_groups)).min(MAX_SPECIALIZATIONS_LIKE_CPP);
        let mut groups = Vec::with_capacity(group_count);
        for (group_index, glyph_ids) in runtime
            .glyph_groups
            .iter()
            .take(group_count)
            .copied()
            .enumerate()
        {
            let talents = runtime.talent_groups[group_index]
                .iter()
                .filter_map(|(talent_id, rank)| {
                    self.represented_talent_info_like_cpp(*talent_id, *rank)
                })
                .collect();
            groups.push(wow_packet::packets::misc::TalentGroupInfoLikeCpp {
                spec_id: MAX_SPECIALIZATIONS_LIKE_CPP as u8,
                talents,
                glyph_ids,
            });
        }

        Some(wow_packet::packets::misc::UpdateTalentData {
            unspent_talent_points: character_points.max(0) as u32,
            active_group: runtime.active_group,
            groups,
            is_pet_talents: false,
        })
    }

    #[cfg(test)]
    pub(crate) fn represented_update_talent_data_packet_like_cpp(
        &self,
    ) -> wow_packet::packets::misc::UpdateTalentData {
        self.build_update_talent_data_packet_like_cpp(self.player_character_points_like_cpp())
            .expect("test Player talent owner must resolve")
    }

    pub(crate) fn represented_active_glyphs_packet_like_cpp(
        &self,
    ) -> wow_packet::packets::misc::ActiveGlyphs {
        // C++ maps active glyphs to bindable spell ids through GlyphBindableSpell.db2.
        // That store is not session-wired yet, so this remains an intentionally empty
        // full update while UpdateTalentData carries the loaded glyph ids.
        wow_packet::packets::misc::ActiveGlyphs {
            glyphs: Vec::new(),
            is_full_update: true,
        }
    }

    /// Builds the represented statement sequence for C++ `Player::_SaveSpells`.
    ///
    /// The runtime full-save path calls this only when the complete represented
    /// `PlayerSpellMap` authority can preserve inactive/disabled/temporary rows
    /// exactly; incomplete snapshots remain fail-closed.
    /// Persist a direct C++ `LearnSpell` result when Rust has not yet hydrated
    /// the complete `PlayerSpellMap`. The DB row is the missing authority:
    /// preserve its active bit if it was disabled, activate it otherwise, and
    /// clear disabled. Favorites are deliberately untouched because learning
    /// preserves them and the incomplete runtime cannot reconstruct them.
    fn mark_equipment_sets_saved_like_cpp(&mut self) {
        let _ = self.with_owned_equipment_sets_mut_like_cpp(|sets, _| {
            sets.retain(|_, equipment_set| {
                if equipment_set.state == RepresentedEquipmentSetUpdateStateLikeCpp::Deleted {
                    return false;
                }
                equipment_set.state = RepresentedEquipmentSetUpdateStateLikeCpp::Unchanged;
                true
            });
        });
    }

    /// Apply XP to the live session state, leveling up if threshold reached.
    /// C++ `Player::GiveXP` visible side effects; persistence is handled by async wrappers.
    /// `group_rate` is packet metadata only: C++ `KillRewarder::_RewardXP`
    /// scales `xp` before calling this method and passes `_groupRate` separately.
    pub(crate) fn give_xp_runtime_like_cpp(
        &mut self,
        mut xp: u32,
        victim: wow_core::ObjectGuid,
        group_rate: f32,
    ) -> bool {
        use wow_packet::packets::misc::{LevelUpInfo, LogXpGain};

        if xp == 0 {
            return false;
        }
        let Some(player_is_alive) = self.resolved_player_is_alive_like_cpp() else {
            return false;
        };
        if !player_is_alive && !self.player_in_represented_battleground_like_cpp() {
            return false;
        }
        if self.represented_player_has_flag_like_cpp(PLAYER_FLAGS_NO_XP_GAIN_LIKE_CPP) {
            return false;
        }
        if victim.is_any_type_creature()
            && !self
                .represented_creature_has_loot_recipient_like_cpp(victim)
                .unwrap_or(false)
        {
            return false;
        }

        // C++ captures the pre-hook level, dispatches the mutable PlayerScript
        // amount, and only then checks max level. Do not reapply the xp == 0
        // guard after dispatch: C++ continues when a hook changes the amount
        // to zero.
        let old_level = self.player_level_like_cpp();
        let script_context = wow_script::player::GivePlayerXpContextLikeCpp {
            player_guid: self.player_guid().unwrap_or(wow_core::ObjectGuid::EMPTY),
            victim_guid: victim,
        };
        #[cfg(test)]
        if let Some(dispatcher) = &self.give_player_xp_script_dispatcher_like_cpp {
            dispatcher(script_context, &mut xp);
        } else {
            let _ = wow_script::player::on_give_player_xp_like_cpp(script_context, &mut xp);
        }
        #[cfg(not(test))]
        let _ = wow_script::player::on_give_player_xp_like_cpp(script_context, &mut xp);
        if self.player_is_max_level_like_cpp() {
            return false;
        } // max level

        // Resolve the generation-checked owner before consuming rest state or
        // publishing LogXPGain. A stale session must produce no side effect.
        let (Some(current_xp), Some(_next_level_xp)) = (
            self.resolved_player_xp_like_cpp(),
            self.resolved_player_next_level_xp_like_cpp(),
        ) else {
            return false;
        };

        // C++ `Player::GiveXP`: Recruit-A-Friend is mutually exclusive with
        // rested XP and contributes 2 * base XP (3x total).
        let recruit_a_friend = self.gets_recruit_a_friend_xp_bonus_like_cpp();
        let (bonus_xp, rest_info_mask) = if recruit_a_friend {
            (xp.saturating_mul(2), 0)
        } else {
            self.take_represented_xp_rest_bonus_for_gain_like_cpp(xp, victim)
        };
        let total_xp = xp.saturating_add(bonus_xp);

        // Send floating XP text — C++ `WorldPackets::Character::LogXPGain`.
        // C++ opcode registration routes SMSG_LOG_XP_GAIN through
        // CONNECTION_TYPE_REALM, even after the session has switched its
        // default channel to the instance connection.
        self.send_packet_realm(&LogXpGain {
            victim,
            original: total_xp.min(i32::MAX as u32) as i32,
            reason: if victim.is_empty() { 1 } else { 0 },
            amount: xp.min(i32::MAX as u32) as i32,
            group_bonus: group_rate,
        });
        if !self.set_player_xp_like_cpp(current_xp.saturating_add(total_xp)) {
            return false;
        }

        // C++ `Player::GiveXP`: while (newXP >= nextLvlXP && !IsMaxLevel()).
        loop {
            let (Some(current_xp), Some(next_level_xp)) = (
                self.resolved_player_xp_like_cpp(),
                self.resolved_player_next_level_xp_like_cpp(),
            ) else {
                return false;
            };
            if current_xp < next_level_xp || self.player_is_max_level_like_cpp() {
                break;
            }
            if !self.set_player_xp_like_cpp(current_xp - next_level_xp) {
                return false;
            }
            let new_level = self.player_level_like_cpp() + 1;

            info!(account = self.account_id, new_level, "Player leveled up");

            // C++ `Player::GiveLevel` computes these deltas from
            // player_classlevelstats + player_racestats and GtBaseMP before
            // updating the live player level.
            let (base_mana_delta, stat_delta) = self
                .level_up_stat_deltas_like_cpp(new_level)
                .unwrap_or((0, [0; 5]));
            let mut power_delta = [0i32; 10];
            power_delta[0] = base_mana_delta;

            // Send SMSG_LEVELUP_INFO — "Ding!" popup.
            // C++ registers SMSG_LEVEL_UP_INFO on CONNECTION_TYPE_REALM too.
            self.send_packet_realm(&LevelUpInfo {
                level: new_level as i32,
                health_delta: 0,
                power_delta,
                stat_delta,
                num_new_talents: 0,
            });

            self.set_player_level_like_cpp(new_level);
            self.refresh_next_level_xp();
            self.send_level_up_stat_update_like_cpp();
        }

        self.sync_represented_xp_level_to_canonical_and_client_like_cpp(
            self.player_level_like_cpp() != old_level,
            rest_info_mask,
        );

        true
    }

    /// Mirror C++ update-field side effects from `SetXP` / `GiveLevel` until
    /// canonical map-owned `SendObjectUpdates` has complete session fanout.
    fn sync_represented_xp_level_to_canonical_and_client_like_cpp(
        &mut self,
        level_changed: bool,
        rest_info_mask: u8,
    ) {
        if self.player_guid().is_none() {
            return;
        }

        let level = self.player_level_like_cpp();
        let (Some(xp), Some(next_level_xp), Some(scaling_player_level_delta)) = (
            self.resolved_player_xp_like_cpp(),
            self.resolved_player_next_level_xp_like_cpp(),
            self.resolved_player_scaling_level_delta_like_cpp(),
        ) else {
            return;
        };
        let xp = xp.min(i32::MAX as u32) as i32;
        let next_level_xp = next_level_xp.min(i32::MAX as u32) as i32;
        // `GiveLevel` may publish and clear its stat delta before C++'s final
        // `SetXP(newXP)`. Preserve that final unconditional ModifyValue mark
        // without writing a second progression value back into the owner.
        let owner_marked = self
            .with_owned_player_mut_like_cpp(|player| {
                player.mark_xp_changed_like_cpp();
                player.mark_scaling_player_level_delta_changed_like_cpp();
            })
            .is_some();
        #[cfg(not(test))]
        if !owner_marked {
            return;
        }
        #[cfg(test)]
        if !owner_marked && self.player_handle_like_cpp.is_some() {
            // A stale handle is an unknown owner in tests too. Only legacy
            // handle-less fixtures may exercise the isolated packet adapter.
            return;
        }

        // C++ mutates RestInfo and XP on the same Player update mask before
        // `Map::SendObjectUpdates`. Build one isolated transitional delta so
        // the explicit session fanout neither splits nor duplicates RestInfo,
        // and does not leak unrelated canonical dirty fields.
        let mut delta = Player::new(None, false);
        delta.clear_data_changes();
        if level_changed {
            delta.unit_mut().set_level(level);
            delta.set_next_level_xp(next_level_xp);
        }
        delta.set_xp(xp);
        delta.mark_xp_changed_like_cpp();
        delta.set_scaling_player_level_delta_like_cpp(scaling_player_level_delta);
        delta.mark_scaling_player_level_delta_changed_like_cpp();
        if rest_info_mask != 0 {
            let (Some(rest_threshold), Some(rest_state)) = (
                self.resolved_xp_rest_threshold_like_cpp(),
                self.resolved_xp_rest_state_like_cpp(),
            ) else {
                return;
            };
            delta.prepare_rest_info_values_update_like_cpp(
                0,
                rest_threshold,
                rest_state,
                rest_info_mask,
            );
        }
        let update = delta.values_update(true);
        self.send_player_values_update_like_cpp(&update);
    }

    /// Give XP to the player, leveling up if threshold reached.
    /// C++ `Player::GiveXP(xp, victim, group_rate)`.
    pub(crate) async fn give_xp(&mut self, xp: u32, victim: wow_core::ObjectGuid, group_rate: f32) {
        let old_level = self.player_level_like_cpp();
        let (Some(old_rest_bonus), Some(old_rest_state)) = (
            self.resolved_xp_rest_bonus_like_cpp(),
            self.resolved_xp_rest_state_like_cpp(),
        ) else {
            return;
        };
        if !self.give_xp_runtime_like_cpp(xp, victim, group_rate) {
            return;
        }

        let (Some(guid), Some(port)) = (
            self.player_guid(),
            self.player_lifecycle_port_like_cpp().map(Arc::clone),
        ) else {
            return;
        };
        let Some(request) = self.resolved_current_player_xp_persistence_request_like_cpp(
            self.player_level_like_cpp() != old_level,
            self.represented_xp_rest_info_changed_since_like_cpp(old_rest_bonus, old_rest_state),
            guid.counter() as u64,
        ) else {
            return;
        };
        match port.persist_xp_like_cpp(request).await {
            wow_persistence::PersistenceOutcomeLikeCpp::Applied { .. } => {}
            wow_persistence::PersistenceOutcomeLikeCpp::Failed { reason }
            | wow_persistence::PersistenceOutcomeLikeCpp::Unknown { reason } => {
                warn!(
                    guid = guid.counter(),
                    "Failed to atomically persist represented XP/rest state: {reason}"
                );
            }
        }
    }

    /// XP reward for killing a creature.
    /// C++ `Trinity::XP::Gain` / `Trinity::XP::BaseGain`.
    pub(crate) fn creature_kill_xp(&self, mob_level: u8) -> u32 {
        let pl = self.player_level_like_cpp() as i32;
        let ml = mob_level as i32;

        // nBaseExp by content level (WotLK = 71-80 content)
        let n_base_exp: i32 = if pl >= 71 {
            580
        } else if pl >= 61 {
            235
        } else {
            45
        };

        // Gray level check
        let gray = self.gray_level(pl as u8) as i32;
        if ml <= gray {
            return 0;
        }

        let base_gain = if ml >= pl {
            let diff = (ml - pl).min(4);
            ((pl * 5 + n_base_exp) * (20 + diff) / 10 + 1) / 2
        } else {
            let zd = self.zero_difference(pl as u8) as i32;
            (pl * 5 + n_base_exp) * (zd + ml - pl) / zd
        };

        base_gain.max(0) as u32
    }

    /// Level at which mobs give 0 XP ("gray") — C++ `Trinity::XP::GetGrayLevel`.
    pub(crate) fn gray_level(&self, pl: u8) -> u8 {
        let level = if pl < 7 {
            0
        } else if pl < 35 {
            let count = (15..=pl).filter(|level| level % 5 == 0).count() as u8;
            (pl - 7).saturating_sub(count.saturating_sub(1))
        } else {
            pl.saturating_sub(10)
        };
        #[cfg(test)]
        let level = self
            .represented_gray_level_script_overrides_like_cpp
            .get(&pl)
            .copied()
            .unwrap_or(level);
        level
    }

    #[cfg(test)]
    pub(crate) fn set_represented_gray_level_script_override_like_cpp(
        &mut self,
        player_level: u8,
        gray_level: u8,
    ) {
        self.represented_gray_level_script_overrides_like_cpp
            .insert(player_level, gray_level);
        if self.player_level_like_cpp() == player_level {
            let _ = self.mutate_canonical_player_like_cpp(|player| {
                player.gameplay_state_mut().gray_level = gray_level;
            });
        }
    }

    /// Zero-difference table — C++ `Trinity::XP::GetZeroDifference`.
    fn zero_difference(&self, pl: u8) -> u8 {
        match pl {
            0..=3 => 5,
            4..=9 => 6,
            10..=11 => 7,
            12..=15 => 8,
            16..=19 => 9,
            20..=29 => 11,
            30..=39 => 12,
            40..=44 => 13,
            45..=49 => 14,
            50..=54 => 15,
            55..=59 => 16,
            _ => 17,
        }
    }

    fn calculate_kill_reputation_gain_like_cpp(
        &self,
        creature_level: u8,
        rep: i32,
        faction_id: u32,
    ) -> i32 {
        self.calculate_reputation_gain_like_cpp(
            ReputationGainSourceLikeCpp::Kill,
            u32::from(creature_level),
            rep,
            faction_id,
            false,
        )
    }

    pub(crate) fn reputation_gain_percent_before_reward_rate_like_cpp(
        &self,
        source: ReputationGainSourceLikeCpp,
        creature_or_quest_level: u32,
        rep: i32,
        faction_id: u32,
        no_quest_bonus: bool,
    ) -> Option<f32> {
        let mut percent = 100.0f32;
        let mut rep_mod = if no_quest_bonus {
            0.0
        } else {
            self.resolved_total_represented_aura_modifier_like_cpp(
                RepresentedAuraEffectLikeCpp::ModReputationGain,
            )? as f32
        };

        if source == ReputationGainSourceLikeCpp::Kill {
            rep_mod += self.resolved_total_represented_aura_modifier_by_misc_value_like_cpp(
                RepresentedAuraEffectLikeCpp::ModFactionReputationGain,
                faction_id as i32,
            )? as f32;
        }

        percent += if rep > 0 { rep_mod } else { -rep_mod };

        let reputation_rates = self.reputation_rates_like_cpp();
        let low_level_rate = match source {
            ReputationGainSourceLikeCpp::Kill => reputation_rates.low_level_kill,
            ReputationGainSourceLikeCpp::Quest
            | ReputationGainSourceLikeCpp::DailyQuest
            | ReputationGainSourceLikeCpp::WeeklyQuest
            | ReputationGainSourceLikeCpp::MonthlyQuest
            | ReputationGainSourceLikeCpp::RepeatableQuest => reputation_rates.low_level_quest,
            ReputationGainSourceLikeCpp::Spell => 1.0,
        };
        if low_level_rate != 1.0
            && creature_or_quest_level < u32::from(self.gray_level(self.player_level_like_cpp()))
        {
            percent *= low_level_rate;
        }

        (percent > 0.0).then_some(percent)
    }

    pub(crate) fn reputation_reward_rate_for_source_like_cpp(
        &self,
        source: ReputationGainSourceLikeCpp,
        faction_id: u32,
    ) -> Option<f32> {
        let rates = self
            .reputation_reward_rate_store()
            .and_then(|store| store.get(faction_id))?;
        let rate = match source {
            ReputationGainSourceLikeCpp::Kill => rates.creature_rate,
            ReputationGainSourceLikeCpp::Quest => rates.quest_rate,
            ReputationGainSourceLikeCpp::DailyQuest => rates.quest_daily_rate,
            ReputationGainSourceLikeCpp::WeeklyQuest => rates.quest_weekly_rate,
            ReputationGainSourceLikeCpp::MonthlyQuest => rates.quest_monthly_rate,
            ReputationGainSourceLikeCpp::RepeatableQuest => rates.quest_repeatable_rate,
            ReputationGainSourceLikeCpp::Spell => rates.spell_rate,
        };
        Some(rate)
    }

    pub(crate) fn calculate_reputation_gain_like_cpp(
        &self,
        source: ReputationGainSourceLikeCpp,
        creature_or_quest_level: u32,
        rep: i32,
        faction_id: u32,
        no_quest_bonus: bool,
    ) -> i32 {
        let Some(mut percent) = self.reputation_gain_percent_before_reward_rate_like_cpp(
            source,
            creature_or_quest_level,
            rep,
            faction_id,
            no_quest_bonus,
        ) else {
            return 0;
        };

        if let Some(rep_rate) = self.reputation_reward_rate_for_source_like_cpp(source, faction_id)
        {
            if rep_rate <= 0.0 {
                return 0;
            }
            percent *= rep_rate;
        }

        percent = self.apply_recruit_a_friend_reputation_bonus_like_cpp(source, percent);

        (rep as f32 * percent / 100.0) as i32
    }

    pub(crate) fn apply_recruit_a_friend_reputation_bonus_like_cpp(
        &self,
        source: ReputationGainSourceLikeCpp,
        mut percent: f32,
    ) -> f32 {
        if source != ReputationGainSourceLikeCpp::Spell
            && self.gets_recruit_a_friend_reputation_bonus_like_cpp()
        {
            percent *= 1.0 + self.reputation_rates_like_cpp().recruit_a_friend_bonus;
        }
        percent
    }

    fn gets_recruit_a_friend_reputation_bonus_like_cpp(&self) -> bool {
        self.gets_recruit_a_friend_bonus_like_cpp(false)
    }

    fn gets_recruit_a_friend_xp_bonus_like_cpp(&self) -> bool {
        self.gets_recruit_a_friend_bonus_like_cpp(true)
    }

    fn gets_recruit_a_friend_bonus_like_cpp(&self, for_xp: bool) -> bool {
        // C++ `WorldObject::IsInMap` requires both players to be in world.
        // In particular, offline rest accrual runs during LoadFromDB before
        // `AddPlayerToMap` and must not normalize the state as RAF-linked.
        if self.state != SessionState::LoggedIn {
            return false;
        }
        let player_level = u32::from(self.player_level_like_cpp());
        if for_xp && player_level > self.max_recruit_a_friend_bonus_player_level_like_cpp {
            return false;
        }
        let (Some(player_guid), Some(group_guid), Some(group_registry), Some(player_registry)) = (
            self.player_guid(),
            self.resolved_group_guid_like_cpp(),
            self.group_registry.as_ref(),
            self.player_registry.as_ref(),
        ) else {
            return false;
        };
        let Some(group) = group_registry.get(&group_guid) else {
            return false;
        };
        if !group.members.contains(&player_guid) {
            return false;
        }
        let group_members = group.members.clone();
        drop(group);

        let Some(player_position) = self.player_position_like_cpp() else {
            return false;
        };
        let player_map_id = self.player_map_id_like_cpp();
        let player_instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let max_distance = self.reputation_rates_like_cpp().recruit_a_friend_distance;

        for member_guid in group_members {
            if member_guid == player_guid {
                continue;
            }
            let Some(member) = player_registry.group_presence(member_guid) else {
                continue;
            };
            if member.map_id != player_map_id {
                continue;
            }
            if member.instance_id != player_instance_id {
                continue;
            }
            if !member.is_in_world {
                continue;
            }
            // C++ measures a dead member from their corpse. The shared registry
            // does not yet publish corpse location, so fail closed instead of
            // granting RAF from a stale live-player position.
            if !member.is_alive {
                continue;
            }
            if member.position.distance(&player_position) > max_distance {
                continue;
            }
            if for_xp {
                let member_level = u32::from(member.level);
                if member_level > self.max_recruit_a_friend_bonus_player_level_like_cpp {
                    continue;
                }
                if member_level < player_level
                    && player_level - member_level
                        > self.max_recruit_a_friend_bonus_player_level_difference_like_cpp
                {
                    continue;
                }
            }

            let member_recruited_self = member.recruiter_id == self.account_id;
            let self_recruited_member = self.recruiter_id_like_cpp() == member.account_id;
            if member_recruited_self || self_recruited_member {
                return true;
            }
        }

        false
    }

    pub(crate) fn current_map_difficulty_id_like_cpp(&self) -> u8 {
        if let Some(difficulty_id) = self.current_canonical_player_map_difficulty_id_like_cpp() {
            return difficulty_id;
        }
        let map_id = u32::from(self.player_map_id_like_cpp());
        self.canonical_map_manager
            .as_ref()
            .and_then(|manager| manager.lock().ok())
            .and_then(|manager| {
                manager
                    .find_map(map_id, 0)
                    .map(|managed| managed.map().spawn_mode())
            })
            .unwrap_or(0)
    }

    /// C++ `Map::GetDifficultyID` for the map that actually owns this Player.
    ///
    /// The same map id can have multiple live instances. Do not infer spell
    /// metadata from the instance-zero map when the canonical player belongs
    /// to a difficulty-specific `ManagedMap`.
    pub(crate) fn current_canonical_player_map_difficulty_id_like_cpp(&self) -> Option<u8> {
        let player_guid = self.player_guid()?;
        let map_id = u32::from(self.player_map_id_like_cpp());
        let manager = self.canonical_map_manager.as_ref()?.lock().ok()?;
        let mut difficulty_id = None;
        manager.do_for_all_maps_with_map_id(map_id, |managed| {
            if difficulty_id.is_none() && managed.map().get_typed_player(player_guid).is_some() {
                difficulty_id = Some(managed.difficulty());
            }
        });
        difficulty_id
    }

    fn represented_championing_faction_for_kill_like_cpp(&self) -> Option<u32> {
        let championing_faction = self.resolved_championing_faction_like_cpp()?;
        if championing_faction == 0 {
            return None;
        }
        let map_id = u32::from(self.player_map_id_like_cpp());
        if !self
            .map_store()
            .and_then(|store| store.get(map_id))
            .is_some_and(|entry| entry.is_non_raid_dungeon_like_cpp())
        {
            return None;
        }
        let difficulty_id = self.current_map_difficulty_id_like_cpp();
        let is_wrath_max_level_lfg = self
            .lfg_dungeons_store
            .as_ref()
            .and_then(|store| store.get_by_map_and_difficulty_like_cpp(map_id, difficulty_id))
            .is_some_and(|dungeon| {
                dungeon.target_level == WRATH_OF_THE_LICH_KING_MAX_LEVEL_LIKE_CPP
            });
        is_wrath_max_level_lfg.then_some(championing_faction)
    }

    fn xp_in_group_rate_like_cpp(count: u32, is_raid: bool) -> f32 {
        if is_raid {
            0.99
        } else {
            match count {
                0..=2 => 1.0,
                3 => 1.166,
                4 => 1.3,
                _ => 1.4,
            }
        }
    }

    fn represented_player_group_reward_state_like_cpp(
        &self,
        player_guid: ObjectGuid,
    ) -> Option<(u8, u16, Position, bool)> {
        if self.player_guid() == Some(player_guid) {
            return Some((
                self.player_level_like_cpp(),
                self.player_map_id_like_cpp(),
                self.player_position_like_cpp()?,
                self.resolved_player_is_alive_like_cpp()?,
            ));
        }
        self.player_registry.as_ref().and_then(|registry| {
            registry
                .group_reward_snapshot(player_guid)
                .map(|entry| (entry.level, entry.map_id, entry.position, entry.is_alive))
        })
    }

    fn represented_creature_kill_reputation_rate_like_cpp(
        &mut self,
        player_guid: ObjectGuid,
        creature_guid: ObjectGuid,
    ) -> f32 {
        let (Some(group_guid), Some(group_registry)) = (
            self.resolved_group_guid_like_cpp(),
            self.group_registry.as_ref(),
        ) else {
            return 1.0;
        };
        let Some(group) = group_registry.get(&group_guid) else {
            return 1.0;
        };
        if !group.members.contains(&player_guid) {
            return 1.0;
        }
        let group_members = group.members.clone();
        drop(group);

        let Some((player_level, player_map_id, player_position, _)) =
            self.represented_player_group_reward_state_like_cpp(player_guid)
        else {
            return 1.0;
        };

        if self
            .map_store()
            .and_then(|store| store.get(u32::from(player_map_id)))
            .is_some_and(|entry| entry.is_dungeon())
        {
            return 1.0;
        }

        let (reward_map_id, reward_position) = self
            .mutate_world_creature(creature_guid, |creature| {
                (creature.map_id() as u16, creature.position())
            })
            .unwrap_or((player_map_id, player_position));

        let mut count = 0_u32;
        let mut sum_level = 0_u32;
        for member_guid in group_members {
            if member_guid == player_guid {
                count = count.saturating_add(1);
                sum_level = sum_level.saturating_add(u32::from(player_level));
                continue;
            }
            let Some((member_level, _member_map_id, _member_position, is_alive)) =
                self.represented_player_group_reward_state_like_cpp(member_guid)
            else {
                continue;
            };
            if is_alive
                && self.represented_player_at_group_reward_distance_like_cpp(
                    member_guid,
                    reward_map_id,
                    reward_position,
                )
            {
                count = count.saturating_add(1);
                sum_level = sum_level.saturating_add(u32::from(member_level));
            }
        }

        if count == 0 || sum_level == 0 {
            return 1.0;
        }

        Self::xp_in_group_rate_like_cpp(count, false) * f32::from(player_level) / sum_level as f32
    }

    fn reward_creature_kill_reputation_branch_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
        faction_id: u32,
        reputation_value: i32,
        max_cap: u8,
        creature_level: u8,
        kill_reward_rate: f32,
    ) {
        #[cfg(not(test))]
        let _ = creature_guid;
        if faction_id == 0 {
            return;
        }

        let effective_faction_id = self
            .represented_championing_faction_for_kill_like_cpp()
            .unwrap_or(faction_id);

        let faction_store = match self.faction_store().map(Arc::clone) {
            Some(store) => store,
            None => return,
        };
        let Some(faction_entry) = faction_store.get(effective_faction_id).cloned() else {
            return;
        };

        let mut reputation = self.calculate_kill_reputation_gain_like_cpp(
            creature_level,
            reputation_value,
            effective_faction_id,
        );
        reputation = (reputation as f32 * kill_reward_rate) as i32;
        if reputation == 0 {
            return;
        }

        let Some(current_rank) = self.with_reputation_mgr_like_cpp(|mgr| {
            mgr.rank_for_faction_entry_like_cpp(
                &faction_entry,
                self.friendship_rep_reaction_store.as_deref(),
                self.player_race_like_cpp(),
                self.player_class_like_cpp(),
            )
        }) else {
            return;
        };
        let spillover_only = current_rank.as_u8() > max_cap;

        let reputation_spillover_template_store =
            self.reputation_spillover_template_store().map(Arc::clone);
        let friendship_rep_reaction_store = self.friendship_rep_reaction_store().map(Arc::clone);
        let paragon_reputation_store = self.paragon_reputation_store().map(Arc::clone);
        let currency_types_store = self.currency_types_store().map(Arc::clone);
        let db_spillover_template = reputation_spillover_template_store
            .as_deref()
            .and_then(|store| store.get(effective_faction_id));
        let options = crate::reputation::mgr::SetReputationOptionsLikeCpp {
            incremental: true,
            spillover_only,
            no_spillover: false,
            reputation_gain_rate: self.reputation_rates_like_cpp().gain,
            paragon_reward_quest_status_none_like_cpp: true,
            renown_current_level_like_cpp: 0,
            renown_currency_increased_cap_quantity_like_cpp: 0,
            player_race: self.player_race_like_cpp(),
            player_class: self.player_class_like_cpp(),
        };
        let Some((outcome, packet)) = self.mutate_reputation_mgr_like_cpp(|mgr| {
            let outcome = mgr.set_reputation_like_cpp(
                &faction_entry,
                reputation,
                options,
                &faction_store,
                db_spillover_template,
                friendship_rep_reaction_store.as_deref(),
                paragon_reputation_store.as_deref(),
                currency_types_store.as_deref(),
            );
            let packet = outcome
                .send_state_rep_list_id
                .map(|rep_list_id| mgr.set_faction_standing_packet_like_cpp(Some(rep_list_id)));
            (outcome, packet)
        }) else {
            return;
        };
        if let Some(packet) = packet {
            self.send_packet(&packet);
        }
        #[cfg(not(test))]
        let _ = outcome;
        #[cfg(test)]
        if outcome.applied {
            self.represented_creature_kill_events_like_cpp.push(
                RepresentedCreatureKillEventLikeCpp::CreatureKillReputationAwarded {
                    creature_guid,
                    faction_id: effective_faction_id,
                    reputation,
                    spillover_only,
                },
            );
        }
    }

    fn reward_reputation_from_creature_kill_like_cpp(
        &mut self,
        creature_entry: u32,
        creature_guid: ObjectGuid,
        creature_level: u8,
        kill_reward_rate: f32,
    ) {
        if self
            .mutate_world_creature(creature_guid, |creature| {
                creature.creature.is_reputation_gain_disabled()
            })
            .unwrap_or(false)
        {
            return;
        }

        let Some(rep) = self
            .creature_onkill_reputation_store()
            .and_then(|store| store.get(creature_entry))
            .copied()
        else {
            return;
        };
        let team = player_team_for_race_cpp(self.player_race_like_cpp());

        if rep.rep_faction_1 != 0 && (!rep.team_dependent || team == Team::Alliance) {
            self.reward_creature_kill_reputation_branch_like_cpp(
                creature_guid,
                rep.rep_faction_1,
                rep.rep_value_1,
                rep.reputation_max_cap_1,
                creature_level,
                kill_reward_rate,
            );
        }
        if rep.rep_faction_2 != 0 && (!rep.team_dependent || team == Team::Horde) {
            self.reward_creature_kill_reputation_branch_like_cpp(
                creature_guid,
                rep.rep_faction_2,
                rep.rep_value_2,
                rep.reputation_max_cap_2,
                creature_level,
                kill_reward_rate,
            );
        }
    }

    async fn update_represented_storing_value_quest_objective_progress_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
        objective_type: u8,
        object_id: i32,
        add_count: i32,
        credit_guid: wow_core::ObjectGuid,
    ) {
        self.invalidate_player_quest_status_authority_like_cpp();
        use wow_packet::packets::quest::{
            QuestUpdateAddCredit, QuestUpdateAddPvpCredit, QuestUpdateComplete,
        };

        let Some(store) = self.quest_store.clone() else {
            return;
        };

        let victim_team =
            if objective_type == QUEST_OBJECTIVE_PLAYERKILLS_LIKE_CPP && !credit_guid.is_empty() {
                self.player_registry
                    .as_ref()
                    .and_then(|registry| registry.quest_credit_race(credit_guid))
                    .map(player_team_for_race_cpp)
            } else {
                None
            };
        let player_team = player_team_for_race_cpp(self.player_race_like_cpp());
        let Some(quests) = self.player_quest_gameplay_snapshot_like_cpp() else {
            return;
        };
        let matching: Vec<(u32, usize, i32, u32)> = quests
            .statuses
            .values()
            .filter(|qs| qs.status == crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP)
            .flat_map(|qs| {
                let quest = store.get(qs.quest_id)?;
                Some(quest.objectives.iter().filter_map(move |obj| {
                    if obj.obj_type != objective_type || obj.object_id != object_id {
                        return None;
                    }
                    if objective_type == QUEST_OBJECTIVE_PLAYERKILLS_LIKE_CPP
                        && (obj.flags & QUEST_OBJECTIVE_FLAG_KILL_PLAYERS_SAME_FACTION_LIKE_CPP)
                            != 0
                        && victim_team.is_some_and(|team| team != player_team)
                    {
                        return None;
                    }
                    let Ok(idx) = usize::try_from(obj.storage_index) else {
                        return None;
                    };
                    Some((qs.quest_id, idx, obj.amount, obj.id))
                }))
            })
            .flatten()
            .collect();

        let mut quests_to_complete = Vec::new();
        let mut quests_to_save = Vec::new();
        for (quest_id, obj_idx, required, objective_id) in matching {
            let Some(current) = self
                .mutate_player_quest_gameplay_like_cpp(|quests| {
                    let qs = quests.statuses.get_mut(&quest_id)?;
                    if qs.objective_counts.len() <= obj_idx {
                        qs.objective_counts.resize(obj_idx + 1, 0);
                    }
                    if add_count >= 0 && qs.objective_counts[obj_idx] >= required {
                        return None;
                    }
                    qs.objective_counts[obj_idx] = qs.objective_counts[obj_idx]
                        .saturating_add(add_count)
                        .clamp(0, required);
                    Some(qs.objective_counts[obj_idx])
                })
                .flatten()
            else {
                continue;
            };
            quests_to_save.push(quest_id);

            debug!(
                account = self.account_id,
                quest_id,
                obj_idx,
                current,
                required,
                objective_type,
                object_id,
                "Quest objective progress"
            );

            if add_count > 0 {
                if objective_type == QUEST_OBJECTIVE_PLAYERKILLS_LIKE_CPP {
                    self.send_packet(&QuestUpdateAddPvpCredit {
                        quest_id,
                        count: current as u16,
                    });
                } else {
                    self.send_packet(&QuestUpdateAddCredit {
                        victim_guid: credit_guid,
                        quest_id,
                        object_id,
                        count: current as u16,
                        required: required as u16,
                        objective_type,
                    });
                }
            }

            if current >= required {
                if let (Some(quest), Some(quests)) = (
                    store.get(quest_id),
                    self.player_quest_gameplay_snapshot_like_cpp(),
                ) {
                    let quest_already_rewarded = quests.rewarded_quest_ids.contains(&quest_id);
                    if quests.statuses.get(&quest_id).is_some_and(|status| {
                        Self::represented_can_complete_quest_after_objective_like_cpp(
                            status,
                            quest,
                            objective_id,
                            quest_already_rewarded,
                        )
                    }) {
                        quests_to_complete.push(quest_id);
                    }
                }
            }
        }

        for quest_id in quests_to_complete {
            let Some(quest) = store.get(quest_id).cloned() else {
                continue;
            };
            let completed = self
                .complete_represented_quest_after_add_with_generator_like_cpp(
                    item_guid_generator,
                    &quest,
                )
                .await;
            if completed {
                if self.represented_player_quest_status_like_cpp(quest_id)
                    == Some(Some(crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP))
                {
                    self.send_packet(&QuestUpdateComplete { quest_id });
                }
                info!(
                    account = self.account_id,
                    quest_id, "Quest objectives complete"
                );
            }
        }
        self.save_changed_represented_quest_statuses_like_cpp(&mut quests_to_save)
            .await;
        self.sync_player_registry_state_like_cpp();
    }

    async fn update_represented_storing_flag_quest_objective_progress_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
        objective_type: u8,
        object_id: i32,
        add_count: i32,
    ) {
        self.invalidate_player_quest_status_authority_like_cpp();
        use wow_packet::packets::quest::{QuestUpdateAddCreditSimple, QuestUpdateComplete};

        let Some(store) = self.quest_store.clone() else {
            return;
        };

        let Some(quests) = self.player_quest_gameplay_snapshot_like_cpp() else {
            return;
        };
        let matching: Vec<(u32, usize, u32)> = quests
            .statuses
            .values()
            .filter(|qs| qs.status == crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP)
            .flat_map(|qs| {
                let quest = store.get(qs.quest_id)?;
                Some(quest.objectives.iter().filter_map(move |obj| {
                    if obj.obj_type != objective_type
                        || obj.object_id != object_id
                        || !obj.is_storing_flag_like_cpp()
                    {
                        return None;
                    }
                    let Ok(idx) = usize::try_from(obj.storage_index) else {
                        return None;
                    };
                    Some((qs.quest_id, idx, obj.id))
                }))
            })
            .flatten()
            .collect();

        let mut quests_to_complete = Vec::new();
        let mut quests_to_save = Vec::new();
        for (quest_id, obj_idx, objective_id) in matching {
            let Some((objective_was_complete, objective_is_now_complete)) = self
                .mutate_player_quest_gameplay_like_cpp(|quests| {
                    let qs = quests.statuses.get_mut(&quest_id)?;
                    if qs.objective_counts.len() <= obj_idx {
                        qs.objective_counts.resize(obj_idx + 1, 0);
                    }
                    let before = qs.objective_counts[obj_idx] != 0;
                    qs.objective_counts[obj_idx] = i32::from(add_count > 0);
                    Some((before, qs.objective_counts[obj_idx] != 0))
                })
                .flatten()
            else {
                continue;
            };
            if objective_was_complete != objective_is_now_complete {
                quests_to_save.push(quest_id);
            }

            if add_count > 0 {
                self.send_packet(&QuestUpdateAddCreditSimple {
                    quest_id,
                    object_id,
                    objective_type,
                });
            }

            if !objective_was_complete && objective_is_now_complete {
                if let (Some(quest), Some(quests)) = (
                    store.get(quest_id),
                    self.player_quest_gameplay_snapshot_like_cpp(),
                ) {
                    let quest_already_rewarded = quests.rewarded_quest_ids.contains(&quest_id);
                    if quests.statuses.get(&quest_id).is_some_and(|status| {
                        Self::represented_can_complete_quest_after_objective_like_cpp(
                            status,
                            quest,
                            objective_id,
                            quest_already_rewarded,
                        )
                    }) {
                        quests_to_complete.push((quest_id, objective_id));
                    }
                }
            }
        }

        for (quest_id, objective_id) in quests_to_complete {
            let Some(quest) = store.get(quest_id).cloned() else {
                continue;
            };
            let completed = self
                .complete_represented_quest_after_objective_with_generator_like_cpp(
                    item_guid_generator,
                    &quest,
                    objective_id,
                )
                .await;
            if completed {
                if self.represented_player_quest_status_like_cpp(quest_id)
                    == Some(Some(crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP))
                {
                    self.send_packet(&QuestUpdateComplete { quest_id });
                }
                info!(
                    account = self.account_id,
                    quest_id, "Quest objectives complete"
                );
            }
        }
        self.save_changed_represented_quest_statuses_like_cpp(&mut quests_to_save)
            .await;
        self.sync_player_registry_state_like_cpp();
    }

    async fn update_represented_money_quest_objective_progress_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
        old_money: u64,
        new_money: u64,
    ) {
        self.invalidate_player_quest_status_authority_like_cpp();
        use wow_packet::packets::quest::QuestUpdateComplete;

        let Some(store) = self.quest_store.clone() else {
            return;
        };

        let old_money = old_money.min(i64::MAX as u64) as i64;
        let new_money_i64 = new_money.min(i64::MAX as u64) as i64;
        let add_count = new_money_i64.saturating_sub(old_money);
        let Some(quests) = self.player_quest_gameplay_snapshot_like_cpp() else {
            return;
        };
        let matching: Vec<(u32, u32, i32, bool, bool)> = quests
            .statuses
            .values()
            .filter(|qs| {
                qs.status == crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP
                    || qs.status == crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP
            })
            .flat_map(|qs| {
                let quest = store.get(qs.quest_id)?;
                Some(quest.objectives.iter().filter_map(move |obj| {
                    if obj.obj_type != QUEST_OBJECTIVE_MONEY_LIKE_CPP || obj.object_id != 0 {
                        return None;
                    }
                    let objective_was_complete = old_money >= i64::from(obj.amount);
                    if objective_was_complete && add_count >= 0 {
                        return None;
                    }
                    let objective_is_now_complete =
                        old_money.saturating_add(add_count) >= i64::from(obj.amount);
                    Some((
                        qs.quest_id,
                        obj.id,
                        obj.amount,
                        objective_was_complete,
                        objective_is_now_complete,
                    ))
                }))
            })
            .flatten()
            .collect();

        let mut quests_to_complete = Vec::new();
        let mut quests_to_save = Vec::new();
        for (quest_id, objective_id, required, objective_was_complete, objective_is_now_complete) in
            matching
        {
            debug!(
                account = self.account_id,
                quest_id,
                old_money,
                new_money = new_money_i64,
                required,
                objective_was_complete,
                objective_is_now_complete,
                "Quest money objective progress"
            );

            if objective_is_now_complete {
                if let (Some(quest), Some(quests)) = (
                    store.get(quest_id),
                    self.player_quest_gameplay_snapshot_like_cpp(),
                ) {
                    let quest_already_rewarded = quests.rewarded_quest_ids.contains(&quest_id);
                    if quests.statuses.get(&quest_id).is_some_and(|status| {
                        Self::represented_can_complete_quest_after_objective_like_cpp(
                            status,
                            quest,
                            objective_id,
                            quest_already_rewarded,
                        )
                    }) {
                        quests_to_complete.push((quest_id, objective_id));
                    }
                }
            } else if objective_was_complete {
                if self
                    .mutate_player_quest_gameplay_like_cpp(|quests| {
                        let Some(status) = quests.statuses.get_mut(&quest_id) else {
                            return false;
                        };
                        if status.status != crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP {
                            return false;
                        }
                        status.status = crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP;
                        true
                    })
                    .unwrap_or(false)
                {
                    quests_to_save.push(quest_id);
                }
            }
        }

        for (quest_id, objective_id) in quests_to_complete {
            let Some(quest) = store.get(quest_id).cloned() else {
                continue;
            };
            let completed = self
                .complete_represented_quest_after_objective_with_generator_like_cpp(
                    item_guid_generator,
                    &quest,
                    objective_id,
                )
                .await;
            if completed {
                quests_to_save.push(quest_id);
                if self.represented_player_quest_status_like_cpp(quest_id)
                    == Some(Some(crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP))
                {
                    self.send_packet(&QuestUpdateComplete { quest_id });
                }
                info!(
                    account = self.account_id,
                    quest_id, "Quest objectives complete"
                );
            }
        }
        self.save_changed_represented_quest_statuses_like_cpp(&mut quests_to_save)
            .await;
        self.sync_player_registry_state_like_cpp();
    }

