    /// Update player_next_level_xp from the table based on current level.
    pub(crate) fn refresh_next_level_xp(&mut self) {
        if let Some(table) = &self.player_xp_table {
            let lvl = self.player_level_like_cpp() as usize;
            self.set_player_next_level_xp_like_cpp(table.get(lvl).copied().unwrap_or(u32::MAX));
        }
    }

    /// C++ `Player::InitStatsForLevel` repairs an invalid persisted XP value
    /// after deriving `ActivePlayerData::NextLevelXP` for the loaded level.
    pub(crate) fn clamp_loaded_player_xp_to_next_level_like_cpp(&mut self) {
        let (Some(player_xp), Some(next_level_xp)) = (
            self.resolved_player_xp_like_cpp(),
            self.resolved_player_next_level_xp_like_cpp(),
        ) else {
            return;
        };
        if player_xp >= next_level_xp {
            self.set_player_xp_like_cpp(next_level_xp.saturating_sub(1));
        }
    }

    /// C++ `Player::SetXP` updates this field every time XP changes. It uses
    /// the client build's compile-time `MAX_LEVEL`, not the configurable or
    /// account-expansion-specific active maximum.
    pub(crate) fn resolved_player_scaling_level_delta_like_cpp(&self) -> Option<i32> {
        let canonical = self
            .with_owned_player_like_cpp(|player| player.active_data().scaling_player_level_delta);
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(
                if self.player_level_like_cpp() < WRATH_OF_THE_LICH_KING_MAX_LEVEL_LIKE_CPP
                    && self.player_xp < self.player_next_level_xp / 2
                {
                    -1
                } else {
                    0
                },
            );
        }
        canonical
    }

    #[cfg(test)]
    pub(crate) fn player_scaling_level_delta_like_cpp(&self) -> i32 {
        self.resolved_player_scaling_level_delta_like_cpp()
            .expect("test Player progression owner must resolve")
    }

    /// C++ `Player::GetQuestLevel`.
    pub(crate) fn player_quest_level_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> i32 {
        if quest.quest_level > 0 {
            quest.quest_level
        } else {
            i32::from(self.player_level_like_cpp()).min(quest.quest_max_scaling_level)
        }
    }

    /// Calculate XP reward for a quest.
    /// C++ `Quest::XPValue(player, questLevel, xpDifficulty, xpMultiplier)`.
    pub(crate) fn calculate_quest_xp(
        &self,
        difficulty: u32,
        quest_level: i32,
        xp_multiplier: f32,
    ) -> u32 {
        if let Some(store) = &self.quest_xp_store {
            store.calculate_xp(
                quest_level,
                self.player_level_like_cpp(),
                difficulty,
                xp_multiplier,
                self.min_quest_scaled_xp_ratio_like_cpp,
            )
        } else {
            // Fallback if DB2 not loaded
            const XP_TABLE: [u32; 10] = [0, 50, 100, 200, 400, 650, 1000, 1500, 2500, 4000];
            XP_TABLE[difficulty.min(9) as usize]
        }
    }

    /// C++ `Player::GetQuestXPReward`.
    pub(crate) fn quest_xp_reward_like_cpp(&self, quest: &wow_data::quest::QuestTemplate) -> u32 {
        let Some(already_rewarded) = self.represented_player_has_rewarded_quest_like_cpp(quest.id)
        else {
            return 0;
        };
        if already_rewarded && !quest.is_df_quest_like_cpp() {
            return 0;
        }

        self.calculate_quest_xp(
            quest.reward_xp_difficulty,
            self.player_quest_level_like_cpp(quest),
            quest.reward_xp_multiplier,
        )
    }

    /// C++ `Player::GetQuestMoneyReward` -> `Quest::MoneyValue`.
    pub(crate) fn quest_money_reward_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> u32 {
        let Some(store) = &self.quest_money_reward_store else {
            return 0;
        };
        let quest_level = self.player_quest_level_like_cpp(quest).max(0) as u32;
        let Some(row) = store.get(quest_level) else {
            return 0;
        };
        let difficulty = quest.reward_money_difficulty as usize;
        let Some(base) = row.difficulty.get(difficulty).copied() else {
            return 0;
        };
        ((base as f32) * quest.reward_money_multiplier).round() as u32
    }

    /// Check if a spell is on cooldown (global or per-spell).
    ///
    /// Returns true if either the global cooldown (1500ms) or the spell-specific
    /// cooldown from SpellStore is still active.
    pub fn is_spell_on_cooldown(&self, spell_id: i32) -> bool {
        let Some(last_cast) = self.last_spell_cast_time else {
            return false; // Never casted
        };

        let elapsed_ms = last_cast.elapsed().as_millis() as u32;

        // Global cooldown: 1500ms
        if elapsed_ms < 1500 {
            return true;
        }

        // Per-spell cooldown (if exists in SpellStore)
        if let Some(store) = &self.spell_store {
            if let Some(spell_info) = store.get(spell_id) {
                if elapsed_ms < spell_info.cooldown_ms {
                    return true;
                }
            }
        }

        false
    }

    /// Set the shared player registry (used for broadcast).
    pub fn set_player_registry(&mut self, registry: Arc<PlayerRegistry>) {
        if let Some(manager) = &self.canonical_map_manager {
            let _ = registry.bind_canonical_map_manager(Arc::clone(manager));
        } else if let Some(manager) = registry.canonical_map_manager_like_cpp() {
            self.canonical_map_manager = Some(manager);
        }
        self.player_registry = Some(registry);
    }

