    pub(crate) fn is_addon_registered_like_cpp(&self, prefix: &str) -> bool {
        // C++ WorldSession::IsAddonRegistered: if the registration filter is
        // disabled (initial state or softcap exceeded), all prefixes pass.
        if !self.filter_addon_messages {
            return true;
        }

        !self.registered_addon_prefixes.is_empty()
            && self
                .registered_addon_prefixes
                .iter()
                .any(|registered| registered == prefix)
    }

    pub(crate) fn load_seasonal_quest_status_like_cpp(
        &mut self,
        rows: impl IntoIterator<Item = SeasonalQuestStatusDbRowLikeCpp>,
        quest_store: Option<&wow_data::quest::QuestStore>,
        quest_v2_store: Option<&QuestV2Store>,
    ) -> LoadSeasonalQuestStatusOutcomeLikeCpp {
        // C++ Player::_LoadSeasonalQuestStatus clears first and always resets
        // m_SeasonalQuestChanged at the end. Rust deliberately skips rows when
        // no quest store is available, because C++ requires a real QuestTemplate.
        let mut seasonal_quests = BTreeMap::<u16, BTreeMap<u32, u64>>::new();
        let mut outcome = LoadSeasonalQuestStatusOutcomeLikeCpp::default();
        for row in rows {
            outcome.rows_seen += 1;

            let Some(quest_store) = quest_store else {
                outcome.skipped_no_quest_store += 1;
                continue;
            };

            if quest_store.get(row.quest_id).is_none() {
                outcome.skipped_missing_quest += 1;
                continue;
            }

            let Ok(event_id) = u16::try_from(row.event_id) else {
                outcome.skipped_event_out_of_range += 1;
                continue;
            };

            let Ok(completed_time) = u64::try_from(row.completed_time) else {
                // Bounded Rust safety divergence: C++ reads int64 then assigns
                // to uint32, but Rust avoids turning negative DB data into a
                // huge cooldown timestamp.
                outcome.skipped_negative_completed_time += 1;
                continue;
            };

            if seasonal_quests
                .entry(event_id)
                .or_default()
                .insert(row.quest_id, completed_time)
                .is_some()
            {
                outcome.replaced += 1;
            } else {
                outcome.inserted += 1;
            }

            let Some(quest_v2_store) = quest_v2_store else {
                outcome.completed_bit_skipped_no_quest_v2_store += 1;
                continue;
            };

            let quest_bit = quest_v2_store.get_quest_unique_bit_flag_like_cpp(row.quest_id);
            if quest_bit == 0 {
                outcome.completed_bit_skipped_zero_unique_bit += 1;
                continue;
            }

            if self.set_loaded_quest_completed_bit_like_cpp(quest_bit) {
                outcome.completed_bit_set += 1;
            } else {
                outcome.completed_bit_no_change_or_noop += 1;
            }
        }

        let _ = self.mutate_player_quest_gameplay_like_cpp(|state| {
            state.seasonal_quests = seasonal_quests;
            state.seasonal_quest_changed = false;
        });
        outcome.seasonal_quest_changed = false;
        outcome
    }

    pub(crate) fn reset_seasonal_quest_status_like_cpp(
        &mut self,
        event_id: u16,
        event_start_time: u64,
    ) -> ResetSeasonalQuestStatusOutcomeLikeCpp {
        // C++ Player::ResetSeasonalQuestStatus: DB data deleted in caller.
        if self
            .mutate_player_quest_gameplay_like_cpp(|state| {
                state.seasonal_quest_changed = false;
            })
            .is_none()
        {
            return ResetSeasonalQuestStatusOutcomeLikeCpp {
                event_id,
                event_start_time,
                reason: ResetSeasonalQuestStatusReasonLikeCpp::MissingEvent,
                removed_quest_ids: Vec::new(),
                completed_bit_cleared: 0,
                completed_bit_skipped_no_quest_v2_store: 0,
                completed_bit_skipped_zero_unique_bit: 0,
                completed_bit_no_change_or_noop: 0,
                completed_bit_clear_unrepresented: 0,
                event_bucket_erased: false,
                seasonal_quest_changed: false,
            };
        }
        let Some(mut recurrence) = self.player_quest_gameplay_snapshot_like_cpp() else {
            return ResetSeasonalQuestStatusOutcomeLikeCpp {
                event_id,
                event_start_time,
                reason: ResetSeasonalQuestStatusReasonLikeCpp::MissingEvent,
                removed_quest_ids: Vec::new(),
                completed_bit_cleared: 0,
                completed_bit_skipped_no_quest_v2_store: 0,
                completed_bit_skipped_zero_unique_bit: 0,
                completed_bit_no_change_or_noop: 0,
                completed_bit_clear_unrepresented: 0,
                event_bucket_erased: false,
                seasonal_quest_changed: false,
            };
        };
        let Some(bucket) = recurrence.seasonal_quests.get_mut(&event_id) else {
            return ResetSeasonalQuestStatusOutcomeLikeCpp {
                event_id,
                event_start_time,
                reason: ResetSeasonalQuestStatusReasonLikeCpp::MissingEvent,
                removed_quest_ids: Vec::new(),
                completed_bit_cleared: 0,
                completed_bit_skipped_no_quest_v2_store: 0,
                completed_bit_skipped_zero_unique_bit: 0,
                completed_bit_no_change_or_noop: 0,
                completed_bit_clear_unrepresented: 0,
                event_bucket_erased: false,
                seasonal_quest_changed: false,
            };
        };

        if bucket.is_empty() {
            return ResetSeasonalQuestStatusOutcomeLikeCpp {
                event_id,
                event_start_time,
                reason: ResetSeasonalQuestStatusReasonLikeCpp::EmptyEvent,
                removed_quest_ids: Vec::new(),
                completed_bit_cleared: 0,
                completed_bit_skipped_no_quest_v2_store: 0,
                completed_bit_skipped_zero_unique_bit: 0,
                completed_bit_no_change_or_noop: 0,
                completed_bit_clear_unrepresented: 0,
                event_bucket_erased: false,
                seasonal_quest_changed: false,
            };
        }

        let removed_quest_ids: Vec<u32> = bucket
            .iter()
            .filter_map(|(quest_id, completed_time)| {
                (*completed_time < event_start_time).then_some(*quest_id)
            })
            .collect();

        for quest_id in &removed_quest_ids {
            bucket.remove(quest_id);
        }

        let event_bucket_erased = bucket.is_empty() && !removed_quest_ids.is_empty();
        if event_bucket_erased {
            recurrence.seasonal_quests.remove(&event_id);
        }
        let seasonal_quests = recurrence.seasonal_quests;
        let _ = self.mutate_player_quest_gameplay_like_cpp(|state| {
            state.seasonal_quests = seasonal_quests;
            state.seasonal_quest_changed = false;
        });

        let mut completed_bit_cleared = 0;
        let mut completed_bit_skipped_no_quest_v2_store = 0;
        let mut completed_bit_skipped_zero_unique_bit = 0;
        let mut completed_bit_no_change_or_noop = 0;
        for quest_id in &removed_quest_ids {
            let Some(quest_v2_store) = self.quest_v2_store.as_ref().map(Arc::clone) else {
                completed_bit_skipped_no_quest_v2_store += 1;
                continue;
            };

            let quest_bit = quest_v2_store.get_quest_unique_bit_flag_like_cpp(*quest_id);
            if quest_bit == 0 {
                completed_bit_skipped_zero_unique_bit += 1;
                continue;
            }

            if self.clear_loaded_quest_completed_bit_like_cpp(quest_bit) {
                completed_bit_cleared += 1;
            } else {
                completed_bit_no_change_or_noop += 1;
            }
        }

        ResetSeasonalQuestStatusOutcomeLikeCpp {
            event_id,
            event_start_time,
            reason: if removed_quest_ids.is_empty() {
                ResetSeasonalQuestStatusReasonLikeCpp::NoOlderCompletions
            } else {
                ResetSeasonalQuestStatusReasonLikeCpp::RemovedOlderCompletions
            },
            removed_quest_ids,
            completed_bit_cleared,
            completed_bit_skipped_no_quest_v2_store,
            completed_bit_skipped_zero_unique_bit,
            completed_bit_no_change_or_noop,
            completed_bit_clear_unrepresented: 0,
            event_bucket_erased,
            seasonal_quest_changed: false,
        }
    }

    #[cfg(test)]
    pub(crate) fn seed_seasonal_quest_status_like_cpp(
        &mut self,
        event_id: u16,
        quest_id: u32,
        completed_time: u64,
    ) {
        let _ = self.mutate_player_quest_gameplay_like_cpp(|state| {
            state
                .seasonal_quests
                .entry(event_id)
                .or_default()
                .insert(quest_id, completed_time);
        });
    }

    #[cfg(test)]
    pub(crate) fn seed_empty_seasonal_event_bucket_like_cpp(&mut self, event_id: u16) {
        let _ = self.mutate_player_quest_gameplay_like_cpp(|state| {
            state.seasonal_quests.entry(event_id).or_default();
        });
    }

    #[cfg(test)]
    pub(crate) fn seasonal_quest_bucket_like_cpp(
        &self,
        event_id: u16,
    ) -> Option<BTreeMap<u32, u64>> {
        self.player_quest_gameplay_snapshot_like_cpp()?
            .seasonal_quests
            .get(&event_id)
            .cloned()
    }

    #[cfg(test)]
    pub(crate) fn set_seasonal_quest_changed_like_cpp_for_test(&mut self, changed: bool) {
        let _ = self.mutate_player_quest_gameplay_like_cpp(|state| {
            state.seasonal_quest_changed = changed;
        });
    }

    #[cfg(test)]
    pub(crate) fn seasonal_quest_changed_like_cpp(&self) -> bool {
        self.player_quest_gameplay_snapshot_like_cpp()
            .expect("test Player quest owner resolves")
            .seasonal_quest_changed
    }

    /// Set the list of legitimate characters for this account.
    pub fn set_legit_characters(&mut self, guids: Vec<ObjectGuid>) {
        self.legit_characters = guids;
    }

    /// Check if a GUID is in the legit characters list.
    pub fn is_legit_character(&self, guid: &ObjectGuid) -> bool {
        self.legit_characters.contains(guid)
    }

    /// Remove a GUID from the legit characters list.
    pub fn remove_legit_character(&mut self, guid: &ObjectGuid) {
        self.legit_characters.retain(|g| g != guid);
    }

    // ── Aura system ───────────────────────────────────────────────

    /// Apply an aura to the player and send SMSG_AURA_UPDATE.
    pub fn apply_aura(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        duration_ms: u32,
        aura_flags: u32,
    ) -> Result<(), &'static str> {
        self.apply_aura_with_effect_mask_like_cpp(
            spell_id,
            caster_guid,
            duration_ms,
            aura_flags,
            0x0000_0001,
        )
    }

    fn apply_aura_with_effect_mask_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        duration_ms: u32,
        aura_flags: u32,
        effect_mask: u32,
    ) -> Result<(), &'static str> {
        self.apply_aura_with_effect_mask_and_update_like_cpp(
            spell_id,
            caster_guid,
            duration_ms,
            aura_flags,
            effect_mask,
            true,
        )
    }

    fn apply_aura_with_effect_mask_without_update_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        duration_ms: u32,
        aura_flags: u32,
        effect_mask: u32,
    ) -> Result<(), &'static str> {
        self.apply_aura_with_effect_mask_and_update_like_cpp(
            spell_id,
            caster_guid,
            duration_ms,
            aura_flags,
            effect_mask,
            false,
        )
    }

    fn apply_aura_with_effect_mask_and_update_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        duration_ms: u32,
        aura_flags: u32,
        effect_mask: u32,
        send_update: bool,
    ) -> Result<(), &'static str> {
        // Find a free slot (0-254) on the canonical Unit owner.
        let slot = self
            .next_player_visible_aura_slot_like_cpp()
            .ok_or("No free aura slots or missing Player aura owner")?;

        // Preserve the represented StatSystem-relevant multiplier on the same
        // AuraApplication. C++ AuraEffect::HandleModTotalPercentStat uses
        // MiscValueB as a per-stat bitmask (zero means all stats), while the
        // generic AuraApplication continues to own the visible slot.
        let (is_ability, total_stat_percentage_effects) = self
            .spell_store()
            .map(|store| {
                let effects = store
                    .get(spell_id)
                    .map(|spell| {
                        spell
                            .effects()
                            .iter()
                            .filter(|effect| {
                                1u32.checked_shl(effect.effect_index)
                                    .is_some_and(|bit| effect_mask & bit != 0)
                                    && effect.effect_aura
                                        == wow_data::spell::aura_types::SPELL_AURA_MOD_TOTAL_STAT_PERCENTAGE
                            })
                            .map(|effect| {
                                (
                                    effect.effect_index,
                                    effect.calc_value_no_caster_like_cpp(),
                                    effect.effect_misc_value_1,
                                    effect.effect_misc_value_2,
                                )
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                (
                    store.has_attribute0_like_cpp(
                        spell_id,
                        wow_data::spell::attributes::SPELL_ATTR0_IS_ABILITY,
                    ),
                    effects,
                )
            })
            .unwrap_or_default();
        let modifies_total_stats = !total_stat_percentage_effects.is_empty();
        let preserve_health_pct = is_ability
            && total_stat_percentage_effects
                .iter()
                .any(|(_, _, _, stat_mask)| *stat_mask == 0 || *stat_mask & (1 << 2) != 0);
        let first_total_stat_percentage = total_stat_percentage_effects.first().copied();
        let (
            represented_effect,
            represented_amount,
            represented_misc_value,
            represented_multiplier,
        ) = if let Some((_, amount, _, stat_mask)) = first_total_stat_percentage {
            (
                Some(RepresentedAuraEffectLikeCpp::ModTotalStatPercentage),
                amount,
                Some(stat_mask),
                1.0 + amount as f32 / 100.0,
            )
        } else {
            (None, 0, None, 1.0)
        };
        let represented_effect_amounts: Vec<_> = total_stat_percentage_effects
            .iter()
            .filter_map(|(effect_index, amount, _, _)| {
                u8::try_from(*effect_index).ok().map(|effect_index| {
                    RepresentedAuraEffectAmountLikeCpp {
                        effect_index,
                        amount: *amount,
                    }
                })
            })
            .collect();

        // Create aura
        let aura = AuraApplication {
            spell_id,
            difficulty_id: self.current_map_difficulty_id_like_cpp(),
            caster_guid,
            slot,
            duration_total: duration_ms,
            duration_remaining: duration_ms,
            stack_count: 1,
            aura_flags,
            effect_mask,
            aura_interrupt_flags: 0,
            aura_interrupt_flags2: 0,
            represented_effect,
            represented_amount,
            represented_effect_amounts: represented_effect_amounts.clone(),
            represented_misc_value,
            represented_multiplier,
            applied_at: Instant::now(),
        };

        if !self.insert_player_visible_aura_like_cpp(aura) {
            return Err("Missing Player aura owner");
        }
        self.sync_canonical_threat_relevant_aura_like_cpp(
            spell_id,
            caster_guid,
            slot,
            effect_mask,
            &represented_effect_amounts,
            true,
        );

        if send_update {
            self.send_aura_update_applied(
                spell_id,
                slot,
                caster_guid,
                duration_ms,
                aura_flags,
                effect_mask,
            );
            // C++ applies login/load auras while Player is not yet in world,
            // then folds their modifiers into UpdateAllStats and the initial
            // CreateObject. Do not publish a VALUES delta for a GUID the
            // client has not created yet.
            if modifies_total_stats && self.state == SessionState::LoggedIn {
                self.send_total_stat_percentage_update_like_cpp(preserve_health_pct);
            }
        }
        if spell_id == SPELL_PVP_RULES_ENABLED_LIKE_CPP {
            let _ = self.update_represented_item_level_area_based_scaling_like_cpp();
        }

        Ok(())
    }

    fn canonical_threat_aura_snapshot_for_difficulty_like_cpp(
        &self,
        spell_id: i32,
        difficulty: u8,
        effect_mask: u32,
        represented_effect_amounts: &[RepresentedAuraEffectAmountLikeCpp],
    ) -> CanonicalThreatAuraSnapshotLikeCpp {
        let interrupt_flags = self
            .spell_store()
            .and_then(|store| {
                store.aura_interrupt_flags_for_difficulty_like_cpp(
                    spell_id,
                    difficulty,
                    self.difficulty_store().map(AsRef::as_ref),
                )
            })
            .unwrap_or([0; 2]);
        let effects = self
            .spell_store()
            .and_then(|store| {
                store.effects_for_difficulty_like_cpp(
                    spell_id,
                    difficulty,
                    self.difficulty_store().map(AsRef::as_ref),
                )
            })
            .map(|effects| {
                effects
                    .iter()
                    .filter_map(|effect| {
                        let bit = 1u32.checked_shl(effect.effect_index)?;
                        let aura_type = effect.effect_aura;
                        (effect_mask & bit != 0
                            && matches!(
                                aura_type,
                                wow_data::spell::aura_types::SPELL_AURA_MOD_THREAT
                                    | wow_data::spell::aura_types::SPELL_AURA_SCHOOL_IMMUNITY
                                    | wow_data::spell::aura_types::SPELL_AURA_DAMAGE_IMMUNITY
                                    | wow_data::spell::aura_types::SPELL_AURA_MOD_CONFUSE
                                    | wow_data::spell::aura_types::SPELL_AURA_MOD_STUN
                            ))
                        .then(|| {
                            let amount = represented_effect_amounts
                                .iter()
                                .find(|represented| {
                                    represented.effect_index == effect.effect_index as u8
                                })
                                .map_or_else(
                                    || effect.calc_value_no_caster_like_cpp(),
                                    |represented| represented.amount,
                                );
                            (bit, aura_type, amount, effect.effect_misc_value_1)
                        })
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        CanonicalThreatAuraSnapshotLikeCpp::new(interrupt_flags, effects)
    }

    fn sync_canonical_threat_relevant_aura_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        slot: u8,
        effect_mask: u32,
        represented_effect_amounts: &[RepresentedAuraEffectAmountLikeCpp],
        apply: bool,
    ) {
        if !apply {
            let Ok(spell_id) = u32::try_from(spell_id) else {
                return;
            };
            let _ = self.mutate_player_aura_subsystem_like_cpp(|auras| {
                auras.remove_threat_snapshot_like_cpp(slot);
                for effect_index in 0..u32::BITS {
                    let effect_bit = 1u32 << effect_index;
                    if effect_mask & effect_bit != 0 {
                        auras.remove_applied(wow_entities::AppliedAuraRef::new(
                            spell_id,
                            caster_guid,
                            slot,
                            effect_bit,
                        ));
                    }
                }
            });
            return;
        }
        let snapshot = self
            .player_aura_subsystem_snapshot_like_cpp()
            .and_then(|auras| auras.threat_snapshot_like_cpp(slot).cloned())
            .unwrap_or_else(|| {
                let difficulty = self.current_map_difficulty_id_like_cpp();
                self.canonical_threat_aura_snapshot_for_difficulty_like_cpp(
                    spell_id,
                    difficulty,
                    effect_mask,
                    represented_effect_amounts,
                )
            });
        let Ok(spell_id) = u32::try_from(spell_id) else {
            return;
        };
        let _ = self.mutate_player_aura_subsystem_like_cpp(|auras| {
            auras.insert_threat_snapshot_like_cpp(slot, snapshot.clone());
            let interrupt_flags = snapshot.interrupt_flags();
            for &(effect_bit, aura_type, amount, misc_value) in snapshot.effects() {
                let aura =
                    wow_entities::AppliedAuraRef::new(spell_id, caster_guid, slot, effect_bit);
                auras.register_applied_aura(aura, None, interrupt_flags[0], interrupt_flags[1]);
                auras.register_applied_aura_effect_like_cpp(aura, aura_type, amount, misc_value);
            }
        });
    }

    fn hydrate_canonical_threat_relevant_auras_like_cpp(&mut self) {
        let Some(auras) = self
            .resolved_player_visible_auras_like_cpp()
            .map(|auras| auras.into_values().collect::<Vec<_>>())
        else {
            return;
        };
        for aura in auras {
            self.sync_canonical_threat_relevant_aura_like_cpp(
                aura.spell_id,
                aura.caster_guid,
                aura.slot,
                aura.effect_mask,
                &aura.represented_effect_amounts,
                true,
            );
        }
    }

    pub(crate) fn apply_loaded_known_spell_dependencies_like_cpp(
        &mut self,
        known_spells: &mut Vec<i32>,
    ) -> usize {
        let roots = known_spells.clone();
        self.apply_loaded_spell_dependencies_from_roots_like_cpp(&roots, known_spells)
    }

    pub(crate) fn apply_loaded_spell_dependency_skills_like_cpp(
        &mut self,
        known_spells: &mut Vec<i32>,
        loaded_spell_side_effect_spells: &mut Vec<i32>,
    ) -> (usize, bool) {
        // C++ AddSpell applies SpellLearnSkill and recursively AddSpell-s every
        // non-auto spell_learn_spell target. Expanding the complete closure
        // first is final-state equivalent only if every reached target then
        // participates in the SpellLearnSkill pass before skill authority is
        // published.
        let dependent_spell_count =
            self.apply_loaded_known_spell_dependencies_like_cpp(known_spells);
        for &spell_id in known_spells.iter() {
            if !loaded_spell_side_effect_spells.contains(&spell_id) {
                loaded_spell_side_effect_spells.push(spell_id);
            }
        }
        let skills_complete =
            self.apply_loaded_spell_learn_skills_like_cpp(loaded_spell_side_effect_spells);
        (dependent_spell_count, skills_complete)
    }

    pub(crate) fn apply_loaded_spell_dependencies_from_roots_like_cpp(
        &mut self,
        roots: &[i32],
        known_spells: &mut Vec<i32>,
    ) -> usize {
        let mut added = 0usize;
        let mut pending = roots.to_vec();
        let mut index = 0usize;
        while index < pending.len() {
            let spell_id = pending[index];
            index += 1;

            let Ok(spell_id_u32) = u32::try_from(spell_id) else {
                continue;
            };
            let learned_spells = self
                .spell_learn_spell_map_bounds_like_cpp(spell_id_u32)
                .to_vec();
            for learned_spell in learned_spells {
                let Ok(learned_spell_id) = i32::try_from(learned_spell.spell) else {
                    continue;
                };
                if !learned_spell.auto_learned && learned_spell.active {
                    let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
                        runtime.dependent_known_spells.insert(learned_spell_id);
                        runtime.favorite_known_spells.remove(&learned_spell_id);
                    });
                    if !known_spells.contains(&learned_spell_id) {
                        known_spells.push(learned_spell_id);
                        pending.push(learned_spell_id);
                        added += 1;
                    }
                }

                // C++ AddSpell rebuilds this edge for every active dependency,
                // including auto-learned and already-known spells.
                if learned_spell.active && learned_spell.overrides_spell != 0 {
                    if let Ok(overrides_spell_id) = i32::try_from(learned_spell.overrides_spell) {
                        self.add_represented_override_spell_like_cpp(
                            overrides_spell_id,
                            learned_spell_id,
                        );
                    }
                }
            }
        }

        added
    }

    pub(crate) fn deactivate_lower_rank_known_spells_for_send_like_cpp(
        &self,
        known_spells: &mut Vec<i32>,
    ) -> usize {
        let Some(spell_chains) = self.spell_chain_store() else {
            return 0;
        };

        let known_set: HashSet<i32> = known_spells.iter().copied().collect();
        let before = known_spells.len();
        known_spells.retain(|spell_id| {
            let Ok(mut next_spell_id) = u32::try_from(*spell_id) else {
                return true;
            };

            loop {
                next_spell_id = spell_chains.next_spell_in_chain_like_cpp(next_spell_id);
                if next_spell_id == 0 {
                    return true;
                }

                if let Ok(next_spell_i32) = i32::try_from(next_spell_id)
                    && known_set.contains(&next_spell_i32)
                {
                    return false;
                }
            }
        });

        before - known_spells.len()
    }

    pub(crate) fn apply_login_passive_known_spell_auras_like_cpp(&mut self) -> usize {
        let Some(player_guid) = self.player_guid() else {
            return 0;
        };
        let Some(spell_store) = self.spell_store().cloned() else {
            return 0;
        };

        let mut applied = 0usize;
        for spell_id in self.known_spells_like_cpp().to_vec() {
            if spell_id <= 0
                || !spell_store.is_passive_like_cpp(spell_id)
                || self.player_has_visible_aura_spell_like_cpp(spell_id) != Some(false)
            {
                continue;
            }

            let Some(spell_info) = spell_store.get(spell_id).cloned() else {
                continue;
            };
            let effect_mask = unit_owned_apply_aura_effect_mask_like_cpp(&spell_info);
            if effect_mask == 0 {
                continue;
            }

            if let Some(equipped) = self
                .spell_equipped_items_store
                .as_ref()
                .and_then(|store| store.entry_for_spell_id_like_cpp(spell_id))
                .filter(|entry| entry.equipped_item_class >= 0)
                .cloned()
            {
                if !self.represented_has_item_fit_to_spell_requirements_like_cpp(&equipped) {
                    continue;
                }
            } else if !self.represented_login_passive_spell_cast_gate_like_cpp(spell_id) {
                continue;
            }

            if self
                .apply_aura_with_effect_mask_like_cpp(
                    spell_id,
                    player_guid,
                    0,
                    AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100 | 0x0000_0200,
                    effect_mask,
                )
                .is_ok()
            {
                applied += 1;
            }
        }

        applied
    }

    pub(crate) fn apply_login_known_spell_proficiencies_like_cpp(
        &mut self,
        known_spells: &[i32],
    ) -> usize {
        if self.player_guid().is_none()
            || self
                .player_persistent_capability_state_snapshot_like_cpp()
                .is_none()
        {
            return 0;
        }
        let Some(spell_store) = self.spell_store().cloned() else {
            return 0;
        };

        let mut applied = 0usize;
        for &spell_id in known_spells {
            let Some(spell_info) = spell_store.get(spell_id) else {
                continue;
            };
            if spell_info.effect_type
                != wow_data::spell::spell_effect_types::SPELL_EFFECT_PROFICIENCY
                && !spell_info.has_effect_like_cpp(
                    wow_data::spell::spell_effect_types::SPELL_EFFECT_PROFICIENCY,
                )
            {
                continue;
            }

            let Some(before) = self.player_persistent_capability_state_snapshot_like_cpp() else {
                return applied;
            };
            if self.apply_proficiency_effect_like_cpp(spell_id).is_ok()
                && self
                    .player_persistent_capability_state_snapshot_like_cpp()
                    .is_some_and(|after| {
                        after.weapon_proficiency != before.weapon_proficiency
                            || after.armor_proficiency != before.armor_proficiency
                    })
            {
                applied += 1;
            }
        }

        applied
    }

    /// Apply the non-aura combat-capability effects cast by C++ `Player::AddSpell`
    /// while `_LoadSpells` reconstructs known passive spells.
    ///
    /// `SPELL_EFFECT_PARRY` and `SPELL_EFFECT_BLOCK` set `m_canParry` /
    /// `m_canBlock` before `Player::UpdateAllStats`, so the first login
    /// projection must observe those flags as well.
    pub(crate) fn apply_login_known_spell_combat_capabilities_like_cpp(
        &mut self,
        known_spells: &[i32],
    ) -> usize {
        if self.player_guid().is_none() {
            return 0;
        }
        let Some(spell_store) = self.spell_store().cloned() else {
            return 0;
        };

        let before = self.canonical_player_parry_block_snapshot_like_cpp();
        for &spell_id in known_spells {
            if !spell_store.is_passive_like_cpp(spell_id) {
                continue;
            }
            let Some(spell_info) = spell_store.get(spell_id) else {
                continue;
            };

            if spell_info
                .has_effect_like_cpp(wow_data::spell::spell_effect_types::SPELL_EFFECT_PARRY)
            {
                let _ = self.apply_parry_effect_like_cpp();
            }
            if spell_info
                .has_effect_like_cpp(wow_data::spell::spell_effect_types::SPELL_EFFECT_BLOCK)
            {
                let _ = self.apply_block_effect_like_cpp();
            }
        }

        let after = self.canonical_player_parry_block_snapshot_like_cpp();
        usize::from(!before.0 && after.0) + usize::from(!before.1 && after.1)
    }

    pub(crate) fn apply_loaded_known_spell_previous_rank_passive_auras_like_cpp(
        &mut self,
        known_spells: &[i32],
    ) -> usize {
        let Some(player_guid) = self.player_guid() else {
            return 0;
        };
        let Some(spell_store) = self.spell_store().cloned() else {
            return 0;
        };

        let mut applied = 0usize;
        for &spell_id in known_spells {
            let Ok(mut previous_spell_id) =
                u32::try_from(spell_id).map(|spell_id| self.prev_spell_in_chain_like_cpp(spell_id))
            else {
                continue;
            };

            while previous_spell_id != 0 {
                let Ok(previous_spell_i32) = i32::try_from(previous_spell_id) else {
                    break;
                };
                if spell_store.is_passive_like_cpp(previous_spell_i32)
                    && self.player_has_visible_aura_spell_like_cpp(previous_spell_i32)
                        == Some(false)
                    && self.represented_login_passive_spell_cast_gate_like_cpp(previous_spell_i32)
                    && let Some(spell_info) = spell_store.get(previous_spell_i32).cloned()
                {
                    let effect_mask = unit_owned_apply_aura_effect_mask_like_cpp(&spell_info);
                    if effect_mask != 0
                        && self
                            .apply_aura_with_effect_mask_like_cpp(
                                previous_spell_i32,
                                player_guid,
                                0,
                                AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100 | 0x0000_0200,
                                effect_mask,
                            )
                            .is_ok()
                    {
                        applied += 1;
                    }
                }

                previous_spell_id = self.prev_spell_in_chain_like_cpp(previous_spell_id);
            }
        }

        applied
    }

    fn represented_login_passive_spell_cast_gate_like_cpp(&self, spell_id: i32) -> bool {
        let Some(spell_store) = self.spell_store.as_ref() else {
            return false;
        };
        let (stances, _) = spell_store.shapeshift_masks_like_cpp(spell_id);
        let Some(form) = self.represented_shapeshift_form_like_cpp() else {
            return false;
        };
        let stance_mask = form
            .checked_sub(1)
            .and_then(|shift| 1u64.checked_shl(shift))
            .unwrap_or(0);
        let need_cast = stances == 0
            || (form != 0 && (stances & stance_mask) != 0)
            || (form == 0
                && spell_store.has_attribute2_like_cpp(
                    spell_id,
                    wow_data::spell::attributes::SPELL_ATTR2_ALLOW_WHILE_NOT_SHAPESHIFTED_CASTER_FORM,
                ));

        if !need_cast {
            return false;
        }

        let Ok(spell_id_u32) = u32::try_from(spell_id) else {
            return false;
        };
        let caster_aura_state = self
            .spell_aura_restrictions_store
            .as_ref()
            .and_then(|store| {
                store
                    .entries_for_spell_id_like_cpp(spell_id_u32)
                    .find(|entry| entry.difficulty_id == 0 || entry.difficulty_id == u8::MAX)
                    .or_else(|| store.entries_for_spell_id_like_cpp(spell_id_u32).next())
            })
            .map(|entry| entry.caster_aura_state)
            .unwrap_or(0);

        caster_aura_state == 0
            || self.represented_has_aura_state_like_cpp(u32::from(caster_aura_state))
    }

    fn represented_has_aura_state_like_cpp(&self, _aura_state: u32) -> bool {
        false
    }

    fn represented_has_item_fit_to_spell_requirements_like_cpp(
        &self,
        equipped: &SpellEquippedItemsEntry,
    ) -> bool {
        const SPELL_ATTR8_REQUIRES_EQUIPPED_INV_TYPES_LIKE_CPP: u32 = 0x0010_0000;

        if equipped.equipped_item_class < 0 {
            return true;
        }

        match equipped.equipped_item_class {
            class if class == ItemClass::Weapon as i8 => {
                self.represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
                    EQUIPMENT_SLOT_MAINHAND,
                    equipped,
                ) || self.represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
                    EQUIPMENT_SLOT_OFFHAND,
                    equipped,
                )
            }
            class if class == ItemClass::Armor as i8 => {
                if self.spell_store.as_ref().is_some_and(|store| {
                    store.has_attribute8_like_cpp(
                        equipped.spell_id,
                        SPELL_ATTR8_REQUIRES_EQUIPPED_INV_TYPES_LIKE_CPP,
                    )
                }) {
                    [
                        EQUIPMENT_SLOT_HEAD,
                        EQUIPMENT_SLOT_SHOULDERS,
                        EQUIPMENT_SLOT_CHEST,
                        EQUIPMENT_SLOT_WAIST,
                        EQUIPMENT_SLOT_LEGS,
                        EQUIPMENT_SLOT_FEET,
                        EQUIPMENT_SLOT_WRISTS,
                        EQUIPMENT_SLOT_HANDS,
                    ]
                    .into_iter()
                    .all(|slot| {
                        self.represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
                            slot, equipped,
                        )
                    })
                } else {
                    self.represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
                        EQUIPMENT_SLOT_OFFHAND,
                        equipped,
                    ) || (EQUIPMENT_SLOT_HEAD..EQUIPMENT_SLOT_MAINHAND).any(|slot| {
                        self.represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
                            slot, equipped,
                        )
                    })
                }
            }
            _ => false,
        }
    }

    fn represented_equipped_item_in_slot_fits_spell_requirements_like_cpp(
        &self,
        slot: u8,
        equipped: &SpellEquippedItemsEntry,
    ) -> bool {
        self.resolved_inventory_item_objects_like_cpp()
            .is_some_and(|items| {
                items
                    .values()
                    .find(|item| item.container_guid().is_empty() && item.slot() == slot)
                    .is_some_and(|item| {
                        self.represented_item_fits_spell_requirements_like_cpp(
                            item.object().entry(),
                            equipped,
                        )
                    })
            })
    }

    fn represented_item_fits_spell_requirements_like_cpp(
        &self,
        item_id: u32,
        equipped: &SpellEquippedItemsEntry,
    ) -> bool {
        let Some(item) = self
            .item_store
            .as_ref()
            .and_then(|store| store.get(item_id))
        else {
            return false;
        };

        if equipped.equipped_item_class >= 0 {
            if equipped.equipped_item_class != item.class_id as i8 {
                return false;
            }

            if equipped.equipped_item_subclass != 0 {
                let subclass = u32::from(item.subclass_id);
                if subclass >= i32::BITS
                    || (equipped.equipped_item_subclass & (1_i32 << subclass)) == 0
                {
                    return false;
                }
            }
        }

        true
    }

    fn apply_represented_mounted_aura_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
        effect: &wow_data::SpellEffectInfo,
    ) -> Result<(), &'static str> {
        let mounted_amount =
            self.calculate_represented_mounted_aura_amount_like_cpp(spell_id, effect);
        let selected_display_id = u32::try_from(spell_id)
            .ok()
            .and_then(|spell_id| self.select_represented_mount_aura_display_like_cpp(spell_id))
            .unwrap_or(0);
        let creature_entry = u32::try_from(effect.effect_misc_value_1).unwrap_or(0);
        let creature_template_mount =
            self.represented_mount_creature_template_fallback_like_cpp(creature_entry);
        let display_id = if selected_display_id != 0 {
            selected_display_id
        } else {
            creature_template_mount
                .map(|(display_id, _)| display_id)
                .unwrap_or(0)
        };
        let vehicle_id = creature_template_mount
            .map(|(_, vehicle_id)| vehicle_id)
            .unwrap_or(0);

        let slot = self
            .next_player_visible_aura_slot_like_cpp()
            .ok_or("No free aura slots or missing Player aura owner")?;

        let aura = AuraApplication {
            spell_id,
            difficulty_id: self.current_map_difficulty_id_like_cpp(),
            caster_guid,
            slot,
            duration_total: 0,
            duration_remaining: 0,
            stack_count: 1,
            aura_flags: 0x0000_0001,
            effect_mask: 1u32 << effect.effect_index,
            aura_interrupt_flags: 0,
            aura_interrupt_flags2: 0,
            represented_effect: Some(RepresentedAuraEffectLikeCpp::Mounted),
            represented_amount: mounted_amount,
            represented_effect_amounts: represented_aura_effect_amounts_like_cpp(effect),
            represented_misc_value: Some(effect.effect_misc_value_1),
            represented_multiplier: 1.0,
            applied_at: Instant::now(),
        };

        if !self.set_player_mount_presentation_like_cpp(display_id, true) {
            return Err("Missing Player presentation owner");
        }
        if !self.insert_player_visible_aura_like_cpp(aura) {
            return Err("Missing Player aura owner");
        }
        if self.create_player_mount_vehicle_kit_like_cpp(vehicle_id, creature_entry) {
            #[cfg(test)]
            {
                self.mount_vehicle_create_requests_like_cpp = self
                    .mount_vehicle_create_requests_like_cpp
                    .saturating_add(1);
            }
            self.send_set_vehicle_rec_id_like_cpp(vehicle_id);
            self.send_on_cancel_expected_vehicle_ride_aura_like_cpp();
        }
        #[cfg(test)]
        {
            self.mount_pet_control_disable_requests_like_cpp = self
                .mount_pet_control_disable_requests_like_cpp
                .saturating_add(1);
        }
        self.disable_pet_controls_on_mount_like_cpp(
            wow_packet::packets::pet::REACT_PASSIVE_LIKE_CPP,
            wow_packet::packets::pet::COMMAND_FOLLOW_LIKE_CPP,
        );
        #[cfg(test)]
        {
            self.mount_collision_height_update_requests_like_cpp = self
                .mount_collision_height_update_requests_like_cpp
                .saturating_add(1);
        }
        self.update_player_collision_height_like_cpp();
        self.send_movement_set_collision_height_like_cpp(
            wow_packet::packets::movement::UPDATE_COLLISION_HEIGHT_REASON_MOUNT_LIKE_CPP,
        );
        self.apply_represented_mount_capability_speed_aura_like_cpp(mounted_amount, caster_guid);

        self.send_aura_update_applied(
            spell_id,
            slot,
            caster_guid,
            0,
            0x0000_0001,
            1u32 << effect.effect_index,
        );
        self.send_represented_mount_unit_update_like_cpp(display_id);

        Ok(())
    }

    fn calculate_represented_mounted_aura_amount_like_cpp(
        &self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
    ) -> i32 {
        let mut mount_type_id = u16::try_from(effect.effect_misc_value_2).unwrap_or_default();
        if let Some(mount_entry) = self.mount_store.as_ref().and_then(|store| {
            u32::try_from(spell_id)
                .ok()
                .and_then(|spell_id| store.get_by_source_spell_id_like_cpp(spell_id))
        }) {
            mount_type_id = mount_entry.mount_type_id;
        }

        if mount_type_id != 0 {
            let Some(riding_skill) =
                self.resolved_player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP)
            else {
                return effect.effect_base_points;
            };
            if let Some((is_submerged, is_in_water)) =
                self.represented_player_mount_liquid_state_like_cpp()
                && let Ok(capability) = self
                    .represented_mount_capability_selection_for_type_like_cpp(
                        mount_type_id,
                        u32::from(riding_skill),
                        None,
                        is_submerged,
                        is_in_water,
                    )
            {
                return i32::try_from(capability.id).unwrap_or(effect.effect_base_points);
            }
        }

        effect.effect_base_points
    }

    fn apply_represented_mount_capability_speed_aura_like_cpp(
        &mut self,
        mount_capability_id: i32,
        caster_guid: ObjectGuid,
    ) {
        let Some(mod_spell_aura_id) =
            self.represented_mount_capability_mod_spell_like_cpp(mount_capability_id)
        else {
            return;
        };

        let Some(spell_info) = self
            .spell_store()
            .and_then(|store| store.get(mod_spell_aura_id))
            .cloned()
        else {
            return;
        };

        for effect in spell_info.effects().iter().filter(|effect| {
            effect.effect == wow_data::spell::spell_effect_types::SPELL_EFFECT_APPLY_AURA
        }) {
            let represented_effect = match effect.effect_aura {
                aura if aura == wow_data::spell::aura_types::SPELL_AURA_MOD_INCREASE_MOUNTED_SPEED => {
                    RepresentedAuraEffectLikeCpp::MountedSpeed
                }
                aura if aura == wow_data::spell::aura_types::SPELL_AURA_MOD_MOUNTED_SPEED_ALWAYS => {
                    RepresentedAuraEffectLikeCpp::MountedSpeedAlways
                }
                aura if aura
                    == wow_data::spell::aura_types::SPELL_AURA_MOD_MOUNTED_SPEED_NOT_STACK =>
                {
                    RepresentedAuraEffectLikeCpp::MountedSpeedNotStack
                }
                aura if aura
                    == wow_data::spell::aura_types::SPELL_AURA_MOD_INCREASE_MOUNTED_FLIGHT_SPEED =>
                {
                    RepresentedAuraEffectLikeCpp::MountedFlightSpeed
                }
                aura if aura
                    == wow_data::spell::aura_types::SPELL_AURA_MOD_MOUNTED_FLIGHT_SPEED_ALWAYS =>
                {
                    RepresentedAuraEffectLikeCpp::MountedFlightSpeedAlways
                }
                aura if aura == wow_data::spell::aura_types::SPELL_AURA_MOD_FLIGHT_SPEED_NOT_STACK => {
                    RepresentedAuraEffectLikeCpp::FlightSpeedNotStack
                }
                _ => continue,
            };

            if self
                .apply_represented_aura_modifier_like_cpp(
                    mod_spell_aura_id,
                    caster_guid,
                    effect,
                    represented_effect,
                    0,
                )
                .is_ok()
            {
                self.recompute_represented_mounted_speed_rates_like_cpp();
            }
        }
    }

    fn represented_mount_capability_mod_spell_like_cpp(
        &self,
        mount_capability_id: i32,
    ) -> Option<i32> {
        u32::try_from(mount_capability_id)
            .ok()
            .and_then(|id| self.mount_capability_store.as_ref()?.get(id))
            .map(|capability| capability.mod_spell_aura_id)
            .filter(|spell_id| *spell_id > 0)
    }

    fn remove_represented_mount_capability_speed_auras_like_cpp(
        &mut self,
        mount_capability_id: i32,
    ) {
        let Some(mod_spell_aura_id) =
            self.represented_mount_capability_mod_spell_like_cpp(mount_capability_id)
        else {
            return;
        };
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return;
        };
        let slots: Vec<u8> = visible_auras
            .values()
            .filter_map(|aura| (aura.spell_id == mod_spell_aura_id).then_some(aura.slot))
            .collect();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
    }

