    fn create_player_mount_vehicle_kit_like_cpp(
        &mut self,
        vehicle_id: u32,
        creature_entry: u32,
    ) -> bool {
        if vehicle_id == 0 {
            return false;
        }
        let Some(player_guid) = self.player_guid() else {
            return false;
        };

        let Some(vehicle) = self
            .vehicle_store
            .as_ref()
            .and_then(|store| store.get(vehicle_id))
        else {
            #[cfg(not(test))]
            return false;
            #[cfg(test)]
            {
                if self.vehicle_store.is_some() {
                    return false;
                }
                self.player_mount_vehicle_id_like_cpp = vehicle_id;
                let _ = self.mutate_player_mount_vehicle_kit_like_cpp(|kit| *kit = None);
                self.player_mount_vehicle_accessories_like_cpp = self
                    .vehicle_accessory_store
                    .as_ref()
                    .and_then(|store| store.accessories_for_vehicle_like_cpp(None, creature_entry))
                    .map(<[VehicleAccessory]>::to_vec)
                    .unwrap_or_default();
                self.player_mount_vehicle_seat_count_like_cpp = 0;
                self.player_mount_vehicle_usable_seat_count_like_cpp = 0;
                return true;
            }
        };

        let seat_defs = self
            .vehicle_seat_store
            .as_ref()
            .map(|store| store.seat_defs_for_vehicle_like_cpp(vehicle))
            .unwrap_or_default();
        let Some(player_position) = self.player_position_like_cpp() else {
            return false;
        };
        let mut vehicle_kit = Vehicle::new(
            player_guid,
            TypeId::Player,
            player_position,
            vehicle_id,
            creature_entry,
            seat_defs,
        );
        vehicle_kit.install();
        let accessories = self
            .vehicle_accessory_store
            .as_ref()
            .and_then(|store| store.accessories_for_vehicle_like_cpp(None, creature_entry))
            .map(<[VehicleAccessory]>::to_vec)
            .unwrap_or_default();
        let _accessory_plan =
            vehicle_kit.install_all_accessories_plan_like_cpp(false, &accessories);
        #[cfg(test)]
        {
            self.player_mount_vehicle_id_like_cpp = vehicle_id;
            self.player_mount_vehicle_seat_count_like_cpp =
                vehicle_kit.seats().len().min(u8::MAX as usize) as u8;
            self.player_mount_vehicle_usable_seat_count_like_cpp =
                vehicle_kit.usable_seat_num().min(u32::from(u8::MAX)) as u8;
            self.player_mount_vehicle_accessories_like_cpp = _accessory_plan.accessories;
        }
        self.mutate_player_mount_vehicle_kit_like_cpp(|kit| *kit = Some(vehicle_kit))
            .is_some()
    }

    #[cfg(test)]
    fn player_mount_vehicle_despawn_delay_ms_like_cpp(&self) -> i32 {
        let Some(Some(vehicle_kit)) = self.player_mount_vehicle_kit_snapshot_like_cpp() else {
            return 1;
        };

        self.vehicle_template_store
            .as_ref()
            .map(|store| store.despawn_delay_ms_like_cpp(vehicle_kit.creature_entry()))
            .unwrap_or(1)
    }

    fn send_set_vehicle_rec_id_like_cpp(&mut self, vehicle_id: u32) {
        let Some(player_guid) = self.player_guid() else {
            return;
        };
        let vehicle_rec_id = i32::try_from(vehicle_id).unwrap_or(i32::MAX);
        let Some(sequence_index) = self.next_movement_counter_like_cpp() else {
            return;
        };

        self.send_packet(&wow_packet::packets::vehicle::MoveSetVehicleRecId {
            mover_guid: player_guid,
            sequence_index,
            vehicle_rec_id,
        });
        self.send_packet(&wow_packet::packets::vehicle::SetVehicleRecId {
            vehicle_guid: player_guid,
            vehicle_rec_id,
        });
    }

    fn send_on_cancel_expected_vehicle_ride_aura_like_cpp(&mut self) {
        #[cfg(test)]
        {
            self.mount_cancel_expected_vehicle_aura_packets_like_cpp = self
                .mount_cancel_expected_vehicle_aura_packets_like_cpp
                .saturating_add(1);
        }
        self.send_packet(&wow_packet::packets::vehicle::OnCancelExpectedRideVehicleAura);
    }

    fn disable_pet_controls_on_mount_like_cpp(&mut self, react_state: u8, command_state: u8) {
        let Some(pet_guid) = self.player_pet_guid_state_like_cpp().flatten() else {
            return;
        };

        let Some((previous_react_state, _)) = self.canonical_pet_mode_state_like_cpp() else {
            return;
        };
        if !self.update_player_pet_lifecycle_state_like_cpp(|state| {
            state.temporary_mount_react_state = Some(previous_react_state);
        }) {
            return;
        }
        if !self.update_canonical_pet_mode_state_like_cpp(react_state, command_state) {
            return;
        }
        self.send_packet(&wow_packet::packets::pet::PetMode {
            pet_guid,
            react_state,
            command_state,
            flag: 0,
        });
    }

    fn enable_pet_controls_on_dismount_like_cpp(&mut self) {
        if let Some(pet_guid) = self.player_pet_guid_state_like_cpp().flatten() {
            if let Some((current_react_state, command_state)) =
                self.canonical_pet_mode_state_like_cpp()
            {
                let react_state = self
                    .player_pet_lifecycle_state_snapshot_like_cpp()
                    .and_then(|state| state.temporary_mount_react_state)
                    .unwrap_or(current_react_state);
                if self.update_canonical_pet_mode_state_like_cpp(react_state, command_state) {
                    self.send_packet(&wow_packet::packets::pet::PetMode {
                        pet_guid,
                        react_state,
                        command_state,
                        flag: 0,
                    });
                }
            }
        }

        let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
            state.temporary_mount_react_state = None;
        });
    }

    fn update_player_collision_height_like_cpp(&mut self) {
        let Some((_, mount_display_id, object_scale)) =
            self.player_unit_presentation_snapshot_like_cpp()
        else {
            return;
        };
        let computed_height = if let (Some(display_store), Some(model_store)) = (
            self.creature_display_info_store.as_ref(),
            self.creature_model_data_store.as_ref(),
        ) {
            let native_display_id = crate::handlers::character::default_display_id(
                self.player_race_like_cpp(),
                self.player_gender_like_cpp(),
            );
            let mount_display_id = u32::try_from(mount_display_id).ok().filter(|id| *id != 0);
            wow_data::unit_collision_height_like_cpp(
                object_scale,
                native_display_id,
                mount_display_id,
                display_store,
                model_store,
            )
        } else {
            None
        };

        let mount_display_id = u32::try_from(mount_display_id).unwrap_or(0);
        let _canonical_height = self.with_owned_player_mut_like_cpp(|player| {
            let unit = player.unit_mut();
            unit.set_mount_display_id(mount_display_id);
            if let Some(height) = computed_height {
                unit.set_collision_height_like_cpp(height);
            }
            unit.collision_height_like_cpp()
        });
        #[cfg(test)]
        if let Some(height) = _canonical_height.or(computed_height)
            && (_canonical_height.is_some() || self.player_handle_like_cpp.is_none())
        {
            self.player_collision_height_like_cpp = height;
        }
    }

    fn send_movement_set_collision_height_like_cpp(&mut self, reason: u8) {
        let Some(player_guid) = self.player_guid() else {
            return;
        };
        let Some((_, mount_display_id, object_scale)) =
            self.player_unit_presentation_snapshot_like_cpp()
        else {
            return;
        };
        let Some(collision_height) = self
            .with_owned_player_like_cpp(|player| player.unit().collision_height_like_cpp())
            .or_else(|| {
                #[cfg(test)]
                {
                    return self
                        .player_handle_like_cpp
                        .is_none()
                        .then_some(self.player_collision_height_like_cpp);
                }
                #[cfg(not(test))]
                {
                    None
                }
            })
        else {
            return;
        };
        let Some(sequence_index) = self.next_movement_counter_like_cpp() else {
            return;
        };

        let Some(scale_duration) = self.resolved_player_scale_duration_like_cpp() else {
            return;
        };

        self.send_packet(&wow_packet::packets::movement::MoveSetCollisionHeight {
            mover_guid: player_guid,
            sequence_index,
            height: collision_height,
            scale: object_scale,
            reason,
            mount_display_id: u32::try_from(mount_display_id).unwrap_or(0),
            scale_duration,
        });

        use wow_packet::ServerPacket;
        let Some(status) = self.current_player_movement_info_like_cpp(player_guid) else {
            return;
        };
        self.broadcast_to_movement_set_like_cpp(
            wow_packet::packets::movement::MoveUpdateCollisionHeight {
                status,
                height: collision_height,
                scale: object_scale,
            }
            .to_bytes(),
            false,
        );
    }

    fn current_player_movement_info_like_cpp(
        &self,
        player_guid: ObjectGuid,
    ) -> Option<wow_packet::packets::movement::MovementInfo> {
        Some(wow_packet::packets::movement::MovementInfo {
            guid: player_guid,
            position: self.player_position_like_cpp()?,
            flags: self.resolved_player_movement_flags_like_cpp()?,
            flags2: if self.resolved_can_swim_to_fly_transition_like_cpp()? {
                wow_constants::movement::MovementFlag2::CAN_SWIM_TO_FLY_TRANS
            } else {
                wow_constants::movement::MovementFlag2::NONE
            },
            time: self.resolved_player_movement_time_like_cpp()?,
            ..wow_packet::packets::movement::MovementInfo::default()
        })
    }

    fn send_represented_mount_unit_update_like_cpp(&mut self, display_id: i32) {
        let Some(player_guid) = self.player_guid() else {
            return;
        };
        let Some((unit_flags, _, _)) = self.player_unit_presentation_snapshot_like_cpp() else {
            return;
        };

        use wow_packet::packets::update::{UnitDataValuesDeltaUpdate, UpdateObject};
        let mut data = UnitDataValuesDeltaUpdate::default();
        data.unit_data_mask[1] |= 1 << (41 - 32);
        data.unit_data_mask[1] |= 1 << (51 - 32);
        data.flags = unit_flags.bits();
        data.mount_display_id = display_id;

        self.send_packet(&UpdateObject::unit_values_update(
            player_guid,
            self.player_map_id_like_cpp(),
            data,
        ));
    }

    /// Remove an aura by slot and send SMSG_AURA_UPDATE.
    pub fn remove_aura(&mut self, slot: u8) -> Result<(), &'static str> {
        let mounted_aura = self
            .resolved_player_visible_auras_like_cpp()
            .and_then(|auras| auras.get(&slot).cloned())
            .is_some_and(|aura| {
                aura.represented_effect == Some(RepresentedAuraEffectLikeCpp::Mounted)
            });
        let was_mounted = if mounted_aura {
            self.resolved_player_mounted_like_cpp()
                .ok_or("Missing Player presentation owner")?
        } else {
            false
        };
        let Some(aura) = self.remove_player_visible_aura_like_cpp(slot) else {
            return Err("Aura slot not found");
        };
        if mounted_aura && !self.set_player_mount_presentation_like_cpp(0, false) {
            let _ = self.insert_player_visible_aura_like_cpp(aura);
            return Err("Missing Player presentation owner");
        }
        self.sync_canonical_threat_relevant_aura_like_cpp(
            aura.spell_id,
            aura.caster_guid,
            aura.slot,
            aura.effect_mask,
            &aura.represented_effect_amounts,
            false,
        );

        if aura.represented_effect == Some(RepresentedAuraEffectLikeCpp::Mounted) {
            let vehicle_id = self
                .player_mount_vehicle_kit_snapshot_like_cpp()
                .flatten()
                .map(|vehicle| vehicle.vehicle_id())
                .unwrap_or(0);
            #[cfg(test)]
            let vehicle_id = if vehicle_id == 0 {
                self.player_mount_vehicle_id_like_cpp
            } else {
                vehicle_id
            };
            let mount_capability_id = aura.represented_amount;
            let _ = self.mutate_player_mount_vehicle_kit_like_cpp(|kit| {
                if let Some(vehicle_kit) = kit.as_mut() {
                    vehicle_kit.uninstall();
                }
                *kit = None;
            });
            #[cfg(test)]
            {
                self.player_mount_vehicle_id_like_cpp = 0;
                self.player_mount_vehicle_accessories_like_cpp.clear();
                self.player_mount_vehicle_seat_count_like_cpp = 0;
                self.player_mount_vehicle_usable_seat_count_like_cpp = 0;
            }
            if was_mounted {
                if vehicle_id != 0 {
                    #[cfg(test)]
                    {
                        self.mount_vehicle_remove_requests_like_cpp = self
                            .mount_vehicle_remove_requests_like_cpp
                            .saturating_add(1);
                    }
                    self.send_set_vehicle_rec_id_like_cpp(0);
                }
                #[cfg(test)]
                {
                    self.mount_pet_control_enable_requests_like_cpp = self
                        .mount_pet_control_enable_requests_like_cpp
                        .saturating_add(1);
                }
                self.enable_pet_controls_on_dismount_like_cpp();
                #[cfg(test)]
                {
                    self.mount_pet_resummon_requests_like_cpp =
                        self.mount_pet_resummon_requests_like_cpp.saturating_add(1);
                    self.mount_collision_height_update_requests_like_cpp = self
                        .mount_collision_height_update_requests_like_cpp
                        .saturating_add(1);
                }
                self.update_player_collision_height_like_cpp();
                self.send_movement_set_collision_height_like_cpp(
                    wow_packet::packets::movement::UPDATE_COLLISION_HEIGHT_REASON_MOUNT_LIKE_CPP,
                );
            }
            self.send_represented_mount_unit_update_like_cpp(0);
            self.remove_represented_mount_capability_speed_auras_like_cpp(mount_capability_id);
        }
        if matches!(
            aura.represented_effect,
            Some(
                RepresentedAuraEffectLikeCpp::MountedSpeed
                    | RepresentedAuraEffectLikeCpp::Speed
                    | RepresentedAuraEffectLikeCpp::SpeedAlways
                    | RepresentedAuraEffectLikeCpp::SpeedNotStack
                    | RepresentedAuraEffectLikeCpp::UseNormalMovementSpeed
                    | RepresentedAuraEffectLikeCpp::DecreaseSpeed
                    | RepresentedAuraEffectLikeCpp::MinimumSpeed
                    | RepresentedAuraEffectLikeCpp::MinimumSpeedRate
                    | RepresentedAuraEffectLikeCpp::MountedSpeedAlways
                    | RepresentedAuraEffectLikeCpp::MountedSpeedNotStack
            )
        ) {
            self.recompute_represented_run_speed_rate_like_cpp();
        }
        if matches!(
            aura.represented_effect,
            Some(
                RepresentedAuraEffectLikeCpp::MountedFlightSpeed
                    | RepresentedAuraEffectLikeCpp::Fly
                    | RepresentedAuraEffectLikeCpp::FlightSpeed
                    | RepresentedAuraEffectLikeCpp::VehicleFlightSpeed
                    | RepresentedAuraEffectLikeCpp::MountedFlightSpeedAlways
                    | RepresentedAuraEffectLikeCpp::FlightSpeedNotStack
            )
        ) {
            if matches!(
                aura.represented_effect,
                Some(
                    RepresentedAuraEffectLikeCpp::MountedFlightSpeed
                        | RepresentedAuraEffectLikeCpp::Fly
                )
            ) {
                self.update_represented_flight_flags_for_flight_aura_like_cpp(false);
            }
            self.recompute_represented_flight_speed_rate_like_cpp();
        }
        if matches!(
            aura.represented_effect,
            Some(RepresentedAuraEffectLikeCpp::SwimSpeed)
        ) {
            self.recompute_represented_swim_speed_rate_like_cpp();
        }
        if matches!(
            aura.represented_effect,
            Some(
                RepresentedAuraEffectLikeCpp::DecreaseSpeed
                    | RepresentedAuraEffectLikeCpp::UseNormalMovementSpeed
            )
        ) {
            self.recompute_represented_swim_speed_rate_like_cpp();
            self.recompute_represented_flight_speed_rate_like_cpp();
        }
        if aura.represented_effect == Some(RepresentedAuraEffectLikeCpp::DecreaseSpeed) {
            self.recompute_represented_backward_speed_rates_like_cpp();
        }

        // Send SMSG_AURA_UPDATE (removal)
        self.send_aura_update_removed(slot);
        if aura.spell_id == SPELL_PVP_RULES_ENABLED_LIKE_CPP {
            let _ = self.update_represented_item_level_area_based_scaling_like_cpp();
        }
        if self.state == SessionState::LoggedIn
            && self.aura_has_total_stat_percentage_effect_like_cpp(&aura)
        {
            let preserve_health_pct =
                self.total_stat_percentage_aura_preserves_health_pct_like_cpp(&aura);
            self.send_total_stat_percentage_update_like_cpp(preserve_health_pct);
        }

        Ok(())
    }

    pub(crate) fn remove_auras_with_looting_interrupt_flags_like_cpp(&mut self) -> usize {
        self.remove_auras_with_interrupt_flags_like_cpp(
            SPELL_AURA_INTERRUPT_FLAG_LOOTING_LIKE_CPP,
            0,
        )
    }

    pub(crate) fn remove_represented_auras_with_attribute0_like_cpp(
        &mut self,
        attribute: u32,
    ) -> usize {
        let Some(spell_store) = self.spell_store.as_ref() else {
            return 0;
        };
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return 0;
        };

        let slots: Vec<u8> = visible_auras
            .values()
            .filter_map(|aura| {
                spell_store
                    .has_attribute0_like_cpp(aura.spell_id, attribute)
                    .then_some(aura.slot)
            })
            .collect();

        let removed = slots.len();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        removed
    }

    pub(crate) fn remove_moving_or_turning_interrupt_auras_for_far_teleport_like_cpp(
        &mut self,
    ) -> usize {
        let represented_removed = self.remove_auras_with_interrupt_flags_like_cpp(
            SPELL_AURA_INTERRUPT_FLAG_MOVING_OR_TURNING_LIKE_CPP,
            0,
        );
        let canonical_removed = self
            .mutate_canonical_player_like_cpp(|player| {
                player
                    .unit_mut()
                    .subsystems_mut()
                    .auras
                    .remove_interruptible_auras(
                        SPELL_AURA_INTERRUPT_FLAG_MOVING_OR_TURNING_LIKE_CPP,
                        0,
                    )
                    .len()
            })
            .unwrap_or(0);

        represented_removed + canonical_removed
    }

    pub(crate) fn remove_represented_feign_death_if_needed_like_cpp(&mut self) -> bool {
        let has_died_state = self
            .mutate_canonical_player_like_cpp(|player| {
                player.unit().has_unit_state(UnitState::DIED.bits())
            })
            .unwrap_or(false);
        if !has_died_state {
            return false;
        }

        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return false;
        };
        let slots: Vec<u8> = visible_auras
            .iter()
            .filter_map(|(slot, aura)| {
                (aura.represented_effect == Some(RepresentedAuraEffectLikeCpp::FeignDeath))
                    .then_some(*slot)
            })
            .collect();
        if slots.is_empty() {
            return false;
        }

        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        let _ = self.mutate_canonical_player_like_cpp(|player| {
            player.unit_mut().clear_unit_state(UnitState::DIED.bits());
        });
        true
    }

    pub(crate) fn remove_represented_mount_auras_cancelable_like_cpp(&mut self) -> usize {
        self.remove_represented_cancelable_auras_by_effect_like_cpp(
            RepresentedAuraEffectLikeCpp::Mounted,
        )
    }

    pub(crate) fn remove_represented_growth_auras_cancelable_like_cpp(&mut self) -> usize {
        self.remove_represented_cancelable_auras_by_effect_like_cpp(
            RepresentedAuraEffectLikeCpp::ModScale,
        )
    }

    pub(crate) fn remove_represented_mod_speed_no_control_auras_cancelable_like_cpp(
        &mut self,
    ) -> usize {
        self.remove_represented_cancelable_auras_by_effect_like_cpp(
            RepresentedAuraEffectLikeCpp::ModSpeedNoControl,
        )
    }

    fn remove_represented_cancelable_auras_by_effect_like_cpp(
        &mut self,
        represented_effect: RepresentedAuraEffectLikeCpp,
    ) -> usize {
        let no_aura_cancel = wow_data::spell::attributes::SPELL_ATTR0_NO_AURA_CANCEL;
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return 0;
        };
        let slots: Vec<u8> = visible_auras
            .values()
            .filter_map(|aura| {
                // C++ removes SPELL_AURA_MOUNTED only when its SpellInfo is
                // cancelable, positive, and non-passive; the same predicate is
                // used for SPELL_AURA_MOD_SCALE in CancelGrowthAura. These
                // represented effects model positive player-cancelable paths;
                // SpellMisc attributes preserve the C++ no-player-cancel gate.
                if self.spell_store.as_ref().is_some_and(|store| {
                    store.has_attribute0_like_cpp(aura.spell_id, no_aura_cancel)
                }) {
                    return None;
                }
                (aura.represented_effect == Some(represented_effect)).then_some(aura.slot)
            })
            .collect();

        let removed = slots.len();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        removed
    }

    pub(crate) fn remove_represented_cancelable_owned_aura_like_cpp(
        &mut self,
        spell_id: i32,
        caster_guid: ObjectGuid,
    ) -> usize {
        let Some(spell_store) = self.spell_store.as_ref() else {
            return 0;
        };
        if spell_store.get(spell_id).is_none()
            || spell_store.has_attribute0_like_cpp(
                spell_id,
                wow_data::spell::attributes::SPELL_ATTR0_NO_AURA_CANCEL,
            )
            || spell_store.is_channeled_like_cpp(spell_id)
            || spell_store.is_passive_like_cpp(spell_id)
        {
            return 0;
        }

        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return 0;
        };
        let slots: Vec<u8> = visible_auras
            .values()
            .filter_map(|aura| {
                if aura.spell_id != spell_id {
                    return None;
                }
                if !caster_guid.is_empty() && aura.caster_guid != caster_guid {
                    return None;
                }
                // C++ checks SpellInfo before RemoveOwnedAura: no
                // SPELL_ATTR0_NO_AURA_CANCEL, positive, and non-passive.
                // Full SpellInfo::IsPositive is not represented yet; allow
                // the locally materialized positive/cancelable aura shapes,
                // including the single-effect generic represented aura.
                (aura.represented_effect.is_none()
                    || matches!(
                        aura.represented_effect,
                        Some(
                            RepresentedAuraEffectLikeCpp::Mounted
                                | RepresentedAuraEffectLikeCpp::ModScale
                                | RepresentedAuraEffectLikeCpp::ModSpeedNoControl
                        )
                    ))
                .then_some(aura.slot)
            })
            .collect();

        let removed = slots.len();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        removed
    }

    pub(crate) fn remove_auras_with_interrupt_flags_like_cpp(
        &mut self,
        flags: u32,
        flags2: u32,
    ) -> usize {
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return 0;
        };
        let slots: Vec<u8> = visible_auras
            .values()
            .filter(|aura| {
                (flags != 0 && aura.aura_interrupt_flags & flags != 0)
                    || (flags2 != 0 && aura.aura_interrupt_flags2 & flags2 != 0)
            })
            .map(|aura| aura.slot)
            .collect();

        let removed = slots.len();
        for slot in slots {
            let _ = self.remove_aura(slot);
        }
        removed
    }

    /// Check all active auras for expiry and remove those whose duration has elapsed.
    /// Called from the synchronous tick loop (~every 200ms via creature_tick).
    pub(crate) fn tick_auras(&mut self) {
        let Some(visible_auras) = self.resolved_player_visible_auras_like_cpp() else {
            return;
        };
        if visible_auras.is_empty() {
            return;
        }

        // Collect expired slots (avoid borrow conflict)
        let expired: Vec<u8> = visible_auras
            .values()
            .filter(|a| {
                // Permanent auras (duration_total == 0) never expire
                a.duration_total > 0
                    && a.applied_at.elapsed().as_millis() as u32 >= a.duration_total
            })
            .map(|a| a.slot)
            .collect();

        for slot in expired {
            let spell_id = visible_auras.get(&slot).map(|a| a.spell_id).unwrap_or(0);
            let _ = self.remove_aura(slot);
            debug!(
                account = self.account_id,
                slot = slot,
                spell_id = spell_id,
                "Aura expired"
            );
        }
    }

    fn send_aura_update_applied(
        &self,
        spell_id: i32,
        slot: u8,
        caster: ObjectGuid,
        duration: u32,
        flags: u32,
        effect_mask: u32,
    ) {
        let Some(target_guid) = self.player_guid() else {
            return;
        };
        let aura = AuraApplication {
            spell_id,
            difficulty_id: self.current_map_difficulty_id_like_cpp(),
            caster_guid: caster,
            slot,
            duration_total: duration,
            duration_remaining: duration,
            stack_count: 1,
            aura_flags: flags,
            effect_mask,
            aura_interrupt_flags: 0,
            aura_interrupt_flags2: 0,
            represented_effect: None,
            represented_amount: 0,
            represented_effect_amounts: Vec::new(),
            represented_misc_value: None,
            represented_multiplier: 1.0,
            applied_at: Instant::now(),
        };
        self.send_packet(&wow_packet::packets::misc::AuraUpdate {
            unit_guid: target_guid,
            update_all: false,
            auras: vec![Self::player_aura_info_like_cpp(
                &aura,
                self.player_level_like_cpp(),
                self.player_map_id_like_cpp(),
            )],
        });
    }

    fn send_aura_update_removed(&self, slot: u8) {
        let Some(target_guid) = self.player_guid() else {
            return;
        };
        self.send_packet(&wow_packet::packets::misc::AuraUpdate {
            unit_guid: target_guid,
            update_all: false,
            auras: vec![wow_packet::packets::misc::AuraInfoLikeCpp {
                slot,
                aura_data: None,
            }],
        });
    }

    /// Send a TimeSyncRequest and schedule the next one.
    pub(crate) fn send_time_sync(&mut self) {
        use wow_packet::packets::misc::TimeSyncRequest;
        let sequence_index = self.time_sync_next_counter;
        self.send_packet(&TimeSyncRequest { sequence_index });
        trace!(
            "Sent TimeSyncRequest(seq={}) for account {}",
            sequence_index, self.account_id
        );
        self.time_sync_pending_requests
            .insert(sequence_index, Self::game_time_ms_like_cpp());
        // C++ uses 5s for the first request, then 10s.
        self.time_sync_timer_ms = if self.time_sync_next_counter == 0 {
            5000
        } else {
            10000
        };
        self.time_sync_next_counter += 1;
    }

    /// Monotonic millisecond counter matching TrinityCore's `getMSTime()` scale.
    pub(crate) fn game_time_ms_like_cpp() -> u32 {
        static SERVER_START: OnceLock<Instant> = OnceLock::new();
        let start = SERVER_START.get_or_init(Instant::now);
        start.elapsed().as_millis() as u32
    }

    pub(crate) fn reset_time_sync_like_cpp(&mut self) {
        self.time_sync_next_counter = 0;
        self.time_sync_pending_requests.clear();
    }

    pub(crate) fn record_time_sync_response_like_cpp(
        &mut self,
        sequence_index: u32,
        client_time: u32,
    ) {
        let Some(server_time_at_sent) = self.time_sync_pending_requests.remove(&sequence_index)
        else {
            return;
        };

        let received_time = Self::game_time_ms_like_cpp();
        let round_trip_duration = received_time.wrapping_sub(server_time_at_sent);
        let lag_delay = round_trip_duration / 2;
        let clock_delta =
            i64::from(server_time_at_sent) + i64::from(lag_delay) - i64::from(client_time);
        if std::env::var_os("RUSTYCORE_LOGIN_TRACE").is_some() {
            info!(
                account = self.account_id,
                sequence_index,
                client_time,
                server_time_at_sent,
                received_time,
                round_trip_duration,
                lag_delay,
                clock_delta,
                "RUST_LOGIN_TRACE time_sync_response"
            );
        }

        if self.time_sync_clock_delta_queue.len() == 6 {
            self.time_sync_clock_delta_queue.pop_front();
        }
        self.time_sync_clock_delta_queue
            .push_back((clock_delta, round_trip_duration));
        self.compute_new_clock_delta_like_cpp();
    }

    fn compute_new_clock_delta_like_cpp(&mut self) {
        if self.time_sync_clock_delta_queue.is_empty() {
            return;
        }

        let mut latencies: Vec<u32> = self
            .time_sync_clock_delta_queue
            .iter()
            .map(|(_, round_trip_duration)| *round_trip_duration)
            .collect();
        latencies.sort_unstable();
        let latency_median = rounded_median_u32(&latencies);
        let latency_mean =
            latencies.iter().map(|v| f64::from(*v)).sum::<f64>() / latencies.len() as f64;
        let latency_variance = latencies
            .iter()
            .map(|v| {
                let diff = f64::from(*v) - latency_mean;
                diff * diff
            })
            .sum::<f64>()
            / latencies.len() as f64;
        let latency_standard_deviation = latency_variance.sqrt().round() as u32;

        let latency_threshold = latency_standard_deviation.saturating_add(latency_median);
        let mut clock_delta_sum = 0i64;
        let mut sample_size_after_filtering = 0u32;
        for (clock_delta, round_trip_duration) in &self.time_sync_clock_delta_queue {
            if *round_trip_duration < latency_threshold {
                clock_delta_sum += *clock_delta;
                sample_size_after_filtering += 1;
            }
        }

        if sample_size_after_filtering != 0 {
            let mean_clock_delta =
                (clock_delta_sum as f64 / f64::from(sample_size_after_filtering)).round() as i64;
            if (mean_clock_delta - self.time_sync_clock_delta).abs() > 25 {
                self.time_sync_clock_delta = mean_clock_delta;
            }
        } else if self.time_sync_clock_delta == 0 {
            self.time_sync_clock_delta = self
                .time_sync_clock_delta_queue
                .back()
                .map(|(clock_delta, _)| *clock_delta)
                .unwrap_or_default();
        }
    }

    pub(crate) fn adjust_client_movement_time_like_cpp(&self, time: u32) -> u32 {
        let movement_time = i64::from(time) + self.time_sync_clock_delta;
        if self.time_sync_clock_delta == 0 || !(0..=i64::from(u32::MAX)).contains(&movement_time) {
            warn!(
                account = self.account_id,
                client_time = time,
                clock_delta = self.time_sync_clock_delta,
                "The computed movement time using clockDelta is erroneous. Using fallback instead"
            );
            Self::game_time_ms_like_cpp()
        } else {
            movement_time as u32
        }
    }

    async fn process_pending_creature_kills_with_generator_like_cpp(
        &mut self,
        item_guid_generator: &wow_core::ObjectGuidGenerator,
    ) {
        let mut pending = std::mem::take(&mut self.pending_creature_kill_loot_like_cpp);
        pending.sort_by_key(|guid| (guid.high_value(), guid.low_value()));
        pending.dedup();
        for creature_guid in pending {
            self.ensure_represented_creature_kill_loot_like_cpp(creature_guid)
                .await;
        }

        let mut rewards = std::mem::take(&mut self.pending_creature_kill_rewards_like_cpp);
        rewards.sort_by_key(|reward| {
            (
                reward.creature_guid.high_value(),
                reward.creature_guid.low_value(),
            )
        });
        rewards.dedup_by_key(|reward| reward.creature_guid);
        for reward in rewards {
            let can_give_experience = self
                .mutate_world_creature(reward.creature_guid, |creature| {
                    creature.creature.can_give_experience_like_cpp()
                })
                .unwrap_or(false);
            let xp = can_give_experience
                .then(|| self.creature_kill_xp(reward.creature_level))
                .unwrap_or(0);
            if xp > 0 {
                // The represented reward queue is still solo-session only.
                // Full C++ KillRewarder group fanout must pre-scale XP per
                // member before passing its separate `_groupRate` here.
                self.give_xp(xp, reward.creature_guid, 1.0).await;
            }
            let reputation_rate = self.represented_creature_kill_reputation_rate_like_cpp(
                reward.killer_guid,
                reward.creature_guid,
            );
            self.reward_reputation_from_creature_kill_like_cpp(
                reward.creature_entry,
                reward.creature_guid,
                reward.creature_level,
                reputation_rate,
            );
            self.on_creature_killed_with_generator_like_cpp(
                item_guid_generator,
                reward.creature_entry,
                reward.creature_guid,
            )
            .await;
            #[cfg(test)]
            self.record_represented_creature_kill_hooks_like_cpp(
                reward.killer_guid,
                reward.creature_guid,
            );
            if let Some(values_update) = self
                .complete_represented_creature_death_state_after_kill_hooks_like_cpp(
                    reward.killer_guid,
                    reward.creature_guid,
                )
                && self
                    .client_visible_guids_like_cpp
                    .contains(&reward.creature_guid)
                && let Some(update) = self.represented_unit_values_update_to_update_object_like_cpp(
                    reward.creature_guid,
                    self.player_map_id_like_cpp(),
                    &values_update,
                )
            {
                self.send_packet(&update);
            }
        }
    }

    /// Check for area triggers at the player's current position.
    ///
    /// This is called after movement updates to handle:
    /// - Teleportation triggers (e.g., dungeon exits)
    /// - Spell effects (e.g., silencing fields)
    /// - Custom trigger actions
    ///
    /// Manages trigger state to prevent retriggering:
    /// - Entry: when player enters a trigger (was not in one)
    /// - Exit: when player leaves a trigger (was in one, no longer is)
    pub async fn check_area_triggers_with_catalogs_like_cpp(
        &mut self,
        catalogs: &AreaTriggerCatalogsLikeCpp,
    ) {
        let Some(pos) = self.player_position_like_cpp() else {
            return;
        };
        let store = catalogs.destinations.as_ref();

        let (exited_trigger_id, entered_trigger) = {
            // Get all triggers at the current position on the player's current map.
            let triggers = store.get_triggers_at_position(self.player_map_id_like_cpp(), &pos);
            let exited_trigger_id = self.active_area_trigger.filter(|prev_trigger_id| {
                !triggers
                    .iter()
                    .any(|trigger| trigger.trigger_id == *prev_trigger_id)
            });
            let entered_trigger = triggers
                .first()
                .map(|trigger| (trigger.trigger_id, trigger.teleport.clone()));
            (exited_trigger_id, entered_trigger)
        };

        // Check if we've exited the previous trigger
        if let Some(prev_trigger_id) = exited_trigger_id {
            info!(
                account = self.account_id,
                trigger_id = prev_trigger_id,
                "Exited area trigger"
            );
            self.handle_represented_tavern_area_trigger_with_catalog_like_cpp(
                catalogs.taverns.as_ref(),
                prev_trigger_id,
                false,
            );
            self.active_area_trigger = None;
        }

        // Check if we've entered a new trigger
        if let Some((trigger_id, teleport)) = entered_trigger {
            // Only trigger if this is a NEW trigger (wasn't active before)
            if self.active_area_trigger != Some(trigger_id) {
                info!(
                    account = self.account_id,
                    trigger_id, "Entered area trigger"
                );
                self.active_area_trigger = Some(trigger_id);

                if self.handle_represented_tavern_area_trigger_with_catalog_like_cpp(
                    catalogs.taverns.as_ref(),
                    trigger_id,
                    true,
                ) {
                    return;
                }

                // Handle teleportation if present
                if let Some(ref teleport) = teleport {
                    info!(
                        account = self.account_id,
                        trigger_id,
                        target_map = teleport.target_map,
                        target_x = teleport.target_position.x,
                        target_y = teleport.target_position.y,
                        target_z = teleport.target_position.z,
                        "Teleporting player via area trigger"
                    );
                    self.teleport_to(teleport.target_map, teleport.target_position)
                        .await;
                }
            }
        }
    }

    #[cfg(test)]
    pub async fn check_area_triggers(&mut self) {
        let catalogs = self.area_trigger_catalogs_for_test_like_cpp();
        self.check_area_triggers_with_catalogs_like_cpp(&catalogs)
            .await;
    }

    /// Teleport the player to a new map and position.
    ///
    /// Sends SMSG_TRANSFER_PENDING (0x25cd) to initiate the transfer.
    /// The client will respond with CMSG_WORLD_PORT_ACK when ready.
    ///
    /// C++ `Player::TeleportTo` → `SendTransferPending`.
    pub async fn teleport_to(&mut self, new_map: u32, new_pos: wow_core::Position) {
        self.teleport_to_with_options(new_map, new_pos, TELE_TO_NONE_LIKE_CPP)
            .await;
    }

    pub(crate) async fn teleport_to_with_options(
        &mut self,
        new_map: u32,
        new_pos: wow_core::Position,
        mut options: TeleportToOptionsLikeCpp,
    ) {
        // Validate inputs
        if new_map as u16 > 0xFFF {
            warn!(
                "Invalid map ID {} for teleport from account {}",
                new_map, self.account_id
            );
            return;
        }

        if self.is_map_disabled_for_player_like_cpp(new_map) {
            warn!(
                account = self.account_id,
                map_id = new_map,
                "Teleport blocked by C++ DisableMgr map gate"
            );
            self.send_transfer_aborted_like_cpp(new_map, TRANSFER_ABORT_MAP_NOT_ALLOWED_LIKE_CPP);
            return;
        }

        if let Some(target_map) = self
            .map_store
            .as_ref()
            .and_then(|store| store.get(new_map).copied())
            && target_map.is_battleground_or_arena()
            && !self.player_in_represented_battleground_like_cpp()
        {
            warn!(
                account = self.account_id,
                map_id = new_map,
                "Teleport silently blocked by C++ battleground assignment gate"
            );
            return;
        }

        if let Some(target_map) = self
            .map_store
            .as_ref()
            .and_then(|store| store.get(new_map).copied())
            && self.expansion < target_map.expansion_like_cpp()
        {
            warn!(
                account = self.account_id,
                map_id = new_map,
                session_expansion = self.expansion,
                required_expansion = target_map.expansion_like_cpp(),
                "Teleport blocked by C++ client expansion gate"
            );
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                TRANSFER_ABORT_INSUF_EXPAN_LVL_LIKE_CPP,
                target_map.expansion_like_cpp(),
                0,
            );
            return;
        }

        let Some(current_pos) = self.player_position_like_cpp() else {
            warn!(
                "Cannot teleport account {}: no current position",
                self.account_id
            );
            return;
        };

        self.exit_represented_vehicle_for_teleport_like_cpp();
        self.reset_teleport_movement_state_like_cpp();

        if self.player_class_like_cpp() == CLASS_DEATH_KNIGHT_LIKE_CPP
            && self.player_map_id_like_cpp() == DEATH_KNIGHT_START_MAP_LIKE_CPP
            && u32::from(self.player_map_id_like_cpp()) != new_map
            && self.player_is_game_master_like_cpp() != Some(true)
            && !self
                .known_spells_like_cpp()
                .contains(&DEATH_KNIGHT_ESCAPE_SPELL_LIKE_CPP)
        {
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                TRANSFER_ABORT_UNIQUE_MESSAGE_LIKE_CPP,
                1,
                0,
            );
            return;
        }

        let same_map_near_teleport = u32::from(self.player_map_id_like_cpp()) == new_map;
        if same_map_near_teleport {
            if !self.set_represented_far_teleport_pending_like_cpp(false) {
                return;
            }
            self.initiate_same_map_near_teleport_like_cpp(new_map, new_pos, options);
            return;
        }

        if let Some((transfer_abort, arg, map_difficulty_x_condition_id)) =
            self.player_cannot_enter_target_map_like_cpp(new_map)
        {
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                transfer_abort,
                arg,
                map_difficulty_x_condition_id,
            );
            return;
        }

        if u32::from(self.player_map_id_like_cpp()) != new_map {
            options = self.teleport_options_after_seamless_gate_like_cpp(new_map, options);
        }

        if u32::from(self.player_map_id_like_cpp()) != new_map {
            let Some(can_delay) = self
                .player_teleport_state_snapshot_like_cpp()
                .map(|state| state.can_delay)
            else {
                return;
            };
            if !self.update_player_teleport_state_like_cpp(|state| {
                state.has_delayed = can_delay;
                if can_delay {
                    state.near_pending = false;
                    state.near_destination = None;
                    state.near_destination_zone_area = None;
                    state.far_pending = true;
                    state.delayed = Some((new_map, new_pos, options));
                }
            }) {
                return;
            }
            if can_delay {
                return;
            }

            self.set_selection_guid_like_cpp(None);
            self.combat_stop_like_cpp();
            self.reset_contested_pvp_like_cpp();
            self.maybe_leave_represented_battleground_on_far_teleport_like_cpp(new_map);
            self.unsummon_represented_pet_temporary_if_any_like_cpp();
            let _ = self.remove_all_dynamic_objects_for_current_player_like_cpp();
            let _ = self.remove_all_area_triggers_for_current_player_like_cpp();
            if options & TELE_TO_SPELL_LIKE_CPP == 0 {
                let _ = self.interrupt_non_melee_spells_for_far_teleport_like_cpp();
            }
            let _ = self.remove_moving_or_turning_interrupt_auras_for_far_teleport_like_cpp();
        }

        info!(
            account = self.account_id,
            old_map = self.player_map_id_like_cpp(),
            new_map = new_map,
            old_pos = format!(
                "({:.2}, {:.2}, {:.2})",
                current_pos.x, current_pos.y, current_pos.z
            ),
            new_pos = format!("({:.2}, {:.2}, {:.2})", new_pos.x, new_pos.y, new_pos.z),
            "Player teleporting to new map"
        );

        use wow_packet::packets::misc::{SuspendToken, TransferPending};

        // 1. SMSG_TRANSFER_PENDING — tell client to start loading screen
        if !self.player_logout_like_cpp && options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            let transfer_pending = TransferPending {
                map_id: new_map,
                old_map_position: current_pos,
                ship: None,
                transfer_spell_id: None,
            };
            self.send_packet(&transfer_pending);
            self.clear_active_player_transport_server_time_override_for_far_teleport_like_cpp();
        }

        let _ = self.remove_current_player_from_canonical_current_map_like_cpp();

        // 2. Store pending destination — completed in handle_world_port_response
        self.pending_teleport = Some((new_map, new_pos));
        self.active_area_trigger = None;

        // 3. SMSG_SUSPEND_TOKEN — pause movement processing on client. C++
        // Player::TeleportTo sets SequenceIndex = m_movementCounter WITHOUT incrementing
        // (Player.cpp:1466), and HandleMoveWorldportAck's ResumeToken uses the SAME counter
        // (the before-add reset happens only after ResumeToken). The client pairs suspend and
        // resume by this index, so they MUST match — a hardcoded 1 here vs the real counter in
        // ResumeToken left the client stuck on the loading screen. #NEXT.R8.ENTITIES.1229.
        if !self.player_logout_like_cpp {
            let Some(suspend_seq) = self.movement_counter_like_cpp() else {
                return;
            };
            self.send_packet(&SuspendToken {
                sequence_index: suspend_seq,
                reason: if options & TELE_TO_SEAMLESS_LIKE_CPP != 0 {
                    2
                } else {
                    1
                },
            });
        }

        // 4. Transition to Transfer state — only WorldPortResponse accepted now
        if !self.set_represented_far_teleport_pending_like_cpp(true) {
            return;
        }
        self.state = SessionState::Transfer;

        info!(
            account = self.account_id,
            "Teleport initiated: map {} → {} dest ({:.2}, {:.2}, {:.2}); awaiting WorldPortResponse",
            self.player_map_id_like_cpp(),
            new_map,
            new_pos.x,
            new_pos.y,
            new_pos.z
        );
    }

    fn exit_represented_vehicle_for_teleport_like_cpp(&mut self) -> bool {
        if self
            .player_vehicle_seat_state_like_cpp()
            .and_then(|(flags, _)| flags)
            .is_none()
        {
            return false;
        }

        if !self.set_player_vehicle_seat_state_like_cpp(None, None) {
            return false;
        }
        self.sync_player_registry_state_like_cpp();
        true
    }

    fn reset_teleport_movement_state_like_cpp(&mut self) {
        let Some(movement_flags) = self.resolved_player_movement_flags_like_cpp() else {
            return;
        };
        let movement_flags = movement_flags & MovementFlag::MASK_HAS_PLAYER_STATUS_OPCODE;
        self.set_player_movement_flags_like_cpp(movement_flags);
        #[cfg(test)]
        {
            self.player_movement_jump_like_cpp = wow_packet::packets::movement::JumpInfo::default();
        }
        let _ = self.mutate_canonical_player_like_cpp(|player| {
            let motion = &mut player.unit_mut().subsystems_mut().motion;
            motion.interrupt_spline();
            let _ =
                motion.remove_generator_kind(MovementGeneratorKind::Effect, MovementSlot::Active);
        });
    }

    fn teleport_options_after_seamless_gate_like_cpp(
        &self,
        new_map: u32,
        mut options: TeleportToOptionsLikeCpp,
    ) -> TeleportToOptionsLikeCpp {
        if options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            return options;
        }

        let Some(map_store) = self.map_store.as_ref() else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };
        let Some(old_map_entry) = map_store
            .get(u32::from(self.player_map_id_like_cpp()))
            .copied()
        else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };
        let Some(new_map_entry) = map_store.get(new_map).copied() else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };

        let old_cosmetic_parent = i32::from(old_map_entry.cosmetic_parent_map_id);
        let new_cosmetic_parent = i32::from(new_map_entry.cosmetic_parent_map_id);
        let current_map_id = i32::from(self.player_map_id_like_cpp());
        let new_map_id = i32::try_from(new_map).unwrap_or(i32::MAX);
        if old_cosmetic_parent != new_map_id
            && current_map_id != new_cosmetic_parent
            && !((old_cosmetic_parent != -1) ^ (old_cosmetic_parent != new_cosmetic_parent))
        {
            options &= !TELE_TO_SEAMLESS_LIKE_CPP;
        }

        options
    }

    fn initiate_same_map_near_teleport_like_cpp(
        &mut self,
        map_id: u32,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        let Some(can_delay) = self
            .player_teleport_state_snapshot_like_cpp()
            .map(|state| state.can_delay)
        else {
            return;
        };
        if !self.update_player_teleport_state_like_cpp(|state| {
            state.has_delayed = can_delay;
        }) {
            return;
        }
        if can_delay {
            let map_id_u16 = u16::try_from(map_id).unwrap_or(self.player_map_id_like_cpp());
            let _ = self.update_player_teleport_state_like_cpp(|state| {
                state.near_pending = true;
                state.near_destination = Some((map_id_u16, destination));
                state.near_destination_zone_area = None;
                state.delayed = Some((map_id, destination, options));
            });
            return;
        }

        self.unsummon_represented_pet_for_same_map_teleport_if_out_of_range_like_cpp(
            destination,
            options,
        );

        if self.resolved_player_is_alive_like_cpp() == Some(false)
            && options & TELE_REVIVE_AT_TELEPORT_LIKE_CPP != 0
        {
            self.resurrect_player_percent_for_teleport_like_cpp(0.5);
        }

        if options & TELE_TO_NOT_LEAVE_COMBAT_LIKE_CPP == 0 {
            self.combat_stop_like_cpp();
        }

        let map_id = u16::try_from(map_id).unwrap_or(self.player_map_id_like_cpp());
        self.pending_teleport = None;
        if !self.update_player_teleport_state_like_cpp(|state| {
            state.near_pending = true;
            state.near_destination = Some((map_id, destination));
            state.near_destination_zone_area = None;
        }) {
            return;
        }
        if let Some(current_pos) = self.player_position_like_cpp() {
            self.set_fall_information_like_cpp(0, current_pos.z);
        }

        if !self.player_logout_like_cpp {
            let Some(sequence_index) = self.next_movement_counter_like_cpp() else {
                return;
            };
            if let Some(mover_guid) = self.player_guid() {
                self.send_same_map_move_update_teleport_to_visible_set_like_cpp(mover_guid);
                self.send_packet(&wow_packet::packets::movement::MoveTeleport {
                    mover_guid,
                    position: destination,
                    facing: destination.orientation,
                    sequence_index,
                    preload_world: 0,
                    transport_guid: None,
                });
            }
        }

        info!(
            account = self.account_id,
            map_id,
            new_pos = format!(
                "({:.2}, {:.2}, {:.2})",
                destination.x, destination.y, destination.z
            ),
            "Player same-map near teleport initiated; awaiting MoveTeleportAck"
        );
    }

    fn process_represented_delayed_teleport_after_update_like_cpp(&mut self) -> bool {
        let Some(teleport) = self.player_teleport_state_snapshot_like_cpp() else {
            return false;
        };
        if !teleport.has_delayed || self.resolved_player_is_alive_like_cpp() != Some(true) {
            return false;
        }

        let Some((map_id, destination, options)) = teleport.delayed else {
            let _ = self.update_player_teleport_state_like_cpp(|state| {
                state.has_delayed = false;
            });
            return false;
        };

        if !self.update_player_teleport_state_like_cpp(|state| {
            state.delayed = None;
            state.can_delay = false;
            state.has_delayed = false;
        }) {
            return false;
        }
        if u32::from(self.player_map_id_like_cpp()) == map_id {
            self.initiate_same_map_near_teleport_like_cpp(map_id, destination, options);
        } else {
            self.initiate_far_teleport_after_delay_like_cpp(map_id, destination, options);
        }
        true
    }

    fn initiate_far_teleport_after_delay_like_cpp(
        &mut self,
        map_id: u32,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        self.set_selection_guid_like_cpp(None);
        self.combat_stop_like_cpp();
        self.reset_contested_pvp_like_cpp();
        self.maybe_leave_represented_battleground_on_far_teleport_like_cpp(map_id);
        self.unsummon_represented_pet_temporary_if_any_like_cpp();
        let _ = self.remove_all_dynamic_objects_for_current_player_like_cpp();
        let _ = self.remove_all_area_triggers_for_current_player_like_cpp();
        if options & TELE_TO_SPELL_LIKE_CPP == 0 {
            let _ = self.interrupt_non_melee_spells_for_far_teleport_like_cpp();
        }
        let _ = self.remove_moving_or_turning_interrupt_auras_for_far_teleport_like_cpp();

        let Some(current_pos) = self.player_position_like_cpp() else {
            return;
        };

        use wow_packet::packets::misc::{SuspendToken, TransferPending};

        if !self.player_logout_like_cpp && options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            let transfer_pending = TransferPending {
                map_id,
                old_map_position: current_pos,
                ship: None,
                transfer_spell_id: None,
            };
            self.send_packet(&transfer_pending);
            self.clear_active_player_transport_server_time_override_for_far_teleport_like_cpp();
        }

        let _ = self.remove_current_player_from_canonical_current_map_like_cpp();

        self.pending_teleport = Some((map_id, destination));
        self.active_area_trigger = None;

        if !self.player_logout_like_cpp {
            // C++ SuspendToken.SequenceIndex = m_movementCounter (Player.cpp:1466); must match
            // the ResumeToken sent later so the client resumes. #NEXT.R8.ENTITIES.1229.
            let Some(suspend_seq) = self.movement_counter_like_cpp() else {
                return;
            };
            self.send_packet(&SuspendToken {
                sequence_index: suspend_seq,
                reason: if options & TELE_TO_SEAMLESS_LIKE_CPP != 0 {
                    2
                } else {
                    1
                },
            });
        }

        if !self.set_represented_far_teleport_pending_like_cpp(true) {
            return;
        }
        self.state = SessionState::Transfer;
    }

    fn unsummon_represented_pet_for_same_map_teleport_if_out_of_range_like_cpp(
        &mut self,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        if options & TELE_TO_NOT_UNSUMMON_PET_LIKE_CPP != 0 {
            return;
        }
        let Some(pet_guid) = self.player_pet_guid_state_like_cpp().flatten() else {
            return;
        };
        let map_id = u32::from(self.player_map_id_like_cpp());
        let instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);

        let should_unsummon = {
            let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
                return;
            };
            let Ok(manager) = manager.lock() else {
                return;
            };
            let Some(managed) = manager.find_map(map_id, instance_id) else {
                return;
            };
            let visibility_range = managed.map().visibility_range();
            managed
                .map()
                .get_pet(pet_guid)
                .is_some_and(|pet| pet.distance_to_position(destination) > visibility_range)
        };

        if should_unsummon {
            self.unsummon_represented_pet_temporary_if_any_like_cpp();
        }
    }

    fn resurrect_player_percent_for_teleport_like_cpp(&mut self, restore_percent: f32) {
        let restored = self.with_owned_player_mut_like_cpp(|player| {
            let max_health = player
                .unit()
                .data()
                .max_health
                .clamp(1, u64::from(u32::MAX)) as u32;
            let health = ((max_health as f32) * restore_percent)
                .max(0.0)
                .min(max_health as f32) as u32;
            player
                .unit_mut()
                .set_death_state(wow_constants::DeathState::Alive);
            player.unit_mut().set_health(u64::from(health));
            let mana = ((player.get_max_power(PowerType::Mana).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            let energy = ((player.get_max_power(PowerType::Energy).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            let focus = ((player.get_max_power(PowerType::Focus).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            player.unit_mut().set_power(PowerType::Mana, mana);
            player.unit_mut().set_power(PowerType::Rage, 0);
            player.unit_mut().set_power(PowerType::Energy, energy);
            player.unit_mut().set_power(PowerType::Focus, focus);
            health
        });
        if restored.is_none() {
            return;
        }
        self.sync_player_registry_state_like_cpp();
    }

    fn send_same_map_move_update_teleport_to_visible_set_like_cpp(&self, source_guid: ObjectGuid) {
        use wow_packet::ServerPacket;

        let Some(registry) = self.player_registry() else {
            return;
        };
        let Some(source_position) = self.player_position_like_cpp() else {
            return;
        };
        let map_id = self.player_map_id_like_cpp();
        let instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let Some(status) = self.current_player_movement_info_like_cpp(source_guid) else {
            return;
        };
        let packet_bytes = wow_packet::packets::movement::MoveUpdateTeleport { status }.to_bytes();

        for registration in registry.movement_recipients_within_range(
            source_guid,
            map_id,
            instance_id,
            source_position,
            crate::map_manager::VISIBILITY_RADIUS,
        ) {
            let _ = registry.try_send_current_command(
                registration,
                crate::session::mailbox::SessionCommand::SendIfVisibleLikeCpp(
                    crate::session::mailbox::SendIfVisibleLikeCppCommand {
                        queued_at: Instant::now(),
                        source_guid,
                        map_id,
                        instance_id,
                        packet_bytes: packet_bytes.clone(),
                    },
                ),
            );
        }
    }

    fn remove_all_dynamic_objects_for_current_player_like_cpp(
        &self,
    ) -> Option<wow_map::map::RemoveAllDynamicObjectsForCasterOutcomeLikeCpp> {
        let player_guid = self.player_guid()?;
        let map_key = self.current_canonical_player_map_key_like_cpp()?;
        let canonical = self.canonical_map_manager.as_ref()?;
        let mut manager = canonical.lock().ok()?;
        let managed = manager.find_map_mut(map_key.map_id, map_key.instance_id)?;
        Some(
            managed
                .map_mut()
                .remove_all_dynamic_objects_for_caster_like_cpp(player_guid),
        )
    }

