    /// Send session initialization packets (first encrypted packets after
    /// EnterEncryptedModeAck). Matches C++ `WorldSession::InitializeSessionCallback`.
    ///
    /// These packets are sent immediately when the session starts, before any
    /// client packets are processed. They tell the client that auth succeeded
    /// and provide the initial glue screen data (character select).
    ///
    /// Exact C++ order:
    /// 1. AuthResponse
    /// 2. SetTimeZoneInformation
    /// 3. FeatureSystemStatusGlueScreen (NOT the in-game FeatureSystemStatus!)
    /// 4. ClientCacheVersion
    /// 5. AvailableHotfixes
    /// 6. AccountDataTimes (global)
    /// 7. TutorialFlags
    /// 8. ConnectionStatus (State=1)
    pub fn send_session_init_packets_with_policy_like_cpp(
        &self,
        policy: &SupportFeaturePolicyLikeCpp,
    ) {
        use wow_packet::packets::auth::*;
        use wow_packet::packets::misc::*;

        let vra = self.virtual_realm_address();
        let (realm_name_actual, realm_name_normalized) = self
            .realm_names_for_address_like_cpp(vra)
            .unwrap_or(("RustyCore", "RustyCore"));

        // 1. AuthResponse (OK) — tells the client authentication succeeded
        let auth_response = AuthResponse {
            result: 0, // OK
            success_info: Some(AuthSuccessInfo {
                virtual_realm_address: vra,
                virtual_realms: vec![VirtualRealmInfo {
                    realm_address: vra,
                    is_local: true,
                    is_internal_realm: false,
                    realm_name_actual: realm_name_actual.to_string(),
                    realm_name_normalized: realm_name_normalized.to_string(),
                }],
                time_rested: 0,
                active_expansion_level: self.expansion,
                account_expansion_level: self.account_expansion,
                time_seconds_until_pc_kick: 0,
                available_classes: default_available_classes(),
                templates: vec![],
                currency_id: 0,
                time: unix_now(),
                game_time_info: GameTimeInfo {
                    billing_plan: 0,
                    time_remain: 0,
                    unknown735: 0,
                    in_game_room: false,
                },
                is_expansion_trial: false,
                force_character_template: false,
                num_players_horde: None,
                num_players_alliance: None,
                expansion_trial_expiration: None,
            }),
            wait_info: None,
        };
        self.send_packet(&auth_response);

        // 2. SetTimeZoneInformation
        self.send_packet(&SetTimeZoneInformation::utc());

        // 3. FeatureSystemStatusGlueScreen (character select version, NOT in-game)
        self.send_packet(&self.feature_system_status_glue_screen_with_policy_like_cpp(policy));

        // 4. ClientCacheVersion (from world DB version.cache_id = 24081)
        self.send_packet(&ClientCacheVersion {
            cache_version: 24081,
        });

        let hotfixes = self
            .hotfix_blob_cache
            .as_ref()
            .map(|cache| {
                cache
                    .available_hotfix_ids(&self.locale)
                    .into_iter()
                    .map(|id| HotfixId {
                        push_id: id.push_id,
                        unique_id: id.unique_id,
                    })
                    .collect()
            })
            .unwrap_or_default();

        // 5. AvailableHotfixes
        self.send_packet(&AvailableHotfixes {
            virtual_realm_address: vra,
            hotfixes,
        });

        // 6. AccountDataTimes (global)
        self.send_packet(
            &self.account_data_times_like_cpp(ObjectGuid::EMPTY, GLOBAL_CACHE_MASK_LIKE_CPP),
        );

        // 7. TutorialFlags
        self.send_packet(&self.tutorial_flags_packet_like_cpp());

        // 8. ConnectionStatus (State=1, SuppressNotification=true)
        // This compatibility packet has no ConnectionType override,
        // so it's sent on the realm socket. State uses 2 bits, SuppressNotification
        // defaults to true.
        self.send_packet(&ConnectionStatus {
            state: 1,
            suppress_notification: true,
        });

        info!(
            "Session init packets sent for account {} (8 packets: AuthResponse → ConnectionStatus)",
            self.account_id
        );
    }

    /// Set the logged-in player GUID.
    pub fn set_player_guid(&mut self, guid: Option<ObjectGuid>) {
        let previous_player_guid = self.player_guid;
        let player_changed = self.player_guid != guid;
        if player_changed {
            let _ = self.mutate_player_world_local_state_like_cpp(|state| {
                state.zone_area_authority_complete = false;
            });
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        self.player_guid = guid;
        if player_changed {
            self.last_presented_creature_melee_health_state_revision_like_cpp = 0;
            // Visible auras and their completeness proof belong to the C++
            // Player, not the authenticated WorldSession. Clear both at the
            // identity boundary so a later character cannot inherit positive
            // or negative aura-spell authority from the previous one.
            let _ = self.mutate_player_aura_subsystem_like_cpp(|auras| {
                auras.clear_runtime_applications_like_cpp();
                auras.reset_player_aura_source_authority_like_cpp();
            });
            self.begin_player_equipment_inventory_authority_load_like_cpp();
            #[cfg(test)]
            {
                self.player_quest_status_authority_complete_like_cpp = false;
                self.represented_rewarded_quest_rows_like_cpp.clear();
                self.represented_loaded_player_flags_like_cpp = None;
                self.represented_loaded_player_flags_ex_like_cpp = None;
                self.represented_loaded_player_flags_applied_like_cpp = false;
            }
            #[cfg(test)]
            {
                self.represented_guild_id_like_cpp = 0;
                self.represented_guild_id_authority_complete_like_cpp = false;
            }
            let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
                runtime.trait_config_rows.clear();
                runtime.trait_config_rows_complete = false;
                runtime.trait_entry_rows_complete = false;
                runtime.trait_entry_rows_empty = false;
            });
            let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
                state.character_rows_empty_authority_complete = false;
            });
            // C++ owns PlayerMenu (and therefore both InteractionData and its
            // menus) under Player. A WorldSession can survive character
            // logout, so no player-menu state may cross that lifetime here.
            self.reset_player_interaction_data_like_cpp();
            self.clear_player_gossip_options_like_cpp();
            #[cfg(test)]
            self.represented_spell_acquisition_post_commit_actions_like_cpp
                .clear();
            if previous_player_guid.is_some() {
                let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
                    runtime.fallback_rows.clear();
                });
            }
            // `_SaveSkills` tombstones belong to the current C++ Player's
            // update-field slots, not to the authenticated WorldSession.
            if previous_player_guid.is_some() {
                self.clear_player_skill_tombstones_like_cpp();
            }
        }
        if let Some(guid) = guid {
            self.recent_player_guid_low_like_cpp = guid.counter() as u64;
            self.represented_seer_guid_like_cpp = Some(guid);
        }
        if guid.is_none() {
            #[cfg(test)]
            {
                self.player_bootstrap_attached_like_cpp = false;
            }
            self.represented_seer_guid_like_cpp = None;
            // Old registry clones remain permanently closed; a later character
            // selected on this authenticated session receives a fresh fence.
            self.durable_loot_money_persistence_like_cpp =
                Arc::new(DurableLootMoneyPersistenceTrackerLikeCpp::default());
        }
    }

    pub(crate) fn account_data_like_cpp(&self, data_type: u8) -> Option<&AccountDataLikeCpp> {
        self.account_data_like_cpp.get(usize::from(data_type))
    }

    pub(crate) fn account_data_times_like_cpp(
        &self,
        player_guid: ObjectGuid,
        mask: u32,
    ) -> wow_packet::packets::misc::AccountDataTimes {
        let mut times = [0i64; NUM_ACCOUNT_DATA_TYPES];
        for (index, account_data) in self.account_data_like_cpp.iter().enumerate() {
            if mask & (1u32 << index) != 0 {
                times[index] = account_data.time;
            }
        }

        wow_packet::packets::misc::AccountDataTimes::for_times(player_guid, times)
    }

    pub(crate) fn set_account_data_like_cpp(
        &mut self,
        data_type: u8,
        time: i64,
        data: String,
    ) -> bool {
        let Some(account_data) = self.account_data_like_cpp.get_mut(usize::from(data_type)) else {
            return false;
        };

        account_data.time = time;
        account_data.data = data;
        true
    }

    pub(crate) fn tutorial_flags_packet_like_cpp(
        &self,
    ) -> wow_packet::packets::misc::TutorialFlags {
        wow_packet::packets::misc::TutorialFlags {
            tutorial_data: self.tutorials_like_cpp,
        }
    }

    pub(crate) fn load_tutorials_data_values_like_cpp(&mut self, values: Option<[u32; 8]>) {
        self.tutorials_like_cpp = values.unwrap_or([0; 8]);
        self.tutorials_loaded_from_db_like_cpp = values.is_some();
        self.tutorials_loaded_coherently_like_cpp = true;
        self.tutorials_changed_like_cpp = false;
    }

    pub async fn load_tutorials_data_like_cpp(&mut self) {
        self.tutorials_like_cpp = [0; 8];
        self.tutorials_loaded_from_db_like_cpp = false;
        self.tutorials_loaded_coherently_like_cpp = false;
        self.tutorials_changed_like_cpp = false;

        let Some(port) = self
            .persistence_ports_like_cpp
            .admission
            .session_account_state
            .clone()
        else {
            warn!(
                account = self.account_id,
                "LoadTutorialsData skipped: session account-state port unavailable"
            );
            return;
        };

        match port.load_tutorials_like_cpp(self.account_id).await {
            wow_persistence::SessionTutorialsLoadOutcomeLikeCpp::Loaded(values) => {
                self.load_tutorials_data_values_like_cpp(values);
            }
            wow_persistence::SessionTutorialsLoadOutcomeLikeCpp::Failed { reason } => {
                warn!(
                    account = self.account_id,
                    "LoadTutorialsData query failed: {reason}"
                );
            }
        }
    }

    pub(crate) fn set_tutorial_int_like_cpp(&mut self, index: usize, value: u32) -> bool {
        let Some(current) = self.tutorials_like_cpp.get_mut(index) else {
            return false;
        };

        if *current != value {
            *current = value;
            self.tutorials_changed_like_cpp = true;
        }
        true
    }

    pub(crate) fn apply_tutorial_action_like_cpp(
        &mut self,
        action: u8,
        tutorial_bit: Option<u32>,
    ) -> bool {
        match action {
            wow_packet::packets::misc::TUTORIAL_ACTION_UPDATE_LIKE_CPP => {
                let Some(tutorial_bit) = tutorial_bit else {
                    return false;
                };
                let index = (tutorial_bit >> 5) as usize;
                if index >= self.tutorials_like_cpp.len() {
                    return false;
                }
                let flag = self.tutorials_like_cpp[index] | (1u32 << (tutorial_bit & 0x1F));
                self.set_tutorial_int_like_cpp(index, flag)
            }
            wow_packet::packets::misc::TUTORIAL_ACTION_CLEAR_LIKE_CPP => {
                for index in 0..self.tutorials_like_cpp.len() {
                    self.set_tutorial_int_like_cpp(index, u32::MAX);
                }
                true
            }
            wow_packet::packets::misc::TUTORIAL_ACTION_RESET_LIKE_CPP => {
                for index in 0..self.tutorials_like_cpp.len() {
                    self.set_tutorial_int_like_cpp(index, 0);
                }
                true
            }
            _ => false,
        }
    }

    pub async fn load_global_account_data_like_cpp(&mut self) {
        self.load_account_data_like_cpp(ObjectGuid::EMPTY, GLOBAL_CACHE_MASK_LIKE_CPP)
            .await;
    }

    pub async fn load_player_account_data_like_cpp(&mut self, guid: ObjectGuid) {
        self.load_account_data_like_cpp(guid, PER_CHARACTER_CACHE_MASK_LIKE_CPP)
            .await;
    }

    async fn load_account_data_like_cpp(&mut self, guid: ObjectGuid, mask: u32) {
        debug_assert_eq!(
            GLOBAL_CACHE_MASK_LIKE_CPP | PER_CHARACTER_CACHE_MASK_LIKE_CPP,
            ALL_ACCOUNT_DATA_CACHE_MASK_LIKE_CPP
        );

        for index in 0..NUM_ACCOUNT_DATA_TYPES {
            if mask & (1u32 << index) != 0 {
                self.account_data_like_cpp[index] = AccountDataLikeCpp::default();
            }
        }

        let scope = if mask == GLOBAL_CACHE_MASK_LIKE_CPP {
            wow_persistence::SessionAccountDataScopeLikeCpp::Global {
                account_id: self.account_id,
            }
        } else {
            wow_persistence::SessionAccountDataScopeLikeCpp::Character {
                guid_low: guid.counter() as u64,
            }
        };

        let Some(port) = self
            .persistence_ports_like_cpp
            .admission
            .session_account_state
            .clone()
        else {
            warn!(
                account = self.account_id,
                mask, "LoadAccountData skipped: session account-state port unavailable"
            );
            return;
        };

        let rows = match port.load_account_data_like_cpp(scope).await {
            wow_persistence::SessionAccountDataLoadOutcomeLikeCpp::Loaded(rows) => rows,
            wow_persistence::SessionAccountDataLoadOutcomeLikeCpp::Failed { reason } => {
                warn!(
                    account = self.account_id,
                    mask, "LoadAccountData query failed: {reason}"
                );
                return;
            }
        };

        let table_name = if mask == GLOBAL_CACHE_MASK_LIKE_CPP {
            "account_data"
        } else {
            "character_account_data"
        };
        for row in rows {
            let data_type = row.data_type;
            if usize::from(data_type) >= NUM_ACCOUNT_DATA_TYPES {
                warn!(
                    table = table_name,
                    data_type, "LoadAccountData ignored invalid account data type like C++"
                );
            } else if mask & (1u32 << data_type) == 0 {
                warn!(
                    table = table_name,
                    data_type,
                    "LoadAccountData ignored account data type inappropriate for table like C++"
                );
            } else {
                self.account_data_like_cpp[usize::from(data_type)].time = row.time;
                self.account_data_like_cpp[usize::from(data_type)].data = row.data;
            }
        }
    }

    pub async fn set_account_data_persisted_like_cpp(
        &mut self,
        data_type: u8,
        time: i64,
        data: String,
    ) -> bool {
        if usize::from(data_type) >= NUM_ACCOUNT_DATA_TYPES {
            return false;
        }

        let is_global = (1u32 << data_type) & GLOBAL_CACHE_MASK_LIKE_CPP != 0;
        let player_guid_low = self.recent_player_guid_low_like_cpp;

        if !is_global && player_guid_low == 0 {
            return false;
        }

        let scope = if is_global {
            wow_persistence::SessionAccountDataScopeLikeCpp::Global {
                account_id: self.account_id,
            }
        } else {
            wow_persistence::SessionAccountDataScopeLikeCpp::Character {
                guid_low: player_guid_low,
            }
        };

        let Some(port) = self
            .persistence_ports_like_cpp
            .admission
            .session_account_state
            .clone()
        else {
            warn!(
                account = self.account_id,
                data_type, "SetAccountData persisted fallback: account-state port unavailable"
            );
            return self.set_account_data_like_cpp(data_type, time, data);
        };

        let save = wow_persistence::SessionAccountDataSaveLikeCpp {
            scope,
            data_type,
            time,
            data: data.clone(),
        };
        match port.save_account_data_like_cpp(save).await {
            wow_persistence::PersistenceOutcomeLikeCpp::Applied { .. } => {}
            wow_persistence::PersistenceOutcomeLikeCpp::Failed { reason }
            | wow_persistence::PersistenceOutcomeLikeCpp::Unknown { reason } => {
                warn!(
                    account = self.account_id,
                    data_type, "SetAccountData persistence failed: {reason}"
                );
                return false;
            }
        }

        self.set_account_data_like_cpp(data_type, time, data)
    }

    pub(crate) fn set_loaded_player_name_like_cpp(&mut self, name: String) {
        self.player_name = Some(name);
    }

    pub(crate) fn set_loaded_player_identity_like_cpp(
        &mut self,
        map_id: u16,
        race: u8,
        class: u8,
        level: u8,
        gender: u8,
    ) {
        if self.player_map_id_like_cpp() != map_id
            || self.player_race_like_cpp() != race
            || self.player_class_like_cpp() != class
            || self.player_gender_like_cpp() != gender
        {
            self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        }
        self.current_map_id = map_id;
        self.player_race = race;
        self.player_class = class;
        self.player_level = level;
        self.player_gender = gender;
        self.set_player_faction_for_race_like_cpp(race);
        self.initialize_reputation_mgr_like_cpp();
        self.refresh_represented_talent_points_like_cpp();
    }

    /// C++ `Player::SetFactionForRace`: `Player::LoadFromDB` resolves the
    /// player's live faction template from `ChrRacesEntry::FactionID` before
    /// the player is added to the map or published through ObjectAccessor.
    fn set_player_faction_for_race_like_cpp(&mut self, race: u8) {
        let Some(chr_races_store) = self.chr_races_store.as_ref() else {
            return;
        };
        let faction_template = chr_races_store
            .get(u32::from(race))
            .and_then(|entry| u32::try_from(entry.faction_id).ok())
            .filter(|faction_template| *faction_template != 0);
        let faction_template = faction_template.unwrap_or(0);
        let _canonical = self.with_owned_player_mut_like_cpp(|player| {
            player.unit_mut().set_faction(faction_template);
        });
        #[cfg(test)]
        if _canonical.is_some() || self.player_handle_like_cpp.is_none() {
            self.player_faction_template_like_cpp =
                (faction_template != 0).then_some(faction_template);
        }
    }

    pub(crate) fn set_loaded_player_flags_like_cpp(&mut self, player_flags: u32) {
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        let _canonical = self
            .mutate_canonical_player_like_cpp(|player| {
                player.replace_all_player_flags(player_flags)
            })
            .is_some();
        #[cfg(test)]
        {
            self.represented_loaded_player_flags_like_cpp = Some(player_flags);
            self.represented_loaded_player_flags_ex_like_cpp
                .get_or_insert(0);
            self.represented_loaded_player_flags_applied_like_cpp = _canonical;
        }
    }

    pub(crate) fn set_loaded_player_flags_ex_like_cpp(&mut self, player_flags_ex: u32) {
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        let _canonical = self
            .mutate_canonical_player_like_cpp(|player| {
                player.replace_all_player_flags_ex(player_flags_ex)
            })
            .is_some();
        #[cfg(test)]
        {
            self.represented_loaded_player_flags_ex_like_cpp = Some(player_flags_ex);
            self.represented_loaded_player_flags_applied_like_cpp = _canonical;
        }
    }

    #[cfg(test)]
    pub(crate) fn apply_loaded_player_flags_to_canonical_like_cpp(&mut self) {
        let Some(player_flags) = self.represented_loaded_player_flags_like_cpp else {
            return;
        };
        let player_flags_ex = self
            .represented_loaded_player_flags_ex_like_cpp
            .unwrap_or(0);
        if self
            .mutate_canonical_player_like_cpp(|player| {
                player.replace_all_player_flags(player_flags);
                player.replace_all_player_flags_ex(player_flags_ex);
            })
            .is_some()
        {
            self.represented_loaded_player_flags_applied_like_cpp = true;
        }
    }

    pub(crate) fn set_loaded_player_powers_like_cpp(
        &mut self,
        powers: [i32; MAX_POWERS_PER_CLASS],
    ) {
        let _canonical = self.with_owned_player_mut_for_power_like_cpp(|player| {
            let max_power = player.unit().data().max_power;
            player
                .unit_mut()
                .replace_create_power_arrays_like_cpp(powers.map(|value| value.max(0)), max_power);
        });
        #[cfg(test)]
        if _canonical.is_some() || self.player_handle_like_cpp.is_none() {
            self.represented_player_powers_like_cpp =
                loaded_character_power_snapshot_like_cpp(powers);
        }
    }

    #[cfg(test)]
    pub(crate) fn set_represented_player_power_slot_like_cpp(
        &mut self,
        slot: usize,
        current: i32,
        max: Option<i32>,
    ) {
        if slot >= MAX_POWERS_PER_CLASS {
            return;
        }
        self.represented_player_powers_like_cpp[slot] = Some(current.max(0));
        if let Some(max) = max {
            self.represented_player_max_powers_like_cpp[slot] = Some(max.max(0));
        }
    }

