    pub(crate) fn set_known_spells_like_cpp(&mut self, spells: Vec<i32>) {
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        self.invalidate_represented_player_spell_rows_like_cpp();
        let known_spells = spells.clone();
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.known_spells = spells;
            runtime.removed_known_spells.clear();
            runtime
                .dependent_known_spells
                .retain(|spell_id| known_spells.contains(spell_id));
            runtime
                .favorite_known_spells
                .retain(|spell_id| known_spells.contains(spell_id));
        });
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime
                .trait_definition_ids
                .retain(|spell_id, _| known_spells.contains(spell_id));
        });
        self.learn_account_mount_spells_like_cpp();
    }

    fn invalidate_represented_player_spell_rows_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.rows.clear();
            runtime.rows_loaded = false;
            runtime.rows_complete = false;
        });
        self.invalidate_represented_spell_acquisition_auxiliary_authority_like_cpp();
    }

    fn invalidate_represented_spell_acquisition_auxiliary_authority_like_cpp(&mut self) {
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.trait_definition_ids_complete = false;
            runtime.override_spells_complete = false;
        });
    }

    pub(crate) fn set_complete_represented_player_spell_rows_like_cpp(
        &mut self,
        rows: impl IntoIterator<Item = RepresentedPlayerSpellLikeCpp>,
    ) -> bool {
        self.replace_loaded_represented_player_spell_rows_like_cpp(rows, true)
    }

    pub(crate) fn replace_loaded_represented_player_spell_rows_like_cpp(
        &mut self,
        rows: impl IntoIterator<Item = RepresentedPlayerSpellLikeCpp>,
        complete: bool,
    ) -> bool {
        // A replacement can describe another logical PlayerSpellMap. Existing
        // trait/override mirrors must be re-authorized even when spell IDs happen
        // to overlap, otherwise residual state can be attributed to the new map.
        self.invalidate_represented_spell_acquisition_auxiliary_authority_like_cpp();
        let mut exact_rows = BTreeMap::new();
        for row in rows {
            if row.spell_id <= 0 || exact_rows.insert(row.spell_id, row).is_some() {
                self.invalidate_represented_player_spell_rows_like_cpp();
                return false;
            }
        }

        // A coherent load must not erase a dirty base grant produced earlier
        // in this same Player lifetime while ancillary planner authority was
        // unavailable. Reconcile it against the newly authoritative row using
        // C++ `Player::LearnSpell`: disabled rows preserve active, other rows
        // become active, and favorite/dependent state comes from the load.
        let fallback_rows = self
            .player_spell_runtime_snapshot_like_cpp()
            .map(|runtime| runtime.fallback_rows)
            .unwrap_or_default();
        for (&spell_id, &fallback) in &fallback_rows {
            let reconciled = if let Some(loaded) = exact_rows.get(&spell_id).copied() {
                let active = if loaded.disabled { loaded.active } else { true };
                let dependent_promoted = fallback.dependent && !loaded.dependent;
                RepresentedPlayerSpellLikeCpp {
                    active,
                    disabled: false,
                    state: match loaded.state {
                        RepresentedPlayerSpellStateLikeCpp::New => {
                            RepresentedPlayerSpellStateLikeCpp::New
                        }
                        RepresentedPlayerSpellStateLikeCpp::Removed => {
                            RepresentedPlayerSpellStateLikeCpp::Changed
                        }
                        RepresentedPlayerSpellStateLikeCpp::Temporary => {
                            RepresentedPlayerSpellStateLikeCpp::New
                        }
                        _ if loaded.disabled || loaded.active != active || dependent_promoted => {
                            RepresentedPlayerSpellStateLikeCpp::Changed
                        }
                        _ => loaded.state,
                    },
                    dependent: loaded.dependent || fallback.dependent,
                    ..loaded
                }
            } else {
                fallback
            };
            exact_rows.insert(spell_id, reconciled);
        }

        self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.rows = exact_rows;
            runtime.rows_loaded = true;
            runtime.rows_complete = complete;
        })
        .is_some()
    }

    /// Authorizes the current post-login spell, trait and override mirrors as one
    /// coherent acquisition snapshot. Call only after all represented `AddSpell`
    /// work for character login has completed.
    pub(crate) fn mark_represented_spell_acquisition_snapshot_complete_like_cpp(&mut self) {
        let _ = self.mutate_player_spell_runtime_like_cpp(|runtime| {
            runtime.override_spells_complete = true;
        });
    }

    pub(crate) fn set_account_mounts_like_cpp(&mut self, mounts: Vec<AccountMount>) {
        let mounts = mounts
            .into_iter()
            .map(|mount| (mount.spell_id, mount.flags))
            .collect();
        let _ = self.mutate_player_collection_state_like_cpp(|collections| {
            collections.mounts = mounts;
        });
        self.expand_account_mount_faction_definitions_like_cpp();
        self.learn_account_mount_spells_like_cpp();
    }

    pub(crate) fn promote_loaded_character_mount_spells_like_cpp(
        &mut self,
        spells: &[i32],
    ) -> usize {
        if self.mount_store.is_none() {
            return 0;
        }

        let mut added = 0usize;
        for &spell_id in spells {
            added +=
                usize::from(self.add_account_mount_with_faction_counterpart_like_cpp(spell_id, 0));
        }
        added
    }

    fn add_account_mount_with_faction_counterpart_like_cpp(
        &mut self,
        spell_id: i32,
        flags: u8,
    ) -> bool {
        self.add_account_mount_like_cpp(spell_id, flags, true)
    }

    fn add_account_mount_like_cpp(
        &mut self,
        spell_id: i32,
        flags: u8,
        include_faction_counterpart: bool,
    ) -> bool {
        let Ok(spell_id_u32) = u32::try_from(spell_id) else {
            return false;
        };
        if self.mount_store.as_ref().is_some_and(|store| {
            store
                .get_by_source_spell_id_like_cpp(spell_id_u32)
                .is_none()
        }) {
            return false;
        }

        if include_faction_counterpart
            && let Some(other_faction_spell_id) = self
                .mount_definition_store_like_cpp
                .as_ref()
                .and_then(|store| store.other_faction_spell_id_like_cpp(spell_id_u32))
            && let Ok(other_faction_spell_id) = i32::try_from(other_faction_spell_id)
        {
            self.add_account_mount_like_cpp(other_faction_spell_id, flags, false);
        }

        self.mutate_player_collection_state_like_cpp(|collections| {
            match collections.mounts.entry(spell_id) {
                std::collections::hash_map::Entry::Vacant(entry) => {
                    entry.insert(flags);
                    true
                }
                std::collections::hash_map::Entry::Occupied(_) => false,
            }
        })
        .unwrap_or(false)
    }

    fn expand_account_mount_faction_definitions_like_cpp(&mut self) {
        let Some(mounts) = self
            .player_collection_state_snapshot_like_cpp()
            .map(|collections| collections.mounts.into_iter().collect::<Vec<_>>())
        else {
            return;
        };
        for (spell_id, flags) in mounts {
            self.add_account_mount_with_faction_counterpart_like_cpp(spell_id, flags);
        }
    }

    fn learn_account_mount_spells_like_cpp(&mut self) -> usize {
        let Some(mut spell_ids) = self
            .player_collection_state_snapshot_like_cpp()
            .map(|collections| collections.mounts.into_keys().collect::<Vec<_>>())
        else {
            return 0;
        };
        spell_ids.sort_unstable();
        spell_ids.dedup();

        let mut learned = 0usize;
        for spell_id in spell_ids {
            let Ok(spell_id_u32) = u32::try_from(spell_id) else {
                continue;
            };
            if !self.mount_store.as_ref().is_none_or(|store| {
                store
                    .get_by_source_spell_id_like_cpp(spell_id_u32)
                    .is_some()
            }) {
                continue;
            }
            let before = self.known_spells_like_cpp().len();
            self.learn_dependent_known_spell_like_cpp(spell_id);
            learned += usize::from(self.known_spells_like_cpp().len() != before);
        }
        learned
    }

    pub(crate) const fn account_mount_spells_are_session_dependent_like_cpp() -> bool {
        true
    }

    fn with_canonical_pet_like_cpp<R>(
        &self,
        pet_guid: ObjectGuid,
        inspect: impl FnOnce(&Pet) -> R,
    ) -> Option<R> {
        let manager = self.canonical_map_manager.as_ref()?.lock().ok()?;
        let mut inspect = Some(inspect);
        let mut result = None;
        manager.do_for_all_maps(|managed| {
            if result.is_some() {
                return;
            }
            if let Some(pet) = managed.map().get_typed_pet(pet_guid) {
                result = Some(inspect.take().expect("pet inspector consumed once")(pet));
            }
        });
        result
    }

    fn with_canonical_pet_mut_like_cpp<R>(
        &self,
        pet_guid: ObjectGuid,
        mutate: impl FnOnce(&mut Pet) -> R,
    ) -> Option<R> {
        let mut manager = self.canonical_map_manager.as_ref()?.lock().ok()?;
        let mut mutate = Some(mutate);
        let mut result = None;
        manager.do_for_all_maps_mut(|managed| {
            if result.is_some() {
                return;
            }
            if let Some(pet) = managed.map_mut().get_typed_pet_mut(pet_guid) {
                result = Some(mutate.take().expect("pet mutation consumed once")(pet));
            }
        });
        result
    }

    fn canonical_pet_mode_state_like_cpp(&self) -> Option<(u8, u8)> {
        let pet_guid = self.player_pet_guid_state_like_cpp().flatten()?;
        let canonical = self.with_canonical_pet_like_cpp(pet_guid, |pet| {
            let react_state = pet.creature().react_state() as u8;
            let command_state = pet
                .creature()
                .unit()
                .subsystems()
                .control
                .charm_info
                .as_ref()
                .map_or(wow_packet::packets::pet::COMMAND_FOLLOW_LIKE_CPP, |info| {
                    info.command_state
                });
            (react_state, command_state)
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some((
                self.represented_pet_react_state_like_cpp,
                self.represented_pet_command_state_like_cpp,
            ));
        }
        canonical
    }

    fn update_canonical_pet_mode_state_like_cpp(
        &mut self,
        react_state: u8,
        command_state: u8,
    ) -> bool {
        let Some(pet_guid) = self.player_pet_guid_state_like_cpp().flatten() else {
            return false;
        };
        let canonical = self
            .with_canonical_pet_mut_like_cpp(pet_guid, |pet| {
                pet.creature_mut()
                    .set_react_state(react_state_from_db_like_cpp(react_state));
                pet.creature_mut()
                    .unit_mut()
                    .subsystems_mut()
                    .control
                    .init_charm_info()
                    .command_state = command_state;
            })
            .is_some();
        #[cfg(test)]
        if !canonical && self.player_handle_like_cpp.is_none() {
            self.represented_pet_react_state_like_cpp = react_state;
            self.represented_pet_command_state_like_cpp = command_state;
            return true;
        }
        canonical
    }

    fn player_pet_lifecycle_state_snapshot_like_cpp(
        &self,
    ) -> Option<PlayerPetLifecycleStateLikeCpp> {
        let canonical =
            self.with_owned_player_like_cpp(|player| player.pet_lifecycle_state_like_cpp().clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(PlayerPetLifecycleStateLikeCpp {
                stable: self.represented_pet_stable_like_cpp.clone(),
                character_rows_empty_authority_complete: self
                    .represented_character_pet_rows_empty_authority_complete_like_cpp,
                temporary_unsummoned_pet_number: self
                    .represented_temporary_unsummoned_pet_number_like_cpp,
                old_pet_spell: self.represented_old_pet_spell_like_cpp,
                temporary_mount_react_state: self.temporary_mount_pet_react_state_like_cpp,
            });
        }
        canonical
    }

    fn update_player_pet_lifecycle_state_like_cpp(
        &mut self,
        update: impl FnOnce(&mut PlayerPetLifecycleStateLikeCpp),
    ) -> bool {
        if self.player_handle_like_cpp.is_some() {
            return self
                .with_owned_player_mut_like_cpp(|player| {
                    update(player.pet_lifecycle_state_mut_like_cpp())
                })
                .is_some();
        }
        #[cfg(test)]
        {
            let mut state = self
                .player_pet_lifecycle_state_snapshot_like_cpp()
                .unwrap_or_default();
            update(&mut state);
            self.represented_pet_stable_like_cpp = state.stable;
            self.represented_character_pet_rows_empty_authority_complete_like_cpp =
                state.character_rows_empty_authority_complete;
            self.represented_temporary_unsummoned_pet_number_like_cpp =
                state.temporary_unsummoned_pet_number;
            self.represented_old_pet_spell_like_cpp = state.old_pet_spell;
            self.temporary_mount_pet_react_state_like_cpp = state.temporary_mount_react_state;
            true
        }
        #[cfg(not(test))]
        {
            let _ = update;
            false
        }
    }

    pub(crate) fn begin_represented_character_pet_authority_load_like_cpp(&mut self) {
        self.pet_load_query_holder_rows_like_cpp.reset();
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
    }

    fn invalidate_represented_character_pet_empty_authority_like_cpp(&mut self) {
        let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
            state.character_rows_empty_authority_complete = false;
        });
        self.invalidate_canonical_player_spell_hit_aura_authority_like_cpp();
    }

    #[allow(dead_code)]
    pub(crate) fn set_represented_pet_mode_state_like_cpp(
        &mut self,
        pet_guid: Option<ObjectGuid>,
        react_state: u8,
        command_state: u8,
    ) {
        self.set_represented_pet_mode_state_with_spell_like_cpp(
            pet_guid,
            react_state,
            command_state,
            0,
        );
    }

    #[allow(dead_code)]
    pub(crate) fn set_represented_pet_mode_state_with_spell_like_cpp(
        &mut self,
        pet_guid: Option<ObjectGuid>,
        react_state: u8,
        command_state: u8,
        created_by_spell: u32,
    ) {
        if !self.set_player_pet_guid_like_cpp(pet_guid) {
            return;
        }
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let canonical = pet_guid.is_some_and(|pet_guid| {
            self.with_canonical_pet_mut_like_cpp(pet_guid, |pet| {
                pet.set_created_by_spell_id_like_cpp(created_by_spell);
                pet.creature_mut()
                    .set_react_state(react_state_from_db_like_cpp(react_state));
                pet.creature_mut()
                    .unit_mut()
                    .subsystems_mut()
                    .control
                    .init_charm_info()
                    .command_state = command_state;
            })
            .is_some()
        });
        #[cfg(test)]
        if !canonical {
            self.represented_pet_created_by_spell_like_cpp = created_by_spell;
            self.represented_pet_react_state_like_cpp = react_state;
            self.represented_pet_command_state_like_cpp = command_state;
        }
        #[cfg(not(test))]
        let _ = canonical;
        if pet_guid.is_none() {
            let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
                state.temporary_unsummoned_pet_number = 0;
                state.old_pet_spell = 0;
            });
            #[cfg(test)]
            {
                self.represented_pet_movement_speed_rates_like_cpp =
                    [1.0; UnitMoveTypeLikeCpp::COUNT];
            }
        }
        let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
            state.temporary_mount_react_state = None;
        });
    }

    pub(crate) fn set_represented_pet_stable_like_cpp(&mut self, stable: PetStable) {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| state.stable = stable);
    }

    pub(crate) fn apply_represented_login_pet_talent_reset_like_cpp(&mut self) -> bool {
        const AT_LOGIN_RESET_PET_TALENTS_LIKE_CPP: u16 = 0x010;

        if !self
            .resolved_represented_at_login_flags_like_cpp()
            .is_some_and(|flags| (flags & AT_LOGIN_RESET_PET_TALENTS_LIKE_CPP) != 0)
        {
            return false;
        }

        self.invalidate_represented_character_pet_empty_authority_like_cpp();

        if !self.update_player_pet_lifecycle_state_like_cpp(|state| {
            for pet in state.stable.active_pets.iter_mut().flatten() {
                pet.specialization_id = 0;
            }
            for pet in state.stable.stabled_pets.iter_mut().flatten() {
                pet.specialization_id = 0;
            }
            for pet in &mut state.stable.unslotted_pets {
                pet.specialization_id = 0;
            }
        }) {
            return false;
        }
        self.pet_load_query_holder_rows_like_cpp.spells.clear();
        true
    }

    /// C++ `Player::RemovePet(nullptr, PET_SAVE_NOT_IN_SLOT, true)`.
    ///
    /// Represented boundary: clears the active represented pet link, resets
    /// `PetStable::CurrentPetIndex`, and removes the live typed pet from the
    /// canonical map if present. Reagent return and exact `Pet::SavePetToDB`
    /// remain owned by the future full pet/inventory persistence runtime.
    pub(crate) fn remove_represented_pet_not_in_slot_like_cpp(&mut self) {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let pet_guid = self.player_pet_guid_state_like_cpp().flatten();
        if let Some(pet_guid) = pet_guid
            && let Some(manager) = self.canonical_map_manager.as_ref().map(Arc::clone)
            && let Ok(mut manager) = manager.lock()
        {
            let mut removed = false;
            manager.do_for_all_maps_mut(|managed| {
                if removed {
                    return;
                }
                match managed.map_mut().remove_from_map_like_cpp(pet_guid, false) {
                    Ok(_) => removed = true,
                    Err(wow_map::RemoveFromMapError::ObjectNotFound { .. }) => {}
                    Err(_) => {}
                }
            });
        }

        if self.player_pet_guid_state_like_cpp().flatten().is_some() {
            let _ = self.set_player_pet_guid_like_cpp(None);
            #[cfg(test)]
            {
                self.represented_pet_created_by_spell_like_cpp = 0;
                self.represented_pet_react_state_like_cpp =
                    wow_packet::packets::pet::REACT_DEFENSIVE_LIKE_CPP;
                self.represented_pet_command_state_like_cpp =
                    wow_packet::packets::pet::COMMAND_FOLLOW_LIKE_CPP;
            }
            let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
                state.temporary_mount_react_state = None;
            });
            #[cfg(test)]
            {
                self.represented_pet_movement_speed_rates_like_cpp =
                    [1.0; UnitMoveTypeLikeCpp::COUNT];
            }
        }
        let _ = self.update_player_pet_lifecycle_state_like_cpp(|state| {
            state.stable.current_pet_index = None;
        });
    }

    #[cfg(test)]
    pub(crate) fn represented_pet_stable_current_index_like_cpp(&self) -> Option<u32> {
        self.player_pet_lifecycle_state_snapshot_like_cpp()
            .and_then(|state| state.stable.current_pet_index)
    }

    pub(crate) fn load_represented_pet_stable_rows_like_cpp(
        &mut self,
        summoned_pet_number: u32,
        rows: impl IntoIterator<Item = CharacterPetStableRowLikeCpp>,
    ) -> usize {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let mut stable = PetStable::default();
        let mut loaded = 0usize;
        let mut query_had_rows = false;

        for row in rows {
            query_had_rows = true;
            let slot = row.slot;
            let pet_info = PetStableInfo {
                name: row.name,
                action_bar: row.action_bar,
                pet_number: row.pet_number,
                creature_id: row.creature_id,
                display_id: row.display_id,
                experience: row.experience,
                health: row.health,
                mana: row.mana,
                last_save_time: row.last_save_time,
                created_by_spell_id: row.created_by_spell_id,
                specialization_id: row.specialization_id,
                level: row.level,
                react_state: react_state_from_db_like_cpp(row.react_state),
                pet_type: pet_type_from_db_like_cpp(row.pet_type),
                was_renamed: row.was_renamed,
            };

            if PetSaveMode::is_active_slot(slot) {
                let index = slot as usize;
                if stable.active_pets.len() <= index {
                    stable.active_pets.resize_with(index + 1, || None);
                }
                stable.active_pets[index] = Some(pet_info);
            } else if PetSaveMode::is_stabled_slot(slot) {
                let index = (slot - PetSaveMode::stable_slot(0)) as usize;
                if stable.stabled_pets.len() <= index {
                    stable.stabled_pets.resize_with(index + 1, || None);
                }
                stable.stabled_pets[index] = Some(pet_info);
            } else if slot == PetSaveMode::NotInSlot as i16 {
                stable.unslotted_pets.push(pet_info);
            } else {
                continue;
            }

            loaded = loaded.saturating_add(1);
        }

        let selected_summoned_pet =
            Pet::get_load_pet_info(&stable, 0, summoned_pet_number, None).is_some();
        if selected_summoned_pet {
            stable.current_pet_index = stable
                .active_pets
                .iter()
                .position(|pet| {
                    pet.as_ref()
                        .is_some_and(|pet| pet.pet_number == summoned_pet_number)
                })
                .map(|index| index as u32);
        }

        if !self.update_player_pet_lifecycle_state_like_cpp(|state| {
            // C++ remembers the selected controlled pet on the Player even
            // while the live Pet object is absent from Map storage.
            if selected_summoned_pet {
                state.temporary_unsummoned_pet_number = summoned_pet_number;
            }
            state.stable = stable;
            state.character_rows_empty_authority_complete = !query_had_rows;
        }) {
            return 0;
        }
        loaded
    }

    pub(crate) fn load_represented_pet_spell_rows_like_cpp(
        &mut self,
        pet_number: u32,
        rows: impl IntoIterator<Item = CharacterPetSpellRowLikeCpp>,
    ) -> usize {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let spells: Vec<_> = rows.into_iter().filter(|row| row.spell_id != 0).collect();
        let loaded = spells.len();
        if loaded == 0 {
            self.pet_load_query_holder_rows_like_cpp
                .spells
                .remove(&pet_number);
        } else {
            self.pet_load_query_holder_rows_like_cpp
                .spells
                .insert(pet_number, spells);
        }
        loaded
    }

