    pub(crate) fn load_represented_pet_aura_rows_like_cpp(
        &mut self,
        pet_number: u32,
        rows: impl IntoIterator<Item = CharacterPetAuraRowLikeCpp>,
    ) -> usize {
        self.load_represented_pet_aura_rows_with_timediff_like_cpp(pet_number, rows, 0)
    }

    pub(crate) fn load_represented_pet_aura_rows_with_timediff_like_cpp(
        &mut self,
        pet_number: u32,
        rows: impl IntoIterator<Item = CharacterPetAuraRowLikeCpp>,
        timediff_secs: u32,
    ) -> usize {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let spell_store = self.spell_store().cloned();
        let difficulty_store = self.difficulty_store().cloned();
        let aura_options_store = self.spell_aura_options_store.clone();
        let spell_misc_store = self.spell_misc_store().cloned();
        let auras: Vec<_> = rows
            .into_iter()
            .filter(|row| {
                row.spell_id != 0
                    && spell_store
                        .as_ref()
                        .is_none_or(|store| store.get(row.spell_id as i32).is_some())
                    && (row.difficulty == 0
                        || difficulty_store
                            .as_ref()
                            .is_none_or(|store| store.contains(u32::from(row.difficulty))))
            })
            .filter_map(|mut row| {
                let aura_expires_offline = spell_misc_store
                    .as_ref()
                    .and_then(|store| store.get_by_spell_id(row.spell_id))
                    .is_some_and(|misc| {
                        (misc.attributes[4] as u32
                            & wow_data::spell::attributes::SPELL_ATTR4_AURA_EXPIRES_OFFLINE)
                            != 0
                    });
                if let Some(remain_time_ms) = adjusted_represented_pet_aura_remain_time_like_cpp(
                    row.remain_time_ms,
                    timediff_secs,
                    true,
                    aura_expires_offline,
                ) {
                    row.remain_time_ms = remain_time_ms;
                } else {
                    return None;
                }

                if let Some(store) = aura_options_store.as_ref() {
                    let proc_charges = store.proc_charges_like_cpp(row.spell_id, row.difficulty);
                    row.remain_charges = if proc_charges == 0 {
                        0
                    } else if row.remain_charges == 0 {
                        proc_charges
                    } else {
                        row.remain_charges
                    };
                }
                Some(row)
            })
            .collect();
        let loaded = auras.len();
        if loaded == 0 {
            self.pet_load_query_holder_rows_like_cpp
                .auras
                .remove(&pet_number);
        } else {
            self.pet_load_query_holder_rows_like_cpp
                .auras
                .insert(pet_number, auras);
        }
        loaded
    }

    pub(crate) fn load_represented_pet_aura_effect_rows_like_cpp(
        &mut self,
        pet_number: u32,
        rows: impl IntoIterator<Item = CharacterPetAuraEffectRowLikeCpp>,
    ) -> usize {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        let effects: Vec<_> = rows
            .into_iter()
            .filter(|row| {
                row.spell_id != 0
                    && u32::from(row.effect_index)
                        < wow_data::conditions::MAX_SPELL_EFFECTS_LIKE_CPP
            })
            .collect();
        let loaded = effects.len();
        if loaded == 0 {
            self.pet_load_query_holder_rows_like_cpp
                .aura_effects
                .remove(&pet_number);
        } else {
            self.pet_load_query_holder_rows_like_cpp
                .aura_effects
                .insert(pet_number, effects);
        }
        loaded
    }

    pub(crate) fn load_represented_character_auras_like_cpp(
        &mut self,
        aura_rows: impl IntoIterator<Item = CharacterAuraRowLikeCpp>,
        effect_rows: impl IntoIterator<Item = CharacterAuraEffectRowLikeCpp>,
        timediff_secs: u32,
    ) -> usize {
        let Some(player_guid) = self.player_guid() else {
            return 0;
        };
        let spell_store = self.spell_store().cloned();
        let difficulty_store = self.difficulty_store().cloned();
        let aura_options_store = self.spell_aura_options_store.clone();
        let spell_misc_store = self.spell_misc_store().cloned();

        let effects: Vec<_> = effect_rows
            .into_iter()
            .filter(|row| {
                row.spell_id != 0
                    && u32::from(row.effect_index)
                        < wow_data::conditions::MAX_SPELL_EFFECTS_LIKE_CPP
            })
            .collect();

        let mut loaded = 0usize;
        for mut row in aura_rows {
            if row.spell_id == 0
                || spell_store
                    .as_ref()
                    .is_some_and(|store| store.get(row.spell_id as i32).is_none())
                || (row.difficulty != 0
                    && difficulty_store
                        .as_ref()
                        .is_some_and(|store| !store.contains(u32::from(row.difficulty))))
            {
                continue;
            }

            let aura_expires_offline = spell_misc_store
                .as_ref()
                .and_then(|store| store.get_by_spell_id(row.spell_id))
                .is_some_and(|misc| {
                    (misc.attributes[4] as u32
                        & wow_data::spell::attributes::SPELL_ATTR4_AURA_EXPIRES_OFFLINE)
                        != 0
                });
            let Some(remain_time_ms) = adjusted_represented_pet_aura_remain_time_like_cpp(
                row.remain_time_ms,
                timediff_secs,
                true,
                aura_expires_offline,
            ) else {
                continue;
            };
            row.remain_time_ms = remain_time_ms;

            if let Some(store) = aura_options_store.as_ref() {
                let proc_charges = store.proc_charges_like_cpp(row.spell_id, row.difficulty);
                row.remain_charges = if proc_charges == 0 {
                    0
                } else if row.remain_charges == 0 {
                    proc_charges
                } else {
                    row.remain_charges
                };
            }

            let Some(slot) = self.next_player_visible_aura_slot_like_cpp() else {
                break;
            };

            let caster_guid = if row.caster_guid.is_empty() {
                player_guid
            } else {
                row.caster_guid
            };
            let represented_effect_amounts: Vec<_> = effects
                .iter()
                .filter(|effect| {
                    let effect_caster_guid = if effect.caster_guid.is_empty() {
                        player_guid
                    } else {
                        effect.caster_guid
                    };
                    effect_caster_guid == caster_guid
                        && effect.spell_id == row.spell_id
                        && effect.effect_mask == row.effect_mask
                })
                .map(|effect| RepresentedAuraEffectAmountLikeCpp {
                    effect_index: effect.effect_index,
                    amount: effect.amount,
                })
                .collect();
            let duration_total = u32::try_from(row.max_duration_ms).unwrap_or(0);
            let duration_remaining = u32::try_from(row.remain_time_ms).unwrap_or(0);
            let spell_id = i32::try_from(row.spell_id).unwrap_or(i32::MAX);
            let aura_flags = AFLAG_NOCASTER_LIKE_CPP | 0x0000_0100;
            let canonical_snapshot = self.canonical_threat_aura_snapshot_for_difficulty_like_cpp(
                spell_id,
                row.difficulty,
                row.effect_mask,
                &represented_effect_amounts,
            );
            let installed = self.mutate_player_aura_subsystem_like_cpp(|auras| {
                auras.insert_threat_snapshot_like_cpp(slot, canonical_snapshot);
                auras.insert_runtime_application_like_cpp(AuraApplication {
                    spell_id,
                    difficulty_id: row.difficulty,
                    caster_guid,
                    slot,
                    duration_total,
                    duration_remaining,
                    stack_count: row.stack_count.max(1),
                    aura_flags,
                    effect_mask: row.effect_mask,
                    aura_interrupt_flags: 0,
                    aura_interrupt_flags2: 0,
                    represented_effect: None,
                    represented_amount: 0,
                    represented_effect_amounts,
                    represented_misc_value: None,
                    represented_multiplier: 1.0,
                    applied_at: Instant::now(),
                });
            });
            if installed.is_none() {
                break;
            }
            self.send_aura_update_applied(
                spell_id,
                slot,
                caster_guid,
                duration_total,
                aura_flags,
                row.effect_mask,
            );
            loaded += 1;
        }
        loaded
    }

    pub(crate) fn load_represented_pet_declined_names_like_cpp(
        &mut self,
        pet_number: u32,
        row: Option<CharacterPetDeclinedNamesRowLikeCpp>,
    ) -> bool {
        self.invalidate_represented_character_pet_empty_authority_like_cpp();
        if let Some(row) = row {
            self.pet_load_query_holder_rows_like_cpp
                .declined_names
                .insert(pet_number, row);
            true
        } else {
            self.pet_load_query_holder_rows_like_cpp
                .declined_names
                .remove(&pet_number)
                .is_some()
        }
    }

