            self.player_collection_state_snapshot_like_cpp()
                .map(|collections| {
                    collections
                        .mounts
                        .into_iter()
                        .map(|(spell_id, flags)| AccountMount { spell_id, flags })
                        .collect::<Vec<_>>()
                })
