    fn complete_represented_creature_death_state_after_kill_hooks_like_cpp(
        &mut self,
        attacker_guid: ObjectGuid,
        creature_guid: ObjectGuid,
    ) -> Option<wow_entities::UnitValuesUpdate> {
        #[cfg(not(test))]
        let _ = attacker_guid;
        let lootable = self
            .loot_table
            .get(&creature_guid)
            .is_some_and(|loot| loot.coins != 0 || loot.unlooted_count != 0);
        let can_skin = self.represented_creature_can_skin_after_death_state_like_cpp(creature_guid);
        let values_update = self.mutate_world_creature(creature_guid, |creature| {
            creature.complete_death_state_after_kill_hooks_like_cpp();
            creature.apply_corpse_loot_flags_after_death_state_like_cpp(lootable, can_skin);
            creature.creature.unit().values_update()
        })?;
        #[cfg(test)]
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::DeathStateJustDied {
                victim_guid: creature_guid,
            },
        );
        #[cfg(test)]
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::ZoneScriptUnitDeath {
                unit_guid: creature_guid,
            },
        );
        #[cfg(test)]
        self.record_represented_tapper_pet_killed_unit_hooks_like_cpp(creature_guid);
        #[cfg(test)]
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::LootFlagsApplied {
                creature_guid,
                lootable,
                can_skin,
                skinnable: can_skin,
            },
        );
        #[cfg(test)]
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::CreatureOnHealthDepletedAi {
                creature_guid,
                attacker_guid,
                is_kill: true,
            },
        );
        #[cfg(test)]
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::CreatureJustDiedAi {
                creature_guid,
                killer_guid: attacker_guid,
            },
        );
        #[cfg(test)]
        if attacker_guid.is_player() {
            self.represented_creature_kill_events_like_cpp.push(
                RepresentedCreatureKillEventLikeCpp::ScriptMgrOnCreatureKill {
                    killer_guid: attacker_guid,
                    creature_guid,
                },
            );
        }
        Some(values_update)
    }

    #[cfg(test)]
    fn record_represented_tapper_pet_killed_unit_hooks_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
    ) {
        let (Some(player_guid), Some(pet_guid)) = (
            self.player_guid(),
            self.player_pet_guid_state_like_cpp().flatten(),
        ) else {
            return;
        };
        let tapper_has_current_player = self
            .mutate_world_creature(creature_guid, |creature| {
                creature.creature.tap_list().contains(&player_guid)
            })
            .unwrap_or(true);
        if !tapper_has_current_player {
            return;
        }
        self.represented_creature_kill_events_like_cpp.push(
            RepresentedCreatureKillEventLikeCpp::TapperPetKilledUnitAi {
                tapper_guid: player_guid,
                pet_guid,
                victim_guid: creature_guid,
            },
        );
    }

    pub(crate) fn apply_move_init_active_mover_complete_like_cpp(&mut self, ticks: u32) {
        let transport_server_time = Self::game_time_ms_like_cpp().saturating_sub(ticks) as i32;
        if self
            .mutate_active_player_update_state_like_cpp(|state| {
                state.active_local_flags |=
                    PLAYER_LOCAL_FLAG_OVERRIDE_TRANSPORT_SERVER_TIME_LIKE_CPP;
                state.active_transport_server_time = transport_server_time;
            })
            .is_none()
        {
            return;
        }
        self.sync_current_player_session_visibility_detection_like_cpp();
        // C++ `HandleMoveInitActiveMoverComplete` calls
        // `Player::UpdateObjectVisibility(false)`, which only queues
        // `NOTIFY_VISIBILITY_CHANGED`. The represented Rust visibility scanner
        // is broader than C++ `VisibleNotifier` today; materializing it here
        // creates creatures/gameobjects that the captured C++ login stream does
        // not send and corrupts the client during world load. Keep the packet
        // side effect below, but do not turn the deferred notify into an
        // immediate object-create batch until the map-owned notify pass is
        // ported method-for-method.
        self.send_active_player_transport_server_time_update_like_cpp();
    }

    pub(crate) fn player_moved_unit_guid_like_cpp(&self) -> Option<ObjectGuid> {
        let canonical = self.with_owned_player_like_cpp(|player| {
            player.unit().subsystems().control.unit_moved_by_me
        });
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            let guid = if self.player_moved_unit_guid_like_cpp.is_empty() {
                self.player_guid()?
            } else {
                self.player_moved_unit_guid_like_cpp
            };
            return Some(guid);
        }
        canonical.flatten()
    }

    pub fn set_player_moved_unit_guid_like_cpp(&mut self, guid: ObjectGuid) {
        #[cfg_attr(not(test), allow(unused_variables))]
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                player
                    .unit_mut()
                    .subsystems_mut()
                    .control
                    .set_moved_unit((!guid.is_empty()).then_some(guid));
            })
            .is_some();
        #[cfg(test)]
        if canonical || self.player_handle_like_cpp.is_none() {
            self.player_moved_unit_guid_like_cpp = guid;
        }
    }

    pub(crate) fn represented_gameobject_use_allowed_by_mover_like_cpp(
        &self,
        gameobject_usable_mounted: bool,
    ) -> bool {
        let Some(player_guid) = self.player_guid() else {
            return false;
        };
        if self.player_moved_unit_guid_like_cpp() == Some(player_guid) {
            return true;
        }

        self.player_vehicle_seat_state_like_cpp()
            .and_then(|(flags, _)| flags)
            .is_some()
            || self.resolved_player_mounted_like_cpp() == Some(true)
            || gameobject_usable_mounted
    }

    pub(crate) fn represented_request_vehicle_exit_like_cpp(&mut self) -> bool {
        let Some(seat_flags) = self
            .player_vehicle_seat_state_like_cpp()
            .and_then(|(flags, _)| flags)
        else {
            return false;
        };
        if !wow_data::vehicle_seat_flags_can_enter_or_exit_like_cpp(seat_flags) {
            return false;
        }

        if !self.set_player_vehicle_seat_state_like_cpp(None, None) {
            return false;
        }
        self.sync_player_registry_state_like_cpp();
        true
    }

    pub(crate) fn represented_current_vehicle_seat_can_switch_from_like_cpp(&self) -> bool {
        self.player_vehicle_seat_state_like_cpp()
            .and_then(|(flags, _)| flags)
            .is_some_and(wow_data::vehicle_seat_flags_can_switch_from_seat_like_cpp)
    }

    pub(crate) fn represented_request_adjacent_vehicle_seat_like_cpp(
        &mut self,
        next: bool,
    ) -> bool {
        match crate::handlers::vehicle::request_adjacent_vehicle_seat_action_like_cpp(
            self.player_vehicle_seat_state_like_cpp()
                .and_then(|(flags, _)| flags)
                .is_some(),
            self.represented_current_vehicle_seat_can_switch_from_like_cpp(),
            next,
        ) {
            crate::handlers::vehicle::VehicleHandlerAction::ChangeSeat { seat_id, next } => {
                #[cfg(test)]
                self.represented_vehicle_seat_change_requests_like_cpp
                    .push(RepresentedVehicleSeatChangeRequestLikeCpp { seat_id, next });
                #[cfg(not(test))]
                let _ = (seat_id, next);
                true
            }
            _ => false,
        }
    }

