    fn represented_vehicle_base_guid_for_switch_like_cpp(&self) -> Option<ObjectGuid> {
        if self
            .player_vehicle_seat_state_like_cpp()
            .and_then(|(flags, _)| flags)
            .is_none()
        {
            return None;
        }
        self.player_moved_unit_guid_like_cpp()
    }

    fn represented_vehicle_seat_spell_click_plan_available_like_cpp(
        &self,
        vehicle_guid: ObjectGuid,
        seat_id: i8,
    ) -> bool {
        !self
            .represented_handle_spell_click_plan_with_seat_like_cpp(vehicle_guid, Some(seat_id))
            .casts
            .is_empty()
    }

    fn record_represented_vehicle_seat_action_like_cpp(
        &mut self,
        action: crate::handlers::vehicle::VehicleHandlerAction,
    ) -> bool {
        match action {
            crate::handlers::vehicle::VehicleHandlerAction::ChangeSeat { seat_id, next } => {
                #[cfg(test)]
                self.represented_vehicle_seat_change_requests_like_cpp
                    .push(RepresentedVehicleSeatChangeRequestLikeCpp { seat_id, next });
                #[cfg(not(test))]
                let _ = (seat_id, next);
                true
            }
            crate::handlers::vehicle::VehicleHandlerAction::ValidateMovementAndChangeSeat {
                next,
            } => {
                #[cfg(test)]
                self.represented_vehicle_seat_change_requests_like_cpp
                    .push(RepresentedVehicleSeatChangeRequestLikeCpp { seat_id: -1, next });
                #[cfg(not(test))]
                let _ = next;
                true
            }
            crate::handlers::vehicle::VehicleHandlerAction::HandleSpellClick {
                vehicle,
                seat_id,
            } => {
                let plan = self
                    .represented_handle_spell_click_plan_with_seat_like_cpp(vehicle, Some(seat_id));
                if plan.casts.is_empty() {
                    return false;
                }
                #[cfg(test)]
                self.represented_vehicle_seat_spell_click_requests_like_cpp
                    .push(RepresentedVehicleSeatSpellClickRequestLikeCpp {
                        vehicle_guid: vehicle,
                        seat_id,
                        planned_casts: plan.casts.len(),
                        exact_context_unrepresented: plan.exact_context_unrepresented,
                    });
                true
            }
            _ => false,
        }
    }

    pub(crate) fn represented_move_change_vehicle_seats_like_cpp(
        &mut self,
        status: &mut wow_packet::packets::movement::MovementInfo,
        dst_vehicle: ObjectGuid,
        dst_seat_index: u8,
    ) -> bool {
        let Some(vehicle_base_guid) = self.represented_vehicle_base_guid_for_switch_like_cpp()
        else {
            return false;
        };
        if !self.represented_current_vehicle_seat_can_switch_from_like_cpp() {
            return false;
        }

        self.sanitize_movement_info_represented_like_cpp(status);
        if status.guid != vehicle_base_guid {
            return false;
        }

        let dst_seat_id = dst_seat_index as i8;
        let dst_vehicle_exists_with_empty_seat = !dst_vehicle.is_empty()
            && self.represented_vehicle_seat_spell_click_plan_available_like_cpp(
                dst_vehicle,
                dst_seat_id,
            );
        let action = crate::handlers::vehicle::move_change_vehicle_seats_action_like_cpp(
            true,
            true,
            vehicle_base_guid,
            status.guid,
            dst_vehicle,
            dst_seat_index,
            dst_vehicle_exists_with_empty_seat,
        );

        #[cfg(test)]
        self.represented_vehicle_base_movements_like_cpp.push(
            RepresentedVehicleBaseMovementLikeCpp {
                vehicle_guid: vehicle_base_guid,
                sanitized_flags: status.flags,
                position: status.position,
                time: status.time,
            },
        );
        let _ = self.record_represented_vehicle_seat_action_like_cpp(action);
        true
    }

    pub(crate) fn represented_request_vehicle_switch_seat_like_cpp(
        &mut self,
        requested_vehicle: ObjectGuid,
        seat_index: u8,
    ) -> bool {
        let Some(vehicle_base_guid) = self.represented_vehicle_base_guid_for_switch_like_cpp()
        else {
            return false;
        };
        let seat_id = seat_index as i8;
        let requested_vehicle_exists_with_empty_seat = vehicle_base_guid != requested_vehicle
            && self.represented_vehicle_seat_spell_click_plan_available_like_cpp(
                requested_vehicle,
                seat_id,
            );
        let action = crate::handlers::vehicle::request_vehicle_switch_seat_action_like_cpp(
            true,
            self.represented_current_vehicle_seat_can_switch_from_like_cpp(),
            vehicle_base_guid,
            requested_vehicle,
            seat_index,
            requested_vehicle_exists_with_empty_seat,
        );
        self.record_represented_vehicle_seat_action_like_cpp(action)
    }

    pub(crate) fn represented_ride_vehicle_interact_like_cpp(
        &mut self,
        vehicle_guid: ObjectGuid,
    ) -> bool {
        const INTERACTION_DISTANCE_LIKE_CPP: f32 = 5.0;

        let Some(player_guid) = self.player_guid() else {
            return false;
        };
        let Some(player_position) = self.player_position_like_cpp() else {
            return false;
        };
        let Some(registry) = self.player_registry() else {
            return false;
        };
        let Some(target) = registry.vehicle_interaction_snapshot(vehicle_guid) else {
            return false;
        };

        let target_is_player_with_vehicle_kit = vehicle_guid.is_player() && target.has_vehicle_kit;
        let target_is_raid_member =
            self.represented_player_is_same_raid_with_like_cpp(player_guid, vehicle_guid);
        let current_map_id = self.player_map_id_like_cpp();
        let current_instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let target_is_within_interaction_distance = target.map_id == current_map_id
            && target.instance_id == current_instance_id
            && target
                .position
                .is_within_dist(&player_position, INTERACTION_DISTANCE_LIKE_CPP);
        let current_map_entry = self
            .map_store()
            .and_then(|store| store.get(u32::from(current_map_id)));
        let map_exists = current_map_entry.is_some();
        let map_is_battle_arena =
            current_map_entry.is_some_and(|entry| entry.instance_type == wow_data::map::MAP_ARENA);

        let action = crate::handlers::vehicle::ride_vehicle_interact_action_like_cpp(
            vehicle_guid,
            target_is_player_with_vehicle_kit,
            target_is_raid_member,
            target_is_within_interaction_distance,
            map_exists,
            map_is_battle_arena,
        );
        match action {
            crate::handlers::vehicle::VehicleHandlerAction::EnterVehicle { vehicle } => {
                #[cfg(test)]
                self.represented_vehicle_enter_requests_like_cpp.push(
                    RepresentedVehicleEnterRequestLikeCpp {
                        vehicle_guid: vehicle,
                    },
                );
                #[cfg(not(test))]
                let _ = vehicle;
                true
            }
            _ => false,
        }
    }

    pub(crate) fn represented_eject_passenger_like_cpp(
        &mut self,
        passenger_guid: ObjectGuid,
    ) -> bool {
        if !passenger_guid.is_unit() {
            return false;
        }

        let passenger_type_id = if passenger_guid.is_player() {
            TypeId::Player
        } else {
            TypeId::Unit
        };
        self.mutate_player_mount_vehicle_kit_like_cpp(|kit| {
            let Some(vehicle_kit) = kit.as_mut() else {
                return false;
            };
            if !vehicle_kit
                .seat_info_for_passenger_like_cpp(passenger_guid)
                .is_some_and(|seat| seat.ejectable)
            {
                return false;
            }
            vehicle_kit
                .remove_passenger_plan_like_cpp(
                    passenger_guid,
                    passenger_type_id,
                    false,
                    false,
                    false,
                    false,
                )
                .is_some()
        })
        .unwrap_or(false)
    }

    fn has_recently_dropped_flag_debuff_like_cpp(&self) -> Option<bool> {
        const SPELL_RECENTLY_DROPPED_ALLIANCE_FLAG: i32 = 42_792;
        const SPELL_RECENTLY_DROPPED_HORDE_FLAG: i32 = 50_326;
        const SPELL_RECENTLY_DROPPED_NEUTRAL_FLAG: i32 = 50_327;

        self.resolved_player_visible_auras_like_cpp().map(|auras| {
            auras.values().any(|aura| {
                matches!(
                    aura.spell_id,
                    SPELL_RECENTLY_DROPPED_ALLIANCE_FLAG
                        | SPELL_RECENTLY_DROPPED_HORDE_FLAG
                        | SPELL_RECENTLY_DROPPED_NEUTRAL_FLAG
                )
            })
        })
    }

    pub(crate) fn represented_player_can_use_battleground_object_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
    ) -> bool {
        let gameobject_faction = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.faction_template);
        if let (Some(player_faction), Some(gameobject_faction), Some(store)) = (
            self.player_faction_template_id_like_cpp(),
            gameobject_faction,
            self.faction_template_store.as_ref(),
        ) && let (Some(player_entry), Some(gameobject_entry)) =
            (store.get(player_faction), store.get(gameobject_faction))
            && !player_entry.is_friendly_to_like_cpp(gameobject_entry)
        {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::BattlegroundObjectUseRejected {
                    gameobject_guid,
                    player_guid,
                    reason: RepresentedBattlegroundObjectUseRejection::UnfriendlyFaction,
                },
            );
            return false;
        }

        let Some((player_unit_flags, _, _)) = self.player_unit_presentation_snapshot_like_cpp()
        else {
            return false;
        };
        if player_unit_flags.contains(UnitFlags::IMMUNE) {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::BattlegroundObjectUseRejected {
                    gameobject_guid,
                    player_guid,
                    reason: RepresentedBattlegroundObjectUseRejection::DamageImmune,
                },
            );
            return false;
        }

        let Some(has_recently_dropped_flag_debuff) =
            self.has_recently_dropped_flag_debuff_like_cpp()
        else {
            return false;
        };
        if has_recently_dropped_flag_debuff {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::BattlegroundObjectUseRejected {
                    gameobject_guid,
                    player_guid,
                    reason: RepresentedBattlegroundObjectUseRejection::RecentlyDroppedFlag,
                },
            );
            return false;
        }

        let Some(player_is_alive) = self.resolved_player_is_alive_like_cpp() else {
            return false;
        };
        if !player_is_alive {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::BattlegroundObjectUseRejected {
                    gameobject_guid,
                    player_guid,
                    reason: RepresentedBattlegroundObjectUseRejection::Dead,
                },
            );
            return false;
        }

        true
    }

