    pub(crate) fn player_taxi_state_snapshot_like_cpp(
        &self,
    ) -> Option<wow_entities::PlayerTaxiState> {
        let canonical =
            self.with_owned_player_like_cpp(|player| player.taxi_state_like_cpp().clone());
        #[cfg(test)]
        if canonical.is_none() && self.player_handle_like_cpp.is_none() {
            return Some(wow_entities::PlayerTaxiState {
                destinations: self.taxi_destinations_like_cpp.clone(),
                flight: self
                    .taxi_flight_state_like_cpp
                    .map(canonical_taxi_flight_state_like_cpp),
                unit_flags: self.taxi_unit_flags_like_cpp.bits(),
                mounted: self.taxi_mounted_like_cpp,
                ..Default::default()
            });
        }
        canonical
    }

    pub(crate) fn replace_player_taxi_state_like_cpp(
        &mut self,
        state: wow_entities::PlayerTaxiState,
    ) -> bool {
        let canonical = self
            .with_owned_player_mut_like_cpp(|player| {
                player.replace_taxi_state_like_cpp(state.clone())
            })
            .is_some();
        #[cfg(test)]
        if self.player_handle_like_cpp.is_none() {
            self.taxi_destinations_like_cpp = state.destinations;
            self.taxi_flight_state_like_cpp =
                state.flight.map(represented_taxi_flight_state_like_cpp);
            self.taxi_unit_flags_like_cpp = UnitFlags::from_bits_retain(state.unit_flags);
            self.taxi_mounted_like_cpp = state.mounted;
            return true;
        }
        canonical
    }

    fn mutate_player_taxi_state_like_cpp<R>(
        &mut self,
        f: impl FnOnce(&mut wow_entities::PlayerTaxiState) -> R,
    ) -> Option<R> {
        let mut state = self.player_taxi_state_snapshot_like_cpp()?;
        let result = f(&mut state);
        self.replace_player_taxi_state_like_cpp(state)
            .then_some(result)
    }

    pub(crate) fn handle_move_spline_done_taxi_like_cpp(
        &mut self,
        status: &mut wow_packet::packets::movement::MovementInfo,
        spline_id: i32,
    ) -> MoveSplineDoneTaxiActionLikeCpp {
        if !self.record_move_spline_done_like_cpp(status, spline_id) {
            return self.record_move_spline_done_taxi_event_like_cpp(
                spline_id,
                MoveSplineDoneTaxiActionLikeCpp::InvalidMovement,
                None,
                None,
                None,
                false,
            );
        }

        let Some(taxi_state) = self.player_taxi_state_snapshot_like_cpp() else {
            return self.record_move_spline_done_taxi_event_like_cpp(
                spline_id,
                MoveSplineDoneTaxiActionLikeCpp::IgnoredUnexpectedFinalPath,
                None,
                None,
                None,
                false,
            );
        };
        let current_destination = taxi_state.destinations.get(1).copied();
        if let Some(destination_node_id) = current_destination {
            let Some(flight) = taxi_state.flight else {
                return self.record_move_spline_done_taxi_event_like_cpp(
                    spline_id,
                    MoveSplineDoneTaxiActionLikeCpp::InProgressNoFlightGenerator,
                    Some(destination_node_id),
                    None,
                    None,
                    false,
                );
            };

            let destination_map_id = self
                .taxi_node_map_ids_like_cpp
                .get(&destination_node_id)
                .copied();
            let should_teleport = destination_map_id
                .map(|map_id| map_id != self.player_map_id_like_cpp())
                .unwrap_or(false)
                || flight.current_node.teleport_flag;

            if should_teleport {
                if let (Some(map_id), Some(node)) = (destination_map_id, flight.node_after_teleport)
                {
                    if self
                        .mutate_player_taxi_state_like_cpp(|taxi| {
                            taxi.flight = Some(wow_entities::PlayerTaxiFlightStateLikeCpp {
                                current_node: node,
                                node_after_teleport: None,
                            });
                        })
                        .is_none()
                    {
                        return self.record_move_spline_done_taxi_event_like_cpp(
                            spline_id,
                            MoveSplineDoneTaxiActionLikeCpp::IgnoredUnexpectedFinalPath,
                            Some(destination_node_id),
                            None,
                            None,
                            false,
                        );
                    }
                    self.set_player_map_position_like_cpp(map_id, node.position);
                    return self.record_move_spline_done_taxi_event_like_cpp(
                        spline_id,
                        MoveSplineDoneTaxiActionLikeCpp::TeleportRequested,
                        Some(destination_node_id),
                        Some(map_id),
                        Some(node.position),
                        false,
                    );
                }
            }

            return self.record_move_spline_done_taxi_event_like_cpp(
                spline_id,
                MoveSplineDoneTaxiActionLikeCpp::InProgressNoTeleport,
                Some(destination_node_id),
                None,
                None,
                false,
            );
        }

        if taxi_state.destinations.len() != 1 {
            return self.record_move_spline_done_taxi_event_like_cpp(
                spline_id,
                MoveSplineDoneTaxiActionLikeCpp::IgnoredUnexpectedFinalPath,
                None,
                None,
                None,
                false,
            );
        }

        if self
            .mutate_player_taxi_state_like_cpp(|taxi| {
                taxi.destinations.clear();
                taxi.flight = None;
                taxi.mounted = false;
                taxi.unit_flags &= !(UnitFlags::REMOVE_CLIENT_CONTROL | UnitFlags::ON_TAXI).bits();
            })
            .is_none()
        {
            return self.record_move_spline_done_taxi_event_like_cpp(
                spline_id,
                MoveSplineDoneTaxiActionLikeCpp::IgnoredUnexpectedFinalPath,
                None,
                None,
                None,
                false,
            );
        }
        let current_z = self
            .player_position_like_cpp()
            .map(|position| position.z)
            .unwrap_or(status.position.z);
        self.set_fall_information_like_cpp(0, current_z);
        let honorless_target_cast = self
            .player_world_local_state_like_cpp()
            .is_some_and(|state| state.pvp_hostile);

        self.record_move_spline_done_taxi_event_like_cpp(
            spline_id,
            MoveSplineDoneTaxiActionLikeCpp::FinalCleanup,
            None,
            None,
            None,
            honorless_target_cast,
        )
    }

    fn record_move_spline_done_taxi_event_like_cpp(
        &mut self,
        spline_id: i32,
        action: MoveSplineDoneTaxiActionLikeCpp,
        destination_node_id: Option<u32>,
        teleport_map_id: Option<u16>,
        teleport_position: Option<wow_core::Position>,
        honorless_target_cast: bool,
    ) -> MoveSplineDoneTaxiActionLikeCpp {
        #[cfg(test)]
        self.move_spline_done_taxi_events_like_cpp
            .push(MoveSplineDoneTaxiEventLikeCpp {
                spline_id,
                action,
                destination_node_id,
                teleport_map_id,
                teleport_position,
                honorless_target_cast,
            });
        #[cfg(not(test))]
        let _ = (
            spline_id,
            destination_node_id,
            teleport_map_id,
            teleport_position,
            honorless_target_cast,
        );
        action
    }

    pub(crate) fn record_move_teleport_ack_like_cpp(
        &mut self,
        mover_guid: ObjectGuid,
        ack_index: i32,
        move_time: i32,
    ) -> bool {
        let accepted = self.player_guid() == Some(mover_guid);
        self.record_movement_ack_event_like_cpp(MovementAckEventLikeCpp {
            opcode: ClientOpcodes::MoveTeleportAck,
            mover_guid,
            ack_index: Some(ack_index),
            movement_force_id: None,
            movement_force_type: None,
            adjusted_time: (move_time >= 0).then_some(move_time as u32),
            speed: None,
            time_skipped: None,
            spline_id: None,
            accepted,
        });
        accepted
    }

    pub(crate) fn handle_move_teleport_ack_like_cpp(
        &mut self,
        mover_guid: ObjectGuid,
        ack_index: i32,
        move_time: i32,
    ) -> MoveTeleportAckActionLikeCpp {
        let accepted = self.record_move_teleport_ack_like_cpp(mover_guid, ack_index, move_time);
        if !self.near_teleport_pending_like_cpp() {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::NotBeingTeleportedNear,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        }

        if !accepted {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::WrongMover,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        }

        let Some(teleport) = self.player_teleport_state_snapshot_like_cpp() else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };
        let Some((map_id, destination)) = teleport.near_destination else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingDestination,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };

        let Some(world_local_before) = self.player_world_local_state_like_cpp() else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };
        let Some(player_guid) = self.player_guid() else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };
        let Some(pvp_enabled_before) = self.player_is_pvp_like_cpp(player_guid) else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };
        let Some(in_pvp_before) = self.player_has_in_pvp_flag_like_cpp(player_guid) else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        };

        if !self.update_player_teleport_state_like_cpp(|state| state.near_pending = false) {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                Some(map_id),
                Some(destination),
                None,
                None,
                None,
                false,
                false,
                false,
                false,
            );
        }
        let old_zone = world_local_before.zone_id;
        self.set_player_map_position_like_cpp(map_id, destination);
        self.update_registry_position();
        self.set_fall_information_like_cpp(0, destination.z);

        let (new_zone, new_area) = teleport
            .near_destination_zone_area
            .unwrap_or((world_local_before.zone_id, world_local_before.area_id));
        self.update_zone_represented_like_cpp(new_zone, new_area);

        let zone_changed = old_zone != new_zone;
        let Some(world_local_after) = self.player_world_local_state_like_cpp() else {
            return self.record_move_teleport_ack_event_like_cpp(
                mover_guid,
                ack_index,
                move_time,
                MoveTeleportAckActionLikeCpp::MissingPlayerOwner,
                Some(map_id),
                Some(destination),
                Some(old_zone),
                Some(new_zone),
                Some(new_area),
                false,
                false,
                false,
                false,
            );
        };
        let honorless_target_cast = zone_changed && world_local_after.pvp_hostile;
        let pvp_disabled =
            zone_changed && !world_local_after.pvp_hostile && pvp_enabled_before && !in_pvp_before;
        if pvp_disabled {
            self.update_player_pvp_like_cpp(false, true);
        }

        self.resummon_pet_temporary_unsummoned_if_any_like_cpp();
        self.process_represented_delayed_resurrection_after_teleport_like_cpp();
        #[cfg(test)]
        {
            self.delayed_operations_processed_like_cpp =
                self.delayed_operations_processed_like_cpp.saturating_add(1);
        }

        self.record_move_teleport_ack_event_like_cpp(
            mover_guid,
            ack_index,
            move_time,
            MoveTeleportAckActionLikeCpp::Accepted,
            Some(map_id),
            Some(destination),
            Some(old_zone),
            Some(new_zone),
            Some(new_area),
            honorless_target_cast,
            pvp_disabled,
            true,
            true,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn record_move_teleport_ack_event_like_cpp(
        &mut self,
        mover_guid: ObjectGuid,
        ack_index: i32,
        move_time: i32,
        action: MoveTeleportAckActionLikeCpp,
        destination_map_id: Option<u16>,
        destination_position: Option<wow_core::Position>,
        old_zone_id: Option<u32>,
        new_zone_id: Option<u32>,
        new_area_id: Option<u32>,
        honorless_target_cast: bool,
        pvp_disabled: bool,
        pet_resummon_requested: bool,
        delayed_operations_processed: bool,
    ) -> MoveTeleportAckActionLikeCpp {
        #[cfg(test)]
        self.move_teleport_ack_events_like_cpp
            .push(MoveTeleportAckEventLikeCpp {
                mover_guid,
                ack_index,
                move_time,
                action,
                destination_map_id,
                destination_position,
                old_zone_id,
                new_zone_id,
                new_area_id,
                honorless_target_cast,
                pvp_disabled,
                pet_resummon_requested,
                delayed_operations_processed,
            });
        #[cfg(not(test))]
        let _ = (
            mover_guid,
            ack_index,
            move_time,
            destination_map_id,
            destination_position,
            old_zone_id,
            new_zone_id,
            new_area_id,
            honorless_target_cast,
            pvp_disabled,
            pet_resummon_requested,
            delayed_operations_processed,
        );
        action
    }

